        public string GetDashBoardValue(string SId, string SpeedLimit, string DashboardAccess)
        {
            try
            {
                //logWriter.WriteToLog("BLL:GetDashBoardValue() Start:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);
                String maxGprsDelayStr = "1200";
                String appMaxGprsDelayStr = "";
                //Added by Madhuri for making not reporting interval configurable-15122023 by default Not reporting interval is 72 hrs
                DataTable dtNrInterval = dbx.getNRconfigurationByAccount(SId);
                if (dtNrInterval != null && dtNrInterval.Rows.Count > 0)
                {
                    if (!string.IsNullOrEmpty(dtNrInterval.Rows[0]["NRInterval"].ToString()))
                    {
                        int NRInhrs = Convert.ToInt32(dtNrInterval.Rows[0]["NRInterval"]);
                        int NRintervalInSeconds = NRInhrs * 3600;
                        maxGprsDelayStr = NRintervalInSeconds.ToString();
                    }
                }
                else
                {
                    appMaxGprsDelayStr = System.Web.Configuration.WebConfigurationManager.AppSettings["MAXGPRSDELAY"];
                    if (!String.IsNullOrEmpty(appMaxGprsDelayStr))
                        maxGprsDelayStr = appMaxGprsDelayStr;
                }
                /*else
                {
                    appMaxGprsDelayStr = System.Web.Configuration.WebConfigurationManager.AppSettings["MAXGPRSDELAY"];
                    if (!String.IsNullOrEmpty(appMaxGprsDelayStr))
                        maxGprsDelayStr = appMaxGprsDelayStr;
                }*/
                //logWriter.WriteToLog("BLL:GetDashBoardValue() End:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);

                return dbx.dashBoardString(SId, SpeedLimit, maxGprsDelayStr, DashboardAccess);
            }
            catch
            {
                return string.Empty;
            }
            finally { dbx.close(); }
        }


