        public int getLastDirection(String vehicleId, String date)
        {
            try
            {
                int arrow = -1;
                Object[] direction = dbx.getLastDirection(vehicleId, date);
                if (direction.Length == 0)
                {
                    return arrow;
                }
                int lastIndex = 0;
                int prevIndex = direction.Length - 1;
                double lastLat = Convert.ToDouble(((Object[])direction[lastIndex])[0].ToString());
                double lastLong = Convert.ToDouble(((Object[])direction[lastIndex])[1].ToString());
                double prevLat = Convert.ToDouble(((Object[])direction[prevIndex])[0].ToString());
                double prevLong = Convert.ToDouble(((Object[])direction[prevIndex])[1].ToString());

                double deltaLong = lastLong - prevLong;
                double deltaLat = lastLat - prevLat;
                if (deltaLat == 0 || deltaLong == 0)
                {
                    return arrow;
                }
                double theta = Math.Atan(deltaLat / deltaLong);
                if (theta > 0 && deltaLat < 0)
                {
                    theta -= Math.PI;
                }
                if (theta < 0 && deltaLat > 0)
                {
                    theta += Math.PI;
                }
                //Response.Write(lastLat + ":" + lastLong + ":" + prevLat + ":" + prevLong + ":" + deltaLat + ":" + deltaLong + ":" + theta + "\n");
                if (theta > 0 && theta < 1.0 * Math.PI / 8.0
                    || theta < 0 && theta > -1.0 * Math.PI / 8.0)
                {
                    arrow = 0;
                }
                else if (theta < 3.0 * Math.PI / 8.0 && theta > 1.0 * Math.PI / 8.0)
                {
                    arrow = 1;
                }
                else if (theta < 5.0 * Math.PI / 8.0 && theta > 3.0 * Math.PI / 8.0)
                {
                    arrow = 2;
                }
                else if (theta < 7.0 * Math.PI / 8.0 && theta > 5.0 * Math.PI / 8.0)
                {
                    arrow = 3;
                }
                else if (theta < -7.0 * Math.PI / 8.0 || theta > 7.0 * Math.PI / 8.0)
                {
                    arrow = 4;
                }
                else if (theta < -5.0 * Math.PI / 8.0 && theta > -7.0 * Math.PI / 8.0)
                {
                    arrow = 5;
                }
                else if (theta < -3.0 * Math.PI / 8.0 && theta > -5.0 * Math.PI / 8.0)
                {
                    arrow = 6;
                }
                else if (theta < -1.0 * Math.PI / 8.0 && theta > -3.0 * Math.PI / 8.0)
                {
                    arrow = 7;
                }
                return arrow;
            }
            catch
            {
                dbx.close();
                throw;
            }
            finally { dbx.close(); }
        }

