        public DataTable OmniCommSoapServiceFuelData(String vehicleId, String fromDateStr, String toDateStr, String fuelSensorType)
        {
            int timeDiff = GetTimeZoneDiff();
            DateTime fromDate = Convert.ToDateTime(fromDateStr).AddSeconds(-timeDiff);
            DateTime toDate = Convert.ToDateTime(toDateStr).AddSeconds(-timeDiff);
            DataTable resultDt = new DataTable();
            ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12;

            string sessionId = getOmniCommSessionId();
            if (!string.IsNullOrEmpty(sessionId))
            {
                DataTable dt = dbx.getFuelSensorDetailsByVehicleId(vehicleId, fuelSensorType);
                string objectId = "";
                if (dt.Rows.Count > 0)
                {
                    objectId = dt.Rows[0]["FuelSensorId"].ToString();
                }
                else
                {
                    objectId = getOmniCommObjectId(sessionId, vehicleId);
                    if (!string.IsNullOrEmpty(objectId))
                        dbx.insertFuelSensorDetails(vehicleId, objectId, fuelSensorType);
                }
                if (!string.IsNullOrEmpty(objectId))
                {
                    resultDt = getOmniCommFuelLogDetails(sessionId, objectId, fromDate, toDate, fuelSensorType, vehicleId);
                }
            }
            for (int i = 0; i < resultDt.Rows.Count; i++)
            {
                resultDt.Rows[i]["Datetime"] = Convert.ToDateTime(resultDt.Rows[i]["Datetime"].ToString());
            }
            return resultDt;
        }

        public DataTable getOmniCommFuelLogDetails(string sessionId, string objectId, DateTime timeBegin, DateTime timeEnd, string fuelSensorType, string vehicleId)
        {
            DataTable resultDt = new DataTable();
            resultDt.Columns.Add("Datetime", typeof(DateTime));
            resultDt.Columns.Add("Level", typeof(double));
            long beginSecs = ConvertDateTimeToUnixTimestampSecs(Convert.ToDateTime(timeBegin).AddHours(-1));
            long endSecs = ConvertDateTimeToUnixTimestampSecs(Convert.ToDateTime(timeEnd));
            HttpWebRequest request = CreateSOAPWebRequest("https://senseltelematics.asymbix.net/AnalyticalServer/ws", "getSmoothedFuelLevelsByPeriod");

            XmlDocument SOAPReqBody = new XmlDocument();
            //SOAP Body Request  
            SOAPReqBody.LoadXml(@"<soapenv:Envelope xmlns:soapenv=""http://schemas.xmlsoap.org/soap/envelope/"" xmlns:anal=""http://omnicomm.ru/analyticalserver"">" +
   "<soapenv:Header/>" +
   "<soapenv:Body>" +
      "<anal:getSmoothedFuelLevelsByPeriod>" +
         "<sessionId>" + sessionId + "</sessionId>" +
         "<timeBegin>" + beginSecs + "</timeBegin>" +
         "<timeEnd>" + endSecs + "</timeEnd>" +
         "<vehicleAndTankIds>" +
            "<vehicleAndTankId>" +
               "<vehicleId>" + objectId + "</vehicleId>" +
            "</vehicleAndTankId >" +
         "</vehicleAndTankIds>" +
      "</anal:getSmoothedFuelLevelsByPeriod>" +
   "</soapenv:Body>" +
"</soapenv:Envelope>");


            using (Stream stream = request.GetRequestStream())
            {
                SOAPReqBody.Save(stream);
            }
            //Geting response from request  
            using (WebResponse Serviceres = request.GetResponse())
            {
                using (StreamReader rd = new StreamReader(Serviceres.GetResponseStream()))
                {
                    //reading stream  
                    var ServiceResult = rd.ReadToEnd();
                    XmlDocument doc = new XmlDocument();
                    doc.LoadXml(ServiceResult);
                    XmlNodeList returnVal = doc.GetElementsByTagName("return");

                    foreach (XmlNode node in returnVal)
                    {
                        XmlElement element = (XmlElement)node;
                        XmlNodeList nodeList = element.GetElementsByTagName("fuelDataSet");
                        foreach (XmlNode node1 in nodeList)
                        {
                            XmlElement element1 = (XmlElement)node1;
                            XmlNodeList nodeList1 = element1.GetElementsByTagName("fuelLevels");
                            foreach (XmlNode node2 in nodeList1)
                            {
                                XmlElement element2 = (XmlElement)node2;
                                XmlNodeList nodeList2 = element1.GetElementsByTagName("fuelLevel");
                                foreach (XmlNode node3 in nodeList2)
                                {
                                    XmlElement element3 = (XmlElement)node3;
                                    double level = Convert.ToDouble(element3.GetElementsByTagName("level")[0].InnerText);
                                    DateTime timeStamp = ConvertUnixTimestampSecsToDateTime(Convert.ToInt64(element3.GetElementsByTagName("timeStamp")[0].InnerText));
                                    resultDt.Rows.Add(timeStamp, level);
                                }
                            }
                        }
                    }
                }
            }
            return resultDt;
        }

