        public string getOmniCommRefuelingDetails(string sessionId, string objectId, string timeBegin, string timeEnd, string fuelSensorType, string vehicleId)
        {
            long beginSecs = ConvertDateTimeToUnixTimestampSecs(Convert.ToDateTime(timeBegin).AddMonths(-2));
            long endSecs = ConvertDateTimeToUnixTimestampSecs(Convert.ToDateTime(timeEnd));
            HttpWebRequest request = CreateSOAPWebRequest("https://senseltelematics.asymbix.net/AnalyticalServer/ws", "getRefuelingsAndDrainsByPeriod");

            XmlDocument SOAPReqBody = new XmlDocument();
            //SOAP Body Request  
            SOAPReqBody.LoadXml(@"<soapenv:Envelope xmlns:soapenv=""http://schemas.xmlsoap.org/soap/envelope/"" xmlns:anal=""http://omnicomm.ru/analyticalserver"">" +
   "<soapenv:Header/>" +
   "<soapenv:Body>" +
      "<anal:getRefuelingsAndDrainsByPeriod>" +
         "<sessionId>" + sessionId + "</sessionId>" +
         "<timeBegin>" + beginSecs + "</timeBegin>" +
         "<timeEnd>" + endSecs + "</timeEnd>" +
      "</anal:getRefuelingsAndDrainsByPeriod>" +
   "</soapenv:Body>" +
"</soapenv:Envelope>");


            using (Stream stream = request.GetRequestStream())
            {
                SOAPReqBody.Save(stream);
            }
            //Geting response from request  
            using (WebResponse Serviceres = request.GetResponse())
            {
                using (StreamReader rd = new StreamReader(Serviceres.GetResponseStream()))
                {
                    //reading stream  
                    var ServiceResult = rd.ReadToEnd();
                    XmlDocument doc = new XmlDocument();
                    doc.LoadXml(ServiceResult);
                    XmlNodeList returnVal = doc.GetElementsByTagName("return");

                    foreach (XmlNode node in returnVal)
                    {
                        XmlElement element = (XmlElement)node;
                        XmlNodeList nodeList = element.GetElementsByTagName("RefuelingsAndDrains");
                        foreach (XmlNode node1 in nodeList)
                        {
                            XmlElement element1 = (XmlElement)node1;
                            XmlNodeList nodeList1 = element1.GetElementsByTagName("RefuelingsAndDrainsData");
                            foreach (XmlNode node2 in nodeList1)
                            {
                                XmlElement element2 = (XmlElement)node2;
                                string xmlVehicleName = element2.GetElementsByTagName("vehicleName")[0].InnerText;
                                if (vehicleId == xmlVehicleName)
                                {
                                    string xmlTimeBegin = element2.GetElementsByTagName("timeBegin")[0].InnerText;
                                    DateTime fuelTimestamp = ConvertUnixTimestampSecsToDateTime(Convert.ToInt64(xmlTimeBegin));
                                    DataTable dt = dbx.checkFuelDataByVeh(xmlVehicleName, fuelTimestamp, fuelSensorType);
                                    if (dt.Rows.Count == 0)
                                    {
                                        string xmlVolume = element2.GetElementsByTagName("volume")[0].InnerText;
                                        double prefuel = getOmniCommFuelAtTime(sessionId, objectId, xmlTimeBegin);
                                        DataTable prevFuelDt = dbx.getPrevFuelData(xmlVehicleName, fuelTimestamp, fuelSensorType);
                                        int distance = 0;
                                        double mileage = 0;
                                        if (prevFuelDt.Rows.Count > 0)
                                        {
                                            Object[] ret = accumulateDistance(xmlVehicleName, formatDBDate(Convert.ToDateTime(prevFuelDt.Rows[0]["TimeStamp"].ToString())), formatDBDate(fuelTimestamp), null);
                                            distance = Convert.ToInt16(ret[0]);
                                            mileage = distance / (Convert.ToDouble(prevFuelDt.Rows[0]["PostFuel"].ToString()) - prefuel);
                                        }
                                        int res = dbx.insertFuelData(xmlVehicleName, fuelTimestamp, Convert.ToDouble(xmlVolume), prefuel, distance, mileage, fuelSensorType);
                                    }
                                }
                            }
                        }
                    }
                }
            }
            return objectId;
        }

