        public HttpWebRequest CreateSOAPWebRequest(string httpWebRequestUrl, string methodName)
        {
            //Making Web Request  
            HttpWebRequest Req = (HttpWebRequest)WebRequest.Create(httpWebRequestUrl);
            //SOAPAction  
            Req.Headers.Add(@"SOAPAction:http://tempuri.org/" + methodName);
            //Content_type  
            Req.ContentType = "text/xml;charset=\"utf-8\"";
            Req.Accept = "text/xml";
            //HTTP method  
            Req.Method = "POST";
            //return HttpWebRequest  
            return Req;
        }

        public Object[] accumulateDistanceWithGoogle(string vehicleId, string tripStartStr, string tripEndStr, Object lastLatLong, double DistanceCorrection, Object[] values = null)
        {
            try
            {
                //
                //  There are cases where vehicles remain idle for hours together so the routine has been modified to exclude such IDLING periods.
                //
                double latitudeThresholdIdle = 0.0001; // approx 15m
                double longitudeThresholdIdle = 0.0001; // approx 15m
                double distance = 0;
                TimeSpan runTime = new TimeSpan(0);
                float[] newLastLatLong = new float[3]; // need to store the STOP bit as float
                Object[] retObj = new Object[7];
                retObj[0] = distance;
                retObj[1] = null;
                retObj[2] = runTime;
                retObj[3] = "";
                retObj[4] = "";
                retObj[5] = "";
                retObj[6] = "";

                if (values == null)
                    values = dbx.getLatLong(vehicleId, tripStartStr, tripEndStr);
                String slowVeh = dbx.getTempSensorFlag(vehicleId);
                Boolean ignoreIdling = false;
                if (!String.IsNullOrEmpty(slowVeh) && String.Equals(slowVeh.ToUpper(), "SLOW"))
                    ignoreIdling = true;
                if (values == null || values.Length <= 1)
                {
                    return retObj;
                }
                float stopLatitude;
                float stopLongitude;
                float startLatitude;
                float startLongitude;
                float speed = 0.0F;
                DateTime stopTime;
                DateTime startTime;
                int curStopBit = 0;
                int lastStopBit = 0;
                stopTime = DateTime.Parse(tripStartStr);
                if (lastLatLong != null)
                {
                    stopLatitude = ((Single[])lastLatLong)[0];
                    stopLongitude = ((Single[])lastLatLong)[1];
                    lastStopBit = Convert.ToInt32(((Single[])lastLatLong)[2]); // extract the Stop bit
                    if (ignoreIdling)
                        stopTime = (DateTime)((Object[])values[0])[2];
                }
                else
                {
                    stopLatitude = Convert.ToSingle(((Object[])values[0])[0]);
                    stopLongitude = Convert.ToSingle(((Object[])values[0])[1]);
                    lastStopBit = Convert.ToInt32(((Object[])values[0])[3]); //stop bit is after timestamp
                    stopTime = (DateTime)((Object[])values[0])[2];
                    speed = Convert.ToSingle(((Object[])values[0])[5]);
                }
                retObj[3] = stopLatitude.ToString() + "," + stopLongitude.ToString();
                for (int i = 0; i < values.Length; i++)
                {
                    startLatitude = Convert.ToSingle(((Object[])values[i])[0]);
                    startLongitude = Convert.ToSingle(((Object[])values[i])[1]);
                    startTime = (DateTime)((Object[])values[i])[2];
                    curStopBit = Convert.ToInt32(((Object[])values[i])[3]);
                    speed = Convert.ToSingle(((Object[])values[i])[5]);
                    double deltaLastLatitude = Math.Abs(stopLatitude - startLatitude);
                    double deltaLastLongitude = Math.Abs(stopLongitude - startLongitude);
                    if (curStopBit == 0 || lastStopBit == 0 || (curStopBit == 1 && speed > 9.0F)) //do not accumulate dsitance when HALTED
                    {
                        //
                        // the latitude and longitude threshold IDLE is a function of update rate. For 24 sec update rate the 0.0001 is probably ok 
                        // as it translates to about 2.5 kmph. Ideally the threshold values should be a function of update rate.
                        // Right now it is set so that anythng less than 4.5 kmph is thought to be IDLE (assuming updates do not get missed). 
                        // Now again this is a simplification as we need to consider the timestamp difference as well But ok for now.
                        //
                        bool IsMlogData = false;
                        TimeSpan elapsedTime = startTime.Subtract(stopTime);
                        if (elapsedTime.TotalSeconds == 1 && speed > 2)//For MLOG Data
                            IsMlogData = true;
                        if ((deltaLastLatitude > latitudeThresholdIdle * 2) || (deltaLastLongitude > longitudeThresholdIdle * 2) || (ignoreIdling) || IsMlogData)
                        {
                            double currentDistance = computeDistance(stopLatitude, stopLongitude, startLatitude, startLongitude);
                            if (currentDistance > 5)//If Distance is more than 5Km,then we need to get distance from google.
                            {
                                decimal dist = getgoogleDistance(stopLatitude.ToString(), stopLongitude.ToString(), startLatitude.ToString(), startLongitude.ToString());
                                if (dist > 0)//If not able to get Distance from google this method will return 0;
                                {
                                    currentDistance = Convert.ToDouble(dist);
                                }
                            }
                            /*
                            if (i == 0)
                            {
                                Response.Write("Distance: " + currentDistance*1.02 + "<BR>\n");
                            }*/
                            // If positions are less than 5 minutes apart, consider vehicle as moving. THIS IS NOT TRUE. HERE's WHY THERE ARE 
                            // 3 POSSIBILITES. i) IF ALL's WELL THEN elapsedTime SHOULD BE < 1.0 SO ADD TO RUNTIME ii) IF A UNIT HAS JUST BOOTED
                            // AFTER A LONG STOP WHICH TAKES < 5 minutes THEN ADD ONLY IF THE DELTA TIME IS < 5 minutes. III)IF THERE ARE STRAIGHTLINES DUE TO
                            // VEHICLE OR UNIT ISSUES AND IF DISTANCE IS ADDED THEN YOU HAVE TO ADD TO RUNTIME AS WELL OTHERWISE IT WILL BE ABSURD I.E 
                            // VEHICLE HAS TRAVELLED THE DISTANCE IN NO TIME.
                            // KLUDGE TO TAKE CARE OF iii)  is to consider distance between two points. Logically it should not be more than 4 kms
                            // assuming all is well with the unit 
                            if (!(currentDistance >= 6 && elapsedTime.TotalMinutes < 1.0))
                            {  // Come here only if there are no zig-zags. This is a KLUDGE and the correct distance value may have to be tweaked
                                double distaddl = (DistanceCorrection / 100) * currentDistance;
                                if ((currentDistance / elapsedTime.TotalMinutes) >= 0.2 && (currentDistance / elapsedTime.TotalMinutes) <= 4 || (ignoreIdling)) // Take care of st lines //Assume Speed Can't more than 4km/min
                                // Atleast 2 scenarios it should take care 
                                // St line while running .... assumption is that avg speed > 18kmph
                                // St line after a HALT that had the unit OFF  in this case do not add the distance and HALT time can be anything
                                { // Now for some reason if the unit takes very long to boot up and get a position and the vehicle has moved far from rest
                                    // then it is a problem. Ideally we need to TEST the start BIT as well which we do not have here
                                    currentDistance = currentDistance + distaddl;
                                    distance += currentDistance;
                                    runTime = runTime.Add(elapsedTime);  // A straight line case so if distance is added then add the time to runTime
                                }
                                else if (elapsedTime.TotalSeconds < 60)
                                {
                                    currentDistance = currentDistance + distaddl;
                                    distance += currentDistance;
                                    runTime = runTime.Add(elapsedTime);
                                }
                                else if ((ignoreIdling && elapsedTime.TotalSeconds < 300))//Slow Moving Vehicle.(Run Time Need To Calculate Some what Acc. So here we need to Consider More Than 5mins Only Vehicle is Off.)
                                {
                                    runTime = runTime.Add(elapsedTime);
                                }
                                else if (currentDistance < 1.1 && elapsedTime.TotalMinutes > 150)//If vehicle is haleted more than 150mins in basement(NO GPS) area.and getting signal after moving some distance.(we are taking 1.1km)
                                {
                                    currentDistance = currentDistance + distaddl;
                                    distance += currentDistance;
                                }
                            }
                            if (distance > 0 && retObj[5].ToString() == "")
                            {
                                retObj[5] = stopTime.ToString("yyyy-MM-dd HH:mm:ss");
                            }
                            if (currentDistance > 0)
                            {
                                retObj[6] = startTime.ToString("yyyy-MM-dd HH:mm:ss");
                            }
                        }
                    }
                    stopLatitude = startLatitude;
                    stopLongitude = startLongitude;
                    stopTime = startTime;
                    lastStopBit = curStopBit;
                }
                //Response.Write("Run:" + runTime.ToString() + "<BR>");
                distance = distance * 1.02;
                newLastLatLong[0] = stopLatitude;
                newLastLatLong[1] = stopLongitude;
                newLastLatLong[2] = Convert.ToSingle(lastStopBit);
                retObj[0] = distance;
                retObj[1] = newLastLatLong;
                retObj[2] = runTime;
                retObj[4] = stopLatitude.ToString() + "," + stopLongitude.ToString();
                return retObj;
            }
            catch
            {
                dbx.close();
                // throw;
                return null;
            }
            // finally { dbx.close(); }
        }

        public object[] calculateNotReachable(string vehicleid, DateTime fromdt, DateTime todt, object[] values = null)
        {
            object[] res = new object[3];
            if (values == null)
                values = dbx.getLatLong(vehicleid, fromdt.ToString("yyyy-MM-dd HH:mm:ss"), todt.ToString("yyyy-MM-dd HH:mm:ss"));
            if (values != null && values.Length > 0)
            {
                res[0] = new TimeSpan(0);
                res[1] = fromdt;
                res[2] = fromdt;
                DateTime lastTime = fromdt;
                for (int i = 0; i <= values.Length; i++)
                {
                    DateTime presentTime = todt;
                    if (i != values.Length)
                        presentTime = Convert.ToDateTime(((Object[])values[i])[2]);
                    if (i != 0)
                        lastTime = Convert.ToDateTime(((Object[])values[i - 1])[2]);
                    TimeSpan diff = presentTime - lastTime;
                    if (TimeSpan.Compare(diff, (TimeSpan)res[0]) == 1)
                    {
                        res[0] = diff;
                        res[1] = lastTime;
                        res[2] = presentTime;
                    }
                }
            }
            else
            {
                res[0] = todt - fromdt;
                res[1] = fromdt;
                res[2] = todt;
            }
            return res;
        }

        //
        // This function  will calculate the total IDLE TIME ONLY or HALT TIME ONLY OR BOTH based on
        // the String what. The code is very similar to showHalt() except that it does not need to know each location
        // In addition this function will also return the first Movement timeStamp and the lastMovement timestamp with the given time frame
        // The values should contain the START bit as well to take care of BATTERY cut-off
        public Object[] calculateIdleAndOrHalt(String curVehicleId, String fromDateStr, String toDateStr, String what, Object[] values = null)
        {
            TimeSpan maxHalt = new TimeSpan(0, 0, 0);
            double latitudeThresholdIdle = 0.0001; // approx 15m
            double longitudeThresholdIdle = 0.0001; // approx 15m
            double latitudeThresholdHalt = 0.04;	// approx 4 km (?). 
            double longitudeThresholdHalt = 0.04;
            Object[] retObj = new Object[7];
            Boolean firstMovement = false;
            Boolean lastMovement = false;

            //Halt-2 algorithm variables;
            bool idlingArmed = false;
            bool haltArmed = false;
            double stopLatitude = 0.0D;
            double stopLongitude = 0.0D;

            DateTime stopTimestamp = DateTime.MinValue;
            double lastLatitude = 0.0D;
            double lastLongitude = 0.0D;
            double currentSpeed = 0.0D;

            DateTime lastTimestamp = DateTime.MinValue;
            DateTime conthalt_start = DateTime.MinValue;//Continous Halt Start Time
            string conthalt_start_latlng = "";
            DateTime conthalt_end = DateTime.MinValue;//Continous Halt End Time
            TimeSpan maxStopTime = new TimeSpan(0);
            DateTime maxStopTs = DateTime.MinValue;
            TimeSpan idleTime = new TimeSpan(0);
            TimeSpan haltTime = new TimeSpan(0);
            TimeSpan continuoushaltTime = new TimeSpan(0);
            TimeSpan maxhaltTime = new TimeSpan(0);
            TimeSpan continuoushaltTime_Chg = new TimeSpan(0);
            List<TimeSpan> maxhaltTime_List = new List<TimeSpan>();
            ArrayList conthalt_start_List = new ArrayList();
            ArrayList conthalt_start_latlng_List = new ArrayList();
            ArrayList conthalt_end_List = new ArrayList();
            double prevousStop_Latitude = 0.0D;
            double prevousStop_Longitude = 0.0D;
            //Initialize
            retObj[0] = stopTimestamp;
            retObj[1] = stopTimestamp;
            retObj[2] = idleTime;
            retObj[3] = maxhaltTime;
            retObj[4] = conthalt_start;
            retObj[5] = conthalt_end;
            retObj[6] = conthalt_start_latlng;
            DateTime fromDate = DateTime.Parse(fromDateStr);
            DateTime toDate = DateTime.Parse(toDateStr);

            if (values == null)
                values = dbx.getLatLong(curVehicleId, fromDateStr, toDateStr);
            if (values.Length > 0)
            {
                DateTime st = DateTime.Parse((((Object[])values[0])[2]).ToString());
                if ((st - fromDate).TotalHours > 1)
                {
                    object[] v = dbx.getLatLong(curVehicleId, dbx.formatDBDate(fromDate.AddHours(-5)), fromDateStr);
                    if (v.Length == 0)
                        v = dbx.getLatLong(curVehicleId, dbx.formatDBDate(fromDate.AddHours(-10)), fromDateStr);
                    if (v.Length == 0)
                        v = dbx.getLatLong(curVehicleId, dbx.formatDBDate(fromDate.AddHours(-20)), fromDateStr);
                    if (v.Length > 0)
                    {
                        var list = new List<object>(values);
                        list.Insert(0, v[v.Length - 1]);
                        values = list.ToArray();
                    }
                }
            }
            for (int index = 0; index < values.Length; index++)
            {	// dbx.getLatLong - Latitude, Longitude, Timestamp, stop
                if (index < 1)
                {
                    lastLatitude = Convert.ToDouble(((Object[])values[0])[0]);
                    lastLongitude = Convert.ToDouble(((Object[])values[0])[1]);
                    currentSpeed = Convert.ToDouble(((Object[])values[0])[5]);
                    prevousStop_Latitude = lastLatitude;
                    prevousStop_Longitude = lastLongitude;
                    lastTimestamp = DateTime.Parse((((Object[])values[0])[2]).ToString());
                    haltArmed = false;
                    idlingArmed = false;
                    // If the first Latlong has a START BIT set then need to add that to the stop time.
                    int STARTbit = Convert.ToInt32((((Object[])values[0])[4]).ToString());
                    if (STARTbit == 1)
                    {
                        TimeSpan diff = lastTimestamp - fromDate;
                        if (TimeSpan.Compare(diff, maxStopTime) == 1)
                        {
                            maxStopTime = diff;
                            maxStopTs = lastTimestamp;
                        }
                        haltTime += diff;
                        continuoushaltTime += diff;
                    }
                    retObj[0] = lastTimestamp;
                    retObj[1] = lastTimestamp;
                    retObj[2] = haltTime;
                    retObj[3] = continuoushaltTime;
                    retObj[4] = conthalt_start;
                    retObj[5] = conthalt_end;
                    conthalt_start_latlng = lastLatitude + "," + lastLongitude;
                    continue;
                }
                // dbx.getLatLongWithStartBit - Latitude, Longitude, Timestamp, start,stop
                double currentLatitude = Convert.ToDouble(((Object[])values[index])[0]);
                double currentLongitude = Convert.ToDouble(((Object[])values[index])[1]);
                currentSpeed = Convert.ToDouble(((Object[])values[index])[5]);
                DateTime currentTimestamp = DateTime.Parse((((Object[])values[index])[2]).ToString());
                // Extract STOP bit
                int STOP = Convert.ToInt32(((Object[])values[index])[3]);

                double deltaLastLatitude = Math.Abs(currentLatitude - lastLatitude);
                double deltaLastLongitude = Math.Abs(currentLongitude - lastLongitude);

                double Cont_deltaLastLatitude = Math.Abs(currentLatitude - prevousStop_Latitude);
                double Cont_deltaLastLongitude = Math.Abs(currentLongitude - prevousStop_Longitude);
                TimeSpan elapsedTime = (currentTimestamp - lastTimestamp);
                /*
                if (Cont_deltaLastLatitude < 0.001 && Cont_deltaLastLongitude < 0.001)//longitudeThresholdHalt - 0.01)
                {
                    continuoushaltTime_Chg += elapsedTime;
                    if (index == (values.Length - 1))
                    {
                        maxhaltTime_List.Add(continuoushaltTime_Chg);
                        conthalt_start_List.Add(lastTimestamp.Add(-continuoushaltTime_Chg));
                        conthalt_start_latlng_List.Add(lastLatitude + "," + lastLongitude);
                        conthalt_end_List.Add(lastTimestamp);
                        continuoushaltTime_Chg = new TimeSpan(0);
                    }
                }
                else
                {
                    double currentDistance=computeDistance(currentLatitude,currentLongitude,lastLatitude,lastLongitude);
                    if (continuoushaltTime_Chg.TotalMinutes > 15 || index == (values.Length - 1))
                    {
                        maxhaltTime_List.Add(continuoushaltTime_Chg);
                        conthalt_start_List.Add(lastTimestamp.Add(-continuoushaltTime_Chg));
                        conthalt_start_latlng_List.Add(lastLatitude + "," + lastLongitude);
                        conthalt_end_List.Add(lastTimestamp);
                    }
                    if (!(currentDistance >= 3 && elapsedTime.TotalMinutes < 1.0))
                    {
                        continuoushaltTime_Chg = new TimeSpan(0);
                        prevousStop_Latitude = currentLatitude;
                        prevousStop_Longitude = currentLongitude;
                    }
                }*/
                if (STOP == 1)
                {
                    if (index == (values.Length - 1) && !lastMovement)
                    {  // capture the time begining of this stop for this vehicle which will be the lAST TIME the vehicle moved in the period
                        retObj[1] = stopTimestamp;
                        lastMovement = true;
                    }
                    if (idlingArmed)
                    {	// accumulate IDLE duration separately.
                        // While ideally the delta should be between lastTimeStamp and stopTimeStamp, there7 is a special case (like Total Oil) 
                        // where the main battery is cut-off which can result in significant time difference between two consecutive points which
                        // should be considered as HALT time. 
                        //

                        TimeSpan deltaTime = currentTimestamp - lastTimestamp;


                        if ((deltaTime.TotalSeconds > 5 * 60) && // gap of 5 minutes between consecutive positiondata due to main battery cut-off or..
                            (deltaLastLatitude < latitudeThresholdHalt) && (deltaLastLongitude < longitudeThresholdHalt) ||
                            (index == (values.Length - 1)))
                        {
                            deltaTime = currentTimestamp - stopTimestamp;
                            stopLatitude = currentLatitude;
                            stopLongitude = currentLongitude;
                            stopTimestamp = currentTimestamp;
                        }
                        else
                        {
                            deltaTime = lastTimestamp - stopTimestamp;
                            stopLatitude = lastLatitude;
                            stopLongitude = lastLongitude;
                            stopTimestamp = lastTimestamp;
                        }
                        // DO not add stoppages due to SIGNAL or traffic which is assumed to be < 3 minutes
                        if (deltaTime.TotalSeconds > 0 * 60)     // was 3 * 60
                        {
                            idleTime += deltaTime;
                            continuoushaltTime += deltaTime;
                        }
                        idlingArmed = false;
                        haltArmed = true;
                    }
                    else if (!haltArmed)
                    {
                        haltArmed = true;
                        if ((currentTimestamp - lastTimestamp).TotalMinutes <= 5)
                        {
                            stopLatitude = lastLatitude;
                            stopLongitude = lastLongitude;
                            //stopUnixts = lastUnixts;
                            stopTimestamp = lastTimestamp;
                        }
                        else
                        {
                            stopLatitude = currentLatitude;
                            stopLongitude = currentLongitude;
                            //stopUnixts = currentUnixts;
                            stopTimestamp = currentTimestamp;
                        }
                    }
                    else if (haltArmed && index == (values.Length - 1))
                    {
                        TimeSpan deltaTime = lastTimestamp - stopTimestamp;
                        if (deltaTime.TotalSeconds > 3 * 60)
                        {
                            haltTime += deltaTime;
                            continuoushaltTime += deltaTime;
                        }
                    }
                }
                else
                {
                    TimeSpan deltaTime = currentTimestamp - lastTimestamp;
                    if (haltArmed)
                    {
                        if (index == (values.Length - 1) && !lastMovement)
                        {  // capture the time begining of this stop for this vehicle which will be the lAST TIME the vehicle moved in the period
                            retObj[1] = stopTimestamp;
                            lastMovement = true;
                        }
                        // While ideally the delta should be between lastTimeStamp and stopTimeStamp, there is a special case (like Total Oil)
                        // where the main battery is cut-off which can result in significant time difference between two consecutive points which
                        // should be considered as HALT time. 
                        //
                        if ((deltaTime.TotalSeconds > 5 * 60) && // gap of 5 minutes between consecutive positiondata due to main battery cut-off or..
                            (deltaLastLatitude <= latitudeThresholdHalt) && (deltaLastLongitude <= longitudeThresholdHalt) ||
                            (index == (values.Length - 1)))
                        {	// device takes about 4 mins to power up
                            deltaTime = currentTimestamp - stopTimestamp;
                            stopLatitude = currentLatitude;
                            stopLongitude = currentLongitude;
                            stopTimestamp = currentTimestamp;
                        }
                        else
                        {
                            deltaTime = lastTimestamp - stopTimestamp;
                            stopLatitude = lastLatitude;
                            stopLongitude = lastLongitude;
                            stopTimestamp = lastTimestamp;
                        }
                        if (deltaTime.TotalSeconds > 0 * 60)   // was 3 *60
                        {
                            haltTime += deltaTime;
                            continuoushaltTime += deltaTime;
                        }
                        haltArmed = false;
                    }
                    else if (idlingArmed)
                    {
                        double deltaStopLatitude = Math.Abs(currentLatitude - stopLatitude);
                        double deltaStopLongitude = Math.Abs(currentLongitude - stopLongitude);
                        if (index == (values.Length - 1) && !lastMovement)
                        {  // capture the time begining of this stop for this vehicle which will be the lAST TIME the vehicle moved in the period
                            retObj[1] = stopTimestamp;
                            lastMovement = true;
                        }
                        // If we come here, it means idling is ON.
                        // Idling will end if there is movement
                        // Also, report any idling in progress if we reach end of data
                        if (((deltaStopLatitude > latitudeThresholdIdle * 10.0) || (deltaStopLongitude > longitudeThresholdIdle * 10.0)) // Modified by suvarna on 14/5/2021 to check whether vehicle had moved atleast 130 to 140m
                            || (index == values.Length - 1))
                        {
                            if ((deltaTime.TotalSeconds > 5 * 60)  // if battery was killed
                                && (deltaLastLatitude <= latitudeThresholdHalt) && (deltaLastLongitude <= longitudeThresholdHalt))
                            {
                                deltaTime = currentTimestamp - stopTimestamp;
                                stopLatitude = currentLatitude;
                                stopLongitude = currentLongitude;
                                stopTimestamp = currentTimestamp;
                            }
                            else
                            {
                                deltaTime = lastTimestamp - stopTimestamp;
                                stopLatitude = lastLatitude;
                                stopLongitude = lastLongitude;
                                stopTimestamp = lastTimestamp;
                            }
                            idlingArmed = false;
                            if (deltaTime.TotalSeconds > 0 * 60)  // was 3*60
                            {
                                idleTime += deltaTime;
                                continuoushaltTime += deltaTime;
                            }
                            //Reset the continuoushaltTime
                            if (continuoushaltTime > maxhaltTime)
                            {
                                maxhaltTime = continuoushaltTime;
                                conthalt_start = lastTimestamp.Add(-continuoushaltTime);
                                conthalt_start_latlng = lastLatitude + "," + lastLongitude;
                                conthalt_end = lastTimestamp;
                            }
                            continuoushaltTime = new TimeSpan(0);
                        }
                    }/*
                    else if (!idlingArmed)
                    {
                        if (((deltaLastLatitude < latitudeThresholdIdle) && (deltaLastLongitude < longitudeThresholdIdle)) && currentSpeed < 0.05)
                        {
                            idlingArmed = true;
                            if ((currentTimestamp - lastTimestamp).TotalMinutes <= 5)
                            {
                                stopLatitude = lastLatitude;
                                stopLongitude = lastLongitude;
                                //stopUnixts = lastUnixts;
                                stopTimestamp = lastTimestamp;
                            }
                            else
                            {
                                stopLatitude = currentLatitude;
                                stopLongitude = currentLongitude;
                                //stopUnixts = currentUnixts;
                                stopTimestamp = currentTimestamp;
                            }
                        }
                    }*/
                    else if ((deltaTime.TotalSeconds > 15 || currentSpeed <= 3.0) && // gap of atleast 15 sec between consecutive positiondata
                    (deltaLastLatitude <= latitudeThresholdIdle * 2) && (deltaLastLongitude <= longitudeThresholdIdle * 2))//Modified by suvarna on 17/9/2021 to fix gps fluctuation issue
                    {
                        idlingArmed = true;
                        stopLatitude = lastLatitude;
                        stopLongitude = lastLongitude;
                        stopTimestamp = lastTimestamp;
                    }
                    else
                    { // special case where neither idlingArmed or haltArmed and the battery (vehicle is killed for a long time then it is considered HALT
                        // There are special cases like loose contact which might be shown as a halt but I guess the distance threshold may take care?
                        if ((deltaTime.TotalSeconds > 5 * 60) && // gap of 5 minutes between consecutive positiondata due to main battery cut-off or..
                            (deltaLastLatitude <= latitudeThresholdHalt) && (deltaLastLongitude <= longitudeThresholdHalt) ||
                            (index == (values.Length - 1)))
                        {
                            deltaTime = currentTimestamp - lastTimestamp;
                            stopLatitude = currentLatitude;
                            stopLongitude = currentLongitude;
                            stopTimestamp = currentTimestamp;
                            haltTime += deltaTime;
                            continuoushaltTime += deltaTime;
                        }
                        else //Moving
                        {
                            //Reset the continuoushaltTime
                            if (continuoushaltTime > maxhaltTime)
                            {
                                maxhaltTime = continuoushaltTime;
                                conthalt_start = lastTimestamp.Add(-continuoushaltTime);
                                conthalt_start_latlng = lastLatitude + "," + lastLongitude;
                                conthalt_end = lastTimestamp;
                            }
                            continuoushaltTime = new TimeSpan(0);
                        }
                    }
                }
                if (!firstMovement)
                {
                    retObj[0] = currentTimestamp;
                    firstMovement = true;
                }
                if (index == (values.Length - 1))
                {
                    if (!lastMovement)
                    {  // capture the time it first stopped
                        retObj[1] = lastTimestamp;
                        lastMovement = true;
                    }
                    // If there is a gap between the currentTimeStamp and the toDate then the vehicle has halted add it to haltTimes
                    TimeSpan diff = toDate - currentTimestamp;

                    haltTime += diff;
                    continuoushaltTime += diff;
                    if (continuoushaltTime > maxhaltTime)
                    {
                        maxhaltTime = continuoushaltTime;
                        conthalt_start = toDate.Add(-continuoushaltTime);
                        conthalt_start_latlng = lastLatitude + "," + lastLongitude;
                        conthalt_end = toDate;
                    }
                    continuoushaltTime = new TimeSpan(0);
                }
                lastLatitude = currentLatitude;
                lastLongitude = currentLongitude;

                lastTimestamp = currentTimestamp;
            }
            if (what.Equals("BOTH"))
                retObj[2] = haltTime + idleTime;		// practically this is what will be chosen.
            else if (what.Equals("IDLE"))
                retObj[2] = idleTime;
            else
                retObj[2] = haltTime;

            TimeSpan max = new TimeSpan(0);
            int max_index = 0;
            for (int i = 0; i < maxhaltTime_List.Count; i++)
            {
                if (maxhaltTime_List[i] > max)
                {
                    max = maxhaltTime_List[i];
                    max_index = i;
                }
            }
            if (max > maxhaltTime)
            {
                retObj[3] = max;
                retObj[4] = conthalt_start_List[max_index];
                retObj[5] = conthalt_end_List[max_index];
                retObj[6] = conthalt_start_latlng_List[max_index];
            }
            else
            {
                retObj[3] = maxhaltTime;
                retObj[4] = conthalt_start;
                retObj[5] = conthalt_end;
                retObj[6] = conthalt_start_latlng;
            }
            return (retObj);
        }

