        public void MetroCloseTrip(string tripId)
        {
            DataTable tripInvoiceStatus = dbx.MetroTripSheetInvoiceStatusData(tripId);
            int count = 0;
            if (tripInvoiceStatus.Rows.Count > 0)
            {
                for (int j = 0; j < tripInvoiceStatus.Rows.Count; j++)
                {
                    DataRow rows = tripInvoiceStatus.Rows[j];
                    if (rows["Delivery_Status"].ToString() == "Pending")
                    {
                        count = count + 1;
                    }
                }
            }
            if (count == 0)
            {
                dbx.MetroCloseTripByDriver(tripId);
            }
        }
