        public Object[] GetLatLngArrayBwnTime(Object[] values, DateTime start, DateTime end)
        {
            ArrayList list = new ArrayList();
            for (int i = 0; i < values.Length; i++)
            {
                DateTime time = DateTime.Parse((((Object[])values[i])[2]).ToString());
                if (time >= start)
                {
                    if (time <= end)
                    {
                        list.Add(((Object[])values[i]));
                    }
                    else
                    {
                        break;
                    }
                }
            }
            return list.ToArray();
        }
        public TimeSpan GetRunTimeFromOnOff(string vehicle, Object[] values, DateTime start, DateTime end)
        {
            if (values.Length > 0)
            {
                try
                {
                    start = DateTime.Parse((((Object[])values[0])[2]).ToString());
                    end = DateTime.Parse((((Object[])values[values.Length - 1])[2]).ToString());
                }
                catch { }
            }
            List<string> trips = GetOnOffTripsTime(vehicle, values, start, end);
            TimeSpan runtime = new TimeSpan(0, 0, 0);
            foreach (string trip in trips)
            {
                string[] temp = trip.Split(',');
                runtime += (Convert.ToDateTime(temp[4]) - Convert.ToDateTime(temp[3]));
            }
            return runtime;
        }
        public List<string> GetOnOffTripsTime(string vehicle, Object[] values, DateTime start, DateTime end, string sessionId = "")
        {
            //Added By Tusar on 19/07/2022 For Nokia Solutions

            bool tripStartByRFIDTag = false;

            try
            {
                int groupid = dbx.getGroupIdByVehicleid(vehicle);
                DataTable dtAccountGroupsDetails = dbx.GetAccountGroupsDetailsByGroupId(groupid);

                if (dtAccountGroupsDetails != null)
                {
                    if (dtAccountGroupsDetails.Rows.Count > 0)
                    {
                        if (dtAccountGroupsDetails.Rows[0]["LanguageSetting"].ToString() == "RFID")
                            tripStartByRFIDTag = true;
                    }
                }
            }
            catch (Exception ex)
            {

            }




            if (values == null)
            {
                values = dbx.getLatLong(vehicle, start.ToString("yyyy-MM-dd HH:mm:ss"), end.ToString("yyyy-MM-dd HH:mm:ss"));
            }
            List<string> trips = new List<string>();
            List<int> RpmNoLst = new List<int>();
            //DataTable dtCanConfig = dbx.GetVehicleCANConfig(vehicle);
            //int Is_CAN_Speed = 1;
            //int Is_CAN_RPM = 1;
            //if (dtCanConfig.Rows.Count > 0)
            //{
            //    Is_CAN_Speed = Convert.ToInt32(dtCanConfig.Rows[0]["Speed"].ToString());
            //    Is_CAN_RPM = Convert.ToInt32(dtCanConfig.Rows[0]["RPM"].ToString());
            //}
            if (true)
            {
                bool considerSpeed = false;
                int speedcount = 0;
                int rpmcount = 0;
                //string sessionid = dbx.GetSessionIdByVehicleId(vehicle);//Added by suvarna on 12/1/2021 to split trips based on shortrestduration threshold
                //string accname = dbx.GetAccountName(sessionid);
                // Object[] keyParams = dbx.getVehicleTripParams(sessionid);
                // int shortRestDuration = Convert.ToInt32(((Object[])keyParams[0])[1]);
                // shortRestDuration = shortRestDuration / 60;
                // if (accname.ToLower().Contains("shell"))
                //     shortRestDuration = 5;
                double CANSpeed_Calibration_Val = dbx.getCANSpeedRatio(vehicle);
                Object[] keyParams;
                //Modified by suvarna on 28/4/2021 to get sessionid by vehicleid for driving hours report or non commit(daily summary) reports 
                if (sessionId == null || sessionId == "")
                {
                    int groupid = dbx.getGroupIdByVehicleid(vehicle);
                    sessionId = dbx.getSessionIdByGroupid(groupid);
                }
                keyParams = dbx.getVehicleTripParams(sessionId);
                int shortRest = 5;
                //int deltaGap = 15;
                int deltaGap = 50; //This we are changing becuase for Shell devices datagap is there for one week. We will keep this for one-two months and then we will revert to the original value;
                if (CANSpeed_Calibration_Val == 0)
                {
                    considerSpeed = true;
                    int shortRestDuration2 = Convert.ToInt32(((Object[])keyParams[0])[11]);
                    shortRest = deltaGap = (shortRestDuration2 - 10 * 60) / 60;//To split the trips according to shortrestduration2   
                }
                else
                {
                    for (int i = 0; i < values.Length; i++)
                    {
                        int stop = Convert.ToInt16(((Object[])values[i])[3]);
                        double speed = Convert.ToDouble(((Object[])values[i])[5]);
                        double LAC = Convert.ToDouble(((Object[])values[i])[7]);
                        double RPM = Convert.ToDouble(((Object[])values[i])[8]);
                        if ((LAC != 0 && stop == 0) || (LAC == 0 && stop == 0))
                        {
                            if (speed > 5 || (speed > 1 && RPM > 0))
                                speedcount++;
                            if (RPM > 0)
                                rpmcount++;
                        }
                    }
                    if (speedcount > 0)
                    {
                        if (rpmcount < 0.5 * speedcount)
                        {
                            considerSpeed = true;
                        }
                    }
                }


                bool onTrip = false;
                DateTime tripStarttime = start;
                double speed_low_min = 0;
                double RPM_low_min = 0;
                bool IsValidTrip_GPS_speed = false;
                DateTime nextDriverTagIn = DateTime.Now;
                bool nextDriverTagInFound = false;
                int rpm_count = 0;
                DateTime prevTime = DateTime.MinValue;


                if (tripStartByRFIDTag == false)
                {
                    for (int i = 0; i < values.Length; i++)
                    {
                        int stop = Convert.ToInt16(((Object[])values[i])[3]);
                        double speed = Convert.ToDouble(((Object[])values[i])[5]);
                        double LAC = Convert.ToDouble(((Object[])values[i])[7]);
                        double RPM = Convert.ToDouble(((Object[])values[i])[8]);
                        DateTime time = DateTime.Parse((((Object[])values[i])[2]).ToString());
                        double delta_time = 0;
                        if (i != values.Length - 1)
                        {
                            DateTime nxt_time = DateTime.Parse((((Object[])values[i + 1])[2]).ToString());
                            delta_time = (nxt_time - time).TotalMinutes;
                        }
                        if (speed < 5)//CD event got captured in GJ27 X 6545 VIPL Guj vehicle due to speed value hance modified by suvarna on 5/8/2021
                        {
                            speed_low_min += delta_time;
                        }
                        else
                            speed_low_min = 0;

                        if (RPM == 0 && LAC != 0)
                        {
                            RPM_low_min += delta_time;
                        }
                        else if (LAC != 0)
                            RPM_low_min = 0;

                        if (onTrip == true && RPM > 100)
                        {
                            rpm_count++;
                        }
                        //RPM and LAC are commented out. problem will come when vehhicle is moving when stop bit is 1. for shell we checked and seems like commenting out ths will not affect the tripend time calculation
                        if (((RPM == 0 && LAC != 0 && speed < 2 && RPM_low_min > 2 && considerSpeed == false) ||
                            (speed_low_min > shortRest && speed < 1 && considerSpeed == true) ||
                            (delta_time > deltaGap) ||
                            (stop == 1 && RPM < 100 && LAC != 0 && considerSpeed == false) ||
                            (stop == 1 && speed < 2 && RPM == 0) ||
                            (nextDriverTagInFound == true && nextDriverTagIn <= time)) && i > 0 && onTrip == true)
                        {
                            if (speed_low_min > shortRest && speed < 1 && considerSpeed == true)
                            {
                                if (IsValidTrip_GPS_speed || (nextDriverTagInFound == true && nextDriverTagIn <= time))
                                {
                                    trips.Add(tripStarttime.ToString("yyyy-MM-dd HH:mm:ss") + "," + time.ToString("yyyy-MM-dd HH:mm:ss"));
                                    RpmNoLst.Add(rpm_count);
                                    rpm_count = 0;
                                }
                            }
                            else
                            {
                                trips.Add(tripStarttime.ToString("yyyy-MM-dd HH:mm:ss") + "," + time.ToString("yyyy-MM-dd HH:mm:ss"));
                                RpmNoLst.Add(rpm_count);
                                rpm_count = 0;
                            }
                            onTrip = false;
                            IsValidTrip_GPS_speed = false;
                            nextDriverTagInFound = false;
                        }
                        else if (((RPM > 0 && LAC != 0) || (LAC == 0 && RPM == 0 && speed > 5) || (speed > 1 && considerSpeed)) && stop == 0 && onTrip == false)
                        {
                            onTrip = true;
                            // In the case of SHELL in Drivinng Hours report the END location and the next start location is not the smae in some instances. As the vehicle has started to move
                            // it is best to pick up the previous row as the START. This will happen for CAN and RPM tap cases only
                            if (considerSpeed)    // all non CAN and non SHELL 
                                tripStarttime = time;
                            else
                                if (prevTime == DateTime.MinValue)  // if prevTime is not initialised then do not take it
                                tripStarttime = time;    // SHELL or other customers with CAN data or RPM tapping
                            else if ((time - prevTime).TotalMinutes > 8)  // take care of data gaps
                                tripStarttime = time;
                            else
                                tripStarttime = prevTime;
                            IsValidTrip_GPS_speed = false;
                            DataTable dtDriverTag = dbx.GetNextDriverTagin(vehicle, time.AddMinutes(2));
                            if (dtDriverTag.Rows.Count > 0)
                            {
                                nextDriverTagIn = Convert.ToDateTime(dtDriverTag.Rows[0]["TimeStamp"].ToString());
                                nextDriverTagInFound = true;
                            }
                            else
                            {
                                nextDriverTagInFound = false;
                            }
                        }
                        if (speed > 5 && considerSpeed && onTrip == true)
                        {
                            IsValidTrip_GPS_speed = true;
                        }
                        if (i == values.Length - 1 && onTrip == true)
                        {
                            trips.Add(tripStarttime.ToString("yyyy-MM-dd HH:mm:ss") + "," + end.ToString("yyyy-MM-dd HH:mm:ss"));
                            RpmNoLst.Add(rpm_count);
                            rpm_count = 0;
                        }
                        prevTime = time; // store this to be used in START TRIP for SHELL
                    }
                }
                else
                {
                    DataTable dtGetDriverTaginOut = new DataTable();
                    DataTable dttripsummary = new DataTable();
                    string previousdate = Convert.ToDateTime(start).AddDays(-1).ToString("yyyy-MM-dd");
                    dtGetDriverTaginOut = dbx.GetDriverTagInOutReport("", Convert.ToDateTime(start.ToString("yyyy-MM-dd HH:mm:ss")), Convert.ToDateTime(end.ToString("yyyy-MM-dd HH:mm:ss")), vehicle);
                    if (dtGetDriverTaginOut.Rows.Count > 0)
                    {
                        dttripsummary = dbx.GettripsummaryReport(dtGetDriverTaginOut.Rows[0]["DriverId"].ToString(), previousdate, vehicle);
                        if (dttripsummary.Rows.Count > 0)
                        {
                            if (dtGetDriverTaginOut.Rows[0]["TimeStamp"].ToString() == dttripsummary.Rows[0]["trip_endtime"].ToString())
                            {
                                if (dtGetDriverTaginOut.Rows.Count > 0)
                                {
                                    dtGetDriverTaginOut.Rows.RemoveAt(0);
                                }
                            }

                        }
                    }
                    if (dtGetDriverTaginOut != null)
                    {
                        if (dtGetDriverTaginOut.Rows.Count > 0)
                        {
                            for (int i = 0; i < dtGetDriverTaginOut.Rows.Count; i++)
                            {
                                int tripcount = trips.Count;
                                String currenttrip = "";
                                if (tripcount > 0)
                                {
                                    String[] alltrips = trips[tripcount - 1].Split(',');
                                    currenttrip = alltrips[1];
                                }
                                if (i != (dtGetDriverTaginOut.Rows.Count - 1))
                                {
                                    DateTime swipein = Convert.ToDateTime(dtGetDriverTaginOut.Rows[i]["TimeStamp"]);
                                    DateTime swipeout = Convert.ToDateTime(dtGetDriverTaginOut.Rows[i + 1]["TimeStamp"]);
                                    DateTime buffertime = end.AddHours(3);
                                    DateTime ForceTripClose = Convert.ToDateTime(dtGetDriverTaginOut.Rows[i]["TimeStamp"]);
                                    DateTime dtForceTripClose = ForceTripClose.AddHours(3);
                                    DataTable dtGetOddTripTagOut = new DataTable();

                                    dtGetOddTripTagOut = dbx.dtGetOddTripTagOut(Convert.ToDateTime(end.ToString("yyyy-MM-dd HH:mm:ss")), Convert.ToDateTime(buffertime.ToString("yyyy-MM-dd HH:mm:ss")), vehicle, dtGetDriverTaginOut.Rows[0]["DriverId"].ToString());
                                    if ((swipeout - swipein).TotalHours > 3)
                                    {
                                        if (trips.Count > 0)
                                        {
                                            if (currenttrip != dtGetDriverTaginOut.Rows[i]["TimeStamp"].ToString())
                                            {
                                                trips.Add(DateTime.Parse(dtGetDriverTaginOut.Rows[i]["TimeStamp"].ToString()).ToString() + "," + Convert.ToDateTime(dtForceTripClose.ToString("yyyy-MM-dd HH:mm:ss")));
                                                RpmNoLst.Add(rpm_count);
                                                rpm_count = 0;
                                            }
                                        }
                                        else
                                        {
                                            if (currenttrip != dtGetDriverTaginOut.Rows[i]["TimeStamp"].ToString())
                                            {
                                                trips.Add(DateTime.Parse(dtGetDriverTaginOut.Rows[i]["TimeStamp"].ToString()).ToString() + "," + Convert.ToDateTime(dtForceTripClose.ToString("yyyy-MM-dd HH:mm:ss")));
                                                RpmNoLst.Add(rpm_count);
                                                rpm_count = 0;
                                            }
                                        }
                                    }
                                    else
                                    {
                                        if (!string.IsNullOrEmpty(dtGetDriverTaginOut.Rows[i + 1]["TimeStamp"].ToString()))
                                        {
                                            if (trips.Count > 0)
                                            {

                                                if (currenttrip != dtGetDriverTaginOut.Rows[i]["TimeStamp"].ToString())
                                                {
                                                    trips.Add(DateTime.Parse(dtGetDriverTaginOut.Rows[i]["TimeStamp"].ToString()).ToString() + "," + DateTime.Parse(dtGetDriverTaginOut.Rows[i + 1]["TimeStamp"].ToString()));
                                                    RpmNoLst.Add(rpm_count);
                                                    rpm_count = 0;
                                                }
                                                //else
                                                //{
                                                //    trips.Add(DateTime.Parse(dtGetDriverTaginOut.Rows[i]["TimeStamp"].ToString()).ToString() + "," + DateTime.Parse(dtGetDriverTaginOut.Rows[i + 1]["TimeStamp"].ToString()));
                                                //}
                                            }
                                            else
                                            {
                                                trips.Add(DateTime.Parse(dtGetDriverTaginOut.Rows[i]["TimeStamp"].ToString()).ToString() + "," + DateTime.Parse(dtGetDriverTaginOut.Rows[i + 1]["TimeStamp"].ToString()));
                                                RpmNoLst.Add(rpm_count);
                                                rpm_count = 0;
                                            }
                                        }
                                        else
                                        {
                                            dtGetOddTripTagOut = dbx.dtGetOddTripTagOut(Convert.ToDateTime(end.ToString("yyyy-MM-dd HH:mm:ss")), Convert.ToDateTime(buffertime.ToString("yyyy-MM-dd HH:mm:ss")), vehicle, dtGetDriverTaginOut.Rows[0]["DriverId"].ToString());
                                            if (dtGetOddTripTagOut.Rows.Count > 0)
                                            {
                                                DateTime lastswipw = Convert.ToDateTime(dtGetDriverTaginOut.Rows[i]["TimeStamp"]);
                                                DateTime after12swipe = Convert.ToDateTime(dtGetOddTripTagOut.Rows[0]["TimeStamp"]);
                                                if ((after12swipe - lastswipw).TotalHours > 3)
                                                {
                                                    trips.Add(DateTime.Parse(dtGetDriverTaginOut.Rows[i]["TimeStamp"].ToString()).ToString() + "," + Convert.ToDateTime(dtForceTripClose.ToString("yyyy-MM-dd HH:mm:ss")));
                                                    RpmNoLst.Add(rpm_count);
                                                    rpm_count = 0;
                                                }
                                                else
                                                {
                                                    trips.Add(DateTime.Parse(dtGetDriverTaginOut.Rows[i]["TimeStamp"].ToString()).ToString() + "," + DateTime.Parse(dtGetOddTripTagOut.Rows[0]["TimeStamp"].ToString()).ToString());
                                                    RpmNoLst.Add(rpm_count);
                                                    rpm_count = 0;
                                                }
                                            }
                                            else
                                            {
                                                trips.Add(DateTime.Parse(dtGetDriverTaginOut.Rows[i]["TimeStamp"].ToString()).ToString() + "," + Convert.ToDateTime(dtForceTripClose.ToString("yyyy-MM-dd HH:mm:ss")));
                                                RpmNoLst.Add(rpm_count);
                                                rpm_count = 0;
                                            }
                                        }
                                    }
                                }
                                else
                                {
                                    if (!string.IsNullOrEmpty(dtGetDriverTaginOut.Rows[i]["TimeStamp"].ToString()))
                                    {
                                        DataRow dtrow = dtGetDriverTaginOut.NewRow();
                                        dtGetDriverTaginOut.Rows.Add(dtrow);
                                        DateTime buffertime = end.AddHours(3);
                                        DateTime ForceTripClose = Convert.ToDateTime(dtGetDriverTaginOut.Rows[i]["TimeStamp"]);
                                        DateTime dtForceTripClose = ForceTripClose.AddHours(3);
                                        DataTable dtGetOddTripTagOut = new DataTable();
                                        dtGetOddTripTagOut = dbx.dtGetOddTripTagOut(Convert.ToDateTime(end.ToString("yyyy-MM-dd HH:mm:ss")), Convert.ToDateTime(buffertime.ToString("yyyy-MM-dd HH:mm:ss")), vehicle, dtGetDriverTaginOut.Rows[0]["DriverId"].ToString());
                                        if (dtGetOddTripTagOut.Rows.Count > 0)
                                        {
                                            DateTime lastswipw = Convert.ToDateTime(dtGetDriverTaginOut.Rows[i]["TimeStamp"]);
                                            DateTime after12swipe = Convert.ToDateTime(dtGetOddTripTagOut.Rows[0]["TimeStamp"]);
                                            if ((after12swipe - lastswipw).TotalHours > 3)
                                            {
                                                if (currenttrip != dtGetDriverTaginOut.Rows[i]["TimeStamp"].ToString())
                                                {
                                                    trips.Add(DateTime.Parse(dtGetDriverTaginOut.Rows[i]["TimeStamp"].ToString()).ToString() + "," + Convert.ToDateTime(dtForceTripClose.ToString("yyyy-MM-dd HH:mm:ss")));
                                                    RpmNoLst.Add(rpm_count);
                                                    rpm_count = 0;
                                                }
                                            }
                                            else
                                            {
                                                if (currenttrip != dtGetDriverTaginOut.Rows[i]["TimeStamp"].ToString())
                                                {
                                                    trips.Add(DateTime.Parse(dtGetDriverTaginOut.Rows[i]["TimeStamp"].ToString()).ToString() + "," + DateTime.Parse(dtGetOddTripTagOut.Rows[0]["TimeStamp"].ToString()).ToString());
                                                    RpmNoLst.Add(rpm_count);
                                                    rpm_count = 0;
                                                }
                                            }
                                        }
                                        else
                                        {
                                            if (currenttrip != dtGetDriverTaginOut.Rows[i]["TimeStamp"].ToString())
                                            {
                                                trips.Add(DateTime.Parse(dtGetDriverTaginOut.Rows[i]["TimeStamp"].ToString()).ToString() + "," + Convert.ToDateTime(dtForceTripClose.ToString("yyyy-MM-dd HH:mm:ss")));
                                                RpmNoLst.Add(rpm_count);
                                                rpm_count = 0;
                                            }
                                        }
                                    }

                                }
                            }
                        }
                        else
                        {
                            trips.Add(DateTime.Parse(Convert.ToDateTime(start.ToString("yyyy-MM-dd HH:mm:ss")).ToString()) + "," + Convert.ToDateTime(end.ToString("yyyy-MM-dd HH:mm:ss")));
                            RpmNoLst.Add(rpm_count);
                            rpm_count = 0;
                        }
                    }
                    //if (dtGetDriverTaginOut != null)
                    //{
                    //    int SwipeCount = dtGetDriverTaginOut.Rows.Count;
