                DateTime tripstart = Convert.ToDateTime(temp[0]);
                DateTime tripend = Convert.ToDateTime(temp[1]);
                object[] vals = GetLatLngArrayBwnTime(values, tripstart, tripend);
                object[] ret = accumulateDistance(vehicle, tripstart.ToString("yyyy-MM-dd HH:mm:ss"), tripend.ToString("yyyy-MM-dd HH:mm:ss"), null, vals, "1");
