                DateTime actualStart = tripstart;
                DateTime actualEnd = tripend;
                string runtime = "0";
                string start_latlng = "";
                string end_latlng = "";
                if (ret != null)
                {
                    distance = (double)ret[0];
                    double decDist = Math.Round(distance, 1);
                    runtime = ((TimeSpan)ret[2]).TotalSeconds.ToString();
                    if (tripStartByRFIDTag == false)
                    {
                        if (decDist >= 0)//Added >= condition- To match Shell Data gap
                        {
                            if (!string.IsNullOrEmpty(ret[5].ToString()))
                            {
                                actualStart = Convert.ToDateTime(ret[5].ToString());
                            }
                            if (!string.IsNullOrEmpty(ret[6].ToString()))
                            {
                                actualEnd = Convert.ToDateTime(ret[6].ToString());
                            }
                        }
                        else
                        {
                            if (vals.Length > 2)
                            {
                                try
                                {
                                    int lstrpm = Convert.ToInt32(((Object[])vals[vals.Length - 1])[8]);
                                    if (lstrpm > 0)
                                    {
                                        actualEnd = Convert.ToDateTime((((Object[])vals[vals.Length - 1])[2]));
                                    }
                                    else
                                    {
                                        actualEnd = Convert.ToDateTime((((Object[])vals[vals.Length - 2])[2]));
                                    }
                                }
                                catch { }

                            }
                        }
                        runtime = (actualEnd - actualStart).TotalSeconds.ToString();
                        //if (distance > 0)
                    }
