                    {
                        if (!string.IsNullOrEmpty(prev_end_latlng) && !string.IsNullOrEmpty(start_latlng))
                        {
                            double diff = computeDistance(Convert.ToDouble(prev_end_latlng.Split('|')[0]), Convert.ToDouble(prev_end_latlng.Split('|')[1]), Convert.ToDouble(start_latlng.Split('|')[0]), Convert.ToDouble(start_latlng.Split('|')[1]));
                            if (diff < 1.0)
                            {
                                start_latlng = prev_end_latlng;
                            }
                            else if (diff < 50)
                            {
                                int dist = 0;
                                if (tripStartByRFIDTag == false && distance == 0)//Added for Nokia Solutions,because if runtime is 0 and distance should be 0
                                {
                                    string googledist = getDistanceByGoogleDistanceMatrix(prev_end_latlng.Split('|')[0], prev_end_latlng.Split('|')[1], start_latlng.Split('|')[0], start_latlng.Split('|')[1]);

                                    if (!string.IsNullOrEmpty(googledist))
                                    {
                                        if (googledist != "NoData")
                                        {
                                            decimal gd = Convert.ToDecimal(googledist) / 1000;//m to km
                                            dist = Convert.ToInt32(gd);
                                        }
                                    }
                                }
                                distance = distance + dist;
                                //double time = (dist / 30.0);
                                //DateTime newActualStartTime = actualStart.AddHours(-time);
                                //if (prev_end_Time < newActualStartTime && (actualEnd - newActualStartTime).TotalHours < 3)
                                //{
                                //    actualStart = newActualStartTime;
                                //    runtime = (actualEnd - actualStart).TotalSeconds.ToString();
                                //}
                                start_latlng = prev_end_latlng;//Uncommented this line- To match Shell Data gap
                            }
                        }
                    }
                    catch { }
                    if (Math.Round(distance, 1) >= 0)//Added >= condition- To match Shell Data gap
                        prev_end_latlng = end_latlng;
                    prev_end_Time = actualEnd;
                }
                string DriverId = getdrivername(vehicle, actualStart.ToString("yyyy-MM-dd HH:mm:ss")).Split(',')[1];
                trips[i] = trips[i] + "," + DriverId + "," + actualStart.ToString("yyyy-MM-dd HH:mm:ss") + "," + actualEnd.ToString("yyyy-MM-dd HH:mm:ss") + "," + distance + "," + runtime + "," + start_latlng + "," + end_latlng;
            }
            return trips;
        }
        protected string getGooglePositionTxt(string latitude, string longitude)
        {
            // Google map API 
            String requestUrl = "http://maps.googleapis.com/maps/api/geocode/xml?latlng=" + latitude + "," + longitude + "&sensor=false";

            WebRequest request = WebRequest.Create(requestUrl);
            request.Method = "GET";
            HttpWebResponse response;
            try
            {
                response = (HttpWebResponse)request.GetResponse();
            }
            catch (Exception)
            {
                return null;
            }
            Encoding encode = System.Text.Encoding.GetEncoding("utf-8");
            // Pipe the stream to a higher level stream reader with the required encoding format. 
            StreamReader readStream = new StreamReader(response.GetResponseStream(), encode);
            Char[] read = new Char[256];
            int count;
            String outBuffer = String.Empty;
            // Read 256 charcters at a time.    
            string positionTxt = "";
            while ((count = readStream.Read(read, 0, 256)) > 0)
            {
                // Dump the 256 characters on a string and display the string onto the console.
                String str = new String(read, 0, count);
                outBuffer += str;
            }
            if (response.StatusCode != HttpStatusCode.OK)
                return positionTxt;

            string comma = "";
            XmlDocument positionXml = new XmlDocument();
            positionXml.LoadXml(outBuffer);
            string status = positionXml.SelectSingleNode("/GeocodeResponse/status/text()").Value;
            if (status != "OK")
            {
                return positionTxt;
            }
            string address = positionXml.SelectSingleNode("/GeocodeResponse/result/formatted_address/text()").Value;
            if (address != "null" && address != "")
            {
                positionTxt += comma + address;
                comma = ", ";
            }
            return positionTxt;
        }

        /// <summary>
        /// Return Map position from open.mapquestapi.com using Latitude and Longitude
        /// </summary>
        /// <param name="lat"></param>
        /// <param name="lon"></param>
        /// <returns></returns>
        protected string getOpenMapquestapiGeoCodeData(string lat, string lon)
        {

            try
            {
                float latitude = float.Parse(lat);
                float longitude = float.Parse(lon);

                var requestUri = "http://open.mapquestapi.com/nominatim/v1/reverse?format=xml&lat=" + latitude + "&lon=" + longitude;

                var request = WebRequest.Create(requestUri);
                var response = request.GetResponse();
                var xdoc = XDocument.Load(response.GetResponseStream());

                if (xdoc.Root.Value == "REQUEST_DENIEDThis API project is not authorized to use this API.")
                    return "";
                if (xdoc.Root.Value == "OVER_QUERY_LIMITYou have exceeded your daily request quota for this API.")
                    return "";
                if (xdoc.Root.Value == "OVER_QUERY_LIMITYou have exceeded your rate-limit for this API.")
                    return "";
                if (xdoc.Root.Value == "ZERO_RESULTS")
                    return "";

                float OpenLat = float.Parse(xdoc.Element("reversegeocode").Element("result").Attribute("lat").Value);
                float OpenLong = float.Parse(xdoc.Element("reversegeocode").Element("result").Attribute("lon").Value);

                float diffLat = OpenLat - latitude;
                float diffLong = OpenLong - longitude;

                if (diffLat > 0.009)
                    return "";
                if (diffLong > 0.009)
                    return "";
                if (diffLat < -0.009)
                    return "";
                if (diffLong < -0.009)
                    return "";


                var result = xdoc.Element("reversegeocode").Element("addressparts");

                if (result == null)
                    return "";

                string sPlace = string.Empty;
                string sRoad = string.Empty;

                string sCity = string.Empty;
                string sDistrict = string.Empty;
                string sState = string.Empty;
                string sCountry = string.Empty;
                string sPincode = string.Empty;

                //======Road==
                sRoad = TryGetsPlaceElementValue(result, sRoad, "road");


                //======Place=
                sPlace = TryGetsPlaceElementValue(result, sPlace, "pub");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "pharmacy");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "post_box");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "restaurant");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "dentist");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "playground");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "cinema");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "electronics");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "supermarket");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "fast_food");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "bar");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "cafe");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "mall");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "water");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "bank");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "bus_stop");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "fuel");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "police");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "park");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "school");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "university");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "college");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "footway");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "hairdresser");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "bus_station");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "fire_station");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "pedestrian");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "sports_centre");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "industrial");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "hospital");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "place_of_worship");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "hotel");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "house");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "building");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "public_building");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "house_number");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "residential");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "address29");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "address27");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "neighbourhood");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "suburb");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "town");
                sPlace = TryGetsPlaceElementValue(result, sPlace, "hamlet");


                //======City======
                sCity = TryGetsPlaceElementValue(result, sCity, "village");
                sCity = TryGetsPlaceElementValue(result, sCity, "county");
                sCity = TryGetsPlaceElementValue(result, sCity, "city");


                sDistrict = result.Element("state_district").Value;
                sState = TryGetsPlaceElementValue(result, sState, "state") == "" ? result.Element("state_district").Value : result.Element("state").Value;
                sCountry = result.Element("country").Value;
                sPincode = TryGetsPlaceElementValue(result, sPincode, "postcode");


                if (!string.IsNullOrEmpty(sCity))
                    sCity = sCity + " " + sPincode;

                string RoadPlace = string.Empty;
                RoadPlace = sRoad;
                if (string.IsNullOrEmpty(RoadPlace))
                    RoadPlace = sPlace;


                if ((!string.IsNullOrEmpty(RoadPlace)) && (!string.IsNullOrEmpty(sState)) && (!string.IsNullOrEmpty(sDistrict)))
                {
                    dbx.AddUpdateGeoCode(sRoad.Replace("'", "''"), sPlace.Replace("'", "''"), sCity, sDistrict, sState, latitude, longitude);
                    return sRoad.Replace("'", "''") + ", " + sPlace.Replace("'", "''") + ", " + sCity + ", " + sDistrict + ", " + sState;
                }

                return "";
            }
            catch
            {
                dbx.close();
                return "";
            }
            finally { dbx.close(); }
        }

        private string TryGetsPlaceElementValue(XElement parentEl, string sData, string elementName, string defaultValue = "")
        {
            string Rvalue = String.Empty;
            var foundEl = parentEl.Element(elementName);
            if (foundEl != null)
            {
                Rvalue = foundEl.Value;
            }
            else
            {
                Rvalue = defaultValue;
            }

            if ((!string.IsNullOrEmpty(sData)) && (!string.IsNullOrEmpty(Rvalue)))
                Rvalue = sData + "," + Rvalue;

            if (Rvalue == "")
                Rvalue = sData;

            return Rvalue;
        }
        /// <summary>
        /// Return Map position from google using Latitude and Longitude
        /// </summary>
        /// <param name="lat"></param>
        /// <param name="lon"></param>
        /// <returns></returns>
        protected string getGoogleGeoCodeData(string lat, string lon)
        {
            try
            {
                float latitude = float.Parse(lat);
                float longitude = float.Parse(lon);

                var requestUri = "https://maps.googleapis.com/maps/api/geocode/xml?latlng=" + latitude + "," + longitude + "&client=gme-senseltelematics";
                requestUri = Sign(requestUri);
                var request = WebRequest.Create(requestUri);
                var response = request.GetResponse();
                var xdoc = XDocument.Load(response.GetResponseStream());

                if (xdoc.Root.Value == "REQUEST_DENIEDThis API project is not authorized to use this API.")
                    return "";
                if (xdoc.Root.Value == "OVER_QUERY_LIMITYou have exceeded your daily request quota for this API.")
                    return "";
                if (xdoc.Root.Value == "OVER_QUERY_LIMITYou have exceeded your rate-limit for this API.")
                    return "";
                if (xdoc.Root.Value == "ZERO_RESULTS")
                    return "";

                var result = xdoc.Element("GeocodeResponse").Element("result");

                if (result == null)
                    return "";

                string sStreetNumber = string.Empty;
                string sRoute = string.Empty;
                string sNeighborhood = string.Empty;
                string sSublocality = string.Empty;



                string sCity = string.Empty;
                string sDistrict = string.Empty;
                string sState = string.Empty;
                string sCountry = string.Empty;
                string sPincode = string.Empty;

                foreach (var s in xdoc.Element("GeocodeResponse").Descendants("result"))
                {
                    foreach (System.Xml.Linq.XElement element in s.Descendants("address_component"))
                    {
                        string strElement = element.ToString();

                        if (strElement.IndexOf("<type>street_number</type>") != -1)
                        {
                            sStreetNumber = element.Element("long_name").Value.Replace("Unnamed Road", "");
                        }
                        else if (strElement.IndexOf("<type>route</type>") != -1)
                        {
                            sRoute = element.Element("long_name").Value.Replace("Unnamed Road", "");
                        }
                        else if ((strElement.IndexOf("<type>neighborhood</type>") != -1) && (strElement.IndexOf("<type>political</type>") != -1))
                        {
                            sNeighborhood = element.Element("long_name").Value.Replace("Unnamed Road", "");
                        }
                        else if ((strElement.IndexOf("<type>sublocality</type>") != -1) && (strElement.IndexOf("<type>political</type>") != -1))
                        {
                            if (!string.IsNullOrEmpty(sSublocality))
                                sSublocality = sSublocality + ", " + element.Element("long_name").Value.Replace("Unnamed Road", "");
                            else
                                sSublocality = element.Element("long_name").Value.Replace("Unnamed Road", "");
                        }
                        else if ((strElement.IndexOf("<type>locality</type>") != -1) && (strElement.IndexOf("<type>political</type>") != -1)) //City
                        {
                            sCity = element.Element("long_name").Value.Replace("Unnamed Road", "");
                        }
                        else if ((strElement.IndexOf("<type>administrative_area_level_3</type>") != -1) && (strElement.IndexOf("<type>political</type>") != -1)) //District
                        {
                            sDistrict = element.Element("long_name").Value.Replace("Unnamed Road", "");
                        }
                        else if ((strElement.IndexOf("<type>administrative_area_level_2</type>") != -1) && (strElement.IndexOf("<type>political</type>") != -1)) //District
                        {
                            sDistrict = element.Element("long_name").Value.Replace("Unnamed Road", "");
                        }
                        else if ((strElement.IndexOf("<type>administrative_area_level_1</type>") != -1) && (strElement.IndexOf("<type>political</type>") != -1)) //State
                        {
                            sState = element.Element("long_name").Value.Replace("Unnamed Road", "");
                        }
                        else if ((strElement.IndexOf("<type>country</type>") != -1) && (strElement.IndexOf("<type>political</type>") != -1)) //Country
                        {
                            sCountry = element.Element("long_name").Value.Replace("Unnamed Road", "");
                        }
                        else if (strElement.IndexOf("<type>postal_code</type>") != -1)   //PinCode
                        {
                            sPincode = element.Element("long_name").Value.Replace("Unnamed Road", "");
                            if (!string.IsNullOrEmpty(sPincode))
                                sPincode = " - " + sPincode;
                        }
                    }
                }

                string sPlace = string.Empty;
                string sRoad = string.Empty;

                if ((!string.IsNullOrEmpty(sStreetNumber)) && (!string.IsNullOrEmpty(sRoute)))
                    sRoad = sStreetNumber + ", " + sRoute;
                if ((!string.IsNullOrEmpty(sStreetNumber)) && (string.IsNullOrEmpty(sRoute)))
                    sRoad = sStreetNumber;
                if ((string.IsNullOrEmpty(sStreetNumber)) && (!string.IsNullOrEmpty(sRoute)))
                    sRoad = sRoute;
                if ((string.IsNullOrEmpty(sStreetNumber)) && (string.IsNullOrEmpty(sRoute)))
                    sRoad = "";

                if ((!string.IsNullOrEmpty(sNeighborhood)) && (!string.IsNullOrEmpty(sSublocality)))
                    sPlace = sNeighborhood + ", " + sSublocality;
                if ((!string.IsNullOrEmpty(sNeighborhood)) && (string.IsNullOrEmpty(sSublocality)))
                    sPlace = sStreetNumber;
                if ((string.IsNullOrEmpty(sNeighborhood)) && (!string.IsNullOrEmpty(sSublocality)))
                    sPlace = sSublocality;
                if ((string.IsNullOrEmpty(sNeighborhood)) && (string.IsNullOrEmpty(sSublocality)))
                    sPlace = "";

                if (!string.IsNullOrEmpty(sCity))
                    sCity = sCity + sPincode;

                string RoadPlace = string.Empty;
                RoadPlace = sRoad;
                if (string.IsNullOrEmpty(RoadPlace))
                    RoadPlace = sPlace;

                if (string.IsNullOrEmpty(RoadPlace))
                {
                    string rs = result.Element("formatted_address").Value;
                    string[] words = rs.Split(',');
                    RoadPlace = words[0].Replace("Unnamed Road", "");
                    sPlace = RoadPlace;
                }
                dbx.insertMapApiLog("Google", "Reverse Geocoding");
                if ((!string.IsNullOrEmpty(RoadPlace)) && (!string.IsNullOrEmpty(sState)) && (!string.IsNullOrEmpty(sDistrict)))
                {
                    AddUpdateGeoCode(sRoad.Replace("'", ""), sPlace.Replace("'", ""), sCity, sDistrict, sState, latitude, longitude);
                    return sRoad.Replace("'", "") + ", " + sPlace.Replace("'", "") + ", " + sCity + ", " + sDistrict + ", " + sState;
                }
                else if ((!string.IsNullOrEmpty(sCity)) && (!string.IsNullOrEmpty(sState)) && (!string.IsNullOrEmpty(sDistrict)))
                {
                    AddUpdateGeoCode(sRoad.Replace("'", ""), sPlace.Replace("'", ""), sCity, sDistrict, sState, latitude, longitude);
                    return (sRoad.Replace("'", "") + ", " + sPlace.Replace("'", "") + ", " + sCity + ", " + sDistrict + ", " + sState).Replace(",,", ",");
                }
                else if ((!string.IsNullOrEmpty(sState)) && (!string.IsNullOrEmpty(sDistrict)))
                {
                    AddUpdateGeoCode(sRoad.Replace("'", ""), sPlace.Replace("'", ""), sCity, sDistrict, sState, latitude, longitude);
                    return (sRoad.Replace("'", "") + ", " + sPlace.Replace("'", "") + ", " + sCity + ", " + sDistrict + ", " + sState).Replace(",,", ",");
                }
                else if ((!string.IsNullOrEmpty(RoadPlace)) || (!string.IsNullOrEmpty(sCity)) || (!string.IsNullOrEmpty(sState)) || (!string.IsNullOrEmpty(sDistrict)))
                {
                    return (sRoad.Replace("'", "") + ", " + sPlace.Replace("'", "") + ", " + sCity + ", " + sDistrict + ", " + sState).Replace(",,", ",");
                }

                return "";
            }
            catch
            {
                dbx.close();
                return "";
            }
            finally { dbx.close(); }
        }
