        public static string Sign(string url)
        {
            string keyString = "lI29kiNoHOxFvWf6-DDWGZ5RAo0=";

            ASCIIEncoding encoding = new ASCIIEncoding();

            // converting key to bytes will throw an exception, need to replace '-' and '_' characters first.
            string usablePrivateKey = keyString.Replace("-", "+").Replace("_", "/");
            byte[] privateKeyBytes = Convert.FromBase64String(usablePrivateKey);

            Uri uri = new Uri(url);
            byte[] encodedPathAndQueryBytes = encoding.GetBytes(uri.LocalPath + uri.Query);

            // compute the hash
            HMACSHA1 algorithm = new HMACSHA1(privateKeyBytes);
            byte[] hash = algorithm.ComputeHash(encodedPathAndQueryBytes);

            // convert the bytes to string and make url-safe by replacing '+' and '/' characters
            string signature = Convert.ToBase64String(hash).Replace("+", "-").Replace("/", "_");

            // Add the signature to the existing URI.
            return uri.Scheme + "://" + uri.Host + uri.LocalPath + uri.Query + "&signature=" + signature;
        }

        private string computeSpanAjax(Object[] values, int index, string latLong)
        {
            float minVal = 180;
            float maxVal = -180;
            float val;
            for (int i = 0; i < values.Length; i++)
            {
                val = Convert.ToSingle(((Object[])values[i])[index]);
                if (val < minVal)
                {
                    minVal = val;
                }
                if (val > maxVal)
                {
                    maxVal = val;
                }
            }
            string maxMinVal = maxVal.ToString() + "," + minVal.ToString();
            return maxMinVal;
        }

        public string writeZoomAjax(Object[] values, int latIndex, int longIndex)
        {
            float defaultZoom = 12.0F;
            float defaultSpan = 2.5F;
            //float defaultZoom = 5.0F;  V1.0 Zoom Setting
            //float defaultSpan = 2.5F;  V1.0 Zoom Setting

            string maxMinLat = computeSpanAjax(values, latIndex, "Lat");//retuns maxLat,minLat
            string[] maxMinLatLong = maxMinLat.Split(',');
            float maxLat = Convert.ToSingle(maxMinLatLong[0]);
            float minLat = Convert.ToSingle(maxMinLatLong[1]);
            string maxMinLong = computeSpanAjax(values, longIndex, "Long");
            maxMinLatLong = maxMinLong.Split(',');
            float maxLong = Convert.ToSingle(maxMinLatLong[0]);
            float minLong = Convert.ToSingle(maxMinLatLong[1]);
            float latSpan = maxLat - minLat;
            float longSpan = maxLong - minLong;
            //Response.Write("var latspan = " + latSpan + ";\n");			
            //Response.Write("var longspan = " + longSpan + ";\n");	
            float span = latSpan;
            if (longSpan > span)
            {
                span = longSpan;
            }
            float extraZoom = (float)Math.Max(Math.Log(span / defaultSpan, 2), -12);
            //float extraZoom = (float)Math.Max(Math.Log(span/defaultSpan, 2), -5); V 1.0 setting
            //Response.Write("var extraZoom = " + extraZoom + ";\n");
            float zoom = defaultZoom + extraZoom;
            //float zoom = defaultZoom - extraZoom; V1.0 setting
            //Response.Write("var zoom = " + Math.Ceiling(zoom) + ";\n");
            //Response.Write("var zoom = " + Math.Truncate(zoom) + ";\n"); V1.0 setting
            return (maxLat.ToString() + "#" + minLat.ToString() + "#" + maxLong.ToString() + "#" +
                   minLong.ToString() + "#" + latSpan.ToString() + "#" + longSpan.ToString()
                   + "#" + extraZoom.ToString() + "#" + zoom.ToString());
        }

