        public string getOMQPositionTxt(string latitude, string longitude)
        {
            //return "<resultset type='reverseGeocode'><result num='1'><road name='2nd Cross Road' routeNo='null' alternateName='null'/><fow name='null'/><state name='Karnataka'/><city name='Bangalore'/><locality name='AECS Layout'/><district name='Bangalore'/></result></resultset>";
            //OLD OLD REVERSE GEO CODING API
            //String requestUrl = "http://locator.mapmyindia.com/reverseGeocode/x=" + longitude + "&y=" + latitude + "&type=WGS84";
            // OLD REVERSE GEOCODING API
            //String requestUrl = "http://senseltelematics.com/Handlers/ReverseMappingRedirect.ashx?mmiAPI/reverseGeocode/x=" + longitude + "&y=" + latitude + "&key=455b3696b64aa2096ec3d831649e4e1a";
            //Latest GeoCoding API - Oct 2011
            String requestUrl = "http://open.mapquestapi.com/nominatim/v1/reverse?format=xml&lat=" + latitude + "&lon=" + longitude;
            //String requestUrl = "http://apis.mapmyindia.com/v2.0/reversegeocode/x=" + longitude + "&y=" + latitude + "&type=WGS84&key=fc0d0e8165990568bf28641dd1e0fff7";
            //String reverseMappingUrl = System.Web.Configuration.WebConfigurationManager.AppSettings["reverseMappingUrl"];
            //if (reverseMappingUrl != null)
            //{
            //requestUrl = reverseMappingUrl + "?mmiAPI/reverseGeocodeBeta/x=" + longitude + "&y=" + latitude + "&type=WGS84" + "&key=455b3696b64aa2096ec3d831649e4e1a";
            //requestUrl = reverseMappingUrl + "?v2.0/reversegeocode/x=" + longitude + "&y=" + latitude + "&type=WGS84&key=fc0d0e8165990568bf28641dd1e0fff7";
            //}
            WebRequest request = WebRequest.Create(requestUrl);
            request.Method = "GET";
            HttpWebResponse response;
            try
            {
                response = (HttpWebResponse)request.GetResponse();
            }
            catch (Exception)
            {
                return null;
            }
            Encoding encode = System.Text.Encoding.GetEncoding("utf-8");
            // Pipe the stream to a higher level stream reader with the required encoding format. 
            StreamReader readStream = new StreamReader(response.GetResponseStream(), encode);
            Char[] read = new Char[256];
            int count;
            String outBuffer = String.Empty;
            string positionTxt = "";
            //StringBuilder outBuffer = new StringBuilder();
            // Read 256 charcters at a time.    
            while ((count = readStream.Read(read, 0, 256)) > 0)
            {
                // Dump the 256 characters on a string and display the string onto the console.
                String str = new String(read, 0, count);
                outBuffer += str;
            }

            // 
            // If there is some error in reverse MMI result then return empty position text
            //
            if (response.StatusCode != HttpStatusCode.OK || String.IsNullOrEmpty(outBuffer))
                return positionTxt;
            //
            // Another possibility is that there is some ERROR in the reverseMapping Handler so try and work around that issue
            //

            int index = outBuffer.IndexOf("<?x");
            if (index < 0) // return empty positionTxt
                return positionTxt;
            else
                if (index > 0)  // remove all chars till the XML string
                outBuffer = outBuffer.Remove(0, index);
            string comma = "";
            XmlDocument positionXml = new XmlDocument();
            positionXml.LoadXml(outBuffer.ToString());

            XmlNode industrialNode = positionXml.SelectSingleNode("/reversegeocode/addressparts/industrial");
            if (industrialNode != null)
            {
                string industrial = positionXml.SelectSingleNode("./reversegeocode/addressparts/industrial/text()").Value;
                if (industrial != "null" && industrial != "")
                    if (industrial != "")
                    {
                        positionTxt += comma + industrial;
                        comma = ", ";
                    }
            }
            XmlNode roadNode = positionXml.SelectSingleNode("/reversegeocode/addressparts/road");
            if (roadNode != null)
            {
                string road = positionXml.SelectSingleNode("./reversegeocode/addressparts/road/text()").Value;
                if (road != "null" && road != "")
                    if (road != "")
                    {
                        positionTxt += comma + road;
                        comma = ", ";
                    }
            }
            XmlNode suburbNode = positionXml.SelectSingleNode("./reversegeocode/addressparts/suburb");
            if (suburbNode != null)
            {
                string suburb = positionXml.SelectSingleNode("./reversegeocode/addressparts/suburb/text()").Value;
                if (suburb != "null" && suburb != "")
                {
                    positionTxt += comma + suburb;
                    comma = ", ";
                }
            }
            XmlNode cityNode = positionXml.SelectSingleNode("./reversegeocode/addressparts/city");
            if (cityNode != null)
            {
                string city = positionXml.SelectSingleNode("./reversegeocode/addressparts/city/text()").Value;
                if (city != "null" && city != "")
                {
                    positionTxt += comma + city;
                    comma = ", ";
                }
            }
            /*           
            XmlNode cityNode = positionXml.SelectSingleNode("/resultset/result/city_town_village/@name");
            string city = String.Empty;
            if (cityNode != null)
            {
	            city = positionXml.SelectSingleNode("/resultset/result/city_town_village/@name").Value;
	            if (city != "null" && city != "")
	            {
	            	positionTxt += comma + city;
	            	comma = ", ";
	            }
            } */
            // Don't add district and State for Bangalore!, to make output small
            // Can add other major cities to skip if required

            XmlNode districtNode = positionXml.SelectSingleNode("./reversegeocode/addressparts/state_district");
            if (districtNode != null)
                positionTxt += comma + positionXml.SelectSingleNode("./reversegeocode/addressparts/state_district/text()").Value;
            /*comma = ", ";
            XmlNode stateNode = positionXml.SelectSingleNode("./resultset/result/state/@name");
            if (stateNode != null)
              	positionTxt += comma + positionXml.SelectSingleNode("./resultset/result/state/@name").Value; */

            return positionTxt;
        }
        public string writeZoomAndResponse(String[] headers, String name, Object[] values, Object[] positionTxtArray, string fuel, string dial, int latIndex, int longIndex, Object[] idlinginstancesArray, Object[] Remarks, String panicbuttonstr, String acAlertStr, Object[] IconTypes, Object[] DirAngles, Object[] TripStatus)
        {
            logWriter.WriteToLog("BLL:writeZoomAndResponse() Start:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);
            /*
            * This function is called to return last positions of chosen vehicles as a string in response to an AJAX
            * call. All javascript variables like maxLat,minLat,maxLong,minLong,latSpan,LongSpan,extraZoom,zoom and 
            * vehicle information is packaged as a string and sent. Format
            * maxLat#minLat#maxLong#minLong#latSpan#longSpan#extraZoom#zoom#fuel#Dial#PANIC SWITCH PRESENT(optional)#acOn/OffAlertPresent(OPTIONAL)#vehicleid#DateTime#LAt#long#Speed#id#vehicleInfo
            * #Location#direction#idlingInstance(if enabled AC 0/1 or DUTY 0/1 OR NC)
            * The vehicle information repeats for all selected vehicles
            */
            string vehiclesPositionInfo = String.Empty;
            vehiclesPositionInfo = writeZoomAjax(values, latIndex, longIndex);
            vehiclesPositionInfo += "#";
            // Write fuel info.
            vehiclesPositionInfo += fuel + "#" + dial + "#";
            vehiclesPositionInfo += panicbuttonstr + "#";
            vehiclesPositionInfo += acAlertStr + "#";
            for (int i = 0; i < values.Length; i++)
            {
                for (int j = 0; j < headers.Length; j++)
                {
                    Object outObj = ((Object[])values[i])[j];

                    vehiclesPositionInfo += outObj.ToString() + "#";
                }
                vehiclesPositionInfo += ((Object[])positionTxtArray[i])[0] + "#";
                vehiclesPositionInfo += ((Object[])positionTxtArray[i])[1] + "#";
                if (idlinginstancesArray.Length == 1 && idlinginstancesArray[0] == "NC")
                    vehiclesPositionInfo += "NC" + "#";
                else
                    vehiclesPositionInfo += idlinginstancesArray[i] + "#";
                vehiclesPositionInfo += Remarks[i] + "#";
                vehiclesPositionInfo += IconTypes[i] + "#";
                vehiclesPositionInfo += DirAngles[i] + "#";
                vehiclesPositionInfo += TripStatus[i] + "#";
            }
            logWriter.WriteToLog("BLL:writeZoomAndResponse() End:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);
            return vehiclesPositionInfo;

        }
        public string writeZoomAndResponse1(
        String[] headers,
        String name,
        Object[] values,
        Object[] positionTxtArray,
        string fuel,
        string dial,
        int latIndex,
        int longIndex,
        Object[] idlinginstancesArray,
        Object[] Remarks,
        String panicbuttonstr,
        String acAlertStr,
        Object[] IconTypes,
        Object[] DirAngles,
        Object[] TripStatus)
        {
            logWriter.WriteToLog("BLL:writeZoomAndResponse() Start:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);

            // Pre-allocate big enough buffer (assume ~250 chars per row × 4000 = ~1 MB)
            var sb = new StringBuilder(values.Length * 256);

            // Write zoom/fuel/dial/panic/AC info once
            sb.Append(writeZoomAjax(values, latIndex, longIndex)).Append('#')
              .Append(fuel).Append('#')
              .Append(dial).Append('#')
              .Append(panicbuttonstr).Append('#')
              .Append(acAlertStr).Append('#');

            int headersCount = headers.Length;
            int valuesCount = values.Length;

            for (int i = 0; i < valuesCount; i++)
            {
                var row = (Object[])values[i];

                // Write headers for this row
                for (int j = 0; j < headersCount; j++)
                {
                    var outObj = row[j];
                    if (outObj != null)
                        sb.Append(outObj);
                    sb.Append('#');
                }

                // Position text
                var posRow = (Object[])positionTxtArray[i];
                sb.Append(posRow[0]).Append('#')
                  .Append(posRow[1]).Append('#');

                // Idling instance
                if (idlinginstancesArray.Length == 1 && Equals(idlinginstancesArray[0], "NC"))
                {
                    sb.Append("NC#");
                }
                else
                {
                    sb.Append(idlinginstancesArray[i]).Append('#');
                }

                // Remaining fields
                sb.Append(Remarks[i]).Append('#')
                  .Append(IconTypes[i]).Append('#')
                  .Append(DirAngles[i]).Append('#')
                  .Append(TripStatus[i]).Append('#');
            }

            logWriter.WriteToLog("BLL:writeZoomAndResponse() End:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);

            return sb.ToString();
        }


