        //To get violationdata for BIAL 14-03-2024 sahana
        public DataTable GetAPIViolationReport(string fromDateStr, string toDateStr, string viotype, string vehicles, string sessionId)
        {
            int groupid = getGroupId(sessionId);
            object[] tripparams = dbx.getVehicleTripParams(sessionId);
            DataTable data = GetViolationsByVehicleIDs(vehicles, fromDateStr, toDateStr, viotype, Convert.ToString(groupid));

            data.Columns.Add("alertThreshold", typeof(string));
            data.Columns.Add("uid", typeof(string));

            string filterExpression = "remarks <> 'ALARM'";
            DataRow[] selectedRows = data.Select(filterExpression);

            DataTable filteredData = data.Clone();
            foreach (DataRow row in selectedRows)
            {
                string remarks = row["remarks"].ToString();
                string type = row["type"].ToString();
                string threshold = "0";
                string remvalue = "0";

                string vehicle = row["vehicleId"].ToString();
                string uid = dbx.GetUIDByVehicleId(vehicle);

                if (type == "OVERSPEEDING")
                {
                    string[] parts = remarks.Split('-');
                    remvalue = parts[1];
                    threshold = ((Object[])tripparams[0])[5].ToString();
                }
                else if (type == "HARSH BRAKING" || type == "HIGH ACCELERATION")
                {
                    threshold = ((Object[])tripparams[0])[6].ToString();
                    Match match = Regex.Match(remarks, @"\d+(\.\d+)?");
                    if (match.Success)
                    {
                        string numericValue = match.Value;
                        double HA_HB = double.Parse(numericValue);
                        remvalue = Convert.ToString(HA_HB);
                    }
                }
                else if (type == "NIGHT DRIVING")
                {
                    threshold = "10pm-6am";
                }
                else if (type == "SHORT RUNTIME")
                {
                    remvalue = remarks;
                }
                // Add the fetched values to the new DataRow
                DataRow newRow = filteredData.NewRow();
                newRow["vehicleId"] = row["vehicleId"];
                newRow["type"] = row["type"];
                newRow["remarks"] = remvalue;
                newRow["alertThreshold"] = threshold;
                newRow["uid"] = uid;
                newRow["duration"] = row["duration"];
                newRow["datetime"] = row["datetime"];
                newRow["Location"] = row["Location"];
                newRow["latitude"] = row["latitude"];
                newRow["longitude"] = row["longitude"];
                filteredData.Rows.Add(newRow);
            }

            return filteredData;
        }
