        public int ReffRouteInsert(string ReffRoute, string SelectedVehicles, string RouteName)
        {
            int Result = 0;
            var ReffRouteValues = ReffRoute.Split('|');
            var lParameter = new Dictionary<string, object>();
            for (int j = 0; j < ReffRouteValues.Length; j++)
            {
                String Query = string.Empty;
                Query = "insert into referenceroutedetail(accountid,routename,minlat,minlong,maxlat,maxlong,locstr,crossed,timestamp,sequence,isvehicleassigned) values " + ReffRouteValues[j];
                Result = dbx.InsertReffRouteData(Query.ToString());
            }
            if (Result > 0)
            {
                string query = string.Empty;
                var lVehicles = SelectedVehicles.Split(',');
                for (int i = 0; i < lVehicles.Length; i++)
                {
                    if (lVehicles[i].ToString() != "")
                    {
                        query = "insert into assignedvehicleroute(RouteName,VehicleId) values(?,?)";
                        lParameter.Clear();
                        lParameter.Add("RouteName", RouteName);
                        lParameter.Add("VehicleId", lVehicles[i].ToString());
                        Result = dbx.InsertReffRouteData(query, lParameter);
                    }
                }
            }
            return Result;
        }
