        public int ReffRouteDelete(string ReffRouteName, string AccountID)
        {
            StringBuilder Query = new StringBuilder();
            Query.Append("delete from referenceroutedetail where routename=? and accountid=?");
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("routename", ReffRouteName);
            lParameter.Add("accountid", AccountID);
            return dbx.DeleteReffRouteData(Query.ToString(), lParameter, ReffRouteName);
        }
