        //metro BlockedTransportervehicles - sahana 28/03/2024 
        public bool Isvehtransporterblocked(string vehicleNo, string session)
        {
            try
            {
                DataTable dt = dbx.MetroGetBlockedTransporterVehicles(session);
                if (dt != null && dt.Rows.Count > 0)
                {
                    foreach (DataRow row in dt.Rows)
                    {
                        string blockedVehicleNumber = row["vehicleid"].ToString();
                        if (MatchCount(blockedVehicleNumber, vehicleNo) >= 8)  // Check if the count of matching characters is greater than or equal to 6
                        {
                            return true;
                        }
                    }
                }

                return false;
            }
            catch (Exception ex)
            {
                return false;
            }
        }
        int MatchCount(string blockedVehicleNumber, string vehicleNumber)
        {
            blockedVehicleNumber = blockedVehicleNumber.Replace(" ", "");
            vehicleNumber = vehicleNumber.Replace(" ", "");
            int count = 0;
            int minLength = Math.Min(blockedVehicleNumber.Length, vehicleNumber.Length);
            for (int i = 0; i < minLength; i++)
            {
                if (blockedVehicleNumber[i] == vehicleNumber[i])
                    count++;
                else
                    break; // Stop counting if characters don't match
            }
            return count;
        }
