        public string GenerateTripSheet(string sessionid, Metro_TripInfo data, string shortestPath, long estimatedTripDistance, string TripSheetNo, string isByMetro = "0", string routingBy = "", string routingFor = "", string tripsFor = "", string paymentType = "")
        {
            string username = getUserId(sessionid);
            string StoreNo = dbx.getMetroStoreNo(username);
            string TripId = "";
            if (String.IsNullOrEmpty(TripSheetNo))
            {
                TripSheetNo = GenerateTripSheetNo(StoreNo);
                TripId = dbx.GenerateTripSheet(sessionid, data, estimatedTripDistance, TripSheetNo, StoreNo, isByMetro, routingBy, routingFor, tripsFor, paymentType);
            }
            else
            {
                TripId = dbx.UpdateTripSheet(estimatedTripDistance, TripSheetNo);
            }

            DataTable tripSheetHeaderData = dbx.MetroTripSheetHeaderData(TripId);
            DataTable tripSheetInvoiceData = dbx.MetroTripSheetPDFInvoiceData(TripId);
            DataTable tripInvoicesTotal = dbx.MetroInvoiceTotal(TripId);
            if (tripInvoicesTotal.Rows.Count > 0)
            {
                tripInvoicesTotal.Columns.Add("PaymentType", typeof(System.String));

                foreach (DataRow row in tripInvoicesTotal.Rows)
                {
                    //need to set value to NewColumn column
                    row["PaymentType"] = paymentType;   // or set it to some other value
                }
            }
            dbx.MetroUpdateTripInfo(TripId, "Manual", tripInvoicesTotal.Rows[0]["No_Of_Customer"].ToString(), tripInvoicesTotal.Rows[0]["No_Of_Invoices"].ToString(), tripInvoicesTotal.Rows[0]["TotalAmount"].ToString(), tripInvoicesTotal.Rows[0]["TotalCharge"].ToString());
            //SaveRouteMapAsImage(data, shortestPath);
            SaveTripSheetAsPdf(tripSheetHeaderData, tripSheetInvoiceData, tripInvoicesTotal, TripSheetNo, estimatedTripDistance);
            return TripSheetNo;
        }
