        public List<DataTable> SplitTable(DataTable originalTable, int batchSize)
        {
            List<DataTable> tables = new List<DataTable>();
            int i = 0;
            int j = 1;
            DataTable newDt = originalTable.Clone();
            newDt.TableName = "Table_" + j;
            newDt.Clear();
            foreach (DataRow row in originalTable.Rows)
            {
                DataRow newRow = newDt.NewRow();
                newRow.ItemArray = row.ItemArray;
                newDt.Rows.Add(newRow);
                i++;
                if (i == batchSize)
                {
                    tables.Add(newDt);
                    j++;
                    newDt = originalTable.Clone();
                    newDt.TableName = "Table_" + j;
                    newDt.Clear();
                    i = 0;
                }
            }
            if (i != 0)
            {
                tables.Add(newDt);
                newDt.TableName = "Table_" + j;
            }
            return tables;
        }

        public String MapsDistanceAPICall(DataTable dataTable, string sessionId)
        {
            DataTable MetroGetStoreLocation = dbx.MetroGetStoreLocation(sessionId).Tables[0];
            string destLat = MetroGetStoreLocation.Rows[0]["Latitude"].ToString();
            string destLong = MetroGetStoreLocation.Rows[0]["Longitude"].ToString();
            StringBuilder tempResult = new StringBuilder();
            var result = "";
            StringBuilder origins = new StringBuilder();
            StringBuilder distanceMatrixUrl = new StringBuilder();
            int requestSize = dataTable.Rows.Count;
            for (int i = 0; i < requestSize; i++)
            {
                origins.Append(dataTable.Rows[i]["Latitude"].ToString());
                origins.Append(",");
                origins.Append(dataTable.Rows[i]["Longitude"].ToString());
                origins.Append("|");
            }

            string strLlatLong = origins.ToString().TrimEnd();
            distanceMatrixUrl.Append("https://maps.googleapis.com/maps/api/distancematrix/json?units=imperial");
            distanceMatrixUrl.Append("&origins=");
            distanceMatrixUrl.Append(strLlatLong);
            distanceMatrixUrl.Append("&destinations=");
            distanceMatrixUrl.Append(destLat + "," + destLong);
            distanceMatrixUrl.Append("&key=AIzaSyCACZOOfvdmPNZ77Fh-CkIAh52BztqwjGg");

            //Pass request to google api with orgin and destination details
            HttpWebRequest request = (HttpWebRequest)WebRequest.Create(distanceMatrixUrl.ToString());
            HttpWebResponse response = (HttpWebResponse)request.GetResponse();
            using (var streamReader = new StreamReader(response.GetResponseStream()))
            {
                result = streamReader.ReadToEnd();
            }
            return result;
        }

        public List<string> ETADataTable(Rootobject rootObject, DataTable dataTable)
        {
            List<string> arrivalTimes = new List<string>();
            Row[] rowObject = rootObject.rows;
            int rowCount = rowObject.Length;
            Row row = rowObject[0];
            Element[] elementObject;
            int elementsCount;
            for (int i = 0; i < rowCount; i++)
            {
                elementObject = rowObject[i].elements;
                elementsCount = elementObject.Length;
                for (int j = 0; j < elementsCount; j++)
                {
                    arrivalTimes.Add(elementObject[j].duration.text);
                }
            }

            return arrivalTimes;
        }

        public double[,] CreateDistanceMatrix(Rootobject rootObject, Metro_TripInfo data)
        {
            int rows, columns;
            rows = rootObject.destination_addresses.Length;
            columns = rootObject.origin_addresses.Length;
            double[,] distanceMatrix = new double[rows, columns];
            double[,] timeMatrix = new double[rows, columns];
            DataTable originDestinationLatLong = dbx.MetroGetLatLong(data);

            int StoreNo = Convert.ToInt32(originDestinationLatLong.Rows[0]["StoreNo"]);
            List<int> NodeList = new List<int>();
            NodeList.Add(StoreNo);
            for (int i = 0; i < originDestinationLatLong.Rows.Count; i++)
            {
                NodeList.Add(Convert.ToInt32(originDestinationLatLong.Rows[i]["AddressId"]));
            }
            NodeList.Add(StoreNo);
            int[] nodeArray = NodeList.ToArray();
            Row[] rowObject = rootObject.rows;
            int rowCount = rowObject.Length;
            Row row = rowObject[0];
            Element[] elementObject;
            int elementsCount;
            for (int i = 0; i < rowCount; i++)
            {
                elementObject = rowObject[i].elements;
                elementsCount = elementObject.Length;
                for (int j = 0; j < elementsCount; j++)
                {
                    distanceMatrix[i, j] = elementObject[j].distance.value;
                    timeMatrix[i, j] = elementObject[j].duration.value;
                    if (i != j)
                    {
                        dbx.SaveDistance(nodeArray[i], nodeArray[j], elementObject[j].duration.value, elementObject[j].distance.value);
                    }
                }

            }

            return distanceMatrix;

        }

