        public void SaveRouteMapAsImage(Metro_TripInfo data, string shortestPath)
        {
            DataTable originDestinationLatLong = dbx.MetroGetLatLong(data);
            string originLat = "";
            string originLong = "";
            StringBuilder origins = new StringBuilder();
            for (int i = 0; i < originDestinationLatLong.Rows.Count; i++)
            {
                originLat = originDestinationLatLong.Rows[i]["SrcLatitude"].ToString();
                originLong = originDestinationLatLong.Rows[i]["SrcLongitude"].ToString();
                origins.Append("|");
                origins.Append(originDestinationLatLong.Rows[i]["DestLatitude"].ToString());
                origins.Append(",");
                origins.Append(originDestinationLatLong.Rows[i]["DestLongitude"].ToString());
            }

            string strLatLong = originLat + "," + originLong + "" + origins;

            int routeIndex;
            StringBuilder shortestPathUrl = new StringBuilder();
            StringBuilder shortestPathUrlPath = new StringBuilder();
            shortestPathUrl.Append("http://maps.google.com/maps/api/staticmap?zoom=12&size=800x300&maptype=roadmap");
            string[] strLatLongArray = strLatLong.Split('|');
            string[] routes = shortestPath.Split(new string[] { "-->" }, StringSplitOptions.None);
            for (int i = 0; i < routes.Length; i++)
            {
                routeIndex = Convert.ToInt32(routes[i]);
                shortestPathUrl.Append("&markers=color:red|label:" + i + "|" + strLatLongArray[routeIndex]);
                if (i != 0 && i != routes.Length - 1)
                {
                    shortestPathUrlPath.Append(strLatLongArray[routeIndex] + "|");
                }
            }
            if (shortestPathUrlPath.Length > 0)
                shortestPathUrlPath = new StringBuilder(shortestPathUrlPath.ToString().Substring(0, shortestPathUrlPath.ToString().Length - 1));
            string routePoints = GetDirectionsApi(strLatLongArray[0], strLatLongArray[0], shortestPathUrlPath.ToString());
            dynamic userObj = JObject.Parse(routePoints);
            string overlay_points = userObj.routes[0].overview_polyline.points;
            shortestPathUrl.Append("&path=enc%3A" + overlay_points);
            shortestPathUrl.Append("&key=AIzaSyCI0vU7L7IpkW6auMLZIkgYoJo3_h4-EOI");

            byte[] datas;
            WebClient webClient = new WebClient();
            datas = webClient.DownloadData(shortestPathUrl.ToString());
            File.WriteAllBytes(System.Web.Hosting.HostingEnvironment.MapPath("~/Uploads/staticImage.jpg"), datas);
        }

        public double CalculateTripDistance(double[,] distanceMatrix, string shortestPath)
        {
            double distance = 0;
            int firstIndex;
            int nextIndex;

            string[] routes = shortestPath.Split(new string[] { "-->" }, StringSplitOptions.None);
            for (int i = 0; i < routes.Length - 1; i++)
            {
                firstIndex = Convert.ToInt32(routes[i]);
                nextIndex = Convert.ToInt32(routes[++i]);

                distance = distance + distanceMatrix[firstIndex, nextIndex];
                i = i - 1;
            }
            return distance;
        }
        public string GenerateTripSheetNo(string StoreNo)
        {

            DataTable dtTripNo = dbx.GetLastTripSheetNo(StoreNo);
            string pDate = DateTime.Now.ToString("ddMMyyyy");
            int counter = 0;
            if (dtTripNo.Rows.Count > 0)
            {
                string TripNo = dtTripNo.Rows[0][0].ToString();
                pDate = TripNo.Substring(2, 6);
                counter = Convert.ToInt32(TripNo.Substring(12));
            }
            StringBuilder tripSheetNo = new StringBuilder();
            string lastDigits = "";
            string date = DateTime.Now.Date.ToString("ddMMyy");
            string time = DateTime.Now.ToString("HHmm");
            if (pDate != date)
            {
                counter = 1;
            }
            else
            {
                counter = counter + 1;
            }
            if (counter <= 9)
            {
                lastDigits = "00";
            }
            else if (counter > 9 & counter <= 99)
            {
                lastDigits = "0";
            }
            tripSheetNo.Append(StoreNo);
            tripSheetNo.Append(DateTime.Now.Date.ToString("ddMMyy"));
            tripSheetNo.Append(time);
            tripSheetNo.Append(lastDigits);
            tripSheetNo.Append(counter);
            return tripSheetNo.ToString();
        }

