        public void SaveTripSheetAsPdf(DataTable HeaderData, DataTable InvoiceData, DataTable InvoicesTotal, string TripSheetNo, long estimatedTripDistance)
        {
            try
            {
                String filepath = System.Web.Hosting.HostingEnvironment.MapPath("~/Uploads/");
                String filename = TripSheetNo + "_TripSheet.pdf";
                PDFReport report = new PDFReport(filepath, filename, "Metro");
                long estimatedTripDistanceInKMS = estimatedTripDistance;
                //To get transportername and show in the trip sheet
                string transporterName = "";
                try
                {
                    DataTable dtTripDetailsByTripNum = dbx.MetroGetTripDetailsByTripNum(TripSheetNo);
                    if (dtTripDetailsByTripNum != null)
                    {
                        if (dtTripDetailsByTripNum.Rows.Count > 0)
                            transporterName = " - " + dtTripDetailsByTripNum.Rows[0]["ShortName"].ToString();

                    }
                }
                catch (Exception ex)
                {

                }
                //adding Invoice Title - as Paragraph
                report.addMetroParagraph("Trip Sheet " + transporterName + "\n", "center");

                //DataTable For First Table Of TripSheet
                String[] title_headers = { "Vehicle No", "Vehicle Type", "Capacity", "Trip No", "Created Date", "Driver Name", "Phone No" };
                float[] title_widths = new float[] { 2.28f, 2.28f, 2.00f, 2.56f, 2.28f, 2.28f, 2.28f };
                String[] row1 = { HeaderData.Rows[0]["VehicleId"].ToString(), HeaderData.Rows[0]["VehicleInfo"].ToString(), HeaderData.Rows[0]["Capacity"].ToString() + " Ton(s)", TripSheetNo, HeaderData.Rows[0]["TripDate"].ToString(), HeaderData.Rows[0]["DriverName"].ToString(), HeaderData.Rows[0]["MobileNo"].ToString() };
                DataTable dtTripDetails = new DataTable();
                dtTripDetails.Columns.Add("Vehicle No");
                dtTripDetails.Columns.Add("Vehicle Type");
                dtTripDetails.Columns.Add("Capacity");
                dtTripDetails.Columns.Add("Trip No");
                dtTripDetails.Columns.Add("Trip Date");
                dtTripDetails.Columns.Add("Driver Name");
                dtTripDetails.Columns.Add("Phone No");
                dtTripDetails.Rows.Add(row1);

                //DataTable For Second Table Of TripSheet
                DataTable dtRoute = new DataTable();
                String[] header2 = { "Dispatch Mode", "Route", "Estimated Distance(Km)" };
                float[] header2_widths = new float[] { 3f, 10f, 3f };
                String[] row2 = { "Manual", HeaderData.Rows[0]["Places"].ToString(), estimatedTripDistanceInKMS.ToString() };
                dtRoute.Columns.Add("Dispatch Mode");
                dtRoute.Columns.Add("Route");
                dtRoute.Columns.Add("Estimated Distance(Km)");
                dtRoute.Rows.Add(row2);

                //Table Design For Third Table/Invoice Table Of TripSheet
                String[] headers = { "#", "Customer Name", "Mobile", "InvoiceNum", "Invoice Date", "Delivery Time", "Amount", "Delivery Charge" };
                float[] widths = new float[] { 1f, 4f, 2f, 3f, 3f, 2f, 2f, 2f };

                //Table Design For Fourth Table Of TripSheet
                String[] header3 = { "No Of Customers", "No Of Invoices", "Total Amount", "Delivery Charge", "Payment Type" };
                float[] header3_widths = new float[] { 3f, 3f, 3f, 3f, 3f };

                //Binding Data with Tables
                Object[] obj0 = ConvertDt2Obj(dtTripDetails);
                report.addMetroTable(title_headers, title_widths, obj0);

                Object[] obj1 = ConvertDt2Obj(dtRoute);
                report.addMetroTable(header2, header2_widths, obj1);

                Object[] obj = ConvertDt2Obj(InvoiceData);
                report.addMetroTable(headers, widths, obj);

                report.addMetroEmptyTable(1, HeaderData.Rows[0]["TripsFor"].ToString());

                //string imageURL = System.Web.Hosting.HostingEnvironment.MapPath("~/Uploads/") + "staticImage.jpg";
                //report.addMetroImage(imageURL, "staticImage");
                report.addMetroParagraph("----------------------------------------------------------------------------------------------------------------------\n", "center");

                report.addMetroTable(title_headers, title_widths, obj0);

                Object[] obj3 = ConvertDt2Obj(InvoicesTotal);
                report.addMetroTable(header3, header3_widths, obj3);

                report.addMetroEmptyTable(2, "");

                report.close();
                BusinessLogicLayer.AmazonS3Upload.UploadFiles(filepath, filename, "db-flatfile-backup", "", "PublicRead");
            }
            catch (Exception e)
            {

            }
        }

        public string ConvertDataTableToHTML(DataTable dt)
        {
            string html = "<table style='border-collapse: collapse;border: 1px solid black;'>";
            //add header row
            html += "<tr style='border: 1px solid black;'>";
            for (int i = 0; i < dt.Columns.Count; i++)
                html += "<th style='border: 1px solid black;'>" + dt.Columns[i].ColumnName + "</td>";
            html += "</tr>";
            //add rows
            for (int i = 0; i < dt.Rows.Count; i++)
            {
                html += "<tr style='border: 1px solid black;'>";
                for (int j = 0; j < dt.Columns.Count; j++)
                    html += "<td style='border: 1px solid black;'>" + dt.Rows[i][j].ToString() + "</td>";
                html += "</tr>";
            }
            html += "</table>";
            return html;
        }

        public bool ConvertDataToExcel(DataTable ExportToExcel, string Filepath, string ReportName)
        {
            try
            {
                for (int i = 0; i < ExportToExcel.Columns.Count; i++)
                {
                    if (ExportToExcel.Columns[i].DataType == typeof(DateTime))
                    {
                        DataTable dtCloned = ExportToExcel.Clone();
                        dtCloned.Columns[i].DataType = typeof(string);
                        foreach (DataRow row in ExportToExcel.Rows)
                        {
                            dtCloned.ImportRow(row);
                        }
                        ExportToExcel = dtCloned;
                    }
                }
                using (ExcelPackage objExcelPackage = new ExcelPackage())
                {

                    //Create the worksheet    
                    ExcelWorksheet objWorksheet = objExcelPackage.Workbook.Worksheets.Add(ReportName.Replace(" ", ""));
                    //Load the datatable into the sheet, starting from cell A1. Print the column names on row 1    
                    objWorksheet.Cells["A1"].LoadFromDataTable(ExportToExcel, true);
                    objWorksheet.Cells.Style.Font.SetFromFont(new Font("Calibri", 11));
                    objWorksheet.Cells.AutoFitColumns(25, 40);
                    objWorksheet.Cells[1, 1, 1, ExportToExcel.Columns.Count].AutoFilter = true;

                    //Format the header    
                    using (ExcelRange objRange = objWorksheet.Cells[1, 1, 1, ExportToExcel.Columns.Count])
                    {
                        objRange.Style.Font.Bold = true;
                        objRange.Style.Font.Color.SetColor(Color.White);
                        objRange.Style.WrapText = true;
                        objWorksheet.Cells.Style.Font.SetFromFont(new Font("Calibri", 12));
                        objRange.Style.VerticalAlignment = ExcelVerticalAlignment.Center;
                        objRange.Style.HorizontalAlignment = ExcelHorizontalAlignment.Center;
                        objRange.Style.Fill.PatternType = ExcelFillStyle.Solid;
                        objRange.Style.Fill.BackgroundColor.SetColor(Color.DarkGray);
                    }
                    //Write it back to the client    
                    if (File.Exists(Filepath))
                        File.Delete(Filepath);

                    //Create excel file on physical disk    
                    FileStream objFileStrm = File.Create(Filepath);
                    objFileStrm.Close();

                    //Write content to excel file    
                    File.WriteAllBytes(Filepath, objExcelPackage.GetAsByteArray());
                    objExcelPackage.Dispose();
                    return true;
                }
            }
            catch (Exception ex)
            {
                return false;
            }
        }

