                    row1[1] = vetStaticDetails.Rows[0]["Latitude"].ToString() + "," + vetStaticDetails.Rows[0]["Longitude"].ToString();
                    row1[2] = "Location of Inspector";
                    row1[3] = getPositionTxt(vetStaticDetails.Rows[0]["Latitude"].ToString(), vetStaticDetails.Rows[0]["Longitude"].ToString(), 1);
                    report.addTableRowWithCellHeader(row1, cell_headers, textsize);

                    report.endTable();
                }
                #endregion

                DataTable checklistValues = dbx.getVetChecklistDetails(vetId);
                DataTable categories = checklistValues.DefaultView.ToTable(true, "Name");

                string[] xValues = new string[categories.Rows.Count];
                double[] yValues = new double[categories.Rows.Count];
                Double sum = 0;
                long chklistScore = 0;
                long chklistTotalScore = 0;

                title_headers = new string[] { "Category-Wise Scores" };
                title_widths = new float[] { 30, 30 };
                cells2Cover = new int[] { title_widths.Length };
                report.beginTableWithCell(title_headers, title_widths, cells2Cover, textsize);
                cell_headers = new bool[title_widths.Length];
                cell_headers[0] = true;

                for (int i = 0; i < categories.Rows.Count; i++)
                {
                    string category = categories.Rows[i]["Name"].ToString();
                    long categoryScore = checklistValues.Select("Name='" + category + "'").Sum(a => a.Field<Int64>("TotalScore"));
                    long categoryTotalScore = checklistValues.Select("Name='" + category + "'").Sum(a => a.Field<Int32>("Coefficient") * a.Field<Int32>("MaxScore"));
                    string percentVal = ((categoryScore * 100) / categoryTotalScore).ToString();
                    xValues[i] = category;
                    yValues[i] = Convert.ToInt32(percentVal);
                    sum += Convert.ToInt32(percentVal);
                    chklistScore += categoryScore;
                    chklistTotalScore += categoryTotalScore;
                    row1 = new string[title_widths.Length];
                    row1[0] = category;
                    row1[1] = percentVal;
                    report.addTableRowWithCellHeader(row1, cell_headers, textsize);
                }
                report.endTable();
                string Grade = "";
                string DriverCategory = "";
                Double overallScore = Math.Round(sum / categories.Rows.Count);
                if (vetStaticDetails.Rows[0]["OverallScoring"].ToString() == "Overall")
                    //overallScore = (chklistScore * 100) / chklistTotalScore;
                    overallScore = Math.Round((sum) / categories.Rows.Count);
                if (overallScore >= 86)
                {
                    Grade = "A";
                    DriverCategory = "SAFE DRIVER";
                }
                if (overallScore > 70 && overallScore < 86)
                {
                    Grade = "B";
                    DriverCategory = "LOW RISK DRIVER ";
                }
                if (overallScore <= 70)
                {
                    Grade = "C";
                    DriverCategory = "HIGH RISK DRIVER";
                }
                report.addHeader("Overall Score : " + overallScore + "%  Grade : " + Grade + " Category :  " + DriverCategory + "", "center", 15);

                //Drawing spider graph for category wise vetting scores
                spiderGraph(xValues, yValues);
                string imageURL = System.Web.Hosting.HostingEnvironment.MapPath("~/Uploads/") + "spiderGraph.jpg";
                report.addImage(imageURL, "staticImage");

                #region Fields
                DataTable fieldValues = dbx.getVetFieldDetails(vetId);
                categories = fieldValues.DefaultView.ToTable(true, "Name");

                report.addHeader("Field details", "center", 15);

                //Checklist values for category wise vetting
                for (int i = 0; i < categories.Rows.Count; i++)
                {
                    string category = categories.Rows[i]["Name"].ToString();

                    title_headers = new string[] { category };
                    title_widths = new float[] { 30, 30 };
                    cells2Cover = new int[] { title_widths.Length };
                    cell_headers = new bool[title_widths.Length];
                    cell_headers[0] = true;
                    report.beginTableWithCell(title_headers, title_widths, cells2Cover, textsize);

                    DataRow[] dr = fieldValues.Select("Name='" + category + "'");

                    for (int j = 0; j < dr.Length; j++)
                    {
                        string[] row = new string[title_widths.Length];
                        row[0] = dr[j]["FieldName"].ToString();
                        row[1] = dr[j]["Value"].ToString();
                        report.addTableRowWithCellHeader(row, cell_headers, textsize);
                        if (dr[j]["FieldType"].ToString() == "3" && dr[j]["Validation"].ToString() == "1" &&
                            (dr[j]["fieldVal"].ToString() == "1" || dr[j]["fieldVal"].ToString() == "4"))
                        {
                            if (appId == "2" || appId == "4")
                                uniqueValue = dr[j]["Value"].ToString();
                            DataTable ddlDt = GetVetMainDetails(sessionId, appId, dr[j]["Id"].ToString(), dr[j]["Value"].ToString());
                            if (ddlDt != null && ddlDt.Rows.Count > 0)
                            {
                                for (int k = 0; k < ddlDt.Rows.Count; k++)
                                {
                                    row = new string[title_widths.Length];
                                    row[0] = Convert.ToString(ddlDt.Rows[k]["FieldName"]);
                                    row[1] = Convert.ToString(ddlDt.Rows[k]["Value"].ToString());
                                    report.addTableRowWithCellHeader(row, cell_headers, textsize);
                                }
                            }
                        }
                    }
                    report.endTable();
                }
                #endregion

                #region CheckList
                categories = checklistValues.DefaultView.ToTable(true, "Name");

                report.addHeader("Checklist details", "center", 15);

                //Checklist values for category wise vetting
                for (int i = 0; i < categories.Rows.Count; i++)
                {
                    string category = categories.Rows[i]["Name"].ToString();
                    long categoryScore = checklistValues.Select("Name='" + category + "'").Sum(a => a.Field<Int64>("TotalScore"));
                    long categoryTotalScore = checklistValues.Select("Name='" + category + "'").Sum(a => a.Field<Int32>("Coefficient") * a.Field<Int32>("MaxScore"));


                    title_headers = new string[] { "SL. No", category, "Input", "Coeff.", "Score", "Total Score", "Comments", "Photo" };
                    title_widths = new float[] { 1f, 4f, 3.5f, 1f, 1f, 1f, 2.28f, 2.28f };
                    cells2Cover = new int[title_headers.Length];
                    report.beginTableWithCell(title_headers, title_widths, cells2Cover, textsize);

                    DataRow[] dr = checklistValues.Select("Name='" + category + "'");
                    for (int j = 0; j < dr.Length; j++)
                    {
                        string[] row = new string[title_headers.Length];
                        row[0] = (j + 1).ToString();
                        row[1] = dr[j]["RuleName"].ToString();
                        row[2] = dr[j]["Option"].ToString();
                        row[3] = dr[j]["Coefficient"].ToString();
                        row[4] = dr[j]["Score"].ToString();
                        row[5] = dr[j]["TotalScore"].ToString();
                        row[6] = dr[j]["Comments"].ToString();
                        bool highlighter = false;
                        if (Convert.ToInt16(row[4]) < Convert.ToInt16(dr[j]["MaxScore"].ToString()))
                            highlighter = true;
                        row[7] = "";
                        if (!string.IsNullOrEmpty(dr[j]["Photo"].ToString()))
                        {
                            if (dr[j]["Photo"].ToString().Contains(","))
                            {
                                string[] photosStr = dr[j]["Photo"].ToString().Split(',');
                                for (int k = 0; k < photosStr.Length; k++)
                                {
                                    if (k != 0)
                                    {
                                        for (int a = 0; a < row.Length; a++)
                                        {
                                            row[a] = "";
                                        }
                                    }
                                    row[7] = filepath + photosStr[k];
                                    if (!File.Exists(row[7].ToString()))
                                    {
                                        try
                                        {
                                            BusinessLogicLayer.AmazonS3Upload.DownloadDbFiles(photosStr[k], "", filepath);
                                        }
                                        catch { }
                                    }
                                    report.addTableRowWithImage(row, false, highlighter, null, "#ffffff", textsize);
                                }
                            }
                            else
                            {
                                row[7] = filepath + dr[j]["Photo"].ToString();
                                if (!File.Exists(row[7].ToString()))
                                {
                                    try
                                    {
                                        BusinessLogicLayer.AmazonS3Upload.DownloadDbFiles(dr[j]["Photo"].ToString(), "", filepath);
                                    }
                                    catch { }
                                }
                                report.addTableRowWithImage(row, false, highlighter, null, "#ffffff", textsize);
                            }
                        }
                        else
                            report.addTableRowWithImage(row, false, highlighter, null, "#ffffff", textsize);
                        if (j == dr.Length - 1)
                        {
                            row = new string[] { "Compliance Percentage of " + category + " : " + ((categoryScore * 100) / categoryTotalScore).ToString() + "%" };
                            report.addTableRowWithImage(row, true, false, new int[] { title_headers.Length }, "#C0C0C0");
                        }
                    }

                    report.endTable();
                }
                report.addHeader("Remarks", "left", 10);
                report.addParagraph(vetStaticDetails.Rows[0]["Summary"].ToString());
                report.close();
                #endregion


                BusinessLogicLayer.AmazonS3Upload.UploadFiles(filepath, filename, "db-flatfile-backup", "", "PublicRead");
                int res = dbx.updateReportNameByVettingId(vetId, filename);
                if (res > 0)
                {
                    string username = getUserId(sessionId);
                    string additionalmailids = "";
                    int accountid = GetAccountId(sessionId);
                    if (appId == "2" || appId == "4")
                    {
                        additionalmailids = GetDIPTransporterMailIdByVetVal(accountid, uniqueValue);
                    }
                    string accountname = GetAccountName(sessionId);
                    SendFormatedMailWithAttachment(sessionId, "Please see attached " + vetStaticDetails.Rows[0]["ReportHeader"].ToString() + " generated on "
                        + Convert.ToDateTime(vetStaticDetails.Rows[0]["DateTime"].ToString()).ToString("yyyy-MM-dd"), "Senseltelematics "
                        + vetStaticDetails.Rows[0]["ReportHeader"].ToString() + " - " + accountname, Convert.ToString(vetStaticDetails.Rows[0]["ReportMailKey"]),
                        new string[] { filepath + filename }, additionalmailids, false);
                }

                return filename;
            }
            catch (Exception e)
            {
                return "SaveVetReportAsPdf_" + e.ToString();
            }
        }

        public string GetDIPTransporterMailIdByVetVal(int accountid, string value)
        {
            return dbx.GetDIPTransporterMailIdByVetVal(accountid, value);
        }

        public string SaveVettingReportAsPdf(string vettingId)
        {
            try
            {
                String filepath = System.Web.Hosting.HostingEnvironment.MapPath("~/Uploads/");
                String filename = "VettingReport_" + DateTime.Now.ToString("yyyyMMddHHmmss") + "_" + vettingId + ".pdf";
                #region Vetting Score Report
                PDFReport report = new PDFReport(new FileStream(filepath + filename, FileMode.Create));

                report.addHeader("Vetting Report\n", "center");
                report.addHeader("Compliance Percentage – Parameter Wise", "center", 10);
                //adding category wise scores
                DataTable checklistValues = dbx.getVettingChecklistDetails(vettingId);
                DataTable categories = checklistValues.DefaultView.ToTable(true, "Name");

                string[] xValues = new string[categories.Rows.Count];
                double[] yValues = new double[categories.Rows.Count];
                int textsize = 9;

                string[] title_headers = new string[categories.Rows.Count];
                float[] title_widths = new float[title_headers.Length];
                DataTable dtCheckListValues = new DataTable();
                for (int i = 0; i < categories.Rows.Count; i++)
                {
                    title_headers[i] = categories.Rows[i][0].ToString();
                    title_widths[i] = 2.28f;
                    dtCheckListValues.Columns.Add(categories.Rows[i]["Name"].ToString());
                }
                string[] row1 = new string[categories.Rows.Count];
                for (int i = 0; i < categories.Rows.Count; i++)
                {
                    if (categories.Rows[i]["Name"].ToString() == "RIGID TRUCK/TRUCK/PRIME MOVER")
                        row1[i] = filepath + "Vetting_Rigid_Truck.png";
                    else if (categories.Rows[i]["Name"].ToString() == "Tank")
                        row1[i] = filepath + "Vetting_Tank.png";
                    else if (categories.Rows[i]["Name"].ToString() == "Accessories")
                        row1[i] = filepath + "Vetting_Accessories.png";
                    else if (categories.Rows[i]["Name"].ToString() == "PPE- Driver")
                        row1[i] = filepath + "Vetting_PPE_Driver.png";
                    else if (categories.Rows[i]["Name"].ToString() == "Vehicle Documents")
                        row1[i] = filepath + "Vetting_Vehicle_Documents.png";
                    else if (categories.Rows[i]["Name"].ToString() == "Trailer/Semi-Trailer")
                        row1[i] = filepath + "Vetting_Trailer.png";
                }
                dtCheckListValues.Rows.Add(row1);
                row1 = new string[categories.Rows.Count];
