                                        }
                                    }
                                    row[7] = filepath + photosStr[k];
                                    if (!File.Exists(row[7].ToString()))
                                    {
                                        try
                                        {
                                            BusinessLogicLayer.AmazonS3Upload.DownloadDbFiles(photosStr[k], "", filepath);
                                        }
                                        catch { }
                                    }
                                    report.addTableRowWithImage(row, false, highlighter, null, "#ffffff", textsize);
                                }
                            }
                            else
                            {
                                row[7] = filepath + dr[j]["Photo"].ToString();
                                if (!File.Exists(row[7].ToString()))
                                {
                                    try
                                    {
                                        BusinessLogicLayer.AmazonS3Upload.DownloadDbFiles(dr[j]["Photo"].ToString(), "", filepath);
                                    }
                                    catch { }
                                }
                                report.addTableRowWithImage(row, false, highlighter, null, "#ffffff", textsize);
                            }
                        }
                        else
                            report.addTableRowWithImage(row, false, highlighter, null, "#ffffff", textsize);
                        if (j == dr.Length - 1)
                        {
                            row = new string[] { "Compliance Percentage of " + category + " : " + ((categoryScore * 100) / categoryTotalScore).ToString() + "%" };
                            report.addTableRowWithImage(row, true, false, new int[] { title_headers.Length }, "#C0C0C0");
                        }
                    }

                    report.endTable();
                }
                report.addHeader("Remarks", "left", 10);
                report.addParagraph(vetStaticDetails.Rows[0]["Summary"].ToString());
                report.close();
                #endregion


                BusinessLogicLayer.AmazonS3Upload.UploadFiles(filepath, filename, "db-flatfile-backup", "", "PublicRead");
                dbx.updateReportNameByVettingId(vettingId, filename);

                string mailid = GetTransporterMailIdByVehicleId(vetStaticDetails.Rows[0]["VehicleId"].ToString().Replace(" ", ""), false);

                string accountname = GetAccountName(sessionId);
                SendFormatedMailWithAttachment(sessionId, "Please see attached Vetting Report generated for " + vetStaticDetails.Rows[0]["VehicleId"].ToString() + " on "
                        + Convert.ToDateTime(vetStaticDetails.Rows[0]["VettingDate"].ToString()).ToString("yyyy-MM-dd"), "Senseltelematics Vetting Report - " + accountname,
                        "VettingReport", new string[] { filepath + filename }, mailid);

                return filename;
            }
            catch (Exception e)
            {
                return "";
            }
        }

        public void spiderGraph(string[] xValues, double[] yValues)
        {

            int pixelWidth = 600;
            int pixelHeight = 600;

            var Chart1 = new System.Web.UI.DataVisualization.Charting.Chart();
            Chart1.BackColor = System.Drawing.Color.WhiteSmoke;

            var area = new System.Web.UI.DataVisualization.Charting.ChartArea("ca1");
            area.Area3DStyle.Enable3D = false;
            area.AxisX.Interval = 1;
            area.AxisX.LabelStyle.Font = new System.Drawing.Font("Trebuchet MS", 3F, System.Drawing.FontStyle.Bold);
            area.BackColor = System.Drawing.Color.White;

            area.AxisY.MajorTickMark.Enabled = false;
            area.AxisY.MajorGrid.LineColor = Color.Gray;
            area.AxisY.MajorGrid.Interval = 25;

            area.AxisY.MinorTickMark.Enabled = false;
            area.AxisY.MinorGrid.Interval = 5;
            area.AxisY.MinorGrid.LineColor = Color.LightGray;

            Chart1.ChartAreas.Add(area);


            var series1 = new System.Web.UI.DataVisualization.Charting.Series();

            series1.Name = "Series1";

            series1.Color = System.Drawing.Color.FromArgb(100, 0, 0, 255);

            series1.LegendText = "A";

            series1.ChartType = System.Web.UI.DataVisualization.Charting.SeriesChartType.Radar;

            series1.ChartArea = "ca1";


            Chart1.Series.Add(series1);

            Chart1.Series["Series1"].Points.DataBindXY(xValues, yValues);

            string[] astrRadarStyleList = new string[] { "Area", "Line", "Marker" }; // Fill, Line, or point
            string[] astrAreaDrawingStyleList = new string[] { "Circle", "Polygon" }; // Shape
            string[] astrLabelStyleList = new string[] { "Circular", "Radial", "Horizontal" };



            string strRadarStyle = astrRadarStyleList[0];
            string strAreaDrawingStyle = astrAreaDrawingStyleList[1];
            string strLabelStyle = astrLabelStyleList[0];


            Chart1.Width = System.Web.UI.WebControls.Unit.Pixel(pixelWidth);
            Chart1.Height = System.Web.UI.WebControls.Unit.Pixel(pixelHeight);


            // Set radar chart style
            Chart1.Series["Series1"]["RadarDrawingStyle"] = strRadarStyle;

            if (strRadarStyle == "Area")
            {
                Chart1.Series["Series1"].BorderColor = Color.FromArgb(100, 100, 100);
                Chart1.Series["Series1"].BorderWidth = 1;
            }
            else if (strRadarStyle == "Line")
            {
                Chart1.Series["Series1"].BorderColor = Color.Empty;
                Chart1.Series["Series1"].BorderWidth = 2;
            }
            else if (strRadarStyle == "Marker")
            {
                Chart1.Series["Series1"].BorderColor = Color.Empty;
            }

            // Set circular area drawing style
            Chart1.Series["Series1"]["AreaDrawingStyle"] = strAreaDrawingStyle;


            // Set labels style
            Chart1.Series["Series1"]["CircularLabelsStyle"] = strLabelStyle;

            Chart1.SaveImage(System.Web.Hosting.HostingEnvironment.MapPath("~/Uploads/") + "spiderGraph.jpg", ChartImageFormat.Jpeg);

        }

        public static Object[] ConvertDt2Obj(DataTable dt)
        {
            ArrayList tInfoList = new ArrayList();
            foreach (DataRow row in dt.Rows)
            {
                String[] str = new String[dt.Columns.Count];
                str = Array.ConvertAll(row.ItemArray, x => x.ToString());
                tInfoList.Add(str);
            }
            return tInfoList.ToArray();
        }
