        public string GetVehicles(string sessionid)
        {
            DataSet ds = new DataSet();
            ds = GetVehiclesBySessionId(sessionid);
            DataTable dt = ds.Tables[0];
            string Vehiclelist = string.Empty;
            string temp = "'";
            foreach (var column in dt.Columns)
            {
                DataColumn dc = column as DataColumn;
                Vehiclelist = string.Join("','", dt.Rows.OfType<DataRow>().Select(r => r[dc]));
                break;
            }
            temp = temp + Vehiclelist + "'" + ",'" + "Select" + "'";

            return temp;
        }
