        public string writeDistanceInXml(string vehicleId, DateTime fromDate, DateTime toDate)
        {
            try
            {
                StringBuilder StrDistance = new StringBuilder();


                //StrDistance.Append("<?xml version=" + "\"1.0\"" + " encoding=" + "\"UTF-8\"" + "?>");
                StrDistance.Append("<distanceTable>");
                StrDistance.Append("<vehicle>" + vehicleId + "</vehicle>");
                int count = 0;
                double totalDistance = 0;
                DateTime startDate = fromDate;
                Object lastLatLong = null;
                while (toDate.CompareTo(fromDate) > 0 && count++ < 31)
                {
                    String tripStartStr = dbx.formatDBDate(fromDate);
                    DateTime tripEnd = fromDate.AddDays(1);
                    // from date can have any start time. Days in between should end at midnight
                    tripEnd = tripEnd.AddSeconds(-1 * tripEnd.Second - tripEnd.Minute * 60 - tripEnd.Hour * 60 * 60);
                    // last date should end on toDate.
                    if (tripEnd.CompareTo(toDate) > 0)
                    {
                        tripEnd = toDate;
                    }
                    String tripEndStr = dbx.formatDBDate(tripEnd);
                    double tripDistance = 0;
                    Object[] ret = accumulateDistance(vehicleId, tripStartStr, tripEndStr, lastLatLong);
                    tripDistance = (double)ret[0];
                    lastLatLong = ret[1];
                    totalDistance += tripDistance;
                    fromDate = tripEnd;
                }
                StrDistance.Append("<fromDate>" + startDate.ToString("D") + "</fromDate>"
                               + "<fromTime>" + startDate.ToString("T") + "</fromTime>"
                               + "<toDate>" + toDate.ToString("D") + "</toDate>"
                               + "<toTime>" + toDate.ToString("T") + "</toTime>"
                               + "<distance>" + Math.Round(totalDistance) + "</distance>"
                               + "</distanceTable>\n");
                return StrDistance.ToString();
            }
            catch
            {
                dbx.close();
                throw;
            }
            finally { dbx.close(); }
        }

