        public string GetDistanceSummaryReportXML(string sessionId, DateTime fromDate, DateTime toDate)
        {
            logWriter.WriteToLog("BLL:GetDistanceSummaryReportXML() Start:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);
            Object[] vehicles = GetVehiclesArray(sessionId);
            StringBuilder StrDistanceSummary = new StringBuilder();
            string fromDateStr = formatDBDate(fromDate);
            string toDateStr = formatDBDate(toDate);
            if (vehicles.Length > 0)
            {
                //StrDistanceSummary.Append("<?xml version=" + "\"1.0\"" + " encoding=" + "\"UTF-8\"" + "?>");
                StrDistanceSummary.Append("<DistanceSummary>");
                for (int i = 0; i < vehicles.Length; i++)
                {
                    String vehicle = (String)((Object[])vehicles[i])[0];
                    Object[] ret = accumulateDistance(vehicle, fromDateStr, toDateStr, null);
                    double distance = (double)ret[0];

                    StrDistanceSummary.Append("<vehicle>" + vehicle + "</vehicle>");
                    StrDistanceSummary.Append("<Distance>" + Math.Round(distance, 1) + "</Distance>");

                }
            }
            StrDistanceSummary.Append("</DistanceSummary>");
            logWriter.WriteToLog("BLL:GetDistanceSummaryReportXML() End:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);

            return StrDistanceSummary.ToString();
        }
        public string GetVehiclesInfo(String sessionIdstr, string vehicles = "", string Datetime = null, string vehicleType = "0", string LoginSource = "")
        {
            //logWriter.WriteToLog("BLL:GetVehiclesInfo() Start:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);
            try
            {
                String auxinputinfo = String.Empty;
                string panicbuttonstr = null;
                Object[] panicInfo = null;
                String acAlertStr = null;
                String TipperAlertStr = null;
                String BatteryLowAlertStr = null;
                String[] positionsTxt = null;

                String[] positionHeader = { "positionTxt", "direction" };
                String[] directions = { "right", "tr", "top", "tl", "left", "dl", "down", "dr" };
                Object[] positionsTxtArray = null;
                Object[] idlinginstancesArray = null;
                Object[] Remarksarray = null;
                Object[] IconTypesarray = null;
                Object[] BatteryStatusarray = null;
                Object[] HaltedFromarray = null;
                Object[] Bearerarray = null;
                Object[] SignalLevelarray = null;
                Object[] FuelLevelarray = null;
                String fuelInLts = "-1";
                String[] headersStr = { "trucks", "times", "latitude", "longitude", "speed", "unixts", "info" };
                String dial = String.Empty;
                Boolean geoLocation = false;
                object[] PositiontxtDataGL = null;
                timeZone = GetTimeZoneDiff(sessionIdstr);
                int gid = dbx.getGroupId(sessionIdstr);

                //logWriter.WriteToLog("BLL:GetVehiclesInfo() PGetVehSt" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);
                Object[] selectedValues = dbx.getLastPositions(sessionIdstr, Datetime, vehicles, vehicleType);
                //logWriter.WriteToLog("BLL:GetVehiclesInfo() PGetVehEnd" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);
                // 04 MAr 21 
                // If it is a ASSET_SMART device and only 1 unit is selected for ShowPositions then get the data from corresponding geolocation tables(lastupdtdataGL
                // and vehiclepositiontxtGL. Please remember that GetPostDataFrom should always be set to "lastupdtdata" in web.config
                // The function will return EMPTY/NULL if the current position of the ASSET is obtained from GPS. If the current location is obtained from geolocation 
                // info thenit will return an Object
                // One more check can be done before calling the geolocation method is to do it only for ASSET and not for vehicle
                //
                ArrayList selectedValuesList = new ArrayList();
                //logWriter.WriteToLog("BLL:GetVehiclesInfo() selectedValues start" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);
                if (LoginSource != "LandingWEB")
                {
                    if (!String.IsNullOrEmpty(vehicles))
                    {
                        int numVeh = vehicles.Split(',').Length;
                        if (numVeh == 1)
                        {
                            Object[] valuesGL = null;
                            valuesGL = dbx.getLastUpdateFromGeolocationTbl("'" + vehicles.Replace(",", "','") + "'");
                            if (selectedValues.Length > 0)
                                selectedValuesList.Add(selectedValues[0]);

                            if (valuesGL != null)
                            {
                                selectedValuesList.Add(valuesGL[0]);
                                geoLocation = true;
                            }
                            selectedValues = selectedValuesList.ToArray();
                        }
                    }
                }
                //logWriter.WriteToLog("BLL:GetVehiclesInfo() selectedValues before for loop" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);
                /*here we got all the vehicle list and their corrsponding 
                positiondata list in the selectedValues variable*/

                ArrayList Remarks_List = new ArrayList();
                ArrayList IconTypes_List = new ArrayList();
                ArrayList BatteryStatus_List = new ArrayList();
                ArrayList HaltedFrom_List = new ArrayList();
                ArrayList idlinginstancesList = new ArrayList();
                ArrayList positionsTxtList = new ArrayList();
                ArrayList Bearerarray_List = new ArrayList();
                ArrayList SignalLevelarray_List = new ArrayList();
                ArrayList FuelLevelarray_List = new ArrayList();
                //Added by Madhuri to optimize the code for Asset
                Object[] accountdetails = dbx.getAccountInfo(sessionIdstr);
                String acntGroupAsset = "";
                if (accountdetails != null)
                    if (accountdetails.Length > 0)
                    {
                        acntGroupAsset = accountdetails[3].ToString();//Convert.ToString(((Object[])account[0])[3]);
                    }
                String vehiclesPositionInfo = String.Empty;
                int latIndex = 2;
                int longIndex = 3;
                if (!acntGroupAsset.Contains("AT"))
                {
                    //added for listing out all the remarks field for all  the vehicles combinedly

                    //ArrayList idlinginstancesList = new ArrayList();
                    //added for listing out all the Auxinput field for all  the vehicles combinedly
                    try
                    {
                        Object auxinputinfoObj = dbx.getAuxillaryInputInfo(sessionIdstr);
                        /*for getting whether there is a auxinput field present in the accountgroups
                        table if it is not present put NC in the idlinginstancesList*/
                        if (auxinputinfoObj != null)
                        {
                            auxinputinfo = auxinputinfoObj.ToString();
                        }
                        else
                            auxinputinfo = "null";
                    }
                    catch (Exception)
                    {

                    }

                    if (auxinputinfo == "null" || auxinputinfo.Trim() == "AT")
                    {
                        idlinginstancesList.Add("NC");
                    }
                    //ArrayList positionsTxtList = new ArrayList();
                    panicbuttonstr = null;   //variable to fetch the vehicleid having panic button presed from panic table

                    //ArrayList fuelTxtList = new ArrayList();
                    //String[] fuelTxt = null;				  //to hold fuel in Lts

                    DateTime endDate = DateTime.UtcNow;
                    endDate = endDate.AddSeconds(timeZone);//for converting in to IST
                    if (Datetime != null)
                        endDate = Convert.ToDateTime(Datetime);
                    //panic switch info is to be extracted from the panic table where we will access the alert time with the vehicle
                    //info if the time is within a perticular window value then panic info is to be flashed


                    String maxAlertDelayStr = "3600";

                    String aapMaxAlertDelayStr = System.Web.Configuration.WebConfigurationManager.AppSettings["MAXALERTDELAY"];
                    if (!String.IsNullOrEmpty(aapMaxAlertDelayStr))
                        maxAlertDelayStr = aapMaxAlertDelayStr;

                    String maxPanicDelayStr = "180";
                    String appMaxPanicDelaySt = System.Web.Configuration.WebConfigurationManager.AppSettings["MAXPANICPRESSEDDELAY"];
                    if (!String.IsNullOrEmpty(appMaxPanicDelaySt))
                        maxPanicDelayStr = appMaxPanicDelaySt;
                    logWriter.WriteToLog("BLL:GetVehiclesInfo() PGetPanicSt" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);
                    if (auxinputinfo == "AT")//If Theft Alert (3 Day)
                        maxAlertDelayStr = "259200";
                    Object[] account = dbx.getAccountInfo(sessionIdstr);
                    String acntGrpAtt = "";
                    if (account != null)
                        if (account.Length > 0)
                        {
                            acntGrpAtt = account[3].ToString();//Convert.ToString(((Object[])account[0])[3]);
                        }
                    // a small change in the approach.. previously if the barfeatures contain AT then the last known state is extrated from the PANIC table for each ASSET
                    // Now we extract the panic state from the lastupdtdata for that ASSET. This also help handle large number of ASSETS in the login as well
                    // panic variable is returned in getSelectedVehiclePositions()
                    if (!acntGrpAtt.Contains("AT"))
                        panicInfo = dbx.checkPanic(endDate.AddSeconds(-Convert.ToInt32(maxAlertDelayStr)), gid, acntGrpAtt);
                    logWriter.WriteToLog("BLL:GetVehiclesInfo() PGetPanicEnd" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);

                    int pfl = 0;
                    String GpsNconnected = string.Empty;
                    String BatteryOK = string.Empty;
                    if (panicInfo != null)
                    {
                        for (pfl = 0; pfl < panicInfo.Length; pfl++)
                        {
                            if (((((Object[])panicInfo[pfl])[3]).ToString()).Equals("NO GPS SIGNAL"))
                            {
                                GpsNconnected = GpsNconnected + "|" + (((Object[])panicInfo[pfl])[0]).ToString();
                            }
                            else if (((((Object[])panicInfo[pfl])[3]).ToString()).Equals("BATTERY OK"))
                            {
                                BatteryOK = BatteryOK + "|" + (((Object[])panicInfo[pfl])[0]).ToString();
                            }
                            else if (((((Object[])panicInfo[pfl])[3]).ToString()).Equals("BATTERY LOW"))
                            {
                                BatteryOK = BatteryOK.Replace("|" + (((Object[])panicInfo[pfl])[0]).ToString(), "");
                            }
                        }
                    }


                    //the GPRS last update time can be received from lastaccess table by getDisconnectedVehicles()
                    logWriter.WriteToLog("BLL:GetVehiclesInfo() PGetDistSt" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);
                    Object[] GPRSvalues = dbx.getDisconnectedVehicles(sessionIdstr, 0);
                    logWriter.WriteToLog("BLL:GetVehiclesInfo() PGetDistEnd" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);

                    double maxSpeed = 70.0;
                    if (gid != 0)
                        maxSpeed = Convert.ToDouble(dbx.getMaxSpeed(gid));
                    int maxSpeedDisplayTime = 300;//maximum time in seconds there will be a display of non zero speed
                                                  // Get the delay for GPS and GPRS from the web.config
                    String maxGprsDelayStr = "1200";
                    String appMaxGprsDelayStr = System.Web.Configuration.WebConfigurationManager.AppSettings["MAXGPRSDELAY"];
                    if (!String.IsNullOrEmpty(appMaxGprsDelayStr))
                        maxGprsDelayStr = appMaxGprsDelayStr;

                    String maxGpsDelayStr = "240";
                    String appMaxGpsDelayStr = System.Web.Configuration.WebConfigurationManager.AppSettings["MAXGPSDELAY"];
                    if (!String.IsNullOrEmpty(appMaxGpsDelayStr))
                        maxGpsDelayStr = appMaxGpsDelayStr;
                    logWriter.WriteToLog("BLL:GetVehiclesInfo() InitEnd:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);

                    String GetPosFromVehpostxt = "true";
                    String GetPosFromVehpostxtStr = System.Web.Configuration.WebConfigurationManager.AppSettings["GetPosFromVehpostxt"];
                    if (!String.IsNullOrEmpty(GetPosFromVehpostxtStr))
                        GetPosFromVehpostxt = GetPosFromVehpostxtStr;
                    object[] PositiontxtData = null;
                    if (GetPosFromVehpostxt == "true")
                    {
                        PositiontxtData = dbx.getLatestPositiontxt(sessionIdstr);
                        logWriter.WriteToLog("BLL:GetVehiclesInfo() PosTxtNos:" + PositiontxtData.Length, true);
                    }
                    logWriter.WriteToLog("BLL:GetVehiclesInfo() PGetLoopSt" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);
                    //Added by Madhuri for making not reporting interval configurable-15122023 by default Not reporting interval is 72 hrs
                    DataTable dtNrInterval = dbx.getNRconfigurationByAccount(sessionIdstr);
                    if (dtNrInterval != null && dtNrInterval.Rows.Count > 0)
                    {
                        if (!string.IsNullOrEmpty(dtNrInterval.Rows[0]["NRInterval"].ToString()))
                        {
                            int NRInhrs = Convert.ToInt32(dtNrInterval.Rows[0]["NRInterval"]);
                            int NRintervalInSeconds = NRInhrs * 3600;
                            maxGprsDelayStr = NRintervalInSeconds.ToString();
                            maxGpsDelayStr = maxGprsDelayStr;
                        }

                    }
                    //Ended by Madhuri for making not reporting interval configurable-15122023 by default Not reporting interval is 72 hrs
                    for (int i = 0; i < selectedValues.Length; i++)
                    {
                        string vehicleId = (((Object[])selectedValues[i])[(int)headersIndex.trucksIndex]).ToString();
                        string latStr = (((Object[])selectedValues[i])[(int)headersIndex.latitudeIndex]).ToString();
                        string longStr = (((Object[])selectedValues[i])[(int)headersIndex.longitudeIndex]).ToString();
                        double speed = Convert.ToDouble(((Object[])selectedValues[i])[(int)headersIndex.speedIndex]);
                        string timestamp = (((Object[])selectedValues[i])[(int)headersIndex.timesIndex]).ToString();
                        string TempSense = (((Object[])selectedValues[i])[11]).ToString();
                        string OnOffTypeVal = (((Object[])selectedValues[i])[10]).ToString();
                        string AT_Stolen = string.Empty;

                        if (panicInfo != null && panicInfo.Length > 0)//if panic presssed then add the vehicle no to the list
                        {
                            for (int h = 0; h < panicInfo.Length; h++)
                            {
                                if ((((((Object[])panicInfo[h])[0]).ToString()).Trim()).Equals(vehicleId.Trim()))
                                {
                                    if (((((Object[])panicInfo[h])[3]).ToString()).Equals("panic"))
                                    {
                                        if ((endDate.AddSeconds(-Convert.ToInt32(maxPanicDelayStr))) < DateTime.Parse((((Object[])panicInfo[h])[1]).ToString()))
                                        {
                                            panicbuttonstr = panicbuttonstr + vehicleId + "|" + (((Object[])panicInfo[h])[1]).ToString() + "|" + "alert";
                                            panicbuttonstr = panicbuttonstr + ";";
                                        }
                                        else
                                        {
                                            panicbuttonstr = panicbuttonstr + vehicleId + "|" + (((Object[])panicInfo[h])[1]).ToString() + "|" + "store";
                                            panicbuttonstr = panicbuttonstr + ";";
                                        }
                                    }
                                    else if (((((Object[])panicInfo[h])[3]).ToString()).Equals("STOLEN"))
                                    {
                                        AT_Stolen = "Theft Alert";
                                    }
                                    else if (((((Object[])panicInfo[h])[3]).ToString()).Contains("SENT_STOPFAST_CMD"))
                                    {
                                        if (AT_Stolen.Contains("Theft Alert"))
                                            AT_Stolen = AT_Stolen + "(stop command sent)";
                                    }
                                    else if (((((Object[])panicInfo[h])[3]).ToString()).Contains("FASTTOSLOW"))
                                    {
                                        AT_Stolen = string.Empty;
                                    }
                                    else if (((((Object[])panicInfo[h])[3]).ToString()).Equals("AC"))
                                    {
                                        acAlertStr = acAlertStr + vehicleId + "|" + (DateTime.Parse((((Object[])panicInfo[h])[1]).ToString()).ToString("yyyy-MM-dd hh:mm:ss"));
