        public object[] getConfgParamsbySession(string sessionid, string vehicleid = "")
        {
            try
            {
                Object[] keyParams = dbx.getVehicleTripParams(sessionid, vehicleid);
                if (keyParams == null)
                {
                    return getDefaultConfgParams();
                }
                else if (keyParams.Length == 0)
                {
                    return getDefaultConfgParams();
                }
                return (object[])keyParams[0];
            }
            catch
            {
                return getDefaultConfgParams();
            }
            finally
            {
                dbx.close();
            }
        }
        private object[] getDefaultConfgParams()
        {
            Object[] keyParams = new Object[17];
            keyParams[0] = "0";  //shortRunDuration
            keyParams[1] = "0";  //shortRestDuration
            keyParams[2] = "0";  //longRunDuration
            keyParams[3] = "11:00 PM";   //curfewStart
            keyParams[4] = "05:00 AM";   //curfewEnd
            keyParams[5] = "70"; //maxSpeed
            keyParams[6] = "120";  //suddenAccl
            keyParams[7] = "120";  //harshBreaking
            keyParams[8] = "120";  //allowedMaxSpeedDur
            keyParams[9] = "0";  //smsflags
            keyParams[10] = "0"; //shortRunDuration2
            keyParams[11] = "0"; //shortRestDuration2
            keyParams[12] = DateTime.UtcNow.AddSeconds(timeZone); //change date
            keyParams[13] = "1000"; //routedeviation
            keyParams[14] = "540,525,510,480"; //DailyRestTime Violation Min,Record,Alert,Alarm
            keyParams[15] = "4560,4620,4500,4380"; //WeeklyRestTime  Violation Min,Record,Alert,Alarm
            keyParams[16] = "3360,3420,3540,3660"; //WeeklyRunTime  Violation Min,Record,Alert,Alarm
            keyParams[17] = "0"; //RFID KEY need to check or not
            return keyParams;
        }
