        public DataTable getViolatedVehicles(string sessionId, object[] keyParams, string nowStr, string pastStr, string durationStr)
        {
            try
            {
                logWriter.WriteToLog("BLL:getViolatedVehicles() Start:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);
                //Getting all vehicles by Session
                DataTable vehicles = GetVehiclesBySessionId(sessionId).Tables[0];
                DataTable dtViolation = new DataTable();
                dtViolation.Columns.Add("vehicleId");
                dtViolation.Columns.Add("type");
                dtViolation.Columns.Add("timestamp");
                dtViolation.Columns.Add("duration");
                dtViolation.Columns.Add("remarks");
                dtViolation.Columns.Add("location");
                dtViolation.Columns.Add("drivername");

                if (vehicles.Rows.Count == 0)
                    return dtViolation;
                String maxSpeedLocation = String.Empty;
                String maxSpeedLocationLatLng = "0,0";

                String maxAclLocation = String.Empty;
                String maxAclLocationLatLng = "0,0";

                String maxDclLocation = String.Empty;
                String maxDclLocationLatLng = "0,0";

                String maxDisConDrvgLocation = String.Empty;
                String maxDisConDrvgLocationLatLng = "0,0";

                String RouteViolatedLocation = String.Empty;
                String RouteViolatedLocationLatLng = "0,0";

                String NightDrivingLocation = String.Empty;
                String NightDrivingLocationLatLng = "0,0";


                int numSpeedViolations = 0;
                int numAclViolations = 0;
                int numDclViolations = 0;
                int numDisConDrivingViolations = 0;
                int numRouteViolations = 0;
                int numnightDrivingViolations = 0;

                int totalSpeedViolations = 0;
                int totalAclViolations = 0;
                int totalDclViolations = 0;
                //Extracting Configuration Parameters
                int shortRunDuration = Convert.ToInt32(((Object[])keyParams)[0]);
                int shortRestDuration = Convert.ToInt32(((Object[])keyParams)[1]);
                int longRunDuration = Convert.ToInt32(((Object[])keyParams)[2]);
                String curfewStartStr = (((Object[])keyParams)[3]).ToString(); // In the database it has to be given as 10:00:00 PM
                String curfewEndStr = (((Object[])keyParams)[4]).ToString(); // In the database it has to be given as 5:00:00 aM
                double maxSpeed = Convert.ToDouble(((Object[])keyParams)[5]);
                float maxAcl = Convert.ToSingle(((Object[])keyParams)[6]); 	// in m/sec.sec
                float maxDcl = Convert.ToSingle(((Object[])keyParams)[7]);	// in m/sec.sec
                int allowedMaxSpeedDur = Convert.ToInt32(((Object[])keyParams)[8]); // in secs
                Int64 smsFlags = Convert.ToInt64(((Object[])keyParams)[9]); // 3 bits denoting speed(4),accl(2),harsh braking(1)
                // Short Run Duration can be between a range so store the minimum and the maximum. shortRunDuration is the minimum
                int shortRunDuration2 = Convert.ToInt32(((Object[])keyParams)[10]);
                // short Rest Duration is also a range and shortRunDuration is the minimum
                int shortRestDuration2 = Convert.ToInt32(((Object[])keyParams)[11]);
                string IsMainPowerDisconnected = "false,";
                TimeSpan MainPowerDisDuration = new TimeSpan(0, 0, 0);
                int STOP = 1;
                timeZone = GetTimeZoneDiff(sessionId);
                DateTime now = DateTime.UtcNow.AddSeconds(timeZone);
                DateTime past = Convert.ToDateTime(pastStr);
                DateTime curfewStart = now;
                DateTime curfewEnd = now;
                try
                {
                    curfewStart = DateTime.Parse(curfewStartStr);
                    curfewEnd = DateTime.Parse(curfewEndStr);
                    if (curfewEnd < curfewStart)
                    {
                        if (now.TimeOfDay >= DateTime.Today.TimeOfDay && now.TimeOfDay <= curfewEnd.TimeOfDay)
                        {
                            curfewStart = curfewStart.AddDays(-1);
                        }
                        else
                        {
                            curfewEnd = curfewEnd.AddDays(1);
                        }
                    }
                }
                catch { }


                string accountid = GetAccountId(sessionId).ToString();

                #region Checking Vehicle Data
                for (int k = 0; k < vehicles.Rows.Count; k++)
                {
                    numSpeedViolations = 0;
                    numAclViolations = 0;
                    numDclViolations = 0;
                    numRouteViolations = 0;
                    numnightDrivingViolations = 0;
                    string vehicleId = vehicles.Rows[k][0].ToString();
                    IsMainPowerDisconnected = checkMainPowerDisconnected(vehicleId, "240");
                    DateTime MainDisConTime = DateTime.UtcNow.AddSeconds(timeZone);
                    if (IsMainPowerDisconnected.Contains("true"))
                    {
                        MainDisConTime = Convert.ToDateTime(IsMainPowerDisconnected.Split(',')[1]);
                    }
                    String actDriver = dbx.getCurrentDriver(vehicleId, sessionId, timeZone);

                    //TimeSpan diff;
                    DateTime lastUpdateTime = DateTime.MinValue;

                    if (vehicleId != null)
                    {
                        Object[] values = dbx.getRouteLatLong(vehicleId, pastStr, nowStr);
                        //Finding Min Latitude and Max Langitude
                        ArrayList lMinLat = new ArrayList();
                        ArrayList lMaxLng = new ArrayList();
                        double minLat = double.MaxValue;
                        double maxLat = double.MinValue;
                        double minLong = double.MaxValue;
                        double maxLong = double.MinValue;

                        foreach (object dr in values)
                        {
                            double lat = Convert.ToDouble(((Object[])dr)[(int)headers.latitude]);
                            double longi = Convert.ToDouble(((Object[])dr)[(int)headers.longitude]);
                            minLat = Math.Min(minLat, lat);
                            maxLat = Math.Max(maxLat, lat);
                            minLong = Math.Min(minLong, longi);
                            maxLong = Math.Max(maxLong, longi);
                        }

                        bool IsReffRoute = dbx.IsReferenceRoute(sessionId);
                        DataTable RefRoutePoints = new DataTable();
                        if (IsReffRoute)
                            RefRoutePoints = dbx.GetRoutePointsByLatitudeLongitude(minLat, minLong, maxLat, maxLong, vehicleId, accountid);

                        Object[] AclDclvalues = dbx.getAclDclLatLong(vehicleId, pastStr, nowStr);
                        float currentLatitude = 0.0F;
                        float currentLongitude = 0.0F;
                        float lastLatitude = 0.0F;
                        float lastLongitude = 0.0F;
                        DateTime lastTimeStamp = DateTime.MinValue;
                        DateTime currentTimeStamp = DateTime.MinValue;
                        TimeSpan deltaTime;
                        double currentSpeed;
                        float currentAcl = 0.0F;
                        float currentDcl = 0.0F;

                        int vehMaxSpeed = 0;
                        float vehMaxAcl = 0.0F;
                        float vehMaxDcl = 0.0F;
                        DateTime maxSpeedTs = DateTime.MinValue;
                        DateTime maxAclTs = DateTime.MinValue;
                        DateTime maxDclTs = DateTime.MinValue;
                        DateTime maxDisConDrvgTs = DateTime.MinValue;
                        DateTime routeViolationTimging = DateTime.MinValue;
                        DateTime nightDrvgTs = DateTime.MinValue;

                        int maxSpeedDur = 0;
                        Boolean curfew = false;
                        if (curfewStart < past && curfewEnd > past)
                        {
                            curfew = true;
                            //Response.Write("Curfew Start Time = " + curfewStart + " Curfew End Time = " + curfewEnd);
                        }



                        #region checking Violation for Vehicle
                        for (int i = 0; i < values.Length; i++)
                        {

                            currentLatitude = Convert.ToSingle(((Object[])values[i])[(int)headers.latitude]);
                            currentLongitude = Convert.ToSingle(((Object[])values[i])[(int)headers.longitude]);
                            currentTimeStamp = DateTime.Parse((String)(((Object[])values[i])[(int)headers.timestamp]));
                            currentSpeed = Convert.ToDouble(((Object[])values[i])[(int)headers.speed]);
                            STOP = Convert.ToInt32(((Object[])values[i])[(int)headers.stop]);

                            deltaTime = (currentTimeStamp - lastTimeStamp);
                            try
                            {
                                currentAcl = (float)(Convert.ToUInt32((((Object[])AclDclvalues[i])[1]).ToString()) * 1.852);  // convert from knots to m/sec.sec
                                currentDcl = (float)(Convert.ToUInt32((((Object[])AclDclvalues[i])[2]).ToString()) * 1.852);  // convert from knots to m/sec.sec
                            }
                            catch { currentAcl = 0; currentDcl = 0; }
                            if (currentSpeed > maxSpeed && deltaTime.TotalSeconds < 50) // if there is a gap in data then ignore
                            {

                                maxSpeedDur += (int)deltaTime.TotalSeconds;
                                if (currentSpeed > (double)vehMaxSpeed)
                                {
                                    vehMaxSpeed = (int)currentSpeed;
                                    maxSpeedLocationLatLng = currentLatitude.ToString() + "," + currentLongitude.ToString();
                                    maxSpeedLocation = getPositionTxt(currentLatitude.ToString(), currentLongitude.ToString(), 0);
                                    maxSpeedTs = currentTimeStamp;
                                }
                                if (maxSpeedDur > allowedMaxSpeedDur)
                                {
                                    numSpeedViolations++;
                                    maxSpeedDur = 0;
                                }
                            }
                            else
                                maxSpeedDur = 0;
                            if (currentAcl > maxAcl)
                            {
                                numAclViolations++;
                                if (currentAcl > vehMaxAcl)
                                {
                                    vehMaxAcl = currentAcl;
                                    maxAclLocationLatLng = currentLatitude.ToString() + "," + currentLongitude.ToString();
                                    maxAclLocation = getPositionTxt(currentLatitude.ToString(), currentLongitude.ToString(), 0);
                                    maxAclTs = currentTimeStamp;
                                }
                            }
                            if (currentDcl > maxDcl)
                            {
                                numDclViolations++;
                                if (currentDcl > (double)vehMaxDcl)
                                {
                                    vehMaxDcl = currentDcl;
                                    maxDclLocationLatLng = currentLatitude.ToString() + "," + currentLongitude.ToString();
                                    maxDclLocation = getPositionTxt(currentLatitude.ToString(), currentLongitude.ToString(), 0);
                                    maxDclTs = currentTimeStamp;
                                }
                            }
                            if (IsMainPowerDisconnected.Contains("true") && STOP == 0 && currentSpeed > 5)
                            {
                                if (MainDisConTime >= currentTimeStamp)
                                {
                                    MainPowerDisDuration = MainPowerDisDuration.Add(deltaTime);
                                    if (MainPowerDisDuration.TotalMinutes > 3)
                                    {
                                        numDisConDrivingViolations++;
                                        maxDisConDrvgLocationLatLng = currentLatitude.ToString() + "," + currentLongitude.ToString();
                                        maxDisConDrvgLocation = getPositionTxt(currentLatitude.ToString(), currentLongitude.ToString(), 0);
                                        maxDisConDrvgTs = currentTimeStamp;
                                    }
                                }
                            }
                            if (IsReffRoute)
                            {
                                var IsVoliated = from DataRow myRow in RefRoutePoints.Rows
                                                 where (double)myRow["minlat"] >= currentLatitude && (double)myRow["minlong"] >= currentLongitude && (double)myRow["maxlat"] <= currentLatitude && (double)myRow["maxlong"] <= currentLongitude
                                                 select myRow;
                                if (IsVoliated == null)
                                {
                                    numRouteViolations++;
                                    RouteViolatedLocationLatLng = currentLatitude.ToString() + "," + currentLongitude.ToString();
                                    RouteViolatedLocation = getPositionTxt(currentLatitude.ToString(), currentLongitude.ToString(), 0);
                                    routeViolationTimging = currentTimeStamp;
                                    break;
                                }
                            }
                            if (curfew && now > curfewEnd && STOP == 0 && currentSpeed > 5)
                            {
                                curfew = false;
                                numnightDrivingViolations++;
                                NightDrivingLocationLatLng = currentLatitude.ToString() + "," + currentLongitude.ToString();
                                NightDrivingLocation = getPositionTxt(currentLatitude.ToString(), currentLongitude.ToString(), 0);
                                nightDrvgTs = currentTimeStamp;
                            }
                            lastLatitude = currentLatitude;
                            lastLongitude = currentLongitude;
                            lastTimeStamp = currentTimeStamp;
                        }
                        #endregion


                        try
                        {

                            #region Storing Violation
                            if (numSpeedViolations > 0 || numAclViolations > 0 || numDclViolations > 0 || numRouteViolations > 0 || numnightDrivingViolations > 0)
                            {
                                DataRow row = dtViolation.NewRow();
                                if (numSpeedViolations > 0)
                                {
                                    string remarks = "Max Speed - " + vehMaxSpeed;
                                    dbx.storeVehicleViolations(vehicleId, actDriver, "OVERSPEEDING", dbx.formatDBDate(maxSpeedTs), numSpeedViolations, remarks, maxSpeedLocation, maxSpeedLocationLatLng.Split(',')[0], maxSpeedLocationLatLng.Split(',')[1]);
                                    dtViolation.Rows.Add(new Object[] { vehicleId, "OVERSPEEDING", dbx.formatDBDate(maxSpeedTs), numSpeedViolations, remarks, maxSpeedLocation, actDriver });

                                }
                                //if (numAclViolations > 0)
                                //{
                                //    string remarks = "Max Acceleration - " + vehMaxAcl;
                                //    dbx.storeVehicleViolations(vehicleId, actDriver, "HIGH ACCELERATION", dbx.formatDBDate(maxAclTs), numAclViolations, remarks, maxAclLocation, maxAclLocationLatLng.Split(',')[0],maxAclLocationLatLng.Split(',')[1]);
                                //    dtViolation.Rows.Add(new Object[] { vehicleId, "HIGH ACCELERATION", dbx.formatDBDate(maxAclTs), numAclViolations, remarks, maxAclLocation, actDriver });

                                //}
                                //if (numDclViolations > 0)
                                //{
                                //    string remarks = "Harsh Braking - " + vehMaxDcl;
                                //    dbx.storeVehicleViolations(vehicleId, actDriver, "HARSH BRAKING", dbx.formatDBDate(maxDclTs), numDclViolations, remarks, maxDclLocation, maxDclLocationLatLng.Split(',')[0],maxDclLocationLatLng.Split(',')[1]);
                                //    dtViolation.Rows.Add(new Object[] { vehicleId, "HARSH BRAKING", dbx.formatDBDate(maxDclTs), numDclViolations, remarks, maxDclLocation, actDriver });

                                //}
                                if (numDisConDrivingViolations > 0)
                                {
                                    string remarks = "Driving - " + MainPowerDisDuration.TotalMinutes;
                                    dbx.storeVehicleViolations(vehicleId, actDriver, "MAIN DISCONNECTED DRIVING", dbx.formatDBDate(maxDisConDrvgTs), MainPowerDisDuration.TotalMinutes, remarks, maxDisConDrvgLocation, maxDisConDrvgLocationLatLng.Split(',')[0], maxDisConDrvgLocationLatLng.Split(',')[1]);
                                    dtViolation.Rows.Add(new Object[] { vehicleId, "MAIN DISCONNECTED DRIVING", dbx.formatDBDate(maxDisConDrvgTs), MainPowerDisDuration.TotalMinutes, remarks, maxDisConDrvgLocation, actDriver });
                                }
                                if (numRouteViolations > 0)
                                {
                                    string remarks = "Route Violation On -" + routeViolationTimging;
                                    dbx.storeVehicleViolations(vehicleId, actDriver, "ROUTE DEVIATION", dbx.formatDBDate(routeViolationTimging), numRouteViolations, remarks, RouteViolatedLocation, RouteViolatedLocationLatLng.Split(',')[0], RouteViolatedLocationLatLng.Split(',')[1]);
                                    dtViolation.Rows.Add(new Object[] { vehicleId, "ROUTE DEVIATION", dbx.formatDBDate(routeViolationTimging), numRouteViolations, remarks, RouteViolatedLocation, actDriver });
                                }
                                if (numnightDrivingViolations > 0)
                                {
                                    string remarks = "NIGHT DRIVING";
                                    dbx.storeVehicleViolations(vehicleId, actDriver, "NIGHT DRIVING", dbx.formatDBDate(nightDrvgTs), 0, remarks, NightDrivingLocation, NightDrivingLocationLatLng.Split(',')[0], NightDrivingLocationLatLng.Split(',')[1]);
                                    dtViolation.Rows.Add(new Object[] { vehicleId, "NIGHT DRIVING", dbx.formatDBDate(nightDrvgTs), 0, remarks, NightDrivingLocation, actDriver });
                                }

                            }
                            #endregion
                        }
                        catch { }
                    }

                    totalSpeedViolations += numSpeedViolations;
                    totalAclViolations += numAclViolations;
                    totalDclViolations += numDclViolations;
                }
                #endregion
                logWriter.WriteToLog("BLL:getViolatedVehicles() End:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);

                return dtViolation;
            }
            catch { return null; }
        }
        public string checkMainPowerDisconnected(string vehicleid, string duration)
        {
            object[] discon = dbx.checkMainPowerConnection(vehicleid, duration);
            string IsDisCon = "false,";
            int count = 0;
            for (int i = 0; discon.Length > i; i++)
            {
                object[] row = (object[])discon[i];
                if (row[0].ToString() == "MAIN DISCONNECTED")
                {
                    IsDisCon = "true," + row[1].ToString();
                    count++;
                }
                else
                {
                    IsDisCon = "false,";
                    count++;
                }

            }
            if (count > 10)
            {
                IsDisCon = "false,";
            }
            return IsDisCon;

        }
