            logWriter.WriteToLog("BLL:UpdateVehicleinplant() Start:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);

            DataRow[] value = dbx.GetOuttimedoneNull(fromdata, todate);
