        public class vehicleinplant
        {
            public string vehicle { get; set; }
            public string locationstring { get; set; }
            public string timestamp { get; set; }

        };
        public List<vehicleinplant> GetvehicleinplantUpdates(DataRow[] value, string FromDate = "", string ToDate = "")
        {
            logWriter.WriteToLog("BLL:GetvehicleinplantUpdates() Start:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);

            List<vehicleinplant> updatingvalues = new List<vehicleinplant>();
            double minlat = 0.00;
            double minlng = 0.00;
            double maxlat = 0.00;
            double maxlng = 0.00;
            string fromdate = "";
            string todate = "";
            for (int i = 0; i < value.Length; i++)
            {
                if (FromDate == "" && ToDate == "")
                {
                    timeZone = dbx.GetTimeZoneDiff();
                    DateTime indianTime = DateTime.UtcNow;
                    indianTime = indianTime.AddSeconds(timeZone);
                    todate = dbx.formatDBDate(indianTime);
                    fromdate = dbx.formatDBDate(indianTime.AddMinutes(-1440));
                    minlat = Convert.ToDouble(value[i].ItemArray[3]);
                    minlng = Convert.ToDouble(value[i].ItemArray[4]);
                    maxlat = Convert.ToDouble(value[i].ItemArray[5]);
                    maxlng = Convert.ToDouble(value[i].ItemArray[6]);
                    TimeSpan differenceintime = (Convert.ToDateTime(todate) - Convert.ToDateTime(value[i].ItemArray[2].ToString()));
                    int timediff = differenceintime.Days;
                    if (timediff < 2)
                        fromdate = dbx.formatDBDate(Convert.ToDateTime(value[i].ItemArray[2]));
                }
                else
                {
                    fromdate = FromDate;
                    todate = ToDate;
                }
                if (minlat != 0.0 && minlng != 0.0 && maxlat != 0.0 && maxlng != 0.0)
                {
                    DataSet valuespositiondata = dbx.GetFirstOutTimeFromPlant(value[i].ItemArray[0].ToString(), fromdate, todate, minlat, minlng, maxlat, maxlng);

                    if (valuespositiondata.Tables[0].Rows.Count > 0)
                    {
                        var val = new vehicleinplant()
                        {
                            vehicle = value[i].ItemArray[0].ToString(),
                            locationstring = value[i].ItemArray[1].ToString(),
                            timestamp = dbx.formatDBDate(DateTime.Parse(valuespositiondata.Tables[0].Rows[0]["TimeStamp"].ToString())),
                        };

                        updatingvalues.Add(val);

                    }
                }
            }
            logWriter.WriteToLog("BLL:GetvehicleinplantUpdates() End:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);

            return (updatingvalues);
        }

