        public string FindandUpdateNextDueDate(string checkdate)
        {
            DataTable dt = dbx.getDueDateRemainders(checkdate);
            int Updated = 0;
            for (int i = 0; i < dt.Rows.Count; i++)
            {
                string RepeatFlag = dt.Rows[i]["IsRepeat"].ToString();
                if (RepeatFlag == "True")
                {
                    DateTime CurDueDate = Convert.ToDateTime(dt.Rows[i]["DueDate"].ToString());
                    DateTime CurNextDueDate = Convert.ToDateTime(dt.Rows[i]["NextDueDate"].ToString());
                    DateTime NxtDueDate = CurNextDueDate;
                    string RemType = dt.Rows[i]["RemainderType"].ToString();
                    int RepeatForEvery = Convert.ToInt32(dt.Rows[i]["RepeatForEvery"].ToString());
                    int RepeatationType = Convert.ToInt32(dt.Rows[i]["RepeatationPeriodIn"].ToString());
                    //RepeatationType is 0=Years,1=Months,2=Weeks,3=Days
                    DateTime NxtNextDueDate = CurNextDueDate.AddMonths(RepeatForEvery);//In Months Default (1)
                    if (RepeatationType == 0)  //In Years
                    {
                        NxtNextDueDate = CurNextDueDate.AddYears(RepeatForEvery);
                    }
                    else if (RepeatationType == 2) //In Weeks
                    {
                        NxtNextDueDate = CurNextDueDate.AddDays(RepeatForEvery * 7);
                    }
                    else if (RepeatationType == 3) //In Days
                    {
                        NxtNextDueDate = CurNextDueDate.AddDays(RepeatForEvery);
                    }
                    dbx.UpdateNextDueDateRemainder(dt.Rows[i]["Id"].ToString(), CurDueDate.ToString("yyyy-MM-dd"), NxtDueDate.ToString("yyyy-MM-dd"), NxtNextDueDate.ToString("yyyy-MM-dd"));
                    Updated++;
                }
            }
            return dt.Rows.Count.ToString() + ":" + Updated.ToString();

        }
