        public string UpdateDistanceForServiceReminder()
        {
            DataTable dt = dbx.getAllRepeatingServiceRemainders();
            for (int i = 0; i < dt.Rows.Count; i++)
            {
                string VehicleId = dt.Rows[i]["VehicleId"].ToString();
                string lastupdated = Convert.ToDateTime(dt.Rows[i]["LastUpdatedDistanceOn"].ToString()).ToString("yyyy-MM-dd HH:mm:ss");
                string currenttime = DateTime.UtcNow.AddSeconds(timeZone).ToString("yyyy-MM-dd HH:mm:ss");
                Object[] ret = accumulateDistance(VehicleId, lastupdated, currenttime, null);
                double distance = (double)ret[0];
                double CurrentDistance = Convert.ToInt32(dt.Rows[i]["CurrentDistance"].ToString());

                dbx.UpdateCurrentDistance(dt.Rows[i]["Id"].ToString(), (CurrentDistance + distance), currenttime);
            }
            return dt.Rows.Count.ToString();

        }
