        public double GetTimeDiffBetweeninAndpreviousOut(string vehicleid, string inorout)
        {
            double timediff = 0;
            try
            {
                TimeSpan timediffmin = new TimeSpan(0);
                DataRow[] dates = dbx.GetTimeDiffBetweeninAndpreviousOut(vehicleid);
                if (dates.Length >= 2)
                {
                    if (inorout == "in")
                    {
                        try
                        {
                            if (dates[0].ItemArray[0].ToString() != "" && dates[1].ItemArray[1].ToString() != "")
                                timediffmin = Convert.ToDateTime(dates[0].ItemArray[0]).Subtract(Convert.ToDateTime(dates[1].ItemArray[1]));
                            else if (dates[0].ItemArray[0].ToString() != "" && dates[1].ItemArray[0].ToString() != "")
                                timediffmin = Convert.ToDateTime(dates[0].ItemArray[0]).Subtract(Convert.ToDateTime(dates[1].ItemArray[0]));
                        }
                        catch
                        {
                            timediffmin = Convert.ToDateTime(dates[0].ItemArray[0]).Subtract(Convert.ToDateTime(dates[1].ItemArray[0]));
                        }
                        timediff = (timediffmin.Hours * 60) + (timediffmin.Minutes);
                    }
                    else if (inorout == "out")
                    {
                        try
                        {
                            if (dates[0].ItemArray[1].ToString() != "" && dates[0].ItemArray[0].ToString() != "")
                                timediffmin = Convert.ToDateTime(dates[0].ItemArray[1]).Subtract(Convert.ToDateTime(dates[0].ItemArray[0]));
                            else if (dates[0].ItemArray[0].ToString() != "" && dates[1].ItemArray[1].ToString() != "")
                                timediffmin = Convert.ToDateTime(dates[0].ItemArray[0]).Subtract(Convert.ToDateTime(dates[1].ItemArray[1]));
                        }
                        catch
                        {
                            timediffmin = Convert.ToDateTime(dates[0].ItemArray[0]).Subtract(Convert.ToDateTime(dates[1].ItemArray[1]));

                        }
                        timediff = (timediffmin.Hours * 60) + (timediffmin.Minutes);
                    }
                }
            }
            catch { }
            return timediff;
        }
