        public dynamic GetShowPosition_qry(string sSessionId)
        {
            logWriter.WriteToLog("BLL:GetShowPosition_qry() Start:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);
            Common objCommon = new Common();
            DateTime dCurrentUTC = DateTime.UtcNow;
            timeZone = GetTimeZoneDiff(sSessionId);
            dCurrentUTC = dCurrentUTC.AddSeconds(timeZone);
            string sCurrentDateTime = formatDBDate(dCurrentUTC);

            string maxAlertDelayStr = System.Web.Configuration.WebConfigurationManager.AppSettings["MAXALERTDELAY"];
            if (string.IsNullOrEmpty(maxAlertDelayStr))
                maxAlertDelayStr = "3600";

            string maxPanicDelayStr = System.Web.Configuration.WebConfigurationManager.AppSettings["MAXPANICPRESSEDDELAY"];
            if (string.IsNullOrEmpty(maxPanicDelayStr))
                maxPanicDelayStr = "180";

            string maxGprsDelayStr = System.Web.Configuration.WebConfigurationManager.AppSettings["MAXGPRSDELAY"];
            if (string.IsNullOrEmpty(maxGprsDelayStr))
                maxGprsDelayStr = "1200";

            string maxGpsDelayStr = System.Web.Configuration.WebConfigurationManager.AppSettings["MAXGPSDELAY"];
            if (string.IsNullOrEmpty(maxGpsDelayStr))
                maxGpsDelayStr = "240";

            int maxSpeedDisplayTime = 300;//maximum time in seconds there will be a display of non zero speed

            DataSet ds = dbx.ShowPositions_qry_backup(sSessionId, sCurrentDateTime, maxAlertDelayStr, maxPanicDelayStr, maxGprsDelayStr, maxGpsDelayStr, Convert.ToString(maxSpeedDisplayTime));

            if (ds.Tables[0].Rows.Count <= 0)
                ds = dbx.ShowPositions_qry(sSessionId, sCurrentDateTime, maxAlertDelayStr, maxPanicDelayStr, maxGprsDelayStr, maxGpsDelayStr, Convert.ToString(maxSpeedDisplayTime));

            DataSet dsPanic = dbx.GetPanicDetail(sSessionId, sCurrentDateTime, maxAlertDelayStr);

            var result = (from dataRows1 in ds.Tables[0].AsEnumerable()
                          join dataRows2 in dsPanic.Tables[0].AsEnumerable()
                          on dataRows1.Field<string>("VehicleId") equals dataRows2.Field<string>("VehicleId") into joinData
                          from r in joinData.DefaultIfEmpty()
                          select new VehiclesInfo
                          {
                              VehicleID = dataRows1.Field<string>("VehicleId"),
                              GroupId = dataRows1.Field<long>("GroupId"),
                              LastGprsTimeStamp = dataRows1.Field<string>("LastGprsTimeStamp"),
                              DateTime = dataRows1.Field<string>("LastGprsTimeStamp").Split(',')[0],
                              Time = dataRows1.Field<string>("LastGprsTimeStamp").Split(',')[1],
                              GprsActiveTime = dataRows1.Field<long>("GprsActiveTime"),
                              GprsDelay = dataRows1.Field<string>("GprsDelay"),
                              GpsDelay = dataRows1.Field<string>("GpsDelay"),
                              MaxSpeedDisplayTime = dataRows1.Field<string>("MaxSpeedDisplayTime"),
                              latitude = dataRows1.Field<decimal>("latitude"),
                              longitude = dataRows1.Field<decimal>("longitude"),
                              Speed = dataRows1.Field<string>("Speed"),
                              timestamp = dataRows1.Field<long>("timestamp"),
                              VehicleInfo = dataRows1.Field<string>("VehicleInfo"),
                              Stop = dataRows1.Field<short>("Stop"),
                              OnOffType = dataRows1.Field<string>("OnOffType"),
                              TempSense = dataRows1.Field<string>("TempSense"),
                              MaxSpeed = dataRows1.Field<decimal>("MaxSpeed"),
                              alertTimestamp = r == null ? "" : r.Field<string>("alertTimestamp"),
                              PanicType = r == null ? "" : r.Field<string>("PanicType"),
                              Alert = r == null ? "" : r.Field<string>("Alert"),
                              PanicTypeAndAlertTimeStamp = r == null ? "" : r.Field<string>("PanicTypeAndAlertTimeStamp"),
                              VehicleStatus = (
                                   dataRows1.Field<long>("GprsActiveTime") < Convert.ToInt64(dataRows1.Field<string>("GprsDelay")) ?
                                   Convert.ToInt64(dataRows1.Field<short>("Stop")) == 1 || Convert.ToDecimal(dataRows1.Field<string>("Speed")) <= 3 ?
                                   "Vehicle Halted"
                                   :
                                   Convert.ToDecimal(dataRows1.Field<string>("Speed")) > dataRows1.Field<decimal>("MaxSpeed") ?
                                   "Over Speeding"
                                   :
                                   "Vehicle Moving"
                                   :
                                   "Not Reachable"
                               ),
                              Location = GetVehicleLocation(dataRows1.Field<string>("VehicleId"), sCurrentDateTime, Convert.ToDouble(dataRows1.Field<string>("Speed")), Convert.ToDouble(dataRows1.Field<decimal>("MaxSpeed")), Convert.ToString(dataRows1.Field<decimal>("latitude")), Convert.ToString(dataRows1.Field<decimal>("longitude"))),
                              IdlingInstance = (
                                  dataRows1.Field<string>("OnOffType") == "NC" ? " " :
                                  getOnOffIdlingInstances(dataRows1.Field<string>("VehicleId")) == "1" ? " " + dataRows1.Field<string>("OnOffType") + " " + "ON" : " " + dataRows1.Field<string>("OnOffType") + " " + "OFF"
                              )
                          }).ToList();

            result.ForEach(x =>
            {
                x.Remarks = objCommon.ReplaceLastOccurrence(objCommon.ReplaceFirstOccurrence(x.Alert + "," + x.VehicleStatus + "," + x.IdlingInstance, ",", ""), ",", "");
                x.Status = GetStatus(x.IdlingInstance + "," + x.Alert + "," + x.VehicleStatus);

            });

            logWriter.WriteToLog("BLL:GetShowPosition_qry() End:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);

            return result;
            //List<UserGroup> GroupIdList = (List<UserGroup>)DataFiller.ConvertTo<UserGroup>(dbx.GetGroupId(sSessionId, sCurrentDateTime, maxAlertDelayStr, maxPanicDelayStr, maxGprsDelayStr, maxGpsDelayStr, Convert.ToString(maxSpeedDisplayTime)).Tables[0]);

            //List<LastPosition> LastPositionList = (List<LastPosition>)DataFiller.ConvertTo<LastPosition>(dbx.GetLastPosition(sSessionId, sCurrentDateTime).Tables[0]);

        }

        public DataTable GetShowPosition_qry_Linq(string sSessionId)
        {
            logWriter.WriteToLog("BLL:GetShowPosition_qry_Linq() Start:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);
            Common objCommon = new Common();
            DateTime dCurrentUTC = DateTime.UtcNow;
            timeZone = GetTimeZoneDiff(sSessionId);
            dCurrentUTC = dCurrentUTC.AddSeconds(timeZone);
            string sCurrentDateTime = formatDBDate(dCurrentUTC);

            string maxAlertDelayStr = System.Web.Configuration.WebConfigurationManager.AppSettings["MAXALERTDELAY"];
            if (string.IsNullOrEmpty(maxAlertDelayStr))
                maxAlertDelayStr = "3600";

            string maxPanicDelayStr = System.Web.Configuration.WebConfigurationManager.AppSettings["MAXPANICPRESSEDDELAY"];
            if (string.IsNullOrEmpty(maxPanicDelayStr))
                maxPanicDelayStr = "180";

            string maxGprsDelayStr = System.Web.Configuration.WebConfigurationManager.AppSettings["MAXGPRSDELAY"];
            if (string.IsNullOrEmpty(maxGprsDelayStr))
                maxGprsDelayStr = "1200";

            string maxGpsDelayStr = System.Web.Configuration.WebConfigurationManager.AppSettings["MAXGPSDELAY"];
            if (string.IsNullOrEmpty(maxGpsDelayStr))
                maxGpsDelayStr = "240";

            int maxSpeedDisplayTime = 300;//maximum time in seconds there will be a display of non zero speed

            DataSet ds = dbx.ShowPositions_qry_backup(sSessionId, sCurrentDateTime, maxAlertDelayStr, maxPanicDelayStr, maxGprsDelayStr, maxGpsDelayStr, Convert.ToString(maxSpeedDisplayTime));

            if (ds.Tables[0].Rows.Count <= 0)
                ds = dbx.ShowPositions_qry(sSessionId, sCurrentDateTime, maxAlertDelayStr, maxPanicDelayStr, maxGprsDelayStr, maxGpsDelayStr, Convert.ToString(maxSpeedDisplayTime));

            DataSet dsPanic = dbx.GetPanicDetail(sSessionId, sCurrentDateTime, maxAlertDelayStr);

            DataTable dt = new DataTable();

            dt.Columns.Add("VehicleID", typeof(string));
            dt.Columns.Add("GroupId", typeof(long));
            dt.Columns.Add("LastGprsTimeStamp", typeof(string));
            dt.Columns.Add("DateTime", typeof(string));
            dt.Columns.Add("Time", typeof(string));
            dt.Columns.Add("GprsActiveTime", typeof(long));
            dt.Columns.Add("GprsDelay", typeof(string));
            dt.Columns.Add("GpsDelay", typeof(string));
            dt.Columns.Add("MaxSpeedDisplayTime", typeof(string));
            dt.Columns.Add("latitude", typeof(decimal));
            dt.Columns.Add("longitude", typeof(decimal));
            dt.Columns.Add("Speed", typeof(string));
            dt.Columns.Add("timestamp", typeof(long));
            dt.Columns.Add("VehicleInfo", typeof(string));
            dt.Columns.Add("Stop", typeof(short));
            dt.Columns.Add("OnOffType", typeof(string));
            dt.Columns.Add("TempSense", typeof(string));
            dt.Columns.Add("MaxSpeed", typeof(decimal));
            dt.Columns.Add("alertTimestamp", typeof(string));
            dt.Columns.Add("PanicType", typeof(string));
            dt.Columns.Add("Alert", typeof(string));
            dt.Columns.Add("PanicTypeAndAlertTimeStamp", typeof(string));
            dt.Columns.Add("VehicleStatus", typeof(string));
            dt.Columns.Add("Location", typeof(string));
            dt.Columns.Add("IdlingInstance", typeof(string));

            // //http://stepbystepdotnet.wordpress.com/2012/09/13/how-to-join-two-data-tables-in-c-without-using-loop-in-linq/

            var result = from dataRows1 in ds.Tables[0].AsEnumerable()
                         join dataRows2 in dsPanic.Tables[0].AsEnumerable()
                         on dataRows1.Field<string>("VehicleId") equals dataRows2.Field<string>("VehicleId") into joinData
                         from r in joinData.DefaultIfEmpty()
                         select dt.LoadDataRow(new object[]
                         {
                         dataRows1.Field<string>("VehicleId"),
                         dataRows1.Field<long>("GroupId"),
                         dataRows1.Field<string>("LastGprsTimeStamp"),
                         dataRows1.Field<string>("LastGprsTimeStamp").Split(',')[0],
                         dataRows1.Field<string>("LastGprsTimeStamp").Split(',')[1],
                         dataRows1.Field<long>("GprsActiveTime"),
                         dataRows1.Field<string>("GprsDelay"),
                         dataRows1.Field<string>("GpsDelay"),
                         dataRows1.Field<string>("MaxSpeedDisplayTime"),
                         dataRows1.Field<decimal>("latitude"),
                         dataRows1.Field<decimal>("longitude"),
                         dataRows1.Field<string>("Speed"),
                         dataRows1.Field<long>("timestamp"),
                         dataRows1.Field<string>("VehicleInfo"),
                         dataRows1.Field<short>("Stop"),
                         dataRows1.Field<string>("OnOffType"),
                         dataRows1.Field<string>("TempSense"),
                         dataRows1.Field<decimal>("MaxSpeed"),
                         r == null ? "" : r.Field<string>("alertTimestamp"),
                         r == null ? ""  :r.Field<string>("PanicType"),
                         r == null ? ""  :r.Field<string>("Alert"),
                         r == null ? ""  :r.Field<string>("PanicTypeAndAlertTimeStamp"),
                          (
                              dataRows1.Field<long>("GprsActiveTime") < Convert.ToInt64(dataRows1.Field<string>("GprsDelay")) ?
                              Convert.ToInt64(dataRows1.Field<short>("Stop")) ==1 || Convert.ToDecimal(dataRows1.Field<string>("Speed")) <= 3 ?
                              "Vehicle Halted"
                              :
                              Convert.ToDecimal(dataRows1.Field<string>("Speed")) > dataRows1.Field<decimal>("MaxSpeed") ?
                              "Over Speeding"
                              :
                              "Vehicle Moving"
                              :
                              "Not Reachable"
                          ),
                          GetVehicleLocation(dataRows1.Field<string>("VehicleId"),sCurrentDateTime,Convert.ToDouble(dataRows1.Field<string>("Speed")),Convert.ToDouble(dataRows1.Field<decimal>("MaxSpeed")),Convert.ToString(dataRows1.Field<decimal>("latitude")),Convert.ToString(dataRows1.Field<decimal>("longitude"))),
                          (
                              dataRows1.Field<string>("OnOffType")=="NC"? " ":
                              getOnOffIdlingInstances(dataRows1.Field<string>("VehicleId")) =="1" ? " "+dataRows1.Field<string>("OnOffType") +" "+"ON" :" "+dataRows1.Field<string>("OnOffType") +" "+"OFF"
                          )

                         }, false);



            result.CopyToDataTable();
            logWriter.WriteToLog("BLL:GetShowPosition_qry_Linq() End:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);

            return dt;

        }

