                //                  getOnOffIdlingInstances(Convert.ToString(dr_qry["VehicleId"])) == "1" ? dr_qry["OnOffType"] + " " + "ON" : dr_qry["OnOffType"] + " " + "OFF"
                //              );

                //dr_qry["Remarks"] = objCommon.ReplaceLastOccurrence(objCommon.ReplaceFirstOccurrence(dr_qry["Alert"] + ", " + dr_qry["VehicleStatus"] + ", " +dr_qry["IdlingInstance"], ",", ""), ",", "");
                //dr_qry["Status"] = GetStatus(dr_qry["IdlingInstance"] + "," + dr_qry["Alert"] + "," + dr_qry["VehicleStatus"]);

                row = new Dictionary<string, object>();
                foreach (DataColumn col in ds.Tables["dtqry"].Columns)
                {
                    row.Add(col.ColumnName, dr_qry[col]);
                }
                row.Add("VehicleID", Convert.ToString(dr_qry["VehicleId"]));
                row.Add("DateTime", Convert.ToString(dr_qry["LastGprsTimeStamp"]).Split(',')[0]);
                row.Add("Time", Convert.ToString(dr_qry["LastGprsTimeStamp"]).Split(',')[1]);
                row.Add("VehicleStatus", (Convert.ToInt64(dr_qry["GprsActiveTime"]) < Convert.ToInt64(dr_qry["GprsDelay"]) ?
                                  (Convert.ToInt64(dr_qry["Stop"]) == 1 || Convert.ToDecimal(dr_qry["Speed"]) <= 3) ?
                                  "Vehicle Halted"
                                  :
                                  Convert.ToDecimal(dr_qry["Speed"]) > Convert.ToDecimal(dr_qry["MaxSpeed"]) ?
                                  "Over Speeding"
                                  :
                                  "Vehicle Moving"
                                  :
                                  "Not Reachable"
                              ));
                row.Add("Location", GetVehicleLocation(Convert.ToString(dr_qry["VehicleId"]), sCurrentDateTime, Convert.ToDouble(dr_qry["Speed"]), Convert.ToDouble(dr_qry["MaxSpeed"]), Convert.ToString(dr_qry["latitude"]), Convert.ToString(dr_qry["longitude"])));

                if (Convert.ToString(dr_qry["OnOffType"]).Contains("NC"))
                    row.Add("IdlingInstance", "");
                else
                    row.Add("IdlingInstance", (
                                      getOnOffIdlingInstances(Convert.ToString(dr_qry["VehicleId"])) == "1" ? " " + dr_qry["OnOffType"] + " " + "ON" : " " + dr_qry["OnOffType"] + " " + "OFF"
                                  ));

                object sAlter;
                object sVehicleStatus;
                object sIdlingInstance;
                row.TryGetValue("Alert", out sAlter);
                row.TryGetValue("VehicleStatus", out sVehicleStatus);
                row.TryGetValue("IdlingInstance", out sIdlingInstance);

                row.Add("Remarks", objCommon.ReplaceLastOccurrence(objCommon.ReplaceFirstOccurrence(sAlter + "," + sVehicleStatus + "," + sIdlingInstance, ",", ""), ",", ""));
                row.Add("Status", GetStatus(sIdlingInstance + "," + sAlter + "," + sVehicleStatus));

                rows.Add(row);
            }

            //return  ds.Tables["dtqry"]; 
            logWriter.WriteToLog("BLL:GetShowPosition_qry_dt() End:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);

            return rows;

        }

        public string GetVehicleLocation(string vehicleId, string sCurrentDateTime, double speed, double maxSpeed, string slat, string slong)
        {
            string[] directions = { "right", "tr", "top", "tl", "left", "dl", "down", "dr" };
            int arrow = getLastDirection(vehicleId, sCurrentDateTime);
            string sDirections = "";
            if (arrow != -1)
            {
                if (speed > maxSpeed)
                {
                    sDirections = "fast_" + directions[arrow];
                }
                else
                {
                    sDirections = "run_" + directions[arrow];
                }
            }
            return getPositionTxt(slat, slong, arrow);

        }
        public static string GetStatus(string remark)
        {
            if (remark.Contains("Tipper ON") || remark.Contains("Battery Low"))
                return "<img src=\"images/pink.gif\" height=\"36\" width=\"36\" align=\"center\"/>";
            if (remark.Contains("Vehicle Halted"))
                return "<img src=\"images/redstop.png\" height=\"36\" width=\"36\" align=\"center\"/>";
            else if (remark.Contains("Not Reachable"))
                return "<img src=\"images/black.png\" height=\"36\" width=\"36\" align=\"center\"/>";
            else if (remark.Contains("GPS Not Active"))
                return "<img src=\"images/grey.png\" height=\"36\" width=\"36\" align=\"center\"/>";
            else if (remark.Contains("Vehicle Moving"))
                return "<img src=\"images/greengif.gif\" height=\"36\" width=\"36\" align=\"center\"/>";
            else if (remark.Contains("panic") || remark.Contains("Panic"))
                return "<img src=\"images/red.gif\" height=\"36\" width=\"36\" align=\"center\"/>";
            if (remark.Contains("Over Speeding"))
                return "<img src=\"images/yellow.png\" height=\"36\" width=\"36\" align=\"center\"/>";

            else return null;

        }
