        public string writeHaltXML(string vehicleid, string fromdate, string todate, string haltDurationStr)
        {
            /***********************************************************************************
             * ********************* HTML CODE *************************************************
             * *********************************************************************************
             * Response.Write("<table class='routeReport'>\n");
            Response.Write("<tr><th class='tableHeader'>Date"
                          + "</th><th class='tableHeader'>Time"
                          + "</th><th class='tableHeader'>Location"
                          + "</th><th class='tableHeader'>Remarks</th></tr>\n");
             ************************************************************************************/
            int count = 0;
            Object[] values = dbx.getRouteLatLong(vehicleid, fromdate, todate);
            //string xmlString = "<?xml version=" + "\"1.0\"" + " encoding=" + "\"UTF-8\"" + "?>";
            string xmlString = "";
            xmlString = xmlString + "<HaltsReport>";
            int cnt = 0;
            DateTime lastTS = DateTime.MinValue;
            int minHaltDuration = Convert.ToInt16(haltDurationStr);
            for (int i = 0; i < values.Length; i++)
            {
                Object[] haltInfoList = showHalt2(i, values, true, minHaltDuration);
                if (haltInfoList != null)
                {
                    for (int k = 0; k < haltInfoList.Length; k++)
                    {
                        String[] haltInfo = (String[])haltInfoList[k];
                        /*********************************************************************
                         * *******************HTML CODE***************************************
                         * *******************************************************************
                             Response.Write("<tr><td class='position'>" + haltInfo[0]
                           + "</td><td class='position'>" + haltInfo[1]
                           + "</td><td class='position'>" + haltInfo[2] 
                           + "</td><td class='position'>" + haltInfo[3] + "</td></tr>\n");
                         *********************************************************************/


                        if (!String.IsNullOrEmpty(haltInfo[3]))
                        {
                            count++;
                            xmlString = xmlString + "<Halt" + count + ">";
                            xmlString = xmlString + "<Date>" + Convert.ToDateTime(haltInfo[0]).ToString("dd'/'MM'/'yyyy") + "</Date>"
                                               + "<Time>" + haltInfo[1] + "</Time>"
                                               + "<Location>" + haltInfo[2] + "</Location>"
                                               + "<Remarks>" + haltInfo[3] + "</Remarks>";
                            xmlString = xmlString + "</Halt" + count + ">";
                        }
                        cnt++;
                    }

                }
            }
            xmlString = xmlString + "</HaltsReport>";
            return xmlString;
            /*******************************HTML CODE*************************************
              Response.Write("</table>\n");
            ******************************************************************************/

        }
