                         *********************************************************************/


                        if (!String.IsNullOrEmpty(haltInfo[3]))
                        {
                            string dat = Convert.ToDateTime(haltInfo[0]).ToString("yyyy'-'MM'-'dd") + " " + haltInfo[1];
                            // count++;
                            dbx.storeVehicleViolations(vehicleid, "", "UNSCHEDULED STOP", Convert.ToDateTime(dat).ToString("yyyy-MM-dd HH:mm:ss"), 2.0, haltInfo[3], haltInfo[2]);
