                            //xmlString = xmlString + "</Halt" + count + ">";
                            haltinformations = vehicleid + "," + Convert.ToDateTime(haltInfo[0]).ToString("dd'/'MM'/'yyyy") + " " + haltInfo[1] + "," + haltInfo[2].Replace(',', '-') + "," + haltInfo[3].Replace(',', '-');
