        public string GetCustomerAssetCoordinates(string CustomerCode)
        {
            try
            {

                object[] veh = dbx.GetCustomerDCVehicles(CustomerCode);
                string xmlString = "<?xml version=" + "\"1.0\"" + " encoding=" + "\"UTF-8\"" + "?>";
                xmlString = xmlString + "<Locations>";
                string vehicles = string.Empty;


                for (int i = 0; i < veh.Length; i++)
                {
                    object[] v = (object[])veh[i];
                    int noofdcs = Convert.ToInt32(v[5].ToString());
                    if (!vehicles.Contains(v[0].ToString() + ","))
                    {
                        vehicles = v[0].ToString() + ",";
                        object values = dbx.getLastLatLong(v[0].ToString());
                        object vehicleInfo = dbx.vehicleInfo(v[0].ToString());
                        if (((object[])values).Length > 0)
                        {
                            string lat = ((object[])(((object[])(values))[0]))[0].ToString();
                            string lon = ((object[])(((object[])(values))[0]))[1].ToString();
                            string spdrem = findSpeedRemarks(((object[])(((object[])(values))[0]))[3].ToString(), ((object[])(((object[])(values))[0]))[4].ToString(), ((object[])(((object[])(values))[0]))[2].ToString());


                            //Finding EST
                            DateTime ETA = new DateTime();
                            bool etafound = false;
