        public string findReverseETA(DateTime TripStartTime, double distance, int avgSpeed, int totalMaxDrive, string ShiftStartTime, string ShiftEndTime, int shortRunTime, int shortRestTime, int longrest, int daydriven)
        {
            DateTime now = TripStartTime;
            string start = ShiftStartTime;
            string end = ShiftEndTime;
            int maxContDriving = shortRunTime;
            int rest = shortRestTime;
            DateTime ETA = DateTime.Now;
            double distanceCovered = 0;
            double day_totaldrivinghours = daydriven;
            double distancerem = distance;
            for (int i = 0; 0 < distancerem; i++)
            {
                DateTime curfewEnd = Convert.ToDateTime(now.ToString("yyyy-MM-dd") + " " + start);
                distancerem = distance - distanceCovered;
                DateTime st = now;
                if (day_totaldrivinghours > totalMaxDrive)
                {
                    st = now;
                    now = now.AddSeconds(-longrest);
                    day_totaldrivinghours = 0;
                    Console.WriteLine("Rest :" + st.ToString("yyyy-MM-dd HH:mm:ss") + " to " + now.ToString("yyyy-MM-dd HH:mm:ss"));

                }
                else if (distancerem > (maxContDriving / 3600) * avgSpeed)
                {
                    DateTime nxt = now.AddSeconds(maxContDriving);
                    if (nxt > curfewEnd && start != end)
                    {
                        double ts = Math.Abs((curfewEnd - now).TotalSeconds);
                        if (ts > 0)
                        {
                            if (day_totaldrivinghours + ts > totalMaxDrive)
                                ts = Math.Abs(totalMaxDrive - day_totaldrivinghours);
                            now = now.AddSeconds(-ts);
                            distanceCovered += (ts / 3600) * avgSpeed;
                            Console.WriteLine("Drive :" + st.ToString("yyyy-MM-dd HH:mm:ss") + " to " + now.ToString("yyyy-MM-dd HH:mm:ss") + "     Distance Covered : " + distanceCovered);
                        }
                        st = now;
                        now = Convert.ToDateTime(now.AddDays(-1).ToString("yyyy-MM-dd") + " " + end);
                        day_totaldrivinghours = 0;
                    }
                    else
                    {
                        st = now;
                        double ts = maxContDriving;
                        if (day_totaldrivinghours + ts > totalMaxDrive)
                            ts = totalMaxDrive - day_totaldrivinghours;
                        now = now.AddSeconds(-ts);
                        distanceCovered += (ts / 3600) * avgSpeed;
                        Console.WriteLine("Drive:" + st.ToString("yyyy-MM-dd HH:mm:ss") + " to " + now.ToString("yyyy-MM-dd HH:mm:ss") + "     Distance Covered : " + distanceCovered);
                        st = now;
                        if (now > curfewEnd && start != end)
                        {
                            now = Convert.ToDateTime(now.AddDays(-1).ToString("yyyy-MM-dd") + " " + end);
                            day_totaldrivinghours = 0;
                        }
                        else
                        {
                            now = now.AddSeconds(-rest);
                            day_totaldrivinghours += maxContDriving;
                        }
                    }
                    Console.WriteLine("Rest :" + st.ToString("yyyy-MM-dd HH:mm:ss") + " to " + now.ToString("yyyy-MM-dd HH:mm:ss"));

                }
                else if (distancerem != 0)
                {
                    double timeneedtocomplete = (distancerem / avgSpeed) * 60 * 60;
                    DateTime nxt = now.AddSeconds(timeneedtocomplete);
                    if (nxt < curfewEnd && start != end)
                    {
                        st = now;
                        double ts = Math.Abs((curfewEnd - now).TotalSeconds);

                        if (day_totaldrivinghours + ts > totalMaxDrive)
                            ts = totalMaxDrive - day_totaldrivinghours;

                        now = now.AddSeconds(-ts);
                        distanceCovered += Convert.ToInt32(ts / 3600) * avgSpeed;
                        Console.WriteLine("Drive:" + st.ToString("yyyy-MM-dd HH:mm:ss") + " to " + now.ToString("yyyy-MM-dd HH:mm:ss") + "     Distance Covered : " + distanceCovered);
                        st = now;
                        now = Convert.ToDateTime(now.AddDays(-1).ToString("yyyy-MM-dd") + " " + end);
                        Console.WriteLine("Rest :" + st.ToString("yyyy-MM-dd HH:mm:ss") + " to " + now.ToString("yyyy-MM-dd HH:mm:ss"));
                        day_totaldrivinghours = 0;
                    }
                    else
                    {
                        st = now;
                        double ts = timeneedtocomplete;
                        if (day_totaldrivinghours + ts > totalMaxDrive)
                            ts = totalMaxDrive - day_totaldrivinghours;
                        now = now.AddSeconds(-ts);
                        distanceCovered += distancerem;
                        Console.WriteLine("Drive:" + st.ToString("yyyy-MM-dd HH:mm:ss") + " to " + now.ToString("yyyy-MM-dd HH:mm:ss") + "     Distance Covered : " + distanceCovered);
                        day_totaldrivinghours += ts;
                    }

                }

            }
            return now.ToString("yyyy-MM-dd HH:mm:ss") + "," + day_totaldrivinghours;
        }
