                                string custlong = "0.000000";
                                if (custlatlong.Length > 0)
                                {
                                    custlat = ((object[])custlatlong[0])[0].ToString();
                                    custlong = ((object[])custlatlong[0])[1].ToString();
                                }

                                string googledist = string.Empty;
                                if (custlat != "0.000000" && custlong != "0.000000")
                                    googledist = getDistanceByGoogleDistanceMatrix(lat, lng, custlat, custlong);
                                if (!string.IsNullOrEmpty(googledist))
                                {
                                    if (googledist != "NoData")
                                    {
                                        decimal gd = Convert.ToDecimal(googledist) / 1000;//m to km
                                        distcov = distcov + Convert.ToInt32(gd);
                                    }
                                }

                            }
                        }
                        else
                        {
                            object[] srclatlong = dbx.getplantgeolatlong(custcode);
                            string srclat = "0.000000";
                            string srclong = "0.000000";
                            if (srclatlong.Length > 0)
                            {
                                srclat = ((object[])srclatlong[0])[0].ToString();
                                srclong = ((object[])srclatlong[0])[1].ToString();
                            }
                            string destcustcode = dt.Rows[i - 1]["CustomerCode"].ToString();
                            object[] destlatlong = dbx.getplantgeolatlong(destcustcode);
                            string destlat = "0.000000";
                            string destlong = "0.000000";
                            if (destlatlong.Length > 0)
                            {
                                destlat = ((object[])destlatlong[0])[0].ToString();
                                destlong = ((object[])destlatlong[0])[1].ToString();
                            }
                            string googledist = string.Empty;
                            if (srclat != "0.000000" && srclong != "0.000000" && destlat != "0.000000" && destlong != "0.000000")
                                googledist = getDistanceByGoogleDistanceMatrix(srclat, srclong, destlat, destlong);
                            if (!string.IsNullOrEmpty(googledist))
                            {
                                if (googledist != "NoData")
                                {
                                    decimal gd = Convert.ToDecimal(googledist) / 1000;//m to km
                                    distcov = distcov + Convert.ToInt32(gd);
                                }
                            }

                        }

                    }
                }
            }
            catch { }
            if (distcov > 0)
            {
                try
                {
                    //Distance have Cover to update for next use.
                    dbx.UpdateCustomerDCDisthavetocover(dcid, distcov);
                }
                catch { }

            }
            return distcov;
        }
