        //Modified getDistanceByGoogleDistanceMatrix By Tushar on 25092023 to calculate MMI distance matrix
        public string getDistanceByGoogleDistanceMatrix(string orglat, string orglong, string destlat, string destlong)
        {
            try
            {
                string resultdistanceMMIAPICall = "";
                resultdistanceMMIAPICall =  getDistanceByMMIDistanceMatrix(orglat, orglong, destlat, destlong);
                if(!resultdistanceMMIAPICall.Contains("NoData"))
                {
                    return resultdistanceMMIAPICall;
                }
                else
                {
                    if (System.Web.HttpContext.Current.Session != null)
                    {
                        if (System.Web.HttpContext.Current.Session["LocationRequest"] != null)
                        {
                            if (System.Web.HttpContext.Current.Session["LocationRequest"].ToString() == "GOOGLE")
                            {
                                var requestUri = "https://maps.googleapis.com/maps/api/distancematrix/xml?origins=" + orglat + "," + orglong + "&destinations=" + destlat + "," + destlong + "&mode=driving&client=gme-senseltelematics";
                                requestUri = Sign(requestUri);
                                var request = WebRequest.Create(requestUri);
                                var response = request.GetResponse();
                                XmlDocument xmlDoc = new XmlDocument();
                                xmlDoc.Load(response.GetResponseStream());
                                dbx.insertMapApiLog("Google", "Distance Matrix");
                                foreach (XmlNode xmlNode in xmlDoc.DocumentElement.ChildNodes)
                                {
                                    switch (xmlNode.Name)
                                    {
                                        case "status":
                                            try
                                            {
                                                if (xmlNode.InnerText != "OK")
                                                    return "NoData";
                                            }
                                            catch { }
                                            break;
                                        case "row":
                                            try
                                            {
                                                XmlNode elementNode = xmlNode.ChildNodes[0];
                                                if (elementNode.ChildNodes[0].InnerText == "OK")
                                                {
                                                    string duration = elementNode.ChildNodes[1].ChildNodes[0].InnerText;
                                                    string distance = elementNode.ChildNodes[2].ChildNodes[0].InnerText;
                                                    return distance;
                                                }
                                                else
                                                {
                                                    return "NoData";
                                                }
                                            }
                                            catch { }
                                            break;
                                    };
                                }
                            }
                        }
                    }
                    return getDistanceByMMIDistanceMatrix(orglat, orglong, destlat, destlong);
                }
            }
            catch { return "NoData"; }
        }

