        public string findSpeedRemarks(string Speed, string Stopbit, string timestamp)
        {
            try
            {
                String maxGprsDelayStr = "1200";
                String appMaxGprsDelayStr = System.Web.Configuration.WebConfigurationManager.AppSettings["MAXGPRSDELAY"];
                if (!String.IsNullOrEmpty(appMaxGprsDelayStr))
                    maxGprsDelayStr = appMaxGprsDelayStr;
                DateTime endDate = DateTime.UtcNow;
                int maxSpeedDisplayTime = 300;
                endDate = endDate.AddSeconds(timeZone);
                double speed = Convert.ToDouble(Speed);
                int StopBit = int.Parse(Stopbit);
                string Remarks = string.Empty;
                DateTime timestamp_last_GPRS_update_date = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff()).AddMinutes(-10);
                timestamp_last_GPRS_update_date = DateTime.Parse(timestamp);
                if ((endDate - timestamp_last_GPRS_update_date).TotalSeconds < Convert.ToInt32(maxGprsDelayStr))
                {
                    if ((endDate - timestamp_last_GPRS_update_date).TotalSeconds > maxSpeedDisplayTime || Math.Abs((endDate - timestamp_last_GPRS_update_date).TotalSeconds) > Convert.ToInt32(maxGprsDelayStr))
                    { speed = 0; }
                    if (StopBit == 1)
                    {
                        Remarks = Remarks + "Vehicle Halted";//Vehicle Halted
                        speed = 0;
                    }
                    else if (speed <= 3)
                    {
                        Remarks = Remarks + "Vehicle Idling";//Vehicle Idling
                        speed = 0;
                    }
                    else
                    {
                        Remarks = Remarks + "Vehicle Moving";//Vehicle Moving
                    }
                }
                else
                {
                    if ((endDate - timestamp_last_GPRS_update_date).TotalSeconds > maxSpeedDisplayTime)//Added on 13-7-2014 in the request that the speed should be zero if it is not rechable for more then 20 Mins
                    { speed = 0; }
                    Remarks = Remarks + "Not Reachable";//Not Reachable
                    speed = 0;
                }
                return speed + "," + Remarks;
            }
            catch { return "0,Not Reachable"; }

        }
        public DateTime AddWithinWorkingHours(DateTime start, TimeSpan offset, int hoursPerDay = 12, int startHour = 5, int shortRest = 1800, int shortRuntime = 16200, int totalRuntime = 0, bool IsReverse = false)
        {
            //Adding Rest Hours
            TimeSpan restNeeded = new TimeSpan(0, 0, (int)((offset.TotalSeconds / shortRuntime) * shortRest));
            offset = offset.Add(restNeeded);

            if (!IsReverse)
            {
                if (start.TimeOfDay.TotalHours > startHour + hoursPerDay)
                    start = start.Date.AddDays(1).AddHours(startHour);
                if (start.TimeOfDay.TotalHours < startHour)
                    start = start.Date.AddHours(startHour);
            }
            //if (start.DayOfWeek == DayOfWeek.Sunday)
            //    start.AddDays(1);
            //else if (start.DayOfWeek == DayOfWeek.Saturday)
            //    start.AddDays(2);
            // Calculate how much working time already passed on the first day
            TimeSpan firstDayOffset = new TimeSpan(0, 0, totalRuntime);
            // Calculate number of whole days to add
            int wholeDays = (int)(offset.Add(firstDayOffset).TotalHours / hoursPerDay);
            // How many hours off the specified offset does this many whole days consume?
            TimeSpan wholeDaysHours = TimeSpan.FromHours(wholeDays * hoursPerDay);
            // Calculate the final time of day based on the number of whole days spanned and the specified offset
            TimeSpan remainder = offset - wholeDaysHours;
            // How far into the week is the starting date?
            //int weekOffset = ((int)(start.DayOfWeek + 7) - (int)DayOfWeek.Monday) % 7;
            // How many weekends are spanned?
            //int weekends = (int)((wholeDays) / 7);
            // Calculate the final result using all the above calculated values
            if (IsReverse)
                return start.AddDays(-wholeDays).Add(-remainder);
            else
                return start.AddDays(wholeDays).Add(remainder);
        }
