        public class RMC
        {
            public string fromtime { get; set; }
            public string totime { get; set; }
            public string Duration { get; set; }
            public string EngineStatus { get; set; }
            public string BarrelStatus { get; set; }
            public string Location { get; set; }
        };
        public List<RMC> GetRmcData(string vehicleId, string fromdata, string todate)
        {
            //fields:=From date/time, To date/time, Duration(hrs:mins) , Location, Engine Status (ON or OFF), Barrel Status (Churing or Draining)
            string bitchecker_binary = "000";
            string tempbitchecker_binary = "000";
            string starttime = "";
            string endtime = "";
            string latitude = "";
            string longitude = "";
            string locationstr = "";
            string duration = "";
            string rotation = "";
            string enginstatus = "";
            //t.badSigCount,t.distance,t.IdlingInstances,fromtimestamp 
            //badSigCount=ginp2
            //distance=ginp1
            //IdlingInstances=hvinp
            DataRow[] rmcdata = dbx.getTrackerDataRmc(vehicleId, fromdata, todate);
            List<RMC> rmclst = new List<RMC>();
            foreach (DataRow data in rmcdata)
            {
                if (starttime == "")
                {

                    starttime = dbx.formatDBDate(Convert.ToDateTime(data.ItemArray[3]));
                    bitchecker_binary = data.ItemArray[0].ToString() + data.ItemArray[1].ToString() + data.ItemArray[2].ToString();
                    enginstatus = data.ItemArray[2].ToString();
                }
                tempbitchecker_binary = data.ItemArray[0].ToString() + data.ItemArray[1].ToString() + data.ItemArray[2].ToString();
                if (tempbitchecker_binary != bitchecker_binary)
                {
                    endtime = dbx.formatDBDate(Convert.ToDateTime(data.ItemArray[3]));
                    object[] latlong = dbx.getLastPositionForVehicle(vehicleId, endtime, starttime);
                    if (latlong == null)
                    {
                        starttime = "";
                        continue;

                    }
                    latitude = ((object[])(latlong[0]))[0].ToString();
                    longitude = ((object[])(latlong[0]))[1].ToString();
                    locationstr = dbx.getPositionTxt(latitude, longitude, 1000);
                    TimeSpan diff = Convert.ToDateTime(starttime) - Convert.ToDateTime(endtime);
                    if (bitchecker_binary == "011" || bitchecker_binary == "010")
                    {
                        rotation = " Draining";
                    }
                    else if (bitchecker_binary == "101" || bitchecker_binary == "100")
                    {
                        rotation = " Churning";
                    }
                    else
                        rotation = "Unknown";
                    if (enginstatus == "1")
                    {
                        enginstatus = "on";
                    }
                    else
                        enginstatus = "off";
                    duration = diff.Hours + " Hr" + ":" + diff.Minutes + " Min";
                    RMC objrmc = new RMC
                    {
                        fromtime = endtime,
                        totime = starttime,
                        Duration = duration,
                        Location = locationstr,
                        BarrelStatus = rotation,
                        EngineStatus = enginstatus

                    };
                    rmclst.Add(objrmc);
                    starttime = "";
                }
            }
            return rmclst;
        }

