        public string GetHaltDuration(string vehicleid)
        {
            try
            {
                DataTable dt = dbx.GetHaltDuration(vehicleid);
                if (dt != null)
                {
                    if (dt.Rows.Count > 0)
                    {
                        string longstoptime = dt.Rows[0]["longstopTime"].ToString();
                        string lastUpdateTime = dt.Rows[0]["lastUpdateTime"].ToString();
                        if (longstoptime != "0")
                        {
                            TimeSpan ts = new TimeSpan(0, 0, Convert.ToInt32(longstoptime));
                            DateTime lsdt = Convert.ToDateTime(lastUpdateTime);
                            DateTime now = DateTime.UtcNow.AddSeconds(timeZone);
                            ts = ts.Add(now - lsdt);
                            return (ts.Days > 0 ? ts.Days + " days," : "") + (ts.Hours > 0 ? ts.Hours + " hr," : "") + (ts.Minutes > 0 ? ts.Minutes + " Min" : "");
                        }
                        else
                        {
                            return "";
                        }
                    }
                    else
                    {
                        return "";
                    }
                }
                else
                {
                    return "";
                }
            }
            catch
            {
                return "";
            }
            finally { dbx.close(); }
        }

