        public DataTable checkWeatherAvailable(string latitude, string longitude, double delta, string UpdateFreq, string callapi)
        {
            try
            {

                DataTable dt = dbx.checkweatherzoneavail(latitude, longitude, delta);
                if (dt.Rows.Count == 0)
                {
                    if (callapi == "1")
                        getandStoreWeatherData(latitude, longitude, "Insert", "0");
                    else
                    {
                        System.Threading.Thread.Sleep(3000);
                        dt = dbx.checkweatherzoneavail(latitude, longitude, delta);
                        if (dt.Rows.Count == 0)
                        {
                            System.Threading.Thread.Sleep(5000);
                            dt = dbx.checkweatherzoneavail(latitude, longitude, delta);
                            if (dt.Rows.Count == 0)
                            {
                                getandStoreWeatherData(latitude, longitude, "Insert", "0");
                                return dbx.checkweatherzoneavail(latitude, longitude, delta);
                            }
                            else
                            {
                                return dt;
                            }
                        }
                        else
                        {
                            return dt;
                        }
                    }
                    return dbx.checkweatherzoneavail(latitude, longitude, delta);
                }
                else
                {
                    DateTime dtlast = Convert.ToDateTime(dt.Rows[0]["Last_Updated_On"].ToString());
                    DateTime utcnow = DateTime.UtcNow;
                    if ((utcnow - dtlast).TotalMinutes >= Convert.ToInt32(UpdateFreq))
                    {
                        if (callapi == "1")
                            getandStoreWeatherData(latitude, longitude, "Edit", dt.Rows[0]["Id"].ToString());
                        else
                        {
                            System.Threading.Thread.Sleep(5000);
                            dt = dbx.checkweatherzoneavail(latitude, longitude, delta);
                            dtlast = Convert.ToDateTime(dt.Rows[0]["Last_Updated_On"].ToString());
                            if ((utcnow - dtlast).TotalMinutes >= Convert.ToInt32(UpdateFreq))
                            {
                                getandStoreWeatherData(latitude, longitude, "Edit", dt.Rows[0]["Id"].ToString());
                                return dbx.checkweatherzoneavail(latitude, longitude, delta);
                            }
                            else
                            {
                                return dt;
                            }
                        }
                        return dbx.checkweatherzoneavail(latitude, longitude, delta);
                    }
                    else
                    {
                        return dt;
                    }
                }
            }
            catch { return null; }
        }
        public string getandStoreWeatherData(string latitude, string longitude, string Mode, string Id)
        {
            try
            {
                String WeatherAPI = System.Web.Configuration.WebConfigurationManager.AppSettings["WeatherAPI"];
                if (string.IsNullOrEmpty(WeatherAPI))
                    WeatherAPI = "5336b6f68f0d488193959242d76d0221";
                var requestUri = "http://api.openweathermap.org/data/2.5/weather?lat=" + latitude + "&lon=" + longitude + "&APPID=" + WeatherAPI + "&mode=xml";
                var request = WebRequest.Create(requestUri);
                var response = request.GetResponse();
                XmlDocument xmlDoc = new XmlDocument();
                xmlDoc.Load(response.GetResponseStream());

                string Cityid = string.Empty, Cityname = string.Empty;
                string Current_Temp = string.Empty, Min_Temp = string.Empty, Max_Temp = string.Empty;
                string Humidity = string.Empty, Pressure = string.Empty;
                string Wind_Speed_Value = string.Empty, Wind_Speed_Name = string.Empty;
                string Wind_Direction_Value = string.Empty, Wind_Direction_Code = string.Empty;
                string Clouds_Value = string.Empty, Couds_Name = string.Empty;
                string Visibility = string.Empty, Weather_Number = string.Empty, Weather_Value = string.Empty;
                string Last_Updated_On = string.Empty;
                foreach (XmlNode xmlNode in xmlDoc.DocumentElement.ChildNodes)
                {
                    switch (xmlNode.Name)
                    {
                        case "city":
                            try
                            {
                                Cityid = xmlNode.Attributes["id"].Value;
                                Cityname = xmlNode.Attributes["name"].Value;
                            }
                            catch { }
                            break;
                        case "temperature":
                            try
                            {
                                Current_Temp = xmlNode.Attributes["value"].Value;
                                Min_Temp = xmlNode.Attributes["min"].Value;
                                Max_Temp = xmlNode.Attributes["max"].Value;
                            }
                            catch { }
                            break;
                        case "humidity":
                            try
                            {
                                Humidity = xmlNode.Attributes["value"].Value;
                            }
                            catch { }
                            break;
                        case "pressure":
                            try
                            {
                                Pressure = xmlNode.Attributes["value"].Value;
                            }
                            catch { }
                            break;
                        case "wind":
                            try
                            {
                                foreach (XmlNode windxmlNode in xmlNode.ChildNodes)
                                {
                                    switch (windxmlNode.Name)
                                    {
                                        case "speed":
                                            Wind_Speed_Value = windxmlNode.Attributes["value"].Value;
                                            Wind_Speed_Name = windxmlNode.Attributes["name"].Value;
                                            break;
                                        case "direction":
                                            Wind_Direction_Value = windxmlNode.Attributes["value"].Value;
                                            Wind_Direction_Code = windxmlNode.Attributes["code"].Value;
                                            break;
                                    }
                                }
                            }
                            catch { }
                            break;
                        case "clouds":
                            try
                            {
                                Clouds_Value = xmlNode.Attributes["value"].Value;
                                Couds_Name = xmlNode.Attributes["name"].Value;
                            }
                            catch { }
                            break;
                        case "visibility":
                            try
                            {
                                Visibility = xmlNode.Attributes["value"].Value;
                            }
                            catch { }
                            break;
                        case "weather":
                            try
                            {
                                Weather_Number = xmlNode.Attributes["number"].Value;
                                Weather_Value = xmlNode.Attributes["value"].Value;
                            }
                            catch { }
                            break;
                        case "lastupdate":
                            try
                            {
                                Last_Updated_On = xmlNode.Attributes["value"].Value;
                            }
                            catch { }
                            break;
                    };
                }
                return dbx.AddUpdateWeatherData(latitude, longitude, Mode, Id, Cityid, Cityname,
                         Current_Temp, Min_Temp, Max_Temp, Humidity, Pressure, Wind_Speed_Value,
                         Wind_Speed_Name, Wind_Direction_Value, Wind_Direction_Code, Clouds_Value, Couds_Name,
                         Visibility, Weather_Number, Weather_Value, Last_Updated_On);
            }
            catch { return "0"; }
        }

