        public string StartorStopVehicle(string VehicleId, string Command, string sessionId = "")
        {
            try
            {
                if (VehicleId != null)
                {
                    int uid = dbx.getUidFromConfigdata(VehicleId);
                    string RequestMsg = "";
                    if (uid == 0)
                    {
                        return "UID MISSING FROM DATABASE";
                    }
                    if (uid > 60000)
                    {
                        if (Command == "Stop")
                            RequestMsg = "00000000000000150C01050000000D7365746469676F757420310D0A01000063B8";
                        if (Command == "Start")
                            RequestMsg = "00000000000000150C01050000000D7365746469676F757420300D0A0100009FB9";
                    }
                    else
                    {
                        string globalAccId = "";
                        if (!string.IsNullOrEmpty(sessionId))
                            globalAccId = GetGlobalAccountIdBySession(sessionId);

                        if (Command == "Start")
                        {
                            if (globalAccId == "4183")
                                RequestMsg = "(ACT SERCMD WAKEUP)";
                            else if (uid < 3324)
                                RequestMsg = "(ACT ATCMD AT#GPIO=6,0,1 )";
                            else
                                RequestMsg = "(ACT IMMOBILIZER 0 ;ACT ATCMD AT#GPIO=4,0,1 )";
                        }
                        else if (Command == "Stop")
                        {
                            if (globalAccId == "4183")
                                RequestMsg = "(ACT SERCMD SHUT)";
                            else if (uid < 3324)
                                RequestMsg = "(ACT ATCMD AT#GPIO=6,1,1 )";
                            else
                                RequestMsg = "(ACT IMMOBILIZER 1 ;ACT ATCMD AT#GPIO=4,1,1 )";
                        }
                    }



                    dbx.addServerRequest(VehicleId, 5, RequestMsg);
                    return "Vehicle - " + VehicleId + " " + Command + " Command Sent to VTS Device.";
                }
                return "Vehicle Not Found";
            }
            catch { return "Failed,Please try again"; }
        }
