        public string GetDistanceFromHome(string vehicleid, string lat, string lng, string timestamp)
        {
            string dist = "";
            string latstdist = "";
            try
            {
                DataTable dt = dbx.GetDistanceFromHomeData(vehicleid);
                if (dt != null)
                {
                    if (dt.Rows.Count > 1)
                    {
                        double diffdist = computeDistance(Convert.ToDouble(lat), Convert.ToDouble(lng), Convert.ToDouble(dt.Rows[0]["latitude"].ToString()), Convert.ToDouble(dt.Rows[0]["longitude"].ToString()));
                        if (diffdist > 2)
                        {
                            DataTable hmlatlng = dbx.GetHomeLatLng(vehicleid);
                            dist = getDistanceByGoogleDistanceMatrix(lat, lng, hmlatlng.Rows[0]["HomeLat"].ToString(), hmlatlng.Rows[0]["HomeLong"].ToString());
                            if (dist == "NoData" || string.IsNullOrEmpty(dist))
                                dist = computeDistance(Convert.ToDouble(lat), Convert.ToDouble(lng), Convert.ToDouble(hmlatlng.Rows[0]["HomeLat"].ToString()), Convert.ToDouble(hmlatlng.Rows[0]["HomeLong"].ToString())).ToString();
                            else
                                dist = Convert.ToInt32((Convert.ToDecimal(dist) / 1000)).ToString();

                            dbx.UpdateDistanceFromHome(vehicleid, lat, lng, formatDBDate(Convert.ToDateTime(timestamp)), dist, "1");

                            if (Convert.ToInt32(dist) > 6)
                            {
                                object[] latlng = dbx.getMaxLatLongOnTime(vehicleid, formatDBDate(Convert.ToDateTime(timestamp).AddMinutes(-30)));
                                if (latlng.Length > 0)
                                {
                                    latstdist = getDistanceByGoogleDistanceMatrix(((Object[])latlng[0])[4].ToString(), ((Object[])latlng[0])[5].ToString(), hmlatlng.Rows[0]["HomeLat"].ToString(), hmlatlng.Rows[0]["HomeLong"].ToString());
                                    if (latstdist == "NoData" || string.IsNullOrEmpty(latstdist))
                                        latstdist = computeDistance(Convert.ToDouble(((Object[])latlng[0])[5].ToString()), Convert.ToDouble(((Object[])latlng[0])[5].ToString()), Convert.ToDouble(hmlatlng.Rows[0]["HomeLat"].ToString()), Convert.ToDouble(hmlatlng.Rows[0]["HomeLong"].ToString())).ToString();
                                    else
                                        latstdist = Convert.ToInt32((Convert.ToDecimal(latstdist) / 1000)).ToString();

                                    int diff = Convert.ToInt32(dist) - Convert.ToInt32(latstdist);
                                    if (diff == 0)
                                    {
                                        object[] latlngSec = dbx.getMaxLatLongOnTime(vehicleid, formatDBDate(Convert.ToDateTime(timestamp).AddHours(-5)));
                                        if (latlngSec.Length > 0)
                                        {
                                            latstdist = getDistanceByGoogleDistanceMatrix(((Object[])latlngSec[0])[4].ToString(), ((Object[])latlngSec[0])[5].ToString(), hmlatlng.Rows[0]["HomeLat"].ToString(), hmlatlng.Rows[0]["HomeLong"].ToString());
                                            if (latstdist == "NoData" || string.IsNullOrEmpty(latstdist))
                                                latstdist = computeDistance(Convert.ToDouble(((Object[])latlngSec[0])[4].ToString()), Convert.ToDouble(((Object[])latlngSec[0])[5].ToString()), Convert.ToDouble(hmlatlng.Rows[0]["HomeLat"].ToString()), Convert.ToDouble(hmlatlng.Rows[0]["HomeLong"].ToString())).ToString();
                                            else
                                                latstdist = Convert.ToInt32((Convert.ToDecimal(latstdist) / 1000)).ToString();

                                            int secddiff = Convert.ToInt32(dist) - Convert.ToInt32(latstdist);
                                            if (secddiff == 0)
                                            {
                                                object[] latlngThr = dbx.getMaxLatLongOnTime(vehicleid, formatDBDate(Convert.ToDateTime(timestamp).AddHours(-24)));
                                                if (latlngThr.Length > 0)
                                                {
                                                    latstdist = getDistanceByGoogleDistanceMatrix(((Object[])latlngThr[0])[4].ToString(), ((Object[])latlngThr[0])[5].ToString(), hmlatlng.Rows[0]["HomeLat"].ToString(), hmlatlng.Rows[0]["HomeLong"].ToString());
                                                    if (latstdist == "NoData" || string.IsNullOrEmpty(latstdist))
                                                        latstdist = computeDistance(Convert.ToDouble(((Object[])latlngThr[0])[4].ToString()), Convert.ToDouble(((Object[])latlngThr[0])[5].ToString()), Convert.ToDouble(hmlatlng.Rows[0]["HomeLat"].ToString()), Convert.ToDouble(hmlatlng.Rows[0]["HomeLong"].ToString())).ToString();
                                                    else
                                                        latstdist = Convert.ToInt32((Convert.ToDecimal(latstdist) / 1000)).ToString();
                                                    int thirddiff = Convert.ToInt32(dist) - Convert.ToInt32(latstdist);
                                                    if (thirddiff == 0)
                                                    {
                                                        object[] latlngFourth = dbx.getMaxLatLongOnTime(vehicleid, formatDBDate(Convert.ToDateTime(timestamp).AddHours(-72)));
                                                        if (latlngFourth.Length > 0)
                                                        {
                                                            latstdist = getDistanceByGoogleDistanceMatrix(((Object[])latlngFourth[0])[4].ToString(), ((Object[])latlngFourth[0])[5].ToString(), hmlatlng.Rows[0]["HomeLat"].ToString(), hmlatlng.Rows[0]["HomeLong"].ToString());
                                                            if (latstdist == "NoData" || string.IsNullOrEmpty(latstdist))
                                                                latstdist = computeDistance(Convert.ToDouble(((Object[])latlngFourth[0])[4].ToString()), Convert.ToDouble(((Object[])latlngFourth[0])[5].ToString()), Convert.ToDouble(hmlatlng.Rows[0]["HomeLat"].ToString()), Convert.ToDouble(hmlatlng.Rows[0]["HomeLong"].ToString())).ToString();
                                                            else
                                                                latstdist = Convert.ToInt32((Convert.ToDecimal(latstdist) / 1000)).ToString();
                                                            dbx.UpdateDistanceFromHome(vehicleid, ((Object[])latlngFourth[0])[4].ToString(), ((Object[])latlngFourth[0])[5].ToString(), formatDBDate(Convert.ToDateTime(((Object[])latlngFourth[0])[1].ToString())), latstdist, "2");
                                                        }
                                                    }
                                                    else
                                                    {
                                                        dbx.UpdateDistanceFromHome(vehicleid, ((Object[])latlngThr[0])[4].ToString(), ((Object[])latlngThr[0])[5].ToString(), formatDBDate(Convert.ToDateTime(((Object[])latlngThr[0])[1].ToString())), latstdist, "2");
                                                    }
                                                }
                                            }
                                            else
                                            {
                                                dbx.UpdateDistanceFromHome(vehicleid, ((Object[])latlngSec[0])[4].ToString(), ((Object[])latlngSec[0])[5].ToString(), formatDBDate(Convert.ToDateTime(((Object[])latlngSec[0])[1].ToString())), latstdist, "2");
                                            }

                                        }
                                    }
                                    else
                                    {
                                        dbx.UpdateDistanceFromHome(vehicleid, ((Object[])latlng[0])[4].ToString(), ((Object[])latlng[0])[5].ToString(), formatDBDate(Convert.ToDateTime(((Object[])latlng[0])[1].ToString())), latstdist, "2");
                                    }
                                }
                            }
                            else
                            {
                                return "0,HOME";
                            }
                        }
                        else
                        {
                            dist = dt.Rows[0]["distfromhome"].ToString();
                            latstdist = dt.Rows[1]["distfromhome"].ToString();

                        }
                    }
                    else
                    {
                        DataTable hmlatlng = dbx.GetHomeLatLng(vehicleid);
                        dist = getDistanceByGoogleDistanceMatrix(lat, lng, hmlatlng.Rows[0]["HomeLat"].ToString(), hmlatlng.Rows[0]["HomeLong"].ToString());
                        if (dist == "NoData" || string.IsNullOrEmpty(dist))
                            dist = computeDistance(Convert.ToDouble(lat), Convert.ToDouble(lng), Convert.ToDouble(hmlatlng.Rows[0]["HomeLat"].ToString()), Convert.ToDouble(hmlatlng.Rows[0]["HomeLong"].ToString())).ToString();
                        else
                            dist = Convert.ToInt32((Convert.ToDecimal(dist) / 1000)).ToString();

                        dbx.UpdateDistanceFromHome(vehicleid, lat, lng, formatDBDate(Convert.ToDateTime(timestamp)), dist, "1");
                        if (Convert.ToInt32(dist) > 6)
                        {
                            object[] latlng = dbx.getMaxLatLongOnTime(vehicleid, formatDBDate(Convert.ToDateTime(timestamp).AddMinutes(-30)));
                            if (latlng.Length > 0)
                            {
                                latstdist = getDistanceByGoogleDistanceMatrix(((Object[])latlng[0])[4].ToString(), ((Object[])latlng[0])[5].ToString(), hmlatlng.Rows[0]["HomeLat"].ToString(), hmlatlng.Rows[0]["HomeLong"].ToString());
                                if (latstdist == "NoData" || string.IsNullOrEmpty(latstdist))
                                    latstdist = computeDistance(Convert.ToDouble(((Object[])latlng[0])[4].ToString()), Convert.ToDouble(((Object[])latlng[0])[5].ToString()), Convert.ToDouble(hmlatlng.Rows[0]["HomeLat"].ToString()), Convert.ToDouble(hmlatlng.Rows[0]["HomeLong"].ToString())).ToString();
                                else
                                    latstdist = Convert.ToInt32((Convert.ToDecimal(latstdist) / 1000)).ToString();
                                int diff = Convert.ToInt32(dist) - Convert.ToInt32(latstdist);
                                if (diff == 0)
                                {
                                    object[] latlngSec = dbx.getMaxLatLongOnTime(vehicleid, formatDBDate(Convert.ToDateTime(timestamp).AddHours(-5)));
                                    if (latlngSec.Length > 0)
                                    {
                                        latstdist = getDistanceByGoogleDistanceMatrix(((Object[])latlngSec[0])[4].ToString(), ((Object[])latlngSec[0])[5].ToString(), hmlatlng.Rows[0]["HomeLat"].ToString(), hmlatlng.Rows[0]["HomeLong"].ToString());
                                        if (latstdist == "NoData" || string.IsNullOrEmpty(latstdist))
                                            latstdist = computeDistance(Convert.ToDouble(((Object[])latlngSec[0])[4].ToString()), Convert.ToDouble(((Object[])latlngSec[0])[5].ToString()), Convert.ToDouble(hmlatlng.Rows[0]["HomeLat"].ToString()), Convert.ToDouble(hmlatlng.Rows[0]["HomeLong"].ToString())).ToString();
                                        else
                                            latstdist = Convert.ToInt32((Convert.ToDecimal(latstdist) / 1000)).ToString();

                                        int secddiff = Convert.ToInt32(dist) - Convert.ToInt32(latstdist);
                                        if (secddiff == 0)
                                        {
                                            object[] latlngThr = dbx.getMaxLatLongOnTime(vehicleid, formatDBDate(Convert.ToDateTime(timestamp).AddHours(-24)));
                                            if (latlngThr.Length > 0)
                                            {
                                                latstdist = getDistanceByGoogleDistanceMatrix(((Object[])latlngThr[0])[4].ToString(), ((Object[])latlngThr[0])[5].ToString(), hmlatlng.Rows[0]["HomeLat"].ToString(), hmlatlng.Rows[0]["HomeLong"].ToString());
                                                if (latstdist == "NoData" || string.IsNullOrEmpty(latstdist))
                                                    latstdist = computeDistance(Convert.ToDouble(((Object[])latlngThr[0])[4].ToString()), Convert.ToDouble(((Object[])latlngThr[0])[5].ToString()), Convert.ToDouble(hmlatlng.Rows[0]["HomeLat"].ToString()), Convert.ToDouble(hmlatlng.Rows[0]["HomeLong"].ToString())).ToString();
                                                else
                                                    latstdist = Convert.ToInt32((Convert.ToDecimal(latstdist) / 1000)).ToString();
                                                dbx.UpdateDistanceFromHome(vehicleid, ((Object[])latlngThr[0])[4].ToString(), ((Object[])latlngThr[0])[5].ToString(), formatDBDate(Convert.ToDateTime(((Object[])latlngThr[0])[1].ToString())), latstdist, "2");
                                            }

                                        }
                                        else
                                        {
                                            dbx.UpdateDistanceFromHome(vehicleid, ((Object[])latlngSec[0])[4].ToString(), ((Object[])latlngSec[0])[5].ToString(), formatDBDate(Convert.ToDateTime(((Object[])latlngSec[0])[1].ToString())), latstdist, "2");
                                        }

                                    }

                                }
                                else
                                {
                                    dbx.UpdateDistanceFromHome(vehicleid, ((Object[])latlng[0])[4].ToString(), ((Object[])latlng[0])[5].ToString(), formatDBDate(Convert.ToDateTime(((Object[])latlng[0])[1].ToString())), latstdist, "2");

                                }
                            }
                        }
                        else
                        {
                            return "0,HOME";
                        }
                    }

                }

                if (!string.IsNullOrEmpty(dist) && !string.IsNullOrEmpty(latstdist))
                {
                    int diff = Convert.ToInt32(dist) - Convert.ToInt32(latstdist);
                    if (Convert.ToInt32(dist) <= 6)
                        return "0,HOME";
                    else if (diff > 0)
                        return dist + ",UP";
                    else if (diff < 0)
                        return dist + ",DOWN";
                }
                return dist + ",NA";
            }
            catch
            {
                return dist + ",NA";
            }
            finally
            {
                dbx.close();
            }
        }

