        public string STL_CheckActionTaken(string vehicleId, string workflowid, string EditId)
        {
            DataTable dt = dbx.STL_CheckWorkFlowMC(workflowid, EditId);
            string action = "Allow";
            string comment = "OK";
            if (dt != null)
            {
                if (dt.Rows.Count > 0)
                {
                    action = "Block";
                    comment = "Rejected Due to Mandatory Complaint";
                }
                DataTable dtck = dbx.STL_CheckActionTaken(vehicleId);
                for (int i = 0; i < dtck.Rows.Count; i++)
                {
                    if (dtck.Rows[i]["Action"].ToString() == "Extend")
                    {
                        if (action != "Block")
                        {
                            action = "Extend";
                            comment = "Extended to " + dtck.Rows[i]["ExtendedDate"].ToString();
                        }
                    }
                    else
                    {
                        action = dtck.Rows[i]["Action"].ToString();
                        comment = "";
                    }
                }
            }
            dbx.STL_UpdateWorkFlowsStatus(workflowid, action, comment, EditId);
            return action + "|" + comment;
        }
