        public DataTable STL_GetWorkflow(string workflowid)
        {
            DataTable dt = dbx.STL_GetWorkflow(workflowid);
            if (dt != null)
            {
                if (dt.Rows.Count > 0)
                {
                    string ruleid = "0";
                    DataTable dtres = dt.Clone();
                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        if (dt.Rows[i]["RuleId"].ToString() == ruleid)
                        {
                            string comnt = dt.Rows[i]["Comment"].ToString();
                            string Status = dt.Rows[i]["Status"].ToString();
                            string image_link = dt.Rows[i]["image_link"].ToString();
                            string datetime = dt.Rows[i]["datetime"].ToString();
                            string username = dt.Rows[i]["username"].ToString();
                            string level = dt.Rows[i]["level"].ToString();
                            string Action = dt.Rows[i]["Action"].ToString();
                            string wrk_comment = dt.Rows[i]["wrk_comment"].ToString();

                            if (!string.IsNullOrEmpty(comnt))
                                dtres.Rows[dtres.Rows.Count - 1]["Comment"] = comnt;
                            if (!string.IsNullOrEmpty(image_link))
                                dtres.Rows[dtres.Rows.Count - 1]["image_link"] = image_link;
                            dtres.Rows[dtres.Rows.Count - 1]["Status"] = Status;
                            dtres.Rows[dtres.Rows.Count - 1]["datetime"] = datetime;
                            dtres.Rows[dtres.Rows.Count - 1]["username"] = username;
                            dtres.Rows[dtres.Rows.Count - 1]["level"] = level;
                            dtres.Rows[dtres.Rows.Count - 1]["Action"] = Action;
                            dtres.Rows[dtres.Rows.Count - 1]["wrk_comment"] = wrk_comment;
                            ruleid = dt.Rows[i]["RuleId"].ToString();
                        }
                        else
                        {
                            dtres.Rows.Add(dt.Rows[i].ItemArray);
                            ruleid = dt.Rows[i]["RuleId"].ToString();
                        }
                    }
                    return dtres;
                    DataView dv = dtres.DefaultView;
                    dv.Sort = "ListOrder asc";
                    DataTable sortedDT = dv.ToTable();
                    return sortedDT;
                }
                else
                {
                    return dt;
                }
            }
            else
            {
                return null;
            }
        }
