        public string GetDetailedLastPositionData(string SessionId)
        {
            try
            {
                Object[] selectedValues = dbx.getLastPositions(SessionId, null);
                object[] PositiontxtData = dbx.getLatestPositiontxt(SessionId);
                StringBuilder xmlResult = new StringBuilder();
                DateTime now = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff(SessionId));
                //xmlResult .Append( "<?xml version=" + "\"1.0\"" + " encoding=" + "\"UTF-8\"" + "?>\n");
                xmlResult.Append("<DetailedPositions>\n");
                for (int i = 0; i < selectedValues.Length; i++)
                {
                    string vehicleId = (((Object[])selectedValues[i])[(int)headersIndex.trucksIndex]).ToString();
                    string latStr = (((Object[])selectedValues[i])[(int)headersIndex.latitudeIndex]).ToString();
                    string longStr = (((Object[])selectedValues[i])[(int)headersIndex.longitudeIndex]).ToString();
                    double speed = Convert.ToDouble(((Object[])selectedValues[i])[(int)headersIndex.speedIndex]);
                    string timestamp = (((Object[])selectedValues[i])[(int)headersIndex.timesIndex]).ToString();
                    string vehinfo = (((Object[])selectedValues[i])[(int)headersIndex.infoIndex]).ToString();
                    string stop = (((Object[])selectedValues[i])[(int)headersIndex.StopIndex]).ToString();
                    string hvinp = "0";
                    if ((((Object[])selectedValues[i])[13]) != null)
                        hvinp = (((Object[])selectedValues[i])[13]).ToString();

                    string positionsTxt = string.Empty;
                    if (PositiontxtData != null)
                    {
                        int len = PositiontxtData.Length;
                        for (int k = 0; k < len; k++)
                        {
                            if ((((Object[])PositiontxtData[k])[0]).ToString() == vehicleId)
                            {
                                try
                                {
                                    if (Convert.ToDateTime(timestamp) < Convert.ToDateTime((((Object[])PositiontxtData[k])[2]).ToString()).AddMinutes(5))
                                        positionsTxt = (((Object[])PositiontxtData[k])[1]).ToString();
                                    else
                                        positionsTxt = getPositionTxt(latStr, longStr, 3);
                                }
                                catch { }
                                break;
                            }
                        }
                        if (positionsTxt == "")
                        {
                            positionsTxt = getPositionTxt(latStr, longStr, 3);
                        }
                    }
                    else
                    {
                        positionsTxt = getPositionTxt(latStr, longStr, 3);
                    }
                    DataTable dtgeo = dbx.GetLastGeofenceEntry(vehicleId);
                    string GeofenceName = "N/A";
                    string GeofenceInOrOut = "N/A";
                    string GeofenceTime = "N/A";
                    if (dtgeo.Rows.Count > 0)
                    {
                        GeofenceName = dtgeo.Rows[0]["locationstr"].ToString();
                        GeofenceInOrOut = (dtgeo.Rows[0]["outtimedone"].ToString() == "0") ? "IN" : "OUT";
                        GeofenceTime = (dtgeo.Rows[0]["outtimedone"].ToString() == "0") ? Convert.ToDateTime(dtgeo.Rows[0]["intimestamp"].ToString()).ToString("yyyy'-'MM'-'dd HH:mm:ss") : Convert.ToDateTime(dtgeo.Rows[0]["intimestamp"].ToString()).ToString("yyyy'-'MM'-'dd HH:mm:ss");
                    }
                    string username = dbx.getUserId(SessionId);
                    string dist = "0";
                    string runtime = "";
                    if (username.ToLower().Contains("ramco"))//Implemented ONLY For Ramco Cements.
                    {
                        object[] distobj = accumulateDistance(vehicleId, now.ToString("yyyy-MM-dd") + " 00:00", formatDBDate(now), null);
                        if (distobj.Length > 0)
                        {
                            dist = distobj[0].ToString();
                            runtime = distobj[2].ToString();
                        }
                    }
                    DataTable info = dbx.GetVehicleInfoData(vehicleId);
                    string TransName = string.Empty;
                    string odometer = "0";
                    if (info.Rows.Count > 0)
                    {
                        TransName = info.Rows[0]["TransName"].ToString();
                        string OdometerInitialVal = info.Rows[0]["OdometerInitialVal"].ToString();
                        string OdometerInitialValDate = info.Rows[0]["OdometerInitialValDate"].ToString();
                        string GPSDistance = info.Rows[0]["GPSDistance"].ToString();
                        string GPSDistanceFrom = info.Rows[0]["GPSDistanceFrom"].ToString();
                        string GPSDistanceTo = info.Rows[0]["GPSDistanceTo"].ToString();
                        if (string.IsNullOrEmpty(GPSDistanceFrom) && !string.IsNullOrEmpty(OdometerInitialValDate))
                        {
                            if (username.ToLower().Contains("ramco"))//Implemented ONLY For Ramco Cements.
                            {
                                object[] gpsdistobj = accumulateDistance(vehicleId, formatDBDate(Convert.ToDateTime(OdometerInitialValDate)), now.ToString("yyyy-MM-dd") + " 00:00", null);
                                if (gpsdistobj.Length > 0)
                                {
                                    dbx.UpdateGPSDistAndDateinVehicleInfo(vehicleId, formatDBDate(Convert.ToDateTime(OdometerInitialValDate)), now.ToString("yyyy-MM-dd") + " 00:00", gpsdistobj[0].ToString());
                                }
                            }
                        }
                        else if (Convert.ToDateTime(GPSDistanceTo).ToString("yyyy-MM-dd") != now.ToString("yyyy-MM-dd"))
                        {
                            if (username.ToLower().Contains("ramco"))//Implemented ONLY For Ramco Cements.
                            {
                                object[] gpsdistobj = accumulateDistance(vehicleId, formatDBDate(Convert.ToDateTime(GPSDistanceTo)), now.ToString("yyyy-MM-dd") + " 00:00", null);
                                if (gpsdistobj.Length > 0)
                                {
                                    if (!string.IsNullOrEmpty(GPSDistance))
                                        GPSDistance = Math.Round(Convert.ToDecimal(GPSDistance) + Convert.ToDecimal(gpsdistobj[0].ToString())).ToString();
                                    dbx.UpdateGPSDistAndDateinVehicleInfo(vehicleId, null, now.ToString("yyyy-MM-dd") + " 00:00", GPSDistance);
                                }
                            }
                        }
                        if (!string.IsNullOrEmpty(GPSDistance))
                        {
                            odometer = Math.Round(Convert.ToDecimal(OdometerInitialVal) + Convert.ToDecimal(GPSDistance) + Math.Round(Convert.ToDecimal(dist))).ToString();
                        }
                        else
                        {
                            odometer = dist;
                        }
                    }
                    xmlResult.Append("<postiondata>" + "<vehicle>" + vehicleId + "</vehicle>");
                    xmlResult.Append("<uid>" + dbx.getUidFromConfigdata(vehicleId).ToString() + "</uid>");
                    xmlResult.Append("<vehicleinfo>" + vehinfo + "</vehicleinfo>");
                    xmlResult.Append("<gpsupdatedtime>" + Convert.ToDateTime(timestamp).ToString("yyyy'-'MM'-'dd HH:mm:ss") + "</gpsupdatedtime>");
                    xmlResult.Append("<latitude>" + latStr + "</latitude>");
                    xmlResult.Append("<longitude>" + longStr + "</longitude>");
                    xmlResult.Append("<location>" + positionsTxt + "</location>");
                    xmlResult.Append("<speed>" + speed + "</speed>");
                    xmlResult.Append("<stop>" + stop + "</stop>");
                    if (username.ToLower().Contains("ramco"))//Implemented ONLY For Ramco Cements.
                    {
                        xmlResult.Append("<ditancetoday>" + Math.Round(Convert.ToDecimal(dist)) + "</ditancetoday>");
                    }
                    xmlResult.Append("<geofencelocation>" + GeofenceName + "</geofencelocation>");
                    xmlResult.Append("<geofenceinout>" + GeofenceInOrOut + "</geofenceinout>");
                    xmlResult.Append("<geofencedatetime>" + GeofenceTime + "</geofencedatetime>");
                    xmlResult.Append("<transporter>" + TransName + "</transporter>");
                    xmlResult.Append("<odometer>" + Math.Round(Convert.ToDecimal(odometer)) + "</odometer>");
                    xmlResult.Append("<hvinp>" + hvinp + "</hvinp>");
                    xmlResult.Append("</postiondata>");
                }
                xmlResult.Append("</DetailedPositions>");
                return xmlResult.ToString();
            }
            finally
            {
                dbx.close();
            }
        }

        public string GETLASTDATA(string SessionId)
        {
            try
            {
                Object[] selectedValues = dbx.getLastPositions(SessionId, null);
                StringBuilder xmlResult = new StringBuilder();
                DateTime now = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff(SessionId));
                xmlResult.Append("<GetLastDataResult>\n");
                for (int i = 0; i < selectedValues.Length; i++)
                {
                    string vehicleId = (((Object[])selectedValues[i])[(int)headersIndex.trucksIndex]).ToString();
                    string latStr = (((Object[])selectedValues[i])[(int)headersIndex.latitudeIndex]).ToString();
                    string longStr = (((Object[])selectedValues[i])[(int)headersIndex.longitudeIndex]).ToString();
                    double speed = Convert.ToDouble(((Object[])selectedValues[i])[(int)headersIndex.speedIndex]);
                    string timestamp = (((Object[])selectedValues[i])[(int)headersIndex.timesIndex]).ToString();
                    string vehinfo = (((Object[])selectedValues[i])[(int)headersIndex.infoIndex]).ToString();
                    string stop = (((Object[])selectedValues[i])[(int)headersIndex.StopIndex]).ToString();
                    string hvinp = "0";
                    string uid = dbx.getUidFromConfigdata(vehicleId).ToString();
                    if ((((Object[])selectedValues[i])[13]) != null)
                        hvinp = (((Object[])selectedValues[i])[13]).ToString();
                    xmlResult.Append("<GPSData  VehicleID=\"" + uid + "\">");
                    xmlResult.Append("<GPSDeviceId>" + uid + "</GPSDeviceId>");
                    xmlResult.Append("<GPSTime>" + Convert.ToDateTime(timestamp).ToString("yyyy'-'MM'-'dd HH:mm:ss") + "</GPSTime>");
                    xmlResult.Append("<LastEventTime>" + Convert.ToDateTime(timestamp).ToString("yyyy'-'MM'-'dd HH:mm:ss") + "</LastEventTime>");
                    xmlResult.Append("<Latitude>" + latStr + "</Latitude>");
                    xmlResult.Append("<Longitude>" + longStr + "</Longitude>");
                    xmlResult.Append("<SatellitesCount>null</SatellitesCount>");
                    xmlResult.Append("<Speed>" + speed + "</Speed>");
                    xmlResult.Append("<Course>null</Course>");
                    xmlResult.Append("<Sensors><Sensor nil=\"true\" /><Sensor nil=\"true\" /></Sensors>");
                    xmlResult.Append("<ZoneIds><int>null</int><int>null</int></ZoneIds>");
                    xmlResult.Append("<IsPositionActual>ture</IsPositionActual>");
                    xmlResult.Append("<Accuracy>null</Accuracy>");
                    xmlResult.Append("</GPSData>");
                }
                xmlResult.Append("</GetLastDataResult>");
                return xmlResult.ToString();
            }
            finally
            {
                dbx.close();
            }
        }

