        public DataTable STL_GetCheckListData(string workflowid)
        {
            DataTable dt = dbx.STL_GetWorkflow(workflowid);
            if (dt != null)
            {
                if (dt.Rows.Count > 0)
                {
                    string ruleid = "0";
                    DataTable dtres = dt.Clone();
                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        if (dt.Rows[i]["RuleId"].ToString() == ruleid)
                        {
                            string comnt = dt.Rows[i]["Comment"].ToString();
                            string Status = dt.Rows[i]["Status"].ToString();
                            string image_link = dt.Rows[i]["image_link"].ToString();
                            string datetime = dt.Rows[i]["datetime"].ToString();
                            string username = dt.Rows[i]["username"].ToString();
                            string level = dt.Rows[i]["level"].ToString();
                            string Action = dt.Rows[i]["Action"].ToString();
                            string wrk_comment = dt.Rows[i]["wrk_comment"].ToString();
                            string more_img = dt.Rows[i]["more_img"].ToString();

                            if (!string.IsNullOrEmpty(comnt))
                            {
                                if (!string.IsNullOrEmpty(dtres.Rows[dtres.Rows.Count - 1]["Comment"].ToString()))
                                    dtres.Rows[dtres.Rows.Count - 1]["Comment"] = dtres.Rows[dtres.Rows.Count - 1]["Comment"].ToString() + "," + comnt;
                                else
                                    dtres.Rows[dtres.Rows.Count - 1]["Comment"] = comnt;
                            }
                            if (!string.IsNullOrEmpty(image_link))
                            {
                                if (!string.IsNullOrEmpty(dtres.Rows[dtres.Rows.Count - 1]["image_link"].ToString()))
                                    dtres.Rows[dtres.Rows.Count - 1]["image_link"] = dtres.Rows[dtres.Rows.Count - 1]["image_link"].ToString() + "," + image_link;
                                else
                                    dtres.Rows[dtres.Rows.Count - 1]["image_link"] = image_link;
                                //For Adding More Images
                                if (!string.IsNullOrEmpty(more_img))
                                {
                                    if (!string.IsNullOrEmpty(dtres.Rows[dtres.Rows.Count - 1]["image_link"].ToString()))
                                        dtres.Rows[dtres.Rows.Count - 1]["image_link"] = dtres.Rows[dtres.Rows.Count - 1]["image_link"].ToString() + "," + more_img;
                                    else
                                        dtres.Rows[dtres.Rows.Count - 1]["image_link"] = more_img;
                                }
                            }
                            dtres.Rows[dtres.Rows.Count - 1]["Status"] = Status;
                            dtres.Rows[dtres.Rows.Count - 1]["datetime"] = datetime;
                            dtres.Rows[dtres.Rows.Count - 1]["username"] = username;
                            dtres.Rows[dtres.Rows.Count - 1]["level"] = level;
                            dtres.Rows[dtres.Rows.Count - 1]["Action"] = Action;
                            dtres.Rows[dtres.Rows.Count - 1]["wrk_comment"] = wrk_comment;
                            ruleid = dt.Rows[i]["RuleId"].ToString();
                        }
                        else
                        {
                            dtres.Rows.Add(dt.Rows[i].ItemArray);
                            string more_img = dt.Rows[i]["more_img"].ToString();
                            if (!string.IsNullOrEmpty(more_img))
                                dtres.Rows[dtres.Rows.Count - 1]["image_link"] = dtres.Rows[dtres.Rows.Count - 1]["image_link"].ToString() + "," + more_img;
                            ruleid = dt.Rows[i]["RuleId"].ToString();
                        }
                    }
                    DataView dv = dtres.DefaultView;
                    dv.Sort = "ListOrder asc";
                    DataTable sortedDT = dv.ToTable();
                    return sortedDT;
                }
                else
                {
                    return dt;
                }
            }
            else
            {
                return null;
            }
        }
        public static string GetUser_IP()
        {
            string VisitorsIPAddr = string.Empty;
            try
            {
                if (System.Web.HttpContext.Current.Request.ServerVariables["HTTP_X_FORWARDED_FOR"] != null)
                {
                    VisitorsIPAddr = System.Web.HttpContext.Current.Request.ServerVariables["HTTP_X_FORWARDED_FOR"].ToString();
                }
                else if (System.Web.HttpContext.Current.Request.UserHostAddress.Length != 0)
                {
                    VisitorsIPAddr = System.Web.HttpContext.Current.Request.UserHostAddress;
                }
            }
            catch { }
            return VisitorsIPAddr;
        }
        public static string getHostName()
        {
            try
            {
                try
                {
                    return System.Web.HttpContext.Current.Request.Url.ToString().ToLower().Substring(0, System.Web.HttpContext.Current.Request.Url.ToString().ToLower().IndexOf("senselwebservice.asmx"));
                }
                catch { return System.Web.HttpContext.Current.Request.Url.Host; }
            }
            catch
            {
                return string.Empty;
            }
        }
