        public void WebServiceRequestlog(string MethodName, string Token, string CustomerCode, string login, string sessionId, string HostName, string UserIp)
        {
            try
            {
                string GlobalId = "0";
                try
                {
                    if (!string.IsNullOrEmpty(CustomerCode) && string.IsNullOrEmpty(sessionId))
                        sessionId = getCustomerLoginAccSession(CustomerCode);
                    if (string.IsNullOrEmpty(sessionId) && !string.IsNullOrEmpty(login))
                        sessionId = getSessionIdFromLogin(login);
                    if (!string.IsNullOrEmpty(sessionId))
                        GlobalId = GetGlobalAccountIdBySession(sessionId);
                    if (!string.IsNullOrEmpty(sessionId) && string.IsNullOrEmpty(login))
                        login = getUserId(sessionId);
                }
                catch { }
                XmlDb.AdminService.Service admser = new XmlDb.AdminService.Service();
                admser.WebServiceRequestLog(MethodName, HostName, Token, CustomerCode, login, GlobalId, UserIp);

            }
            catch { }
            finally
            {
                dbx.close();
            }

        }

        public void WebServiceRequestlogIMEI(string MethodName, string Token, string IMEI, string login, string sessionId, string HostName, string UserIp)
        {
            try
            {

                BusinessLogicLayer.BLL objbll = new BusinessLogicLayer.BLL();
                string GlobalId = "0";
                try
                {
                    sessionId = objbll.getSessionIdFromLogin(login);
                    GlobalId = objbll.GetGlobalAccountIdBySession(sessionId);
                }
                catch { }
                XmlDb.AdminService.Service admser = new XmlDb.AdminService.Service();
                admser.WebServiceRequestLog(MethodName, HostName, Token, IMEI, login, GlobalId, UserIp);
            }
            catch { }

        }


