        public DataTable GetConsolidatedReport(string session)
        {

            DataSet ds = GetVehiclesBySessionId(session);
            string vehicles = null;
            for (int i = 0; i < ds.Tables[0].Rows.Count; i++)
            {
                if (i == 0)
                    vehicles = "'" + ds.Tables[0].Rows[0][0].ToString() + "'";
                else
                    vehicles += ",'" + ds.Tables[0].Rows[i][0].ToString() + "'";
            }
            return dbx.GetConsolidatedReport(session, vehicles);
        }

