        public string GetAuxInputByVehicle(string vehicleid, string timestamp)
        {
            DataTable dt = dbx.GetAuxInputByVehicle(vehicleid, timestamp);
            if (dt.Rows.Count > 0)
            {
                string OnOffType = dt.Rows[0]["OnOffType"].ToString();
                if (!string.IsNullOrEmpty(OnOffType))
                {
                    if (OnOffType == "DOOR")
                    {
                        string dist = dt.Rows[0]["distance"].ToString();
                        return OnOffType + " " + ((dist == "0") ? "CLOSE" : "OPEN");
                    }
                    else
                    {
                        string idlinginst = dt.Rows[0]["idlingInstances"].ToString();
                        return OnOffType + " " + ((idlinginst == "1") ? "ON" : "OFF");
                    }
                }
                string TempSense = dt.Rows[0]["TempSense"].ToString();
                if (!string.IsNullOrEmpty(TempSense))
                {
                    if (TempSense == "TEMP")
                    {
                        string Temp = dt.Rows[0]["CallerPhone"].ToString();
                        return ((Temp == "-200" || Temp == "-100" || Temp == "-200.00" || Temp == "-100.00") ? "TS Not Connected" : Temp);
                    }
                    else
                    {
                        return dt.Rows[0]["Temperature"].ToString();
                    }
                }
            }
            return "";
        }
        public string GetDriverInfoByVehicleLanding(string vehicleid)
        {
            DateTime now = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff());
            string drv = dbx.getdrivername(vehicleid, now.ToString("yyyy-MM-dd HH:mm:ss"));
            string DriverId = "0";
            if (drv.Contains(','))
                DriverId = drv.Split(',')[1];
            DataTable dt = dbx.GetDriverInfoByVehicleLanding(vehicleid, DriverId);
            if (dt.Rows.Count > 0)
            {
                string userdefId = dt.Rows[0]["UserDefinedDriverId"].ToString();
                string drivername = dt.Rows[0]["Driver"].ToString();
                if (!string.IsNullOrEmpty(drivername) && !drivername.Contains(userdefId))
                    drivername += " " + userdefId;
                string MobileNo = dt.Rows[0]["MobileNo"].ToString();
                if (!string.IsNullOrEmpty(drivername))
                {
                    return drivername + "\n" + MobileNo;
                }
                else
                {
                    return "No driver Assigned";
                }
            }
            else return "No driver Assigned";
        }
