        public string GetVehicleTripStatus(string vehicleId)
        {
            try
            {
                DataTable dt = dbx.GetVehicleTripStatus(vehicleId);
                string str = "";
                if (dt != null && dt.Rows.Count > 0)
                {
                    if (!string.IsNullOrEmpty(dt.Rows[0]["Destination"].ToString()))
                        str += dt.Rows[0]["Destination"].ToString() + "<br>";
                    if (!string.IsNullOrEmpty(dt.Rows[0]["ETA"].ToString()))
                        str += Convert.ToDateTime(dt.Rows[0]["ETA"].ToString()).ToString("dd'/'MM'/'yyyy HH:mm:ss") + "<br>";
                    if (!string.IsNullOrEmpty(dt.Rows[0]["Status"].ToString()))
                        str += dt.Rows[0]["Status"].ToString() + "<br>";
                    if (!string.IsNullOrEmpty(str))
                        str = str.Substring(0, str.Length - 4);
                }
                return str;
            }
            catch (Exception ex)
            {
                return "";
            }
        }

