        //Distance & RunTime By SessionId/VehicleId
        public DataTable GetDistanceRunTimeData(string sessionId, string fromDateStr, string toDateStr, string vehicleId, int IsDaily)
        {
            Object[] vehicles = dbx.getVehicles(sessionId);
            DateTime fromDate = Convert.ToDateTime(fromDateStr);
            DateTime toDate = Convert.ToDateTime(toDateStr);
            DataTable dtRes = new DataTable();
            dtRes.Columns.Add("SNo");
            dtRes.Columns.Add("Vehicle");
            dtRes.Columns.Add("-");
            for (int j = 0; j < (toDate - fromDate).TotalDays; j++)
            {
                dtRes.Columns.Add(fromDate.AddDays(j).ToString("dd") + " " + fromDate.AddDays(j).ToString("ddd"));
            }
            dtRes.Columns.Add("MonthTotal");
            int cnt = 1;
            for (int i = 0; i < vehicles.Length; i++)
            {
                String vehicle = (String)((Object[])vehicles[i])[0];

                if (!string.IsNullOrEmpty(vehicleId))
                {
                    if (!vehicleId.Contains(vehicle))
                        continue;
                }
                String info = (String)((Object[])vehicles[i])[4];
                int typeIndex = info.IndexOf(',', 0);
                if (typeIndex > 0)
                {
                    info = info.Substring(0, typeIndex);
                }

                string vehcat = dbx.GetCategoryByVehicle(vehicleId);
                if (!string.IsNullOrEmpty(vehcat))
                    info = "(" + vehcat + ")" + info;

                double totalDistance = 0;
                Object lastLatLong = null;
                ArrayList runTimes = new ArrayList();
                TimeSpan totalTime = new TimeSpan(0);
                dtRes.Rows.Add(dtRes.NewRow());
                dtRes.Rows.Add(dtRes.NewRow());
                int rowcnt = dtRes.Rows.Count;
                dtRes.Rows[rowcnt - 2][0] = cnt;
                cnt++;
                dtRes.Rows[rowcnt - 2][1] = vehicle;
                dtRes.Rows[rowcnt - 1][1] = info;

                dtRes.Rows[rowcnt - 2][2] = "Distance (Km)";
                dtRes.Rows[rowcnt - 1][2] = "Run Time (Hr : Min)";

                for (int j = 0; j <= (toDate.Day - fromDate.Day); j++)
                {
                    fromDateStr = dbx.formatDBDate(fromDate.AddDays(j));
                    toDateStr = dbx.formatDBDate(fromDate.AddDays(j + 1));
                    double distance = 0;
                    TimeSpan runTime = new TimeSpan(0, 0, 0);
                    Object[] ret = getDistanceDatabyVehicles(vehicle, fromDate.AddDays(j));
                    if (ret != null)
                    {
                        if (ret.Length > 0)
                        {
                            distance = Convert.ToDouble(((Object[])ret[0])[0]);
                            runTime = TimeSpan.FromSeconds(Convert.ToDouble(((Object[])ret[0])[1]));
                        }
                    }
                    if (distance == 0)
                    {
                        ret = accumulateDistance(vehicle, fromDateStr, toDateStr, lastLatLong);
                        if (ret != null)
                        {
                            distance = (double)ret[0];
                            runTime = (TimeSpan)ret[2];
                            lastLatLong = ret[1];
                        }
                        else
                        {
                            distance = 0;
                            runTime = new TimeSpan(0, 0, 0);
                        }

                        if (fromDate.AddDays(j) < DateTime.Now.AddDays(-2))
                        {
                            dbx.insertDayDistance(vehicle, fromDate.AddDays(j), distance.ToString(), runTime);
                        }
                    }
                    totalTime = totalTime.Add(runTime);
                    totalDistance += distance;

                    dtRes.Rows[rowcnt - 2][j + 3] = Math.Round(distance, 1);
                    dtRes.Rows[rowcnt - 1][j + 3] = String.Format("{0,3}:{1}", runTime.Days * 24 + runTime.Hours, runTime.Minutes).Trim();
                }
                if (IsDaily == 1)
                {
                    DataTable lList = dbx.GetMonthTotalDistance(toDate, vehicle);

                    string TotalMonthDistance = Convert.ToString(lList.Rows[0][0]);
                    double TotalRunTime = 0.0;
                    double.TryParse(Convert.ToString(lList.Rows[0][1]), out TotalRunTime);

                    if (!string.IsNullOrEmpty(TotalMonthDistance))
                    {
                        totalDistance += Convert.ToDouble(TotalMonthDistance);
                        TimeSpan RunTime = TimeSpan.FromSeconds(TotalRunTime);
                        totalTime = totalTime.Add(RunTime);
                    }
                }
                dtRes.Rows[rowcnt - 2][dtRes.Columns.Count - 1] = Math.Round(totalDistance, 1);
                dtRes.Rows[rowcnt - 1][dtRes.Columns.Count - 1] = String.Format("{0,3}:{1}", totalTime.Days * 24 + totalTime.Hours, totalTime.Minutes).Trim();
            }
            return dtRes;
        }

        //Speed Report By SessionId/VehicleId
        public DataTable GetSpeedReport(string sessionId, string fromDateStr, string toDateStr, string vehicleId, double SpeedLimit, string methodtype)
        {
            Object[] vehicles = dbx.getVehicles(sessionId);
            Object[] keyParams = dbx.getVehicleTripParams(sessionId, vehicleId);
            int duration = 0;
            //Modified by suvarna on 7/4/2021 for LMV parameter thresholds
            string allowedMaxSpeedDur = (((Object[])keyParams[0])[8]).ToString();
            if (allowedMaxSpeedDur.Contains(","))
                duration = Convert.ToInt32(allowedMaxSpeedDur.Split(',')[0]);
            else
                duration = Convert.ToInt32(((Object[])keyParams[0])[8]);
            duration = duration / 60;
            DateTime fromDate = Convert.ToDateTime(fromDateStr);
            DateTime toDate = Convert.ToDateTime(toDateStr);
            DataTable dtRes = new DataTable();
            dtRes.Columns.Add("VehicleId");
            dtRes.Columns.Add("Date");
            dtRes.Columns.Add("Time");
            dtRes.Columns.Add("Location");
            dtRes.Columns.Add("Remarks");
            if (methodtype != "SpeedReport")
            {
                dtRes.Columns.Add("Speed(Km/hr)");
            }

            for (int j = 0; j <= (toDate.Day - fromDate.Day); j++)
            {
                fromDateStr = dbx.formatDBDate(fromDate.AddDays(j));
                toDateStr = dbx.formatDBDate(fromDate.AddDays(j + 1));

                for (int i = 0; i < vehicles.Length; i++)
                {

                    Object[] values = new Object[0];
                    String vehicle = (String)((Object[])vehicles[i])[0];

                    if (!string.IsNullOrEmpty(vehicleId))
                    {
                        if (!vehicleId.Contains(vehicle))
                            continue;
                    }
                    String info = (String)((Object[])vehicles[i])[4];
                    int typeIndex = info.IndexOf(',', 0);
                    if (typeIndex > 0)
                    {
                        info = info.Substring(0, typeIndex);
                    }
                    values = dbx.getRouteLatLong(vehicle, fromDateStr, toDateStr);
                    for (int x = 0; x < values.Length; x++)
                    {
                        String[] overspeedInfo = null;
                        if (methodtype == "SpeedReport")
                        {
                            overspeedInfo = showOverspeed(x, values, SpeedLimit);
                            if (overspeedInfo != null)
                            {
                                DataRow lRow = dtRes.NewRow();
                                lRow["VehicleId"] = vehicle;
                                lRow["Date"] = overspeedInfo[0];
                                lRow["Time"] = overspeedInfo[1];
                                lRow["Location"] = overspeedInfo[2];
                                //lRow["Speed(Km/hr)"] = overspeedInfo[4];
                                lRow["Remarks"] = overspeedInfo[3];
                                dtRes.Rows.Add(lRow);

                            }
                        }
                        else
                        {
                            overspeedInfo = vehicleOverspeedInfo(x, values, duration);
                            if (overspeedInfo != null)
                            {
                                DataRow lRow = dtRes.NewRow();
                                lRow["VehicleId"] = vehicle;
                                lRow["Date"] = overspeedInfo[0];
                                lRow["Time"] = overspeedInfo[1];
                                lRow["Location"] = overspeedInfo[2];
                                lRow["Remarks"] = overspeedInfo[4];
                                lRow["Speed(Km/hr)"] = overspeedInfo[3];
                                dtRes.Rows.Add(lRow);
                            }
                        }
                    }
                }
            }
            return dtRes;
        }

        //Added by sagar for new geofence
        public void UpdateVehicleInPlantOutTime(string fromdata = "", string todate = "")
        {
            //get all records for which outtimedone unable to populate
            logWriter.WriteToLog("BLL:UpdateVehicleinplant() Start:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);
            DataRow[] value = dbx.GetAllNullOutTime(fromdata, todate);
            if (value.Length > 0)
            {

                List<vehicleinplant> updateingvalues = GetAllOutTimes(value, fromdata, todate);

                for (int i = 0; i < updateingvalues.Count; i++)
                {
                    dbx.UpdateVehicelinplant(updateingvalues[i].vehicle, updateingvalues[i].locationstring, updateingvalues[i].timestamp);
                }

            }
            logWriter.WriteToLog("BLL:UpdateVehicleinplant() End:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);
        }

        public List<vehicleinplant> GetAllOutTimes(DataRow[] value, string FromDate = "", string ToDate = "")
        {
            logWriter.WriteToLog("BLL:GetvehicleinplantUpdates() Start:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);

            List<vehicleinplant> updatingvalues = new List<vehicleinplant>();
            double minlat = 0.00;
            double minlng = 0.00;
            double maxlat = 0.00;
            double maxlng = 0.00;
            string fromdate = "";
            string todate = "";
            DataSet valuespositiondata;
            for (int i = 0; i < value.Length; i++)
            {
                if (FromDate == "" && ToDate == "")
                {
                    timeZone = dbx.GetTimeZoneDiff();
                    DateTime indianTime = DateTime.UtcNow;
                    indianTime = indianTime.AddSeconds(timeZone);
                    todate = dbx.formatDBDate(indianTime);
                    fromdate = dbx.formatDBDate(indianTime.AddMinutes(-1440));
                    minlat = Convert.ToDouble(value[i].ItemArray[3]);
                    minlng = Convert.ToDouble(value[i].ItemArray[4]);
                    maxlat = Convert.ToDouble(value[i].ItemArray[5]);
                    maxlng = Convert.ToDouble(value[i].ItemArray[6]);
                    TimeSpan differenceintime = (Convert.ToDateTime(todate) - Convert.ToDateTime(value[i].ItemArray[2].ToString()));
                    int timediff = differenceintime.Days;
                    if (timediff < 2)
                        fromdate = dbx.formatDBDate(Convert.ToDateTime(value[i].ItemArray[2]));
                }
                else
                {
                    fromdate = FromDate;
                    todate = ToDate;
                }
                valuespositiondata = dbx.GetFirstOutTimeFromPlant(value[i].ItemArray[0].ToString(), fromdate, todate, minlat, minlng, maxlat, maxlng);

                if (valuespositiondata.Tables[0].Rows.Count > 0)
                {
                    var val = new vehicleinplant()
                    {
                        vehicle = value[i].ItemArray[0].ToString(),
                        locationstring = value[i].ItemArray[1].ToString(),
                        timestamp = dbx.formatDBDate(DateTime.Parse(valuespositiondata.Tables[0].Rows[0]["TimeStamp"].ToString())),
                    };

                    updatingvalues.Add(val);

                }

            }
            logWriter.WriteToLog("BLL:GetvehicleinplantUpdates() End:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);

            return (updatingvalues);
        }

