        public ArrayList GetRouteDeviation(DataTable reffroute, object[] positiondata, string vehicle, string Sms = "")
        {
            string accountid = dbx.getAccountIdByVehicleId(vehicle).ToString();
            ArrayList DeviationList = new ArrayList();
            int table1_count = positiondata.Length;
            int table0_count = reffroute.Rows.Count;

            double start_lat = 0.0;
            double start_lng = 0.0;
            double routedeviationlimit = 1000;
            double latlngThreshold = 0.002;
            Object[] tripParams = dbx.getVehicleTripParams(dbx.getSessionIdByVehicle(vehicle), vehicle);
            try
            {
                routedeviationlimit = (int)(Convert.ToSingle(((Object[])tripParams[0])[13]));
                latlngThreshold = routedeviationlimit / 100000; //100m => 0.001 , 500m => 0.005
            }
            catch (Exception e)
            {

            }
            routedeviationlimit = routedeviationlimit / 1000;//meters to KM
            double extraGeofence = 0.002;

            double end_lat = 0.0;
            double end_lng = 0.0;
            DateTime EndTs = new DateTime();
            DateTime startTs = DateTime.Parse((((Object[])positiondata[0])[1]).ToString());
            int count = 0;
            for (int i = 0; i < table1_count; i++)
            {
                double lat = Convert.ToDouble((((Object[])positiondata[i])[4]).ToString());
                double lng = Convert.ToDouble((((Object[])positiondata[i])[5]).ToString());
                int startbit = Convert.ToInt32((((Object[])positiondata[i])[2]).ToString());//Modified by suvarna on 8/12/2021 to avoid recording of RD during data gap issue
                if (startbit == 1)
                    count = 0;
                bool Found = false;
                int stopbit = Convert.ToInt32((((Object[])positiondata[i])[3]).ToString());
                if (stopbit != 1)//Modified by suvarna on 27/9/2021 to avoid checking RD when stop bit=1
                {
                    for (int j = 0; j < table0_count; j++)
                    {
                        if (lat >= Convert.ToDouble(reffroute.Rows[j]["minlat"]) - extraGeofence && lat <= Convert.ToDouble(reffroute.Rows[j]["maxlat"]) + extraGeofence &&
                            lng >= Convert.ToDouble(reffroute.Rows[j]["minlong"]) - extraGeofence && lng <= Convert.ToDouble(reffroute.Rows[j]["maxlong"]) + extraGeofence)
                        {
                            Found = true;
                            //This method will add flag with vehicle no to check wether it is continous deviation. if it is countinous
                            //deviation it will send only one deviation sms instead every 15 min so it reduce the sms.
                            if (!string.IsNullOrEmpty(Sms) && Sms == "1")
                                dbx.AddRouteDeviatedSmsAlertFlag(vehicle, 0, DateTime.Parse((((Object[])positiondata[i])[1]).ToString()));
                            break;
                        }
                    }
                }
                else Found = true;//Modified by suvarna on 17/12/2021 to avoid recording of rd event when stop bit is 1 due to sudden fluctuation
                if (!Found && count == 0)
                {
                    start_lat = lat;
                    start_lng = lng;
                    startTs = DateTime.Parse((((Object[])positiondata[i])[1]).ToString());
                    count++;
                }
                else if (Found && count >= 2)//Modified by suvarna on 8/12/2021 as there was an exception (dividing by 0)
                {
                    end_lat = lat;
                    end_lng = lng;
                    //compute distance 
                    double distance = dbx.computeDistance(start_lat, start_lng, end_lat, end_lng);
                    string addressStr = dbx.getPositionTxt(end_lat.ToString(), end_lng.ToString(), 0);
                    EndTs = DateTime.Parse((((Object[])positiondata[i])[1]).ToString());

                    if (distance > routedeviationlimit && !addressStr.ToUpper().Contains("TOTAL"))
                    {
                        int estimatedSpeed = 65;//Added by suvarna on 7/12/2021 to avoid recording of RD violations in case of GPS fluctuation/Straightline
                        double estimatedDistance = estimatedSpeed / (count / 2);
                        bool IsAllowedRegion = dbx.IsRouteDeviationAllowedRegion(accountid, end_lat.ToString(), end_lng.ToString());
                        if (!IsAllowedRegion)
                        {
                            if (distance <= estimatedDistance)
                            {
                                dbx.storeVehicleViolations(vehicle, "", "ROUTE DEVIATION", dbx.formatDBDate(startTs), distance, "ROUTE DEVIATION ALERT", addressStr,
                                    start_lat.ToString(), start_lng.ToString(), Convert.ToInt16((EndTs - startTs).TotalMinutes));
                                string SmsFlag = string.Empty;
                                if (!string.IsNullOrEmpty(Sms) && Sms == "1")
                                {
                                    SmsFlag = dbx.IsRouteDeviatedSmsAlertFlag(vehicle);
                                    if (!string.IsNullOrEmpty(SmsFlag) && SmsFlag == "0")
                                        dbx.AddRouteDeviatedSmsAlertFlag(vehicle, 1, DateTime.Parse((((Object[])positiondata[i])[1]).ToString()));
                                    else if (string.IsNullOrEmpty(SmsFlag))
                                    {
                                        dbx.AddRouteDeviatedSmsAlertFlag(vehicle, 0, DateTime.Parse((((Object[])positiondata[i])[1]).ToString()));
                                        SmsFlag = "0";
                                    }
                                }
                                ArrayList Deviation = new ArrayList();
                                Deviation.Add(vehicle);
                                Deviation.Add("ROUTE DEVIATION");
                                Deviation.Add(startTs);
                                Deviation.Add(Math.Round((EndTs - startTs).TotalMinutes, 2));
                                Deviation.Add(distance);
                                Deviation.Add(addressStr);
                                Deviation.Add(SmsFlag);
                                DeviationList.Add(Deviation);
                            }
                        }
                    }
                    count = 0;
                    Found = true;
                }
                else if ((table1_count - 1) == i && count >= 2 && Found == false)
                {
                    end_lat = lat;
                    end_lng = lng;
                    //compute distance 
                    double distance = dbx.computeDistance(start_lat, start_lng, end_lat, end_lng);
                    string addressStr = dbx.getPositionTxt(end_lat.ToString(), end_lng.ToString(), 0);
                    EndTs = DateTime.Parse((((Object[])positiondata[i])[1]).ToString());
                    Object[] value = accumulateDistance(vehicle, startTs.ToString(), EndTs.ToString(), null);

                    if (distance > routedeviationlimit && !addressStr.ToUpper().Contains("TOTAL"))
                    {
                        int estimatedSpeed = 65;
                        double estimatedDistance = estimatedSpeed / (count / 2);
                        bool IsAllowedRegion = dbx.IsRouteDeviationAllowedRegion(accountid, end_lat.ToString(), end_lng.ToString());
                        if (!IsAllowedRegion)
                        {
                            if (distance <= estimatedDistance)
                            {
                                dbx.storeVehicleViolations(vehicle, "", "ROUTE DEVIATION", dbx.formatDBDate(startTs), distance, "ROUTE DEVIATION ALERT", addressStr,
                                start_lat.ToString(), start_lng.ToString(), Convert.ToInt16((EndTs - startTs).TotalMinutes));
                                string SmsFlag = string.Empty;
                                if (!string.IsNullOrEmpty(Sms) && Sms == "1")
                                {
                                    SmsFlag = dbx.IsRouteDeviatedSmsAlertFlag(vehicle);
                                    if (!string.IsNullOrEmpty(SmsFlag) && SmsFlag == "0")
                                        dbx.AddRouteDeviatedSmsAlertFlag(vehicle, 1, DateTime.Parse((((Object[])positiondata[i])[1]).ToString()));
                                    else if (string.IsNullOrEmpty(SmsFlag))
                                    {
                                        dbx.AddRouteDeviatedSmsAlertFlag(vehicle, 0, DateTime.Parse((((Object[])positiondata[i])[1]).ToString()));
                                        SmsFlag = "0";
                                    }
                                }
                                ArrayList Deviation = new ArrayList();
                                Deviation.Add(vehicle);
                                Deviation.Add("ROUTE DEVIATION");
                                Deviation.Add(startTs);
                                Deviation.Add(Math.Round((EndTs - startTs).TotalMinutes, 2));
                                Deviation.Add(distance);
                                Deviation.Add(addressStr);
                                Deviation.Add(SmsFlag);
                                DeviationList.Add(Deviation);
                            }
                        }
                    }
                    count = 0;
                    Found = true;
                }
                else if (!Found)
                {
                    count++;
                }
            }
            return DeviationList;
        }
