            if (table.Rows.Count > 0)
            {
                bool iscustomer = false;
                string dcid = "0";
                foreach (DataRow row in table.Rows)
                {
                    if (row["CustomerCode"].ToString() == customercode)
                    {
                        iscustomer = true;
                        dcid = row["DCNo"].ToString();
                        break;
                    }
                }
                if (iscustomer)
                {
                    return dbx.insertDriverFeedback(customercode, dcid, driver[1], cooperative, attitude, cleanness, PPE, unload_procedure, comments, latlng, IMEI, vehicle, AccountId);
                }
                else
                {
                    return "Customer code is wrong";
                }
            }
            else
                return null;
        }


