        //
        // This method returns the corrected distance in cases where 
        // a. ignition wire has come OFF
        // b. there are straight lines
        // It will correct for num st. lines < 10 and also if the st lines are < 200 km in length
        //
        public float returnCorrectedDistance(string vehicleId, string startTimeStr, string endTimeStr, int numStLines)
        {
            float distance = 0.0F;
            try
            {
                Object[] ret = accumulateDistanceCorrectForStopBit(vehicleId, startTimeStr, endTimeStr, null);
                distance = Convert.ToSingle(ret[0]);
                TimeSpan tripTime = (TimeSpan)(ret[2]);
                String tripDuration = Math.Floor(tripTime.TotalHours).ToString() + "hrs" + ":" + Math.Floor((tripTime.TotalMinutes % 60)).ToString() + "min";
            }
            catch
            {
                //Response.Write("<BR> SKIPPING ");
                // continue;
            }
            if (numStLines < 10)
            {
                Object[] values = dbx.getmissingdataLatLong(vehicleId, startTimeStr, endTimeStr);
                for (int j = 0; j < values.Length; j++)
                {
                    DateTime lastUpdateTime = Convert.ToDateTime(((Object[])values[j])[0]);
                    decimal slat = Convert.ToDecimal(((Object[])values[j])[1]);
                    decimal slong = Convert.ToDecimal(((Object[])values[j])[2]);
                    DateTime currentUpdateTime = Convert.ToDateTime(((Object[])values[j])[3]);
                    decimal elat = Convert.ToDecimal(((Object[])values[j])[4]);
                    decimal elong = Convert.ToDecimal(((Object[])values[j])[5]);
                    bool latepackets = dbx.checkforLatePackets(vehicleId, dbx.formatDBDate(lastUpdateTime), dbx.formatDBDate(currentUpdateTime));
                    if (latepackets == true)
                    {
                        continue;
                    }
                    Object[] straightlineData = accumulateDistance(vehicleId, dbx.formatDBDate(lastUpdateTime), dbx.formatDBDate(currentUpdateTime), null);
                    double straightDistance = Convert.ToDouble(straightlineData[0]);
                    if (straightDistance > 200)
                    {
                        j = values.Length; // exit the loop to take the next trip
                        //nosignal = true;
                    }
                    else
                    {
                        decimal googleDistance = getgoogleDistance(slat.ToString(), slong.ToString(), elat.ToString(), elong.ToString());
                        distance = distance + (float)googleDistance - (float)straightDistance;
                    }
                }
            }
            return (distance);
        }

        public decimal getgoogleDistance(string lat1, string long1, string lat2, string long2)
        {
            BusinessLogicLayer.BLL objBll = new BusinessLogicLayer.BLL();
            string googledist = objBll.getDistanceByGoogleDistanceMatrix(lat1, long1, lat2, long2);
            try
            {

                if (googledist != "NoData" || !string.IsNullOrEmpty(googledist))
                {
                    decimal gd = Convert.ToDecimal(googledist) / 1000;//m to km
                    return gd;

                }
                else
                    return 0;
            }
            catch { return 0; }

        }
