        public DataTable GetAllVehiclesHalt(string SessionId, DateTime FromDate, DateTime Todate, int MaxHaltDuration)
        {

            Object[] vehicles = dbx.getVehicles(SessionId);
            string strFromDate = dbx.formatDBDate(FromDate);
            string strToDate = dbx.formatDBDate(Todate);
            DataTable lVehicleHalt = new DataTable();
            lVehicleHalt.Columns.Add("VehicleId");
            lVehicleHalt.Columns.Add("VehicleInfo");
            lVehicleHalt.Columns.Add("FromDate");
            lVehicleHalt.Columns.Add("Location");
            lVehicleHalt.Columns.Add("ToDate");
            lVehicleHalt.Columns.Add("Remarks");
            for (int i = 0; i < vehicles.Length; i++)
            {
                try
                {
                    string vehicleId = (String)((Object[])vehicles[i])[0];
                    string vehicleinfo = (String)((Object[])vehicles[i])[4];
                    string vehcat = dbx.GetCategoryByVehicle(vehicleId);
                    if (!string.IsNullOrEmpty(vehcat))
                        vehicleinfo = "(" + vehcat + ")" + vehicleinfo;

                    if (Todate.Subtract(FromDate).TotalDays > 3)
                    {
                        for (int m = 0; m < Todate.Subtract(FromDate).TotalDays; m++)
                        {
                            strFromDate = dbx.formatDBDate(FromDate.AddDays(m));
                            strToDate = dbx.formatDBDate(FromDate.AddDays(m + 1).AddSeconds(-1));
                            Object[] values = null;
                            try
                            {
                                values = dbx.getRouteLatLong(vehicleId, strFromDate, strToDate);
                            }
                            catch (Exception e) { try { values = dbx.getRouteLatLong(vehicleId, strFromDate, strToDate); } catch { } }
                            if (values != null)
                            {
                                for (int j = 0; j < values.Length; j++)
                                {
                                    Object[] haltInfoList = showHalt2(j, values, true, MaxHaltDuration);
                                    if (haltInfoList != null)
                                    {
                                        for (int k = 0; k < haltInfoList.Length; k++)
                                        {
                                            String[] haltInfo = (String[])haltInfoList[k];
                                            if (!String.IsNullOrEmpty(haltInfo[3]))  // put entries only when vehicle halted over a threshold minutes
                                            {
                                                DataRow lRow = lVehicleHalt.NewRow();
                                                lRow["VehicleId"] = vehicleId;
                                                lRow["VehicleInfo"] = vehicleinfo;
                                                lRow["FromDate"] = Convert.ToDateTime(haltInfo[0]).ToString("yyyy-MM-dd") + " " + haltInfo[1];
                                                lRow["Location"] = haltInfo[2];
                                                lRow["ToDate"] = Convert.ToDateTime(haltInfo[5]).ToString("yyyy-MM-dd") + " " + haltInfo[6];
                                                lRow["Remarks"] = haltInfo[3];
                                                lVehicleHalt.Rows.Add(lRow);
                                                lVehicleHalt.AcceptChanges();
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                    else
                    {
                        Object[] values = null;
                        try
                        {
                            values = dbx.getRouteLatLong(vehicleId, strFromDate, strToDate);
                        }
                        catch (Exception ex) { try { values = dbx.getRouteLatLong(vehicleId, strFromDate, strToDate); } catch { } }
                        if (values != null)
                        {
                            for (int j = 0; j < values.Length; j++)
                            {
                                Object[] haltInfoList = showHalt2(j, values, true, MaxHaltDuration);
                                if (haltInfoList != null)
                                {
                                    for (int k = 0; k < haltInfoList.Length; k++)
                                    {
                                        String[] haltInfo = (String[])haltInfoList[k];
                                        if (!String.IsNullOrEmpty(haltInfo[3]))  // put entries only when vehicle halted over a threshold minutes
                                        {
                                            DataRow lRow = lVehicleHalt.NewRow();
                                            lRow["VehicleId"] = vehicleId;
                                            lRow["VehicleInfo"] = vehicleinfo;
                                            lRow["FromDate"] = Convert.ToDateTime(haltInfo[0]).ToString("yyyy-MM-dd") + " " + haltInfo[1];
                                            lRow["Location"] = haltInfo[2];
                                            lRow["ToDate"] = Convert.ToDateTime(haltInfo[5]).ToString("yyyy-MM-dd") + " " + haltInfo[6];
                                            lRow["Remarks"] = haltInfo[3];
                                            lVehicleHalt.Rows.Add(lRow);
                                            lVehicleHalt.AcceptChanges();
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                catch (Exception e) { string err = e.Message; }
            }
            return lVehicleHalt;
        }

        public DataTable GetAllVehicleInPlantBySessionIdDate(string SessionId, DateTime fromDate, DateTime toDate, string VehicleId, string Location, int Duration)
        {
            DataTable lVehicleInPlant = dbx.GetAllVehicleInPlantBySessionIdDate(SessionId, fromDate, toDate, VehicleId, Location);
            DataTable lReportTable = new DataTable();
            lReportTable.Columns.Add("VehicleId");
            lReportTable.Columns.Add("Location");
            lReportTable.Columns.Add("PlantInDate");
            lReportTable.Columns.Add("PlantInTime");
            lReportTable.Columns.Add("PlantOutDate");
            lReportTable.Columns.Add("PlantOutTime");
            lReportTable.Columns.Add("TotalInTime");
            lReportTable.Columns.Add("Remarks");

            for (int i = 0; i < lVehicleInPlant.Rows.Count; i++)
            {
                DataRow lRow = lReportTable.NewRow();

                lRow["VehicleId"] = lVehicleInPlant.Rows[i][0].ToString();
                lRow["Location"] = lVehicleInPlant.Rows[i][1].ToString();
                DateTime InDateTime = new DateTime();
                DateTime OutDateTime = new DateTime();
                InDateTime = Convert.ToDateTime(lVehicleInPlant.Rows[i][2].ToString());
                lRow["PlantInDate"] = InDateTime.ToString("dd/MM/yyy");
                lRow["PlantInTime"] = InDateTime.ToString("HH:mm:ss");
                int IsOutTimeDone = Convert.ToInt32(lVehicleInPlant.Rows[i][4].ToString());
                if (IsOutTimeDone > 0)
                {
                    OutDateTime = Convert.ToDateTime(lVehicleInPlant.Rows[i][3].ToString());
                    lRow["PlantOutDate"] = OutDateTime.ToString("dd/MM/yyy");
                    lRow["PlantOutTime"] = OutDateTime.ToString("HH:mm:ss");
                    TimeSpan lTotalTime = OutDateTime.Subtract(InDateTime);
                    lRow["TotalInTime"] = FormatDateTime(lTotalTime);
                    lRow["Remarks"] = "Vehicle Has left the Plant";
                }
                else
                {
                    lRow["PlantOutDate"] = "--";
                    lRow["PlantOutTime"] = "--";
                    int TimeZone = dbx.GetTimeZoneDiff();
                    DateTime CurrentTime = DateTime.UtcNow;
                    OutDateTime = CurrentTime.AddSeconds(TimeZone);
                    TimeSpan lTotalTime = OutDateTime.Subtract(InDateTime);
                    lRow["TotalInTime"] = FormatDateTime(lTotalTime);
                    lRow["Remarks"] = "Vehicle still in the Plant";
                }
                int lTotalMinutes = OutDateTime.Subtract(InDateTime).Minutes;
                if (lTotalMinutes > Duration)
                {
                    lReportTable.Rows.Add(lRow);
                }
            }
            return lReportTable;
        }

        public string FormatDateTime(TimeSpan pTime)
        {
            string time = string.Empty;
            if (pTime.Days > 0)
            {
                time = time + pTime.Days + "D:";
            }
            if (pTime.Hours > 0)
            {
                time = time + pTime.Hours + "Hrs:";
            }
            if (pTime.Minutes >= 0)
            {
                time = time + pTime.Minutes + "Mins";
            }
            return time;
        }

