        public string formatMessage(string sessionid, string type, string templateType, string eventName, string date, string vehicleId, string location,
            string duration, string driver, string eventValue, string message, string speed)
        {
            try
            {
                location = location.Split(',')[0];// Modified by suvarna on 28/5/2021 to reduce length of location, as sms are not getting delivered due to huge length of location
                string startTag = "<";
                string endTag = ">";
                if (templateType == "Email")
                {
                    startTag = "&lt;";
                    endTag = "&gt;";
                }
                string login = getUserId(sessionid);
                StringBuilder htmlTemplate = new StringBuilder(GetHtmlTemplateByUser(login, type, templateType));
                if (!string.IsNullOrEmpty(htmlTemplate.ToString()))
                {
                    htmlTemplate.Replace(startTag + "EventName" + endTag, eventName);
                    htmlTemplate.Replace(startTag + "Date" + endTag, date);
                    htmlTemplate.Replace(startTag + "VehicleNo" + endTag, vehicleId.Replace(" ", string.Empty));
                    htmlTemplate.Replace(startTag + "Transporter" + endTag, GetTransporterNameByVehicleId(vehicleId));
                    htmlTemplate.Replace(startTag + "Location" + endTag, location);
                    if (!string.IsNullOrEmpty(eventValue))
                        htmlTemplate.Replace(startTag + "EventValue" + endTag, Math.Round(Convert.ToDouble(eventValue), 2).ToString());
                    htmlTemplate.Replace(startTag + "Duration" + endTag, duration);
                    htmlTemplate.Replace(startTag + "Speed" + endTag, speed);
                    htmlTemplate.Replace(startTag + "Driver" + endTag, driver);
                    if (templateType == "SMS")
                        htmlTemplate.Replace("<br>", Environment.NewLine);
                    return htmlTemplate.ToString();
                }
                else
                    return message;
            }
            catch
            {
                return message;
            }
        }

