        public string GetVehiclesInfoNew(String sessionIdstr, string Datetime = null)
        {
            //  logWriter.WriteToLog("BLL:GetVehiclesInfo() Start:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);
            try
            {
                String auxinputinfo = String.Empty;
                string panicbuttonstr = null;
                Object[] panicInfo = null;
                String acAlertStr = null;
                String TipperAlertStr = null;
                String BatteryLowAlertStr = null;
                String[] positionsTxt = null;

                String[] positionHeader = { "positionTxt", "direction" };
                String[] directions = { "right", "tr", "top", "tl", "left", "dl", "down", "dr" };
                Object[] positionsTxtArray = null;
                Object[] idlinginstancesArray = null;
                Object[] Remarksarray = null;
                Object[] IconTypesarray = null;
                Object[] BatteryStatusarray = null;
                String fuelInLts = "-1";
                String[] headersStr = { "trucks", "times", "latitude", "longitude", "speed", "unixts", "info" };
                String dial = String.Empty;
                timeZone = GetTimeZoneDiff(sessionIdstr);


                // logWriter.WriteToLog("BLL:GetVehiclesInfo() PCreateViewSt" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);
                //bool ret = dbx.createVehiclesView(sessionIdstr);
                //logWriter.WriteToLog("BLL:GetVehiclesInfo() PCreateViewEnd" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);
                //logWriter.WriteToLog("BLL:GetVehiclesInfo() PGetVehSt" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);
                DataTable selectedValues = dbx.getLastPositionsnew(sessionIdstr, Datetime);
                //  logWriter.WriteToLog("BLL:GetVehiclesInfo() PGetVehEnd" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);

                int gid = dbx.getGroupId(sessionIdstr);


                /*here we got all the vehicle list and their corrsponding 
                positiondata list in the selectedValues variable*/

                ArrayList Remarks_List = new ArrayList();
                ArrayList IconTypes_List = new ArrayList();
                ArrayList BatteryStatus_List = new ArrayList();
                //added for listing out all the remarks field for all  the vehicles combinedly

                ArrayList idlinginstancesList = new ArrayList();
                //added for listing out all the Auxinput field for all  the vehicles combinedly
                try
                {
                    Object auxinputinfoObj = dbx.getAuxillaryInputInfo(sessionIdstr);
                    /*for getting whether there is a auxinput field present in the accountgroups
                    table if it is not present put NC in the idlinginstancesList*/
                    if (auxinputinfoObj != null)
                    {
                        auxinputinfo = auxinputinfoObj.ToString();
                    }
                    else
                        auxinputinfo = "null";
                }
                catch (Exception)
                {

                }

                if (auxinputinfo == "null" || auxinputinfo.Trim() == "AT")
                {
                    idlinginstancesList.Add("NC");
                }
                ArrayList positionsTxtList = new ArrayList();
                panicbuttonstr = null;   //variable to fetch the vehicleid having panic button presed from panic table

                //ArrayList fuelTxtList = new ArrayList();
                //String[] fuelTxt = null;				  //to hold fuel in Lts

                DateTime endDate = DateTime.UtcNow;
                endDate = endDate.AddSeconds(timeZone);//for converting in to IST
                if (Datetime != null)
                    endDate = Convert.ToDateTime(Datetime);
                //panic switch info is to be extracted from the panic table where we will access the alert time with the vehicle
                //info if the time is within a perticular window value then panic info is to be flashed


                String maxAlertDelayStr = "3600";

                String aapMaxAlertDelayStr = System.Web.Configuration.WebConfigurationManager.AppSettings["MAXALERTDELAY"];
                if (!String.IsNullOrEmpty(aapMaxAlertDelayStr))
                    maxAlertDelayStr = aapMaxAlertDelayStr;

                String maxPanicDelayStr = "180";
                String appMaxPanicDelaySt = System.Web.Configuration.WebConfigurationManager.AppSettings["MAXPANICPRESSEDDELAY"];
                if (!String.IsNullOrEmpty(appMaxPanicDelaySt))
                    maxPanicDelayStr = appMaxPanicDelaySt;
                Object[] account = dbx.getAccountInfo(sessionIdstr);
                String acntGrpAtt = "";
                if (account != null)
                    if (account.Length > 0)
                    {
                        acntGrpAtt = account[3].ToString();//Convert.ToString(((Object[])account[0])[3]);
                    }
                logWriter.WriteToLog("BLL:GetVehiclesInfo() PGetPanicSt" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);
                // checkPanic will behave differently if the accountgroup belongs to ASSET-SMART
                panicInfo = dbx.checkPanic(endDate.AddSeconds(-Convert.ToInt32(maxAlertDelayStr)), gid, acntGrpAtt);
                logWriter.WriteToLog("BLL:GetVehiclesInfo() PGetPanicEnd" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);

                int pfl = 0;
                String GpsNconnected = string.Empty;
                String BatteryOK = string.Empty;
                if (panicInfo != null)
                {
                    for (pfl = 0; pfl < panicInfo.Length; pfl++)
                    {
                        if (((((Object[])panicInfo[pfl])[3]).ToString()).Equals("NO GPS SIGNAL"))
                        {
                            GpsNconnected = GpsNconnected + "|" + (((Object[])panicInfo[pfl])[0]).ToString();
                        }
                        else if (((((Object[])panicInfo[pfl])[3]).ToString()).Equals("BATTERY OK"))
                        {
                            BatteryOK = BatteryOK + "|" + (((Object[])panicInfo[pfl])[0]).ToString();
                        }
                        else if (((((Object[])panicInfo[pfl])[3]).ToString()).Equals("BATTERY LOW"))
                        {
                            BatteryOK = BatteryOK.Replace("|" + (((Object[])panicInfo[pfl])[0]).ToString(), "");
                        }
                    }
                }


                //the GPRS last update time can be received from lastaccess table by getDisconnectedVehicles()
                logWriter.WriteToLog("BLL:GetVehiclesInfo() PGetDistSt" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);
                Object[] GPRSvalues = dbx.getDisconnectedVehicles(sessionIdstr, 0);
                logWriter.WriteToLog("BLL:GetVehiclesInfo() PGetDistEnd" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);

                double maxSpeed = 70.0;
                if (gid != 0)
                    maxSpeed = Convert.ToDouble(dbx.getMaxSpeed(gid));
                int maxSpeedDisplayTime = 300;//maximum time in seconds there will be a display of non zero speed
                // Get the delay for GPS and GPRS from the web.config
                String maxGprsDelayStr = "1200";
                String appMaxGprsDelayStr = System.Web.Configuration.WebConfigurationManager.AppSettings["MAXGPRSDELAY"];
                if (!String.IsNullOrEmpty(appMaxGprsDelayStr))
                    maxGprsDelayStr = appMaxGprsDelayStr;

                String maxGpsDelayStr = "240";
                String appMaxGpsDelayStr = System.Web.Configuration.WebConfigurationManager.AppSettings["MAXGPSDELAY"];
                if (!String.IsNullOrEmpty(appMaxGpsDelayStr))
                    maxGpsDelayStr = appMaxGpsDelayStr;
                logWriter.WriteToLog("BLL:GetVehiclesInfo() InitEnd:" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);

                String GetPosFromVehpostxt = "true";
                String GetPosFromVehpostxtStr = System.Web.Configuration.WebConfigurationManager.AppSettings["GetPosFromVehpostxt"];
                if (!String.IsNullOrEmpty(GetPosFromVehpostxtStr))
                    GetPosFromVehpostxt = GetPosFromVehpostxtStr;
                object[] PositiontxtData = null;
                if (GetPosFromVehpostxt == "true")
                {
                    PositiontxtData = dbx.getLatestPositiontxt(sessionIdstr);
                    logWriter.WriteToLog("BLL:GetVehiclesInfo() PosTxtNos:" + PositiontxtData.Length, true);
                }
                logWriter.WriteToLog("BLL:GetVehiclesInfo() PGetLoopSt" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);
                for (int i = 0; i < selectedValues.Rows.Count; i++)
                {
                    string vehicleId = selectedValues.Rows[i]["VehicleID"].ToString();
                    string latStr = selectedValues.Rows[i]["latitude"].ToString();
                    string longStr = selectedValues.Rows[i]["longitude"].ToString();
                    double speed = Convert.ToDouble(selectedValues.Rows[i]["speed"]);
                    string timestamp = selectedValues.Rows[i]["times"].ToString(); ;
                    string TempSense = selectedValues.Rows[i]["TempSense"].ToString();

                    if (panicInfo != null && panicInfo.Length > 0)//if panic presssed then add the vehicle no to the list
                    {
                        for (int h = 0; h < panicInfo.Length; h++)
                        {
                            if ((((((Object[])panicInfo[h])[0]).ToString()).Trim()).Equals(vehicleId.Trim()))
                            {
                                if (((((Object[])panicInfo[h])[3]).ToString()).Equals("panic"))
                                {
                                    if ((endDate.AddSeconds(-Convert.ToInt32(maxPanicDelayStr))) < DateTime.Parse((((Object[])panicInfo[h])[1]).ToString()))
                                    {
                                        panicbuttonstr = panicbuttonstr + vehicleId + "|" + (((Object[])panicInfo[h])[1]).ToString() + "|" + "alert";
                                        panicbuttonstr = panicbuttonstr + ";";
                                    }
                                    else
                                    {
                                        panicbuttonstr = panicbuttonstr + vehicleId + "|" + (((Object[])panicInfo[h])[1]).ToString() + "|" + "store";
                                        panicbuttonstr = panicbuttonstr + ";";
                                    }
                                }
                                else if (((((Object[])panicInfo[h])[3]).ToString()).Equals("AC"))
                                {
                                    acAlertStr = acAlertStr + vehicleId + "|" + (DateTime.Parse((((Object[])panicInfo[h])[1]).ToString()).ToString("yyyy-MM-dd hh:mm:ss"));
                                    acAlertStr = acAlertStr + ";";
                                }
                                else if (((((Object[])panicInfo[h])[3]).ToString()).Equals("Tipper"))
                                {
                                    TipperAlertStr = TipperAlertStr + vehicleId + "|" + (DateTime.Parse((((Object[])panicInfo[h])[1]).ToString()).ToString("yyyy-MM-dd hh:mm:ss"));
                                    TipperAlertStr = TipperAlertStr + ";";
                                }
                                else if (((((Object[])panicInfo[h])[3]).ToString()).Equals("BATTERY LOW"))
                                {
                                    if (!BatteryOK.Contains(vehicleId))
                                    {
                                        BatteryLowAlertStr = BatteryLowAlertStr + vehicleId + "|" + (DateTime.Parse((((Object[])panicInfo[h])[1]).ToString()).ToString("yyyy-MM-dd hh:mm:ss"));
                                        BatteryLowAlertStr = BatteryLowAlertStr + ";";
                                    }
                                }
                            }
                        }

                    }

                    //positionsTxt = new String[2];
                    //positionsTxt[1] = selectedValues.Rows[i]["direction"].ToString();//Angle between last latlng and current latlng
                    //positionsTxt[0] = "";
                    //if (PositiontxtData != null && GetPosFromVehpostxt == "true")
                    //{
                    //    int len = PositiontxtData.Length;
                    //    for (int k = 0; k < len; k++)
                    //    {
                    //        if ((((Object[])PositiontxtData[k])[0]).ToString() == vehicleId)
                    //        {
                    //            try
                    //            {
                    //                if (Convert.ToDateTime(timestamp) < Convert.ToDateTime((((Object[])PositiontxtData[k])[2]).ToString()).AddMinutes(5))
                    //                    positionsTxt[0] = (((Object[])PositiontxtData[k])[1]).ToString();
                    //                else
                    //                    positionsTxt[0] = getPositionTxt(latStr, longStr, 3);
                    //            }
                    //            catch { }
                    //            break;
                    //        }
                    //    }
                    //    if (positionsTxt[0] == "")
                    //    {
                    //        positionsTxt[0] = getPositionTxt(latStr, longStr, 3);
                    //    }
                    //}
                    //else
                    //{
                    //    positionsTxt[0] = getPositionTxt(latStr, longStr, 3);
                    //}

                    //positionsTxtList.Add(positionsTxt);

                    try
                    {
                        if (auxinputinfo == "yes")
                        {
                            String idlinginstance = null;
                            String OnOffType = dbx.getOnOffType(vehicleId);//for getting what type of auxualary input available for the vehicle

                            if (OnOffType == null)
                                idlinginstance = "NC";
                            else
                            {
                                String idlinginstanceOnOff = dbx.getOnOffIdlingInstances(vehicleId);//wheather aux input is switched on or off
                                if (idlinginstanceOnOff == "1")
                                    idlinginstance = "ON";
                                else
                                    idlinginstance = "OFF";
                                //idlinginstance = Convert.ToInt16(idlinginstanceobj.ToString());
                                idlinginstance = String.Concat(OnOffType, " ", idlinginstance);
                            }
                            idlinginstancesList.Add(idlinginstance);
                        }
                    }
                    catch (Exception)
                    {

                    }

                    //CODE STARTED FOR   ADDING REMARKS FIELD


                    String Remarks = null;
                    // Get last GPS access time we can get it from the positiondata which is acesssed by getLastPositions() in xmldb
                    String timestamp_last_GPS_update = selectedValues.Rows[i]["ServerTS"].ToString();
                    DateTime GPS_last_update_date = DateTime.Parse(timestamp_last_GPS_update);

                    int StopBit = int.Parse(selectedValues.Rows[i]["stop"].ToString());

                    DateTime timestamp_last_GPRS_update_date = GPS_last_update_date;
                    if (Datetime != null)
                    {
                        timestamp_last_GPRS_update_date = GPS_last_update_date;
                    }
                    else
                    {
                        for (int j = 0; j < GPRSvalues.Length; j++)
                        {
                            if (vehicleId.Equals((((Object[])GPRSvalues[j])[0]).ToString()))
                            {
                                // GPRS last access time
                                timestamp_last_GPRS_update_date = DateTime.Parse((((Object[])GPRSvalues[j])[2]).ToString());
                                break;
                            }
                        }
                    }
                    if ((endDate - timestamp_last_GPRS_update_date).TotalSeconds < Convert.ToInt32(maxGprsDelayStr))//>>>>>>>>>>>>>>>>>>>>For testing TotalMinutes to TotalDays
                    {

                        if (Math.Abs((endDate - GPS_last_update_date).TotalSeconds) > Convert.ToInt32(maxGpsDelayStr))//>>>>>>>>>>>>>>>>>>>>For testing TotalMinutes to TotalDays
                        {
                            speed = 0; selectedValues.Rows[i]["speed"] = "0";
                            selectedValues.Rows[i]["times"] = timestamp_last_GPRS_update_date.ToString("dd MMM yy,hh:mm:ss tt");
                            Remarks = Remarks + "GNA,";
                        }
                        else
                        {
                            if ((endDate - timestamp_last_GPRS_update_date).TotalSeconds > maxSpeedDisplayTime || Math.Abs((endDate - GPS_last_update_date).TotalSeconds) > Convert.ToInt32(maxGprsDelayStr))//Added on 13-7-2014 in the request that the speed should be zero if it is not rechable for more then 20 Mins
                            { speed = 0; selectedValues.Rows[i]["speed"] = "0"; }
                            if (StopBit == 1)
                            {
                                if (TempSense == "SLOW")
                                    Remarks = Remarks + "VF,";//Vehicle OFF //Asp PerBEML-PSR Req 
                                else
                                    Remarks = Remarks + "VH,";//Vehicle Halted
                                speed = 0;
                                selectedValues.Rows[i]["speed"] = "0";
                            }
                            else if (speed <= 3)
                            {
                                if (TempSense == "SLOW")
                                    Remarks = Remarks + "VO,";//Vehicle ON //Asp PerBEML-PSR Req 
                                else
                                    Remarks = Remarks + "VI,";//Vehicle Idling
                                speed = 0; selectedValues.Rows[i]["speed"] = "0";
                            }
                            else
                            {
                                if (TempSense == "SLOW")
                                    Remarks = Remarks + "VO,";//Vehicle ON //Asp PerBEML-PSR Req 
                                else if (speed > maxSpeed)
                                    Remarks = Remarks + "OS,";//Over Speeding
                                else
                                    Remarks = Remarks + "VM,";//Vehicle Moving
                            }
                        }
                    }
                    else
                    {
                        if ((endDate - timestamp_last_GPRS_update_date).TotalSeconds > maxSpeedDisplayTime)//Added on 13-7-2014 in the request that the speed should be zero if it is not rechable for more then 20 Mins
                        { speed = 0; selectedValues.Rows[i]["speed"] = "0"; }
                        Remarks = Remarks + "NR,";//Not Reachable
                        selectedValues.Rows[i]["speed"] = "0";

                    }
                    if (!String.IsNullOrEmpty(GpsNconnected))
                        if (GpsNconnected.Contains(vehicleId))
                            Remarks = "GNA";//No GPS Signal
                    if (!String.IsNullOrEmpty(panicbuttonstr))
                        if (panicbuttonstr.Contains(vehicleId))
                            Remarks = "PBP";//Panic Button Pressed
                    if (!String.IsNullOrEmpty(TipperAlertStr))
                        if (TipperAlertStr.Contains(vehicleId))
                            Remarks = "TPON";//Tipper ON
                    if (!String.IsNullOrEmpty(BatteryLowAlertStr))
                        if (BatteryLowAlertStr.Contains(vehicleId))
                            Remarks = Remarks + "BL";//Batery Low


                    Remarks_List.Add(Remarks);
                    IconTypes_List.Add(selectedValues.Rows[i]["IconType"]);
                    BatteryStatus_List.Add(selectedValues.Rows[i]["BV"]);
                    //CODE FOR ADDING REMARKS ENDS HERE  			
                }
                logWriter.WriteToLog("BLL:GetVehiclesInfo() PGetLoopEnd" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);

                // Now that fuel information is also being shown we need to dump javascript variables for that as well 
                positionsTxtArray = positionsTxtList.ToArray();
                idlinginstancesArray = idlinginstancesList.ToArray();
                Remarksarray = Remarks_List.ToArray();
                IconTypesarray = IconTypes_List.ToArray();
                BatteryStatusarray = BatteryStatus_List.ToArray();
                if (String.IsNullOrEmpty(panicbuttonstr))
                {
                    int len = 0;
                    try
                    {
                        len = panicbuttonstr.Length;
                    }
                    catch
                    {
                        panicbuttonstr = "NC";
                    }
                    if (len == 0)
                        panicbuttonstr = "NC";
                }

                if (String.IsNullOrEmpty(acAlertStr))
                {
                    int len = 0;
                    try
                    {
                        len = acAlertStr.Length;
                    }
                    catch
                    {
                        acAlertStr = "NC";
                    }
                    if (len == 0)
                        acAlertStr = "NC";
                }
                if (String.IsNullOrEmpty(TipperAlertStr))
                {
                    int len = 0;
                    try
                    {
                        len = TipperAlertStr.Length;
                    }
                    catch
                    {
                        TipperAlertStr = "NC";
                    }
                    if (len == 0)
                        TipperAlertStr = "NC";
                }
                int latIndex = 2;
                int longIndex = 3;
                string vehiclesPositionInfo = String.Empty;
                //vehiclesPositionInfo = writeZoomAjax(selectedValue, 2, 3);
                vehiclesPositionInfo += "#";
                // Write fuel info.
                vehiclesPositionInfo += fuelInLts + "#" + dial + "#";
                vehiclesPositionInfo += panicbuttonstr + "#";
                if (TipperAlertStr == "NC")
                    vehiclesPositionInfo += acAlertStr + "#";
                else
                    vehiclesPositionInfo += TipperAlertStr + "#";

                for (int i = 0; i < selectedValues.Rows.Count; i++)
                {
                    for (int j = 0; j < headersStr.Length; j++)
                    {
                        vehiclesPositionInfo += selectedValues.Rows[i][j].ToString() + "#";
                    }
                    vehiclesPositionInfo += ((Object[])positionsTxtArray[i])[0] + "#";
                    vehiclesPositionInfo += ((Object[])positionsTxtArray[i])[1] + "#";
                    if (idlinginstancesArray.Length == 1 && idlinginstancesArray[0].ToString() == "NC")
                        vehiclesPositionInfo += "NC" + "#";
                    else
                        vehiclesPositionInfo += idlinginstancesArray[i].ToString() + "#";
                    vehiclesPositionInfo += Remarksarray[i].ToString() + "#";
                    vehiclesPositionInfo += IconTypesarray[i].ToString() + "#";
                    vehiclesPositionInfo += BatteryStatusarray[i].ToString() + "#";
                }

                dbx.close();
                logWriter.WriteToLog("BLL:GetVehiclesInfo() PEnd" + DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss:fff"), true);
                return vehiclesPositionInfo;
            }
            catch
            {
                dbx.close();
                throw;
            }
            finally { dbx.close(); }
        }
