        public string VehicleChange(string[] lList)
        {
            try
            {
                string IsExist = dbx.IsVehicleExistByVehicleId(lList[1]);
                if (IsExist == "0")
                    return UpdateConfigData(lList, false);
                else
                {
                    IsExist = dbx.IsVehicleBelongToAccount(lList[1], lList[6]);
                    if (Convert.ToInt32(IsExist) >= 1)
                    {
                        IsExist = dbx.IsVehicleBelongToAccount(lList[1]);
                        if (IsExist == "1")
                            return UpdateConfigData(lList, true);
                        //return "Vehicle number already exist in the system, please make sure you have entered correct...! ";
                        else if (IsExist == "0")
                            return UpdateConfigData(lList, false);
                        else
                            return "Failed,please try again...!";
                    }
                    else
                        return UpdateConfigData(lList, true);
                    //return "Vehicle number already exist in the system, please make sure you have entered correct...! ";
                }
            }
            catch (Exception ex)
            {
                return "Failed,please try again...!";
            }
        }

