        public string MapVehicleToUser(string[] lList)
        {
            try
            {
                string[] VehicleList = lList[0].Split(',');
                string Result = string.Empty;
                if (lList[1] == "0")
                {
                    //Adding vehicles from vehiclegroupsmap
                    foreach (string lVehilce in VehicleList)
                    {
                        dbx.AddVehicleGroupMap(lVehilce, lList[2]);
                    }
                }
                else if (lList[1] == "1")
                {
                    //Removing vehicles from vehiclegroupsmap
                    foreach (string lVehilce in VehicleList)
                    {
                        dbx.RemoveVehicleGroupMapByGroupId(lList[2], lVehilce);
                    }
                }
                return "Moved vehicles for selected user...! ";
            }
