        public string UpdateConfigData(string[] lList, bool Isexists)
        {
            string Result = string.Empty;
            DateTime Current = DateTime.Now;
            if (Isexists)
            {
                string uid = dbx.GetUIDByVehicleIdWithoutSpace(lList[1]);
                if (!string.IsNullOrEmpty(uid))
                {
                    //Replace old uid to inst
                    Result = dbx.UpdateVehicleIdByUID(uid, uid, Current.ToString("yyyy-MM-dd"));
                    if (Result == "1")
                    {
                        DataTable dt = dbx.GetConfigdataByUid(uid);
                        string vehInfo = uid;
                        if (dt != null && dt.Rows.Count > 0)
                            vehInfo += " " + dt.Rows[0]["TrackerPhone"].ToString();
                        //Inserting Vehicle table
                        Result = dbx.AddVehicle(uid, lList[6], lList[7], lList[8], vehInfo);
                        //Inserting VehicleGroupsMap
                        Result = dbx.AddVehicleGroupMap(uid, lList[3]);
                        //Inserting vehicle change log
                        Result = dbx.AddVehicleChange(uid, uid, lList[1], lList[3], lList[4], lList[5]);
                        //Updating vehicleid in vehicle category table with new vehicleid
                        Result = dbx.UpdateVehicleCategoryVehByVehicleid(lList[1], uid);
                    }
                }
            }
            Result = dbx.UpdateVehicleIdByUID(lList[0], lList[1], Current.ToString("yyyy-MM-dd"));
            if (Result == "1")
            {
                DataTable dt = dbx.GetConfigdataByUid(lList[0]);
                string vehInfo = lList[0];
                if (dt != null && dt.Rows.Count > 0)
                    vehInfo += " " + dt.Rows[0]["TrackerPhone"].ToString();
                //Inserting Vehicle table
                Result = dbx.AddVehicle(lList[1], lList[6], lList[7], lList[8], vehInfo);
                //Inserting VehicleGroupsMap
                Result = dbx.AddVehicleGroupMap(lList[1], lList[3]);
                //Inserting vehicle change log
                Result = dbx.AddVehicleChange(lList[0], lList[1], lList[2], lList[3], lList[4], lList[5]);
                //Updating vehicleid in vehicle category table with new vehicleid
                Result = dbx.UpdateVehicleCategoryVehByVehicleid(lList[2], lList[1]);
                return "Updated successfully...!";
            }
            else
                return "Unable to update, please try again...!";
        }

