        public void SendMailTransporterMgmtReviewMailICT(string FormId, string Purpose, string type, string joiningdate, string reasonforchange, string driverapptrainie, string safedriver, string Experience, string login, string addedby, string reviewedby, string drivername, string vehicleid, string status, string remarks, string accountid, string TransporterId)
        {
            string EmailId = "", EmailId_cc = "", EmailId_bcc = "";
            DataTable MailIdConfig = dbx.GetMailIdsConfig(Convert.ToInt32(accountid), Purpose, "");
            string Name = "";
            if (MailIdConfig != null)
            {
                if (MailIdConfig.Rows.Count > 0)
                {
                    Name = MailIdConfig.Rows[0]["Name"].ToString();
                    EmailId = MailIdConfig.Rows[0]["EmailIds"].ToString();
                    EmailId_cc = MailIdConfig.Rows[0]["EmailIds_cc"].ToString();
                    EmailId_bcc = MailIdConfig.Rows[0]["EmailIds_bcc"].ToString();
                }
            }
            //string transmailid = dbx.GetTransporterMailId(TransporterId);
            //if (EmailId == "")
            //    EmailId = transmailid;
            //else
            //    EmailId += "," + transmailid;
            if (EmailId != "")
            {
                String emailServer = System.Web.Configuration.WebConfigurationManager.AppSettings["emailServer"];
                string FromMail = System.Web.Configuration.WebConfigurationManager.AppSettings["ReportingEmailId"];
                string Password = System.Web.Configuration.WebConfigurationManager.AppSettings["ReportingEmailPassword"];
                if (String.IsNullOrEmpty(emailServer))
                    emailServer = "localhost";
                PDFWriter.EmailSender es = new PDFWriter.EmailSender(emailServer);
                es = new PDFWriter.EmailSender(emailServer);
                string emailBody = "<html><body style='font-family: Calibri;'>";
                emailBody += "Dear Sir/Madam,<br/><br/>Please find below details for " + type + " <br/><br/>";
                if (!string.IsNullOrEmpty(vehicleid))
                    emailBody += "Vehicle No:" + vehicleid + "<br/>";
                if (!string.IsNullOrEmpty(drivername))
                    emailBody += "Driver Name:" + drivername + "<br/>";
                if (!string.IsNullOrEmpty(joiningdate))
                    emailBody += "Joining Date:" + joiningdate + "<br/>";
                if (!string.IsNullOrEmpty(reasonforchange))
                    emailBody += "Reason For Change:" + reasonforchange + "<br/>";
                if (!string.IsNullOrEmpty(driverapptrainie))
                    emailBody += "Smart Driver Training:" + driverapptrainie + "<br/>";
                if (!string.IsNullOrEmpty(safedriver))
                    emailBody += "Safe Driver Theme 1-6:" + safedriver + "<br/>";
                if (!string.IsNullOrEmpty(Experience))
                    emailBody += " Total Driving Experience:" + Experience + "<br/>";
                if (!string.IsNullOrEmpty(remarks))
                    emailBody += "Remarks:" + remarks + "<br/>";
                if (!string.IsNullOrEmpty(addedby))
                    emailBody += "Added By:" + addedby + "<br/>";
                if (!string.IsNullOrEmpty(reviewedby))
                    emailBody += "Reviewed By:" + reviewedby + "<br/>";
                if (!string.IsNullOrEmpty(status))
                    emailBody += "Status:" + status + "<br/>";
                string domainName = GetBaseURL();
                StringCipher sc = new StringCipher();
                string data = sc.Encrypt(FormId + "|" + DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss") + "|" + Name);
                string url = domainName + "/TransporterManagement/DriverRecruitment2Review.aspx?secpw=" + data;
                emailBody += "To Review:<a href='" + url + "'>Click here to Review</a><br/>";
                emailBody += "<br/><br/>If a new window doesn't open automatically please copy the URL down and paste it in your browser to manually complete the process.<br/>";
                emailBody += "<br/>" + url;
                emailBody += "<br/><br/>Thanks and Regards,<br/>Sensel Telematics</body><html>";
                es.setupEmail(FromMail, EmailId, "Transporter Management - " + type, emailBody.ToString(), EmailId_cc, EmailId_bcc);
                es.setBodyHtml(true);
                try
                {
                    es.send(FromMail, Password);
                }
                catch { }
            }
        }
        public void SendMailTransporterMgmtICT(string Purpose, string type, string login, string addedby, string reviewedby, string drivername, string vehicleid, string status, string remarks, string accountid, string TransporterId)
        {
            string EmailId = "", EmailId_cc = "", EmailId_bcc = "";
            DataTable MailIdConfig = dbx.GetMailIdsConfig(Convert.ToInt32(accountid), Purpose, login);
            if (MailIdConfig != null)
            {
                if (MailIdConfig.Rows.Count > 0)
                {
                    EmailId = MailIdConfig.Rows[0]["EmailIds"].ToString();
                    EmailId_cc = MailIdConfig.Rows[0]["EmailIds_cc"].ToString();
                    EmailId_bcc = MailIdConfig.Rows[0]["EmailIds_bcc"].ToString();
                }
            }
            string transmailid = dbx.GetTransporterMailId(TransporterId);
            if (EmailId == "")
                EmailId = transmailid;
            else
                EmailId += "," + transmailid;
            if (EmailId != "")
            {
                String emailServer = System.Web.Configuration.WebConfigurationManager.AppSettings["emailServer"];
                string FromMail = System.Web.Configuration.WebConfigurationManager.AppSettings["ReportingEmailId"];
                string Password = System.Web.Configuration.WebConfigurationManager.AppSettings["ReportingEmailPassword"];
                if (String.IsNullOrEmpty(emailServer))
                    emailServer = "localhost";
                PDFWriter.EmailSender es = new PDFWriter.EmailSender(emailServer);
                es = new PDFWriter.EmailSender(emailServer);
                string emailBody = "<html><body style='font-family: Calibri;'>";
                emailBody += "Dear Sir/Madam,<br/><br/>Please find below details for " + type + " <br/><br/>";
                if (!string.IsNullOrEmpty(vehicleid))
                    emailBody += "Vehicle No:" + vehicleid + "<br/>";
                if (!string.IsNullOrEmpty(drivername))
                    emailBody += "Driver Name:" + drivername + "<br/>";
                if (!string.IsNullOrEmpty(remarks))
                    emailBody += "Remarks:" + remarks + "<br/>";
                if (!string.IsNullOrEmpty(addedby))
                    emailBody += "Added By:" + addedby + "<br/>";
                if (!string.IsNullOrEmpty(reviewedby))
                    emailBody += "Reviewed By:" + reviewedby + "<br/>";
                if (!string.IsNullOrEmpty(status))
                    emailBody += "Status:" + status + "<br/>";
                emailBody += "<br/><br/>Thanks and Regards,<br/>Sensel Telematics</body><html>";

                es.setupEmail(FromMail, EmailId, "Transporter Management - " + type, emailBody.ToString(), EmailId_cc, EmailId_bcc);
                es.setBodyHtml(true);
                try
                {
                    es.send(FromMail, Password);
                }
                catch { }
            }
        }
