                + "Date Of Registation : " + Convert2CamelCase(dt.Rows[0]["Date Of Registation"].ToString()) + "<br/>"
                + "Year of Manufacture : " + Convert2CamelCase(dt.Rows[0]["Year of Manufacture"].ToString()) + "<br/>"
                + "Reviewed By : " + reviews.Rows[0]["ReviewBy"].ToString() + "<br/>"
                + "Status : " + reviews.Rows[0]["Status"].ToString() + "<br/>"
                + "Comment : " + reviews.Rows[0]["Comment"].ToString() + "<br/>";
            if (result.StartsWith("Send Mail"))
                emailBody += "<br/><b>Note: </b>Sent For Next Level of Review<br/>";
            SendFormatedMailWithAttachment(sessionid, emailBody, Subject, key + "_Review", new string[] { }, "", false);
            if (result.StartsWith("Send Mail"))
            {
                try
                {
                    string[] splitStr = result.Split(new string[] { "@&@" }, StringSplitOptions.None);
                    Uri myuri = new Uri(System.Web.HttpContext.Current.Request.Url.AbsoluteUri);
                    string host = myuri.GetLeftPart(UriPartial.Authority);
                    StringCipher stringCipher = new StringCipher();
                    int nextLevel = Convert.ToInt16(level) + 1;
                    string link = host + "/TransporterManagement/MultiFormReview.aspx?key=" + stringCipher.Encrypt(key) + "&actionid="
                            + stringCipher.Encrypt(actionId) + "&level=" + stringCipher.Encrypt(nextLevel.ToString()) + "&sessionid=" + stringCipher.Encrypt(sessionid);
                    emailBody = "<a href='" + link + "'>Click here to review</a>";
                    Subject = "Review Request";
                    if (key == "TotalVehicleInfo")
                    {
                        Subject = "Transporter Management - Vehicle Review";
                        emailBody = "Please find below details for Vehicle Review<br/><br/>"
                            + "Vehicle Id : " + Convert2CamelCase(dt.Rows[0]["Vehicle Id"].ToString()) + "<br/>"
                            + "Model : " + Convert2CamelCase(dt.Rows[0]["Model"].ToString()) + "<br/>"
                            + "Date Of Registation : " + Convert2CamelCase(dt.Rows[0]["Date Of Registation"].ToString()) + "<br/>"
                            + "Year of Manufacture : " + Convert2CamelCase(dt.Rows[0]["Year of Manufacture"].ToString()) + "<br/>"
                            + "Reviewed By : " + reviews.Rows[0]["ReviewBy"].ToString() + "<br/>"
                            + "Status : " + reviews.Rows[0]["Status"].ToString() + "<br/>"
                            + "Comment : " + reviews.Rows[0]["Comment"].ToString() + "<br/>"
                            + "To Review : " + emailBody + "<br/><br/>"
                            + "If a new window doesn't open automatically please copy the URL down and paste it in your browser to manually complete the process.<br/>"
                            + "<a href='" + link + "'>" + link + "</a>";
                    }
                    SendFormatedMailWithAttachment(sessionid, emailBody, Subject, "L" + nextLevel + "_" + key + "_Review", new string[] { }, "", false);
                    result = splitStr[splitStr.Length - 1];
                }
                catch (Exception ex) { }
            }
            return result;
        }

