        public string GetShortestPathBtwnAllPoints(double[,] _adjacencyMatrix)
        {
            if (_adjacencyMatrix.GetLength(0) == _adjacencyMatrix.GetLength(1))
            {
                HashSet<int> set = new HashSet<int>();
                Node root = new Node();
                int[] _vertices = new int[_adjacencyMatrix.GetLength(0)];
                for (int i = 0; i < _adjacencyMatrix.GetLength(0); i++)
                {
                    set.Add(i);
                    _vertices[i] = i;
                }

                double minCost = GetMinimumCostRoute(0, set, root, _adjacencyMatrix, _vertices);
                Node tempRoot = root.ChildNodes[0];
                string str = root.Value + "-->";
                while (tempRoot.ChildNodes != null)
                {
                    for (int i = 0; i < tempRoot.ChildNodes.Length; i++)
                    {
                        if (tempRoot.ChildNodes[i].Selected)
                        {
                            str += tempRoot.ChildNodes[i].Value + "-->";
                            tempRoot = tempRoot.ChildNodes[i];
                            break;
                        }
                    }
                }
                if (str.Contains("-->"))
                    str = str.Substring(0, str.Length - 3);
                return str;
            }
            else
                return "Distance Matrix is not in correct format";
        }
        private class Node
        {
            public int Value { get; set; }
            public Node[] ChildNodes { get; set; }
            public bool Selected { get; set; }
        }
        private double GetMinimumCostRoute(int startVertex, HashSet<int> set, Node root, double[,] _adjacencyMatrix, int[] _vertices)
        {
            if (!set.Any())
            {
                //source node is assumed to be the first
                root.ChildNodes = new Node[1] { new Node { Value = _vertices.First(), Selected = true } };
                return _adjacencyMatrix[startVertex, 0];
            }

            double totalCost = double.MaxValue;
            int i = 0;
            int selectedIdx = i;
            root.ChildNodes = new Node[set.Count()];

            foreach (var destination in set)
            {
                root.ChildNodes[i] = new Node { Value = destination };

                double costOfVistingCurrentNode = _adjacencyMatrix[startVertex, destination];

                var newSet = new HashSet<int>(set);
                newSet.Remove(destination);
                double costOfVisitingOtherNodes = GetMinimumCostRoute(destination, newSet, root.ChildNodes[i], _adjacencyMatrix, _vertices);
                double currentCost = costOfVistingCurrentNode + costOfVisitingOtherNodes;

                if (totalCost > currentCost)
                {
                    totalCost = currentCost;
                    selectedIdx = i;
                }

                i++;
            }

            root.ChildNodes[selectedIdx].Selected = true;
            return totalCost;
        }
