        public string GetGoogleRawDataForMultipleSrcDest(string[] srclatlng, string[] destlatlng)
        {
            var result = "";
            StringBuilder origins = new StringBuilder();
            StringBuilder destinations = new StringBuilder();
            StringBuilder distanceMatrixUrl = new StringBuilder();

            for (int i = 0; i < srclatlng.Length; i++)
            {
                origins.Append(srclatlng[i]);
                if (i != srclatlng.Length - 1)
                    origins.Append("|");
            }
            for (int i = 0; i < destlatlng.Length; i++)
            {
                destinations.Append(destlatlng[i]);
                if (i != destlatlng.Length - 1)
                    destinations.Append("|");
            }

            distanceMatrixUrl.Append("https://maps.googleapis.com/maps/api/distancematrix/json?units=imperial");
            distanceMatrixUrl.Append("&origins=");
            distanceMatrixUrl.Append(origins);
            distanceMatrixUrl.Append("&destinations=");
            distanceMatrixUrl.Append(destinations);
            distanceMatrixUrl.Append("&key=AIzaSyCACZOOfvdmPNZ77Fh-CkIAh52BztqwjGg");

            //Pass request to google api with orgin and destination details
            HttpWebRequest request = (HttpWebRequest)WebRequest.Create(distanceMatrixUrl.ToString());
            HttpWebResponse response = (HttpWebResponse)request.GetResponse();
            using (var streamReader = new StreamReader(response.GetResponseStream()))
            {
                result = streamReader.ReadToEnd();
            }
            return result;
        }

        public long[,] CreateMatrixFromRawData(Rootobject rootObject, string key = "Distance", string unit = "kms")
        {
            int rows, columns;
            columns = rootObject.destination_addresses.Length;
            rows = rootObject.origin_addresses.Length;
            long[,] distanceMatrix = new long[rows, columns];
            long[,] timeMatrix = new long[rows, columns];
            Row[] rowObject = rootObject.rows;
            for (int i = 0; i < rowObject.Length; i++)
            {
                Element[] elementObject = rowObject[i].elements;
                for (int j = 0; j < elementObject.Length; j++)
                {
                    if (elementObject[j].status == "OK")
                    {
                        if (unit == "kms")
                        {
                            distanceMatrix[i, j] = Convert.ToInt64(Convert.ToDouble(elementObject[j].distance.value) / 1000);
                        }
                        else
                            distanceMatrix[i, j] = elementObject[j].distance.value;
                        timeMatrix[i, j] = elementObject[j].duration.value;
                    }
                }
            }
            if (key == "time")
                return timeMatrix;
            else
                return distanceMatrix;
        }

