        public string insertVehicleVettingDetails(string sessionid, Vehicle_Vetting_Fields vehicle_Vetting_Fields, List<Vehicle_Vetting_Checklist> vehicle_Vetting_Checklist)
        {
            string vetid = dbx.insertVehicleVettingDetails(sessionid, vehicle_Vetting_Fields, vehicle_Vetting_Checklist);
            try
            {
                string filePath = System.Web.Hosting.HostingEnvironment.MapPath("~/Uploads/Vehicle_Technical_Control.xlsx");
                using (ExcelPackage excelPkg = new ExcelPackage())
                using (FileStream stream = new FileStream(filePath, FileMode.Open))
                {
                    excelPkg.Load(stream);
                    ExcelWorksheet oSheet2 = excelPkg.Workbook.Worksheets[2];
                    ExcelWorksheet oSheet3 = excelPkg.Workbook.Worksheets[3];
                    ExcelWorksheet oSheet4 = excelPkg.Workbook.Worksheets[4];
                    ExcelWorksheet oSheet5 = excelPkg.Workbook.Worksheets[5];
                    ExcelWorksheet oSheet6 = excelPkg.Workbook.Worksheets[6];

                    oSheet3 = FindAndReplace(oSheet3, "<prevInspectDate>", vehicle_Vetting_Fields.prevInspectDate);
                    oSheet3 = FindAndReplace(oSheet3, "<inspectDate>", vehicle_Vetting_Fields.inspectDate);
                    oSheet3 = FindAndReplace(oSheet3, "<inspectStartTime>", vehicle_Vetting_Fields.inspectStartTime);
                    oSheet3 = FindAndReplace(oSheet3, "<inspectEndTime>", vehicle_Vetting_Fields.inspectEndTime);
                    oSheet3 = FindAndReplace(oSheet3, "<inspectName>", vehicle_Vetting_Fields.inspectName);
                    oSheet3 = FindAndReplace(oSheet3, "<transporter>", vehicle_Vetting_Fields.transporter);
                    oSheet3 = FindAndReplace(oSheet3, "<driverName>", vehicle_Vetting_Fields.driverName);
                    oSheet3 = FindAndReplace(oSheet3, "<tractorRegNo>", vehicle_Vetting_Fields.tractorRegNo);
                    oSheet3 = FindAndReplace(oSheet3, "<trailerRegNo>", vehicle_Vetting_Fields.trailerRegNo);
                    oSheet3 = FindAndReplace(oSheet3, "<truckChassisNo>", vehicle_Vetting_Fields.truckChassisNo);
                    oSheet3 = FindAndReplace(oSheet3, "<trailerChassisNo>", vehicle_Vetting_Fields.trailerChassisNo);
                    oSheet3 = FindAndReplace(oSheet3, "<vehCategory>", vehicle_Vetting_Fields.vehCategory);
                    oSheet3 = FindAndReplace(oSheet3, "<vehType>", vehicle_Vetting_Fields.vehType);
                    oSheet3 = FindAndReplace(oSheet3, "<tankCap>", vehicle_Vetting_Fields.tankCap);
                    oSheet3 = FindAndReplace(oSheet3, "<productLoad>", vehicle_Vetting_Fields.productLoad);

                    string ids = "";

                    for (int i = 0; i < vehicle_Vetting_Checklist.Count; i++)
                    {
                        oSheet3 = FindAndReplace(oSheet3, "<CHECKLIST_STATUS_" + vehicle_Vetting_Checklist[i].id + ">", vehicle_Vetting_Checklist[i].status);
                        oSheet4 = FindAndReplace(oSheet4, "<CHECKLIST_STATUS_" + vehicle_Vetting_Checklist[i].id + ">", vehicle_Vetting_Checklist[i].status);
                        oSheet5 = FindAndReplace(oSheet5, "<CHECKLIST_STATUS_" + vehicle_Vetting_Checklist[i].id + ">", vehicle_Vetting_Checklist[i].status);
                        oSheet6 = FindAndReplace(oSheet6, "<CHECKLIST_STATUS_" + vehicle_Vetting_Checklist[i].id + ">", vehicle_Vetting_Checklist[i].status);

                        oSheet3 = FindAndReplace(oSheet3, "<CHECKLIST_COMMENTS_" + vehicle_Vetting_Checklist[i].id + ">", vehicle_Vetting_Checklist[i].comments);
                        oSheet4 = FindAndReplace(oSheet4, "<CHECKLIST_COMMENTS_" + vehicle_Vetting_Checklist[i].id + ">", vehicle_Vetting_Checklist[i].comments);
                        oSheet5 = FindAndReplace(oSheet5, "<CHECKLIST_COMMENTS_" + vehicle_Vetting_Checklist[i].id + ">", vehicle_Vetting_Checklist[i].comments);
                        oSheet6 = FindAndReplace(oSheet6, "<CHECKLIST_COMMENTS_" + vehicle_Vetting_Checklist[i].id + ">", vehicle_Vetting_Checklist[i].comments);

                        oSheet3 = FindAndReplace(oSheet3, "<CHECKLIST_ADD_COMMENTS_" + vehicle_Vetting_Checklist[i].id + ">", vehicle_Vetting_Checklist[i].additonalComments);
                        oSheet4 = FindAndReplace(oSheet4, "<CHECKLIST_ADD_COMMENTS_" + vehicle_Vetting_Checklist[i].id + ">", vehicle_Vetting_Checklist[i].additonalComments);
                        oSheet5 = FindAndReplace(oSheet5, "<CHECKLIST_ADD_COMMENTS_" + vehicle_Vetting_Checklist[i].id + ">", vehicle_Vetting_Checklist[i].additonalComments);
                        oSheet6 = FindAndReplace(oSheet6, "<CHECKLIST_ADD_COMMENTS_" + vehicle_Vetting_Checklist[i].id + ">", vehicle_Vetting_Checklist[i].additonalComments);

                        if (vehicle_Vetting_Checklist[i].status == "No")
                        {
                            if (ids != "")
                                ids += ",";
                            ids += vehicle_Vetting_Checklist[i].id;
                        }
                    }

                    DataTable summary = null;
                    if (!string.IsNullOrEmpty(ids))
                        summary = dbx.getVehVetSummary(ids);
                    string interdictionIdList = "";
                    for (int i = 0; i < 10; i++)
                    {
                        for (int j = 0; j < 3; j++)
                        {
                            string criteriaKey = "I";
                            string criteriaFullKey = "INTERDICTION";
                            if (j == 1)
                            {
                                criteriaKey = "WI";
                                criteriaFullKey = "WITHOUT_INTERDICTION";
                            }
                            else if (j == 2)
                            {
                                criteriaKey = "MP";
                                criteriaFullKey = "MAINTENANCE_PLAN";
                            }
                            DataRow[] dr = null;
                            if (summary != null)
                                dr = summary.Select("Criteria='" + criteriaKey + "' and SectionID=" + (i + 1));
                            string count = "0";
                            string idList = "";
                            if (dr != null && dr.Length > 0)
                            {
                                count = dr[0]["count"].ToString();
                                idList = dr[0]["ids"].ToString();
                            }
                            oSheet2 = FindAndReplace(oSheet2, "<" + criteriaFullKey + "_" + vehicle_Vetting_Checklist[i].id + ">", count);
                            oSheet2 = FindAndReplace(oSheet2, "<" + criteriaFullKey + "_LIST_" + vehicle_Vetting_Checklist[i].id + ">", idList);
                            // Collect non-empty IDs for INTERDICTION
                            if (!string.IsNullOrEmpty(idList) && criteriaFullKey == "INTERDICTION")
                            {
                                if (!string.IsNullOrEmpty(interdictionIdList))
                                {
                                    interdictionIdList += ","; // Add a comma if there's already data
                                }
                                interdictionIdList += idList;
                            }
                        }
                    }
                    // Block the vehicle after the loop once
                    if (!string.IsNullOrEmpty(interdictionIdList))
                    {
                        BlockVehicleduetoNoncompliancePoints("INTERDICTION", interdictionIdList, vehicle_Vetting_Fields.tractorRegNo);
                    }
                    string filename = "Vehicle_Technical_Control" + "_" + DateTime.Now.ToString("ddMMHHmmss") + "_" + vehicle_Vetting_Fields.tractorRegNo.Replace(" ", "") + ".xls";
                    string filepath = System.Web.Hosting.HostingEnvironment.MapPath("~/Uploads/" + filename); ; // ("~/Uploads/" + filename); filename code removed due to some files upload is missing.
                    string filepath1 = System.Web.Hosting.HostingEnvironment.MapPath("~/Uploads");
                    FileInfo fi = new FileInfo(filepath);
                    excelPkg.SaveAs(fi);

                    BusinessLogicLayer.AmazonS3Upload.UploadFiles(filepath1, filename, "db-flatfile-backup", "", "PublicRead");
                    //int res = dbx.updateReportNameByVettingId(vetId, filename);
                    //if (res > 0)
                    //{
                    //    string username = getUserId(sessionId);
                    //    string additionalmailids = "";
                    //    int accountid = GetAccountId(sessionId);
                    //    if (appId == "2" && username == "hubertebner")
                    //    {
                    //        additionalmailids = GetDIPTransporterMailIdByVetVal(accountid, uniqueValue);
                    //    }
                    //    string accountname = GetAccountName(sessionId);
                    //    SendFormatedMailWithAttachment(sessionId, "Please see attached " + vetStaticDetails.Rows[0]["ReportHeader"].ToString() + " generated on "
                    //        + Convert.ToDateTime(vetStaticDetails.Rows[0]["DateTime"].ToString()).ToString("yyyy-MM-dd"), "Senseltelematics "
                    //        + vetStaticDetails.Rows[0]["ReportHeader"].ToString() + " - " + accountname, Convert.ToString(vetStaticDetails.Rows[0]["ReportMailKey"]),
                    //        new string[] { filepath + filename }, additionalmailids, false);
                    //}
                    string accountname = GetAccountName(sessionid);
                    int res = dbx.updateFileNameByVettingId(vetid, filename);
                    string additionalMailids = dbx.GetTransporterMailId("0", vehicle_Vetting_Fields.tractorRegNo.Replace(" ", ""));
                    SendFormatedMailWithAttachment(sessionid, "Please see attached Vehicle Technical Control generated on "
                        + DateTime.Now.ToString("yyyy-MM-dd"), "Senseltelematics Vehicle Technical Control - " + accountname, "VehicleTechnicalReport",
                        new string[] { filepath }, additionalMailids, false);
                }
            }
            catch (Exception ex)
            {
                dbx.STL_RecordErrorMessage("Vehicle_Vetting_" + vetid + "_" + ex.ToString());
            }
            return vetid;
        }
        public void BlockVehicleduetoNoncompliancePoints(string criteriaFullKey, string idList,string vehicleId)
        {
            BusinessLogicLayer.BLL objBll = new BusinessLogicLayer.BLL();
            int accid = objBll.getAccountIdByVehicleId(vehicleId);
            string correctVehicleNo = GetCorrectVehicleNumber(vehicleId);//Added by zoya on 08/05/2026 to correct vehicle Id
            objBll.InsertSTLBlockInfoData(correctVehicleNo, "Synthesis (I)nterdiction non-complaince for - " + idList, "System-Block", accid.ToString());            
        }
