        public bool SaveTechnicalInvariantReport(string vetid)
        {
            try
            {
                string filePath = System.Web.Hosting.HostingEnvironment.MapPath("~/Uploads/Vehicle_Technical_Invariant_1.1.xlsx");
                using (ExcelPackage excelPkg = new ExcelPackage())
                using (FileStream stream = new FileStream(filePath, FileMode.Open))
                {
                    excelPkg.Load(stream);
                    ExcelWorksheet oSheet4 = excelPkg.Workbook.Worksheets[4];
                    ExcelWorksheet oSheet5 = excelPkg.Workbook.Worksheets[5];
                    ExcelWorksheet oSheet6 = excelPkg.Workbook.Worksheets[6];
                    ExcelWorksheet oSheet7 = excelPkg.Workbook.Worksheets[7];
                    ExcelWorksheet oSheet8 = excelPkg.Workbook.Worksheets[8];
                    ExcelWorksheet oSheet9 = excelPkg.Workbook.Worksheets[9];

                    DataTable basicVetDetails = dbx.getTechnicalInvariantBasicDetails(vetid);
                    if (basicVetDetails.Rows.Count > 0)
                    {
                        int accountid = Convert.ToInt16(basicVetDetails.Rows[0]["AccountID"].ToString());
                        DataTable vettingScores = dbx.GetTechnicalInvariantScores(vetid);
                        int total_orange = 0;
                        int total_red = 0;
                        int total_orange_yes = 0;
                        int total_red_yes = 0;
                        int orange_count = 0;
                        int orange_yes_count = 0;
                        int red_count = 0;
                        int red_yes_count = 0;
                        for (int i = 0; i < vettingScores.Rows.Count; i++)
                        {
                            if (vettingScores.Rows[i]["Category"].ToString() == "Tractors and Rigid Trucks")
                            {
                                if (vettingScores.Rows[i]["Criteria"].ToString() == "O")
                                {
                                    orange_count = Convert.ToInt16(vettingScores.Rows[i]["totalcount"].ToString());
                                    orange_yes_count = Convert.ToInt16(vettingScores.Rows[i]["yescount"].ToString());

                                    oSheet4 = FindAndReplace(oSheet4, "<trt_orange>", orange_count.ToString());
                                    oSheet4 = FindAndReplace(oSheet4, "<trt_orange_yes>", orange_yes_count.ToString());
                                    oSheet4 = FindAndReplace(oSheet4, "<trt_orange_compliance>", Math.Round((double)(orange_yes_count * 100) / orange_count).ToString());

                                    oSheet9 = FindAndReplace(oSheet9, "<trt_orange>", orange_count.ToString());
                                    oSheet9 = FindAndReplace(oSheet9, "<trt_orange_yes>", orange_yes_count.ToString());
                                    oSheet9 = FindAndReplace(oSheet9, "<trt_orange_compliance>", Math.Round((double)(orange_yes_count * 100) / orange_count).ToString());
                                }
                                else if (vettingScores.Rows[i]["Criteria"].ToString() == "R")
                                {
                                    red_count = Convert.ToInt16(vettingScores.Rows[i]["totalcount"].ToString());
                                    red_yes_count = Convert.ToInt16(vettingScores.Rows[i]["yescount"].ToString());

                                    oSheet4 = FindAndReplace(oSheet4, "<trt_red>", red_count.ToString());
                                    oSheet4 = FindAndReplace(oSheet4, "<trt_red_yes>", red_yes_count.ToString());
                                    oSheet4 = FindAndReplace(oSheet4, "<trt_red_compliance>", Math.Round((double)(red_yes_count * 100) / red_count).ToString());
                                    oSheet4 = FindAndReplace(oSheet4, "<trt_overall_compliance>", Math.Round((double)((orange_yes_count + red_yes_count) * 100) / (red_count + orange_count)).ToString());

                                    oSheet9 = FindAndReplace(oSheet9, "<trt_red>", red_count.ToString());
                                    oSheet9 = FindAndReplace(oSheet9, "<trt_red_yes>", red_yes_count.ToString());
                                    oSheet9 = FindAndReplace(oSheet9, "<trt_red_compliance>", Math.Round((double)(red_yes_count * 100) / red_count).ToString());
                                    oSheet9 = FindAndReplace(oSheet9, "<trt_overall_compliance>", Math.Round((double)((orange_yes_count + red_yes_count) * 100) / (red_count + orange_count)).ToString());

                                    if (!string.IsNullOrEmpty(basicVetDetails.Rows[0]["trtType"].ToString()))
                                    {
                                        total_orange += orange_count;
                                        total_red += red_count;
                                        total_orange_yes += orange_yes_count;
                                        total_red_yes += red_yes_count;
                                    }
                                }
