        public bool SaveVehicleVettingReport(string vetid)
        {
            DataTable vehicle_Vetting_Fields = dbx.getVehicleVettingDetails(vetid);
            DataTable vehicle_Vetting_Checklist = dbx.getvehicle_Vetting_Checklist(vetid);
            try
            {
                string filePath = System.Web.Hosting.HostingEnvironment.MapPath("~/Uploads/Vehicle_Technical_Control.xlsx");
                using (ExcelPackage excelPkg = new ExcelPackage())
                using (FileStream stream = new FileStream(filePath, FileMode.Open))
                {
                    excelPkg.Load(stream);
                    ExcelWorksheet oSheet2 = excelPkg.Workbook.Worksheets[2];
                    ExcelWorksheet oSheet3 = excelPkg.Workbook.Worksheets[3];
                    ExcelWorksheet oSheet4 = excelPkg.Workbook.Worksheets[4];
                    ExcelWorksheet oSheet5 = excelPkg.Workbook.Worksheets[5];
                    ExcelWorksheet oSheet6 = excelPkg.Workbook.Worksheets[6];
                    if (vehicle_Vetting_Fields.Rows.Count > 0)
                    {
                        oSheet3 = FindAndReplace(oSheet3, "<prevInspectDate>", vehicle_Vetting_Fields.Rows[0]["prevInspectDate"].ToString());
                        oSheet3 = FindAndReplace(oSheet3, "<inspectDate>", vehicle_Vetting_Fields.Rows[0]["inspectDate"].ToString());
                        oSheet3 = FindAndReplace(oSheet3, "<inspectStartTime>", vehicle_Vetting_Fields.Rows[0]["inspectStartTime"].ToString());
                        oSheet3 = FindAndReplace(oSheet3, "<inspectEndTime>", vehicle_Vetting_Fields.Rows[0]["inspectEndTime"].ToString());
                        oSheet3 = FindAndReplace(oSheet3, "<inspectName>", vehicle_Vetting_Fields.Rows[0]["inspectName"].ToString());
                        oSheet3 = FindAndReplace(oSheet3, "<transporter>", vehicle_Vetting_Fields.Rows[0]["transporter"].ToString());
                        oSheet3 = FindAndReplace(oSheet3, "<driverName>", vehicle_Vetting_Fields.Rows[0]["driverName"].ToString());
                        oSheet3 = FindAndReplace(oSheet3, "<tractorRegNo>", vehicle_Vetting_Fields.Rows[0]["tractorRegNo"].ToString());
                        oSheet3 = FindAndReplace(oSheet3, "<trailerRegNo>", vehicle_Vetting_Fields.Rows[0]["trailerRegNo"].ToString());
                        oSheet3 = FindAndReplace(oSheet3, "<truckChassisNo>", vehicle_Vetting_Fields.Rows[0]["truckChassisNo"].ToString());
                        oSheet3 = FindAndReplace(oSheet3, "<trailerChassisNo>", vehicle_Vetting_Fields.Rows[0]["trailerChassisNo"].ToString());
                        oSheet3 = FindAndReplace(oSheet3, "<vehCategory>", vehicle_Vetting_Fields.Rows[0]["vehCategory"].ToString());
                        oSheet3 = FindAndReplace(oSheet3, "<vehType>", vehicle_Vetting_Fields.Rows[0]["vehType"].ToString());
                        oSheet3 = FindAndReplace(oSheet3, "<tankCap>", vehicle_Vetting_Fields.Rows[0]["tankCap"].ToString());
                        oSheet3 = FindAndReplace(oSheet3, "<productLoad>", vehicle_Vetting_Fields.Rows[0]["productLoad"].ToString());

                        string ids = "";

                        for (int i = 0; i < vehicle_Vetting_Checklist.Rows.Count; i++)
                        {
                            oSheet3 = FindAndReplace(oSheet3, "<CHECKLIST_STATUS_" + vehicle_Vetting_Checklist.Rows[i]["chkID"] + ">", vehicle_Vetting_Checklist.Rows[i]["Status"].ToString());
                            oSheet4 = FindAndReplace(oSheet4, "<CHECKLIST_STATUS_" + vehicle_Vetting_Checklist.Rows[i]["chkID"] + ">", vehicle_Vetting_Checklist.Rows[i]["Status"].ToString());
                            oSheet5 = FindAndReplace(oSheet5, "<CHECKLIST_STATUS_" + vehicle_Vetting_Checklist.Rows[i]["chkID"] + ">", vehicle_Vetting_Checklist.Rows[i]["Status"].ToString());
                            oSheet6 = FindAndReplace(oSheet6, "<CHECKLIST_STATUS_" + vehicle_Vetting_Checklist.Rows[i]["chkID"] + ">", vehicle_Vetting_Checklist.Rows[i]["Status"].ToString());

                            oSheet3 = FindAndReplace(oSheet3, "<CHECKLIST_COMMENTS_" + vehicle_Vetting_Checklist.Rows[i]["chkID"] + ">", vehicle_Vetting_Checklist.Rows[i]["Comments"].ToString());
                            oSheet4 = FindAndReplace(oSheet4, "<CHECKLIST_COMMENTS_" + vehicle_Vetting_Checklist.Rows[i]["chkID"] + ">", vehicle_Vetting_Checklist.Rows[i]["Comments"].ToString());
                            oSheet5 = FindAndReplace(oSheet5, "<CHECKLIST_COMMENTS_" + vehicle_Vetting_Checklist.Rows[i]["chkID"] + ">", vehicle_Vetting_Checklist.Rows[i]["Comments"].ToString());
                            oSheet6 = FindAndReplace(oSheet6, "<CHECKLIST_COMMENTS_" + vehicle_Vetting_Checklist.Rows[i]["chkID"] + ">", vehicle_Vetting_Checklist.Rows[i]["Comments"].ToString());

                            oSheet3 = FindAndReplace(oSheet3, "<CHECKLIST_ADD_COMMENTS_" + vehicle_Vetting_Checklist.Rows[i]["chkID"] + ">", vehicle_Vetting_Checklist.Rows[i]["AdditionalComments"].ToString());
                            oSheet4 = FindAndReplace(oSheet4, "<CHECKLIST_ADD_COMMENTS_" + vehicle_Vetting_Checklist.Rows[i]["chkID"] + ">", vehicle_Vetting_Checklist.Rows[i]["AdditionalComments"].ToString());
                            oSheet5 = FindAndReplace(oSheet5, "<CHECKLIST_ADD_COMMENTS_" + vehicle_Vetting_Checklist.Rows[i]["chkID"] + ">", vehicle_Vetting_Checklist.Rows[i]["AdditionalComments"].ToString());
                            oSheet6 = FindAndReplace(oSheet6, "<CHECKLIST_ADD_COMMENTS_" + vehicle_Vetting_Checklist.Rows[i]["chkID"] + ">", vehicle_Vetting_Checklist.Rows[i]["AdditionalComments"].ToString());

                            if (vehicle_Vetting_Checklist.Rows[i]["Status"].ToString() == "No")
                            {
                                if (ids != "")
                                    ids += ",";
                                ids += vehicle_Vetting_Checklist.Rows[i]["chkID"];
                            }
                        }

                        DataTable summary = null;
                        if (!string.IsNullOrEmpty(ids))
                            summary = dbx.getVehVetSummary(ids);
                        for (int i = 0; i < 10; i++)
                        {
                            for (int j = 0; j < 3; j++)
                            {
                                string criteriaKey = "I";
                                string criteriaFullKey = "INTERDICTION";
                                if (j == 1)
                                {
                                    criteriaKey = "WI";
                                    criteriaFullKey = "WITHOUT_INTERDICTION";
                                }
                                else if (j == 2)
                                {
                                    criteriaKey = "MP";
                                    criteriaFullKey = "MAINTENANCE_PLAN";
                                }
                                DataRow[] dr = null;
                                if (summary != null)
                                    dr = summary.Select("Criteria='" + criteriaKey + "' and SectionID=" + (i + 1));
                                string count = "0";
                                string idList = "";
                                if (dr != null && dr.Length > 0)
                                {
                                    count = dr[0]["count"].ToString();
                                    idList = dr[0]["ids"].ToString();
                                }
                                oSheet2 = FindAndReplace(oSheet2, "<" + criteriaFullKey + "_" + vehicle_Vetting_Checklist.Rows[i]["chkID"] + ">", count);
                                oSheet2 = FindAndReplace(oSheet2, "<" + criteriaFullKey + "_LIST_" + vehicle_Vetting_Checklist.Rows[i]["chkID"] + ">", idList);
                            }
                        }

                        string filename = "Vehicle_Technical_Control" + "_" + Convert.ToDateTime(vehicle_Vetting_Fields.Rows[0]["DateTime"].ToString()).ToString("ddMMHHmmss") + "_" + vehicle_Vetting_Fields.Rows[0]["tractorRegNo"].ToString().Replace(" ", "") + ".xls";
                        string filepath = System.Web.Hosting.HostingEnvironment.MapPath("~/Uploads/" + filename);
							string filepath1 = System.Web.Hosting.HostingEnvironment.MapPath("~/Uploads");
							FileInfo fi = new FileInfo(filepath);
							excelPkg.SaveAs(fi);

                        BusinessLogicLayer.AmazonS3Upload.UploadFiles(filepath1, filename, "db-flatfile-backup", "", "PublicRead");
                        string sessionid = dbx.getSessionIdFromLogin(vehicle_Vetting_Fields.Rows[0]["AddedBy"].ToString());
                        string accountname = GetAccountName(sessionid);
                        int res = dbx.updateFileNameByVettingId(vetid, filename);
                        string additionalMailids = dbx.GetTransporterMailId("0", vehicle_Vetting_Fields.Rows[0]["tractorRegNo"].ToString().Replace(" ", ""));
                        SendFormatedMailWithAttachment(sessionid, "Please see attached Vehicle Technical Control generated on "
                             + DateTime.Now.ToString("yyyy-MM-dd"), "Senseltelematics Vehicle Technical Control - " + accountname, "VehicleTechnicalReport",
                             new string[] { filepath }, additionalMailids, false);
                    }
                    else
                    {
                        dbx.STL_RecordErrorMessage("Vehicle_Technical_Control" + vetid + "_No Basic Details Found");
                        return false;
                    }
                }
            }

            catch (Exception ex)
            {
                dbx.STL_RecordErrorMessage("Vehicle_Vetting_" + vetid + "_" + ex.ToString());
            }
            return true;
        }

