        private ExcelWorksheet FindAndReplace(ExcelWorksheet oSheet, string Findtxt, string Replacetxt)
        {
            try
            {
                string StartAddress = oSheet.Cells.Start.Address;
                string EndAddress = oSheet.Cells.End.Address;

                var query = (from cell in oSheet.Cells[StartAddress + ":" + EndAddress]
                             where Convert.ToString(cell.Value).Contains(Findtxt)
                             select cell);
                foreach (var cell in query)    //The cells returned here will all be in column D, since that is the address in the indexer. Use the Offset method to print any other cells from the same row.
                {
                    oSheet.Cells[cell.Address].Value = cell.Value.ToString().Replace(Findtxt, Replacetxt);
                }
                return oSheet;
            }
            catch { return oSheet; }
        }

