        public void SendFormatedMail(string sessionId, string emailBody, string subject, string key, string additionalMailIds = "", bool emailsByLogin = true)
        {
            String emailServer = System.Web.Configuration.WebConfigurationManager.AppSettings["emailServer"];
            string FromMail = System.Web.Configuration.WebConfigurationManager.AppSettings["ReportingEmailId"];
            string Password = System.Web.Configuration.WebConfigurationManager.AppSettings["ReportingEmailPassword"];
            if (String.IsNullOrEmpty(emailServer))
                emailServer = "localhost";
            DateTime now = DateTime.UtcNow.AddSeconds(dbx.GetTimeZoneDiff());
            EmailSender es = new EmailSender(emailServer);
            string emailBodyHeader = "Dear Sir/Madam,<br/><br/>";
            string emailBodyFooter = "\n<br/><br/>Best Regards,<br/>Sensel Telematics Pvt. Ltd.<br/><br/>Note: Please do not reply to this mail as this is an auto-generated email.";
            es = new EmailSender(emailServer);
            string login = "";
            if (emailsByLogin)
                login = dbx.getUserId(sessionId);
            DataTable dtEmailConfig = dbx.GetMailIdsConfig(dbx.GetAccountId(sessionId), key, login);
            for (int i = 0; i < dtEmailConfig.Rows.Count; i++)
            {
                string mailids = dtEmailConfig.Rows[i]["EmailIds"].ToString();
                if (additionalMailIds != "")
                {
                    mailids += "," + additionalMailIds;
                }
                es.setupEmail(FromMail, mailids, subject, emailBodyHeader + emailBody + emailBodyFooter,
                    dtEmailConfig.Rows[i]["EmailIds_cc"].ToString(), dtEmailConfig.Rows[i]["EmailIds_bcc"].ToString());
                es.setBodyHtml(true);
                try
                {
                    es.send(FromMail, Password);
                }
                catch { }
            }
        }

        public void SendFormatedMailWithAttachment(string sessionId, string emailBody, string subject, string key, string[] filepaths, string additionalMailIds = "", bool emailsByLogin = true)
        {
            String emailServer = System.Web.Configuration.WebConfigurationManager.AppSettings["emailServer"];
            string FromMail = System.Web.Configuration.WebConfigurationManager.AppSettings["ReportingEmailId"];
            string Password = System.Web.Configuration.WebConfigurationManager.AppSettings["ReportingEmailPassword"];
            if (String.IsNullOrEmpty(emailServer))
                emailServer = "localhost";
            DateTime now = DateTime.UtcNow.AddSeconds(dbx.GetTimeZoneDiff());
            string emailBodyHeader = "Dear Sir/Madam,<br/><br/>";
            string emailBodyFooter = "\n<br/><br/>Best Regards,<br/>Sensel Telematics Pvt. Ltd.<br/><br/>Note: Please do not reply to this mail as this is an auto-generated email.";
            string login = "";
            if (emailsByLogin)
                login = dbx.getUserId(sessionId);
            if (!string.IsNullOrEmpty(key))
            {
                DataTable dtEmailConfig = dbx.GetMailIdsConfig(dbx.GetAccountId(sessionId), key, login);
                for (int i = 0; i < dtEmailConfig.Rows.Count; i++)
                {
                    string mailids = dtEmailConfig.Rows[i]["EmailIds"].ToString();
                    if (!string.IsNullOrEmpty(additionalMailIds))
                    {
                        mailids += "," + additionalMailIds;
                    }
                    EmailSender es = new EmailSender(emailServer);
                    es.setupEmail(FromMail, mailids, subject, emailBodyHeader + emailBody + emailBodyFooter,
                        dtEmailConfig.Rows[i]["EmailIds_cc"].ToString(), dtEmailConfig.Rows[i]["EmailIds_bcc"].ToString());
                    for (int j = 0; j < filepaths.Length; j++)
                    {
                        es.addAttachment(filepaths[j]);
                    }
                    es.setBodyHtml(true);
                    try
                    {
                        es.send(FromMail, Password);
                    }
                    catch { }
                }
            }
            else if (!string.IsNullOrEmpty(additionalMailIds))
            {
                EmailSender es = new EmailSender(emailServer);
                es.setupEmail(FromMail, additionalMailIds, subject, emailBodyHeader + emailBody + emailBodyFooter, "", "");
                for (int j = 0; j < filepaths.Length; j++)
                {
                    es.addAttachment(filepaths[j]);
                }
                es.setBodyHtml(true);
                try
                {
                    es.send(FromMail, Password);
                }
                catch { }
            }
        }

