        public TimeSpan ConvertStringToTimeSpan(string Time)
        {
            Time = Time.Trim(' ');
            TimeSpan NewTime = new TimeSpan();
            try
            {
                NewTime = TimeSpan.Parse(Time);
            }
            catch
            {
                int Days = 0;
                int Hours = 0;
                int Mins = 0;
                int Sec = 0;
                try
                {
                    string[] TimeValues = Time.Split(':');
                    if (TimeValues.Length <= 3)
                    {
                        string[] dayHour = TimeValues[0].Split('.');
                        if (dayHour.Length > 1)
                        {
                            Days = Convert.ToInt32(dayHour[0]);
                            Hours = Convert.ToInt32(dayHour[1]);
                        }
                        else
                            Hours = Convert.ToInt32(dayHour[0]);

                        Mins = Convert.ToInt32(TimeValues[1]);

                        if (!string.IsNullOrEmpty(TimeValues[2].ToString()))
                        {
                            string[] secMili = TimeValues[2].Split('.');
                            Sec = Convert.ToInt32(secMili[0]);
                        }

                        NewTime = new TimeSpan(Days, Hours, Mins, Sec);
                    }
                    else if (TimeValues.Length == 4)
                    {
                        Days = Convert.ToInt32(TimeValues[0]);
                        Hours = Convert.ToInt32(TimeValues[1]);
                        Mins = Convert.ToInt32(TimeValues[2]);
                        Sec = Convert.ToInt32(TimeValues[3]);
                        NewTime = new TimeSpan(Days, Hours, Mins, Sec);
                    }
                }
                catch
                {
                    return NewTime;
                }

            }
            return NewTime;
        }

