        public DateTime ConvertStringToDateTime(string strDateTime, string first = "day")
        {
            DateTime dt = dbx.ConvertStringToDateTime(strDateTime, first);
            if (dt == DateTime.MinValue)
            {
                if (first.ToLower() == "month")
                {
                    strDateTime = strDateTime.Replace('/', '-');
                    try
                    {
                        dt = DateTime.ParseExact(strDateTime, "MM-dd-yyyy hh:mm:ss tt", CultureInfo.InvariantCulture);
                    }
                    catch
                    {
                        try
                        {
                            dt = DateTime.ParseExact(strDateTime, "MM-dd-yyyy HH:mm:ss", CultureInfo.InvariantCulture);
                        }
                        catch
                        { dt = DateTime.MinValue; }
                    }
                }
                else if (first.ToLower() == "day")
                {
                    try
                    {
                        dt = DateTime.ParseExact(strDateTime, "dd-MM-yyyy hh:mm:ss tt", CultureInfo.InvariantCulture);
                    }
                    catch
                    {
                        try
                        {
                            dt = DateTime.ParseExact(strDateTime, "dd-MM-yyyy HH:mm:ss", CultureInfo.InvariantCulture);
                        }
                        catch { dt = DateTime.MinValue; }
                    }
                }
            }
            return dt;
        }

