        public string[] GetRunDistSpeed(string vehicleNum, string tripStart, string tripEnd)
        {
            Object[] dist = accumulateDistance(vehicleNum, tripStart, tripEnd, null);

            string[] retValue = new string[5];

            string distanceVal = string.Empty; string runTimeVal = string.Empty;
            string speedVal = string.Empty; string haltTime = string.Empty; string totalTime = string.Empty;

            if (dist.Length > 0 && dist != null)
            {
                double distance = (double)dist[0];
                distanceVal = Math.Round(distance, 2).ToString();
                retValue[0] = distanceVal;

                retValue[1] = dist[2].ToString();

                TimeSpan runTime = new TimeSpan();
                try
                {
                    runTime = TimeSpan.Parse(dist[2].ToString());
                }
                catch
                {
                    runTime = ConvertStringToTimeSpan(dist[2].ToString());
                }


                //TimeSpan runTime = ConvertStringToTimeSpan(dist[2].ToString());
                //runTimeVal = runTime.ToString();
                //retValue[1] = runTimeVal;

                double converttokmph = 0.0;
                if (runTime.TotalSeconds != 0)
                    converttokmph = 3.6 * (distance * 1000 / runTime.TotalSeconds);
                speedVal = Math.Round(converttokmph, 2).ToString();
                retValue[2] = speedVal;

                TimeSpan TripTime = Convert.ToDateTime(tripEnd).Subtract(Convert.ToDateTime(tripStart));

                //if (TripTime.Days>0)
                //totalTime = string.Format("{0:00}Days {1:00}:{2:00}:{3:00}", TripTime.Days, TripTime.Hours, TripTime.Minutes, TripTime.Seconds);

                retValue[3] = RemoveMilisec(TripTime).ToString();

                TimeSpan HaltTime = TripTime.Subtract(runTime);
                //haltTime = string.Format("{0:00}:{1:00}:{2:00}", HaltTime.Hours, HaltTime.Minutes, HaltTime.Seconds);
                retValue[4] = RemoveMilisec(HaltTime).ToString();
            }
            return retValue;
        }
        public TimeSpan RemoveMilisec(TimeSpan time)
        {
            TimeSpan newTimeSpan = new TimeSpan(time.Days, time.Hours, time.Minutes, time.Seconds);
            return newTimeSpan;
        }

