        public string GetVehicleStatusByCode(string code)
        {
            code = code.Replace(",", "");
            if (code == "VH")
                return "Vehicle Halted";
            else if (code == "VI")
                return "Vehicle Idling";
            else if (code == "VM")
                return "Vehicle Moving";
            else if (code == "NR")
                return "Not Reachable";
            else if (code == "OS")
                return "Over Speeding";
            else if (code == "PBP")
                return "Panic Button Pressed";
            else if (code == "GNA")
                return "GPS Not Active";
            else if (code == "TPON")
                return "Tipper ON";
            else if (code == "VO")
                return "Vehicle ON";
            else if (code == "VF")
                return "Vehicle OFF";
            else
                return code;
        }

