        public List<String> GetVehicleTrips(string vehicleNo, string fromdate, string toDate, string detailsType = "")
        {
            if (string.IsNullOrEmpty(detailsType))
                detailsType = "alltrips";
            Object[] values = dbx.getLatLong(vehicleNo, fromdate, toDate);
            List<string> tripsList = new List<string>();
            DateTime tripStart = new DateTime();
            DateTime tripend = new DateTime();
            DateTime nxt_time = new DateTime();

            DateTime pre_time = new DateTime();

            if (values.Length > 2 && detailsType == "alltrips")
            {
                try
                {
                    for (int i = 0; i < values.Length; i++)
                    {
                        int nxt_speed = 0;
                        int sec_nxtSpd = 0;
                        int nxt_state = 1;
                        int sec_nxtstate = 1;
                        int stop = Convert.ToInt16(((Object[])values[i])[3]);
                        double speed = Convert.ToDouble(((Object[])values[i])[5]);
                        DateTime time = DateTime.Parse((((Object[])values[i])[2]).ToString());
                        if (i < values.Length - 2)
                        {
                            nxt_time = DateTime.Parse((((Object[])values[i + 1])[2]).ToString());
                            nxt_speed = Convert.ToInt16(((Object[])values[i + 1])[5]);
                            sec_nxtSpd = Convert.ToInt16(((Object[])values[i + 2])[5]);
                            nxt_state = Convert.ToInt16(((Object[])values[i + 1])[3]);
                            sec_nxtstate = Convert.ToInt16(((Object[])values[i + 2])[3]);
                        }
                        else if (i < values.Length - 1)
                        {
                            nxt_time = DateTime.Parse((((Object[])values[i + 1])[2]).ToString());
                            nxt_speed = Convert.ToInt16(((Object[])values[i + 1])[3]);
                            nxt_state = Convert.ToInt16(((Object[])values[i + 1])[3]);
                        }

                        TimeSpan time_gap = nxt_time.Subtract(time);
                        if (time_gap.Minutes > 7 && tripStart != DateTime.MinValue)
                        {
                            tripend = time;
                            tripsList.Add(formatDBDate(tripStart) + "," + formatDBDate(tripend));
                            tripStart = DateTime.MinValue;
                        }
                        if (stop == 0 && speed > 2 && nxt_state == 0 && (nxt_speed > 0 || sec_nxtSpd > 0) && tripStart == DateTime.MinValue)
                        {
                            tripStart = time;
                        }
                        else if (i > 0 && stop == 1 && tripStart != DateTime.MinValue)
                        {
                            tripend = time;
                            tripsList.Add(formatDBDate(tripStart) + "," + formatDBDate(tripend));
                            tripStart = DateTime.MinValue;
                        }
                        else if (i == values.Length - 1 && tripStart != DateTime.MinValue)
                        {
                            tripend = time;
                            tripsList.Add(formatDBDate(tripStart) + "," + formatDBDate(tripend));
                            tripStart = DateTime.MinValue;
                        }
                    }
                }
                catch (Exception ex)
                {
                    string mes = ex.Message;
                }
            }

            else if (values.Length > 3 && detailsType == "firstlasttrips")
            {
                for (int j = 0; j < values.Length; j++)
                {
                    int stop = Convert.ToInt16(((Object[])values[j])[3]);
                    double speed = Convert.ToDouble(((Object[])values[j])[5]);
                    DateTime time = DateTime.Parse((((Object[])values[j])[2]).ToString());
                    if (stop == 0 && speed > 2 && tripStart == DateTime.MinValue)
                    {
                        if (pre_time != DateTime.MinValue)
                            tripStart = pre_time;
                        else
                            tripStart = time;
                    }
                }
            }
            return tripsList;
        }

