        public string FilterDublicateValues(string str_value)
        {
            string filter_str = "";
            if (!string.IsNullOrEmpty(str_value))
            {
                List<string> valueList = str_value.Split(',').Distinct().ToList();
                int i = 0;
                foreach (string val in valueList)
                {
                    if (!string.IsNullOrEmpty(val))
                    {
                        if (i == 0) { filter_str = val; i++; }
                        else { filter_str += "," + val; }
                    }
                }
            }
            return filter_str;
        }

