        public Object[] accumulateDistanceCastrol(string vehicleId, string tripStartStr, string tripEndStr, Object lastLatLong, Object[] values = null, string IgnoreRunTimeCalcByTrip = "0")
        {
            try
            {
                int accid = GetVehAccontId(vehicleId);
                DataTable dtconfig = dbx.GetAccountConfig(accid);
                double DistanceCorrection = 0.0;
                string DistanceWithStopbit = "0";
                string StraightLineDistanceGoole = "0";
                string RunTimeFromOnOff = "0";
                if (dtconfig != null)
                {
                    if (dtconfig.Rows.Count > 0)
                    {
                        DistanceCorrection = Convert.ToDouble(dtconfig.Rows[0]["DistanceCorrection"].ToString());
                        DistanceWithStopbit = dtconfig.Rows[0]["DistanceWithStopbit"].ToString();
                        StraightLineDistanceGoole = dtconfig.Rows[0]["StraightLineDistanceGoole"].ToString();
                        RunTimeFromOnOff = dtconfig.Rows[0]["RunTimeFromOnOff"].ToString();
                    }
                }
                if (IgnoreRunTimeCalcByTrip == "1")
                    RunTimeFromOnOff = "0";
                if (StraightLineDistanceGoole == "1")
                {
                    return accumulateDistanceWithGoogle(vehicleId, tripStartStr, tripEndStr, lastLatLong, DistanceCorrection, values);
                }
                if (DistanceWithStopbit == "1")
                {
                    return accumulateDistanceCorrectForStopBit(vehicleId, tripStartStr, tripEndStr, lastLatLong, values);
                }
                //
                //  There are cases where vehicles remain idle for hours together so the routine has been modified to exclude such IDLING periods.
                //
                double latitudeThresholdIdle = 0.0001; // approx 15m
                double longitudeThresholdIdle = 0.0001; // approx 15m
                double distance = 0;
                TimeSpan runTime = new TimeSpan(0);
                float[] newLastLatLong = new float[3]; // need to store the STOP bit as float
                Object[] retObj = new Object[7];
                retObj[0] = distance;
                retObj[1] = null;
                retObj[2] = runTime;
                retObj[3] = "";
                retObj[4] = "";
                retObj[5] = "";
                retObj[6] = "";

                if (values == null)
                    values = dbx.getLatLong(vehicleId, tripStartStr, tripEndStr);

                String slowVeh = dbx.getTempSensorFlag(vehicleId);
                Boolean ignoreIdling = false;
                if (!String.IsNullOrEmpty(slowVeh) && String.Equals(slowVeh.ToUpper(), "SLOW"))
                    ignoreIdling = true;
                if (values == null || values.Length <= 1)
                {
                    return retObj;
                }
                float stopLatitude;
                float stopLongitude;
                float startLatitude;
                float startLongitude;
                DateTime stopTime;
                DateTime startTime;
                int curStopBit = 0;
                int lastStopBit = 0;
                stopTime = DateTime.Parse(tripStartStr);
                if (lastLatLong != null)
                {
                    stopLatitude = ((Single[])lastLatLong)[0];
                    stopLongitude = ((Single[])lastLatLong)[1];
                    lastStopBit = Convert.ToInt32(((Single[])lastLatLong)[2]); // extract the Stop bit
                    if (ignoreIdling)
                        stopTime = (DateTime)((Object[])values[0])[2];
                }
                else
                {
                    stopLatitude = Convert.ToSingle(((Object[])values[0])[0]);
                    stopLongitude = Convert.ToSingle(((Object[])values[0])[1]);
                    lastStopBit = Convert.ToInt32(((Object[])values[0])[3]); //stop bit is after timestamp
                    stopTime = (DateTime)((Object[])values[0])[2];
                }
                retObj[3] = stopLatitude.ToString() + "," + stopLongitude.ToString();
                bool IsMoving = false;
                for (int i = 0; i < values.Length; i++)
                {
                    IsMoving = false;
                    float rpm = 0;
                    startLatitude = Convert.ToSingle(((Object[])values[i])[0]);
                    startLongitude = Convert.ToSingle(((Object[])values[i])[1]);
                    startTime = (DateTime)((Object[])values[i])[2];
                    curStopBit = Convert.ToInt32(((Object[])values[i])[3]);
                    double speed = Convert.ToDouble(((Object[])values[i])[5]);
                    // double CANSpeed_Calibration_Val = dbx.getCANSpeedRatio(vehicleId);
                    double CANRPM_Calibration_Val = dbx.getCANRPMRatio(vehicleId);
                    if (CANRPM_Calibration_Val != 0)
                        rpm = Convert.ToSingle(((Object[])values[i])[8]);// consider RPM value only for RPM connected vehicles otherwise RPM will be always 0
                    double deltaLastLatitude = Math.Abs(stopLatitude - startLatitude);
                    double deltaLastLongitude = Math.Abs(stopLongitude - startLongitude);
                    if (curStopBit == 0 || lastStopBit == 0) //do not accumulate dsitance when HALTED
                    {
                        //
                        // the latitude and longitude threshold IDLE is a function of update rate. For 24 sec update rate the 0.0001 is probably ok 
                        // as it translates to about 2.5 kmph. Ideally the threshold values should be a function of update rate.
                        // Right now it is set so that anythng less than 4.5 kmph is thought to be IDLE (assuming updates do not get missed). 
                        // Now again this is a simplification as we need to consider the timestamp difference as well But ok for now.
                        //
                        bool IsMlogData = false;
                        TimeSpan elapsedTime = startTime.Subtract(stopTime);
                        if (elapsedTime.TotalSeconds == 1 && speed > 2)//For MLOG Data
                            IsMlogData = true;
                        if ((curStopBit == 0 && speed >= 3) || (ignoreIdling) || IsMlogData || rpm >= 100.00)
                        {
                            double currentDistance = computeDistance(stopLatitude, stopLongitude, startLatitude, startLongitude);
                            /*
                            if (i == 0)
                            {
                                Response.Write("Distance: " + currentDistance*1.02 + "<BR>\n");
                            }*/
                            // If positions are less than 5 minutes apart, consider vehicle as moving. THIS IS NOT TRUE. HERE's WHY THERE ARE 
                            // 3 POSSIBILITES. i) IF ALL's WELL THEN elapsedTime SHOULD BE < 1.0 SO ADD TO RUNTIME ii) IF A UNIT HAS JUST BOOTED
                            // AFTER A LONG STOP WHICH TAKES < 5 minutes THEN ADD ONLY IF THE DELTA TIME IS < 5 minutes. III)IF THERE ARE STRAIGHTLINES DUE TO
                            // VEHICLE OR UNIT ISSUES AND IF DISTANCE IS ADDED THEN YOU HAVE TO ADD TO RUNTIME AS WELL OTHERWISE IT WILL BE ABSURD I.E 
                            // VEHICLE HAS TRAVELLED THE DISTANCE IN NO TIME.
                            // KLUDGE TO TAKE CARE OF iii)  is to consider distance between two points. Logically it should not be more than 4 kms
                            // assuming all is well with the unit 
                            if (!(currentDistance >= 6 && elapsedTime.TotalMinutes < 1.0))
                            {
                                double distaddl = (DistanceCorrection / 100) * currentDistance;
                                // Come here only if there are no zig-zags. This is a KLUDGE and the correct distance value may have to be tweaked
                                if ((currentDistance / elapsedTime.TotalMinutes) >= 0.2 && (currentDistance / elapsedTime.TotalMinutes) <= 4 || (ignoreIdling) || rpm >= 100.00) // Take care of st lines //Assume Speed Can't more than 4km/min
                                                                                                                                                                                 // Atleast 2 scenarios it should take care 
                                                                                                                                                                                 // St line while running .... assumption is that avg speed > 18kmph
                                                                                                                                                                                 // St line after a HALT that had the unit OFF  in this case do not add the distance and HALT time can be anything
                                { // Now for some reason if the unit takes very long to boot up and get a position and the vehicle has moved far from rest
                                  // then it is a problem. Ideally we need to TEST the start BIT as well which we do not have here
                                    currentDistance = currentDistance + distaddl;
                                    distance += currentDistance;
                                    runTime = runTime.Add(elapsedTime);  // A straight line case so if distance is added then add the time to runTime
                                    IsMoving = true;
                                }
                                else if (elapsedTime.TotalSeconds < 60)
                                {
                                    currentDistance = currentDistance + distaddl;
                                    distance += currentDistance;
                                    runTime = runTime.Add(elapsedTime);
                                    IsMoving = true;
                                }
                                else if ((ignoreIdling && elapsedTime.TotalSeconds < 300))//Slow Moving Vehicle.(Run Time Need To Calculate Some what Acc. So here we need to Consider More Than 5mins Only Vehicle is Off.)
                                {
                                    runTime = runTime.Add(elapsedTime);
                                    IsMoving = true;
                                }
                                else if (currentDistance < 1.1 && elapsedTime.TotalMinutes > 150)//If vehicle is haleted more than 150mins in basement(NO GPS) area.and getting signal after moving some distance.(we are taking 1.1km)
                                {
                                    currentDistance = currentDistance + distaddl;
                                    distance += currentDistance;
                                    IsMoving = true;
                                }
                            }
                            if (distance > 0 && retObj[5].ToString() == "")
                            {
                                retObj[5] = stopTime.ToString("yyyy-MM-dd HH:mm:ss");
                            }
                            if (currentDistance > 0 && runTime.TotalSeconds > 0 && IsMoving)
                            {
                                retObj[6] = startTime.ToString("yyyy-MM-dd HH:mm:ss");
                            }
                        }
                    }
                    stopLatitude = startLatitude;
                    stopLongitude = startLongitude;
                    stopTime = startTime;
                    lastStopBit = curStopBit;
                }
                //Response.Write("Run:" + runTime.ToString() + "<BR>");
                distance = distance * 1.02;
                newLastLatLong[0] = stopLatitude;
                newLastLatLong[1] = stopLongitude;
                newLastLatLong[2] = Convert.ToSingle(lastStopBit);
                retObj[0] = distance;
                retObj[1] = newLastLatLong;
                retObj[2] = runTime;
                if (RunTimeFromOnOff == "1")
                {
                    if (distance > 0)
                        retObj[2] = GetRunTimeFromOnOff(vehicleId, values, Convert.ToDateTime(tripStartStr), Convert.ToDateTime(tripEndStr));
                }
                retObj[4] = stopLatitude.ToString() + "," + stopLongitude;
                return retObj;
            }
            catch
            {
                dbx.close();
                // throw;
                return null;
            }
            // finally { dbx.close(); }
        }
