        public string insertUpdtRateRequestLog(string sessionId, string asset, string requestType, int requestedValue, string source)
        {
            try
            {
                int requestNo = 5;
                string RequestMsg = "";
                string res = "";
                switch (requestType)
                {
                    case "Moving Update Rate":
                        RequestMsg = ("(SET FASTTRACKTIME " + requestedValue + ")");//Modified by suvarna on 1/2/2021 to remove mobileno
                        break;

                    case "Theft Enable":
                        RequestMsg = ("(SET ACCL 0)");
                        break;

                    case "Halt Update Rate":
                        RequestMsg = ("(SET SLOWTRACKTIME " + requestedValue + ")");
                        break;

                    case "Theft Disable":
                        RequestMsg = ("(SET ACCL 1)");
                        break;

                    case "Theft Halt Update Rate":
                        RequestMsg = ("(SET THEFTSLOWTRACKTIME " + requestedValue + ")");
                        break;

                    default:
                        return "Invalid request type";
                }
                string[] str = RequestMsg.Split(' ');
                string command = str[1].ToString();
                DataTable dt = dbx.GetAssetServerRequest(asset, command);
                if (dt.Rows.Count > 0)
                {
                    res = dbx.RemoveAssetServerRequest(asset, command);
                }
                dbx.addServerRequest(asset, requestNo, RequestMsg); // "Command sent to device";
                return dbx.insertUpdtRateRequestLog(sessionId, asset, requestType, requestedValue, "queued", source);
            }
            catch (Exception ex) { return ex.ToString(); }

        }
