                    TMARStatus = "NotUpdated";

                    SRate = dt.Rows[0]["Halt Update Rate"].ToString();
                    SRStatus = "NotUpdated";

                    TCRate = dt.Rows[0]["Theft Halt update rate"].ToString();
                    TCRStatus = "NotUpdated";
                    RequestType = "Moving Update Rate";
                }
                var v = new AssetUpdtType()
                {

                    AssetId = details.Rows[i]["VehicleID"].ToString(),
                    //MUpdtType = MRate,
                    //MStatus = MRStatus,
                    //TMAUpdtType = TMARate,
                    //TMAStatus = TMARStatus,
                    //SUpdtType = SRate,
                    //SStatus = SRStatus,
                    //TMIUpdtType = TMIRate,
                    //TMIStatus = TMIRStatus,
                    //TCUpdtType = TCRate,
                    //TCStatus = TCRStatus,

                    MotionRate = MRate,
                    Theftstate = TMARate,
                    haltupdaterate = SRate,
                    thefthaltupdaterate = TCRate,
                    MotionRateStatus = MRStatus,
                    TheftstateStatus = TMARStatus,
                    haltupdaterateStatus = SRStatus,
                    thefthaltupdaterateStatus = TCRStatus,
                    ChangeRequstType = RequestType,
                    ChangeRequstValue = RequestedValue,

                };
                AssetList.Add(v);
            }
            return AssetList;
        }
