                    strendpoint1 = System.Web.HttpUtility.UrlEncode(strendpoint1);
                    strendpoint2 = Uri.EscapeUriString(strendpoint2);
                    strendpoint3 = System.Web.HttpUtility.UrlEncode(strendpoint3);
                    //https://alerts.kaleyra.com/api/v5/?api_key=A208ea0d97e4a1163f8182dcb6054aa42&method=txtly.create&url=
                    url = table.Rows[0]["CallUrl"].ToString();
                    string result = objBll.MakeHttpRequest(url + System.Web.HttpUtility.UrlEncode(sHost) + strendpoint1 + Uri.EscapeUriString(strendpoint2) + strendpoint3, "POST", "application/json");
                    //string result = objBll.MakeHttpRequest(url + sHost + "TrackMe.aspx?sessionId=" + SessionId + "&vehicles=" + deviceid + "&advanced=1&title=abc&format=json", "POST", "application / json");

                    if (result != null)
                    {
