        public string GetRouteURL(string SessionId, string deviceid, string tripId, string estTripStartDateTime, string estTripEndDateTime)
        {
            string link = "";
            try
            {
                String strPathAndQuery = HttpContext.Current.Request.Url.PathAndQuery;
                //String sHost = HttpContext.Current.Request.Url.AbsoluteUri.Replace(strPathAndQuery, "/");
                //sHost = sHost.Replace(":334", "");
                // sHost = sHost.Replace("http://", "https://");

                string frdate = string.Empty;
                string tdate = string.Empty;

                try
                {
                    frdate = formatDBDate(DateTime.ParseExact(estTripStartDateTime, "dd-MMM-yy HH:mm:ss", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception ex)
                {
                    frdate = formatDBDate(Convert.ToDateTime(estTripStartDateTime));
                }


                try
                {
                    tdate = formatDBDate(DateTime.ParseExact(estTripEndDateTime, "dd-MMM-yy HH:mm:ss", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception ex)
                {
                    tdate = formatDBDate(Convert.ToDateTime(estTripEndDateTime));
                }

                BusinessLogicLayer.BLL objBll = new BusinessLogicLayer.BLL();
                string username = objBll.getUserId(SessionId);

                //link = sHost + "/showtriproute.aspx?" + SessionId + "&vehicles=" + deviceid + "&fromDate=" + frdate + "&toDate=" + tdate + "&tripid=" + tripId;

                DataTable table = objBll.GetCallActivationDetails(username, "txtly");
                string url = "";

                if (table.Rows.Count > 0)
                {
                    String sHost = HttpContext.Current.Request.Url.AbsoluteUri.Replace(strPathAndQuery, "/");
                    sHost = sHost.Replace(":334", "");
                    sHost = sHost.Replace("http://", "https://");

                    string strendpoint = sHost;
                    string strendpoint1 = "showtriproute.aspx?sessionId=" + SessionId + "&vehicles=";
                    string strendpoint2 = deviceid;
                    string strendpoint4 = "&fromDate=";
                    string strendpoint5 = "&toDate=";
                    string strendpoint6 = "&tripid=";
                    string strendpoint7 = frdate;
                    string strendpoint8 = tdate;
                    string strendpoint9 = tripId;
                    string strendpoint3 = "&advanced=1&title=abc&format=json";
                    strendpoint = System.Web.HttpUtility.UrlEncode(strendpoint);
                    strendpoint1 = System.Web.HttpUtility.UrlEncode(strendpoint1);
                    strendpoint4 = System.Web.HttpUtility.UrlEncode(strendpoint4);
                    strendpoint5 = System.Web.HttpUtility.UrlEncode(strendpoint5);
                    strendpoint6 = System.Web.HttpUtility.UrlEncode(strendpoint6);
                    strendpoint2 = Uri.EscapeUriString(strendpoint2);
                    strendpoint7 = Uri.EscapeUriString(strendpoint7);
                    strendpoint8 = Uri.EscapeUriString(strendpoint8);
                    strendpoint9 = Uri.EscapeUriString(strendpoint9);
                    strendpoint3 = System.Web.HttpUtility.UrlEncode(strendpoint3);

                    url = table.Rows[0]["CallUrl"].ToString();
                    string result = objBll.MakeHttpRequest(url + System.Web.HttpUtility.UrlEncode(sHost) + strendpoint1 + Uri.EscapeUriString(strendpoint2) + strendpoint4 + Uri.EscapeUriString(strendpoint7) + strendpoint5 + Uri.EscapeUriString(strendpoint8) + strendpoint6 + Uri.EscapeUriString(strendpoint9) + strendpoint3, "POST", "application/json");


                    if (result != null)
                    {
                        var response = JsonConvert.DeserializeObject<dynamic>(result);
                        link = response["txtly"].ToString();
                    }
                }
            }
            catch (Exception ex)
            {
                link = "Error";

            }
            return link;
        }
