        public string getTelinetyauthenticate(string mobile, string drivername, string vehicleid, string licence, string startlocation, string endlocation)
        {
            if (mobile.Length == 10)
                mobile = string.Concat("91", mobile);
            dbx.insertsimtrackingtrips(vehicleid, drivername, mobile, startlocation, endlocation);
            string simstatus = string.Empty;
            string statusmsg = dbx.checktelinetsimtrackingstatus(vehicleid, mobile, startlocation, endlocation);
            if (statusmsg == "tracking")
                return statusmsg;
            if (statusmsg == "add" | statusmsg == "awaiting consent")
            {
                if (statusmsg == "add")
                {
                    try
                    {
                        simstatus = "awaiting consent";
                        dbx.insertsimtrackingstatus(mobile, simstatus, drivername, vehicleid, licence, startlocation, endlocation);
                    }
                    catch (Exception ex) { return "error adding status"; }
                }
                string token = string.Empty;

                string message = dbx.getcurrenttoken("telenit", ref token);
                if (message == "token expired" | message == "insert new token")
                    token = getTelinetytoken();
                string EndPoint = "https://smarttrail.telenity.com/trail-rest/entities/import";
                string HttpMethod = "POST";
                string ContentType = "application/json";
                string Headers = "token," + token;
                string PostData = "{\"entityImportList\": [{\"firstName\":\"" + drivername + "\",\"lastName\": \"\",\"msisdn\":\"" + mobile + "\"}]}";
                string cleaned = PostData.Replace("\n", "").Replace("\r", "");
                /*'{\"entityImportList\": [{\"firstName\": \"Test\",\"lastName\": \"user\",\"msisdn\": \"918197611159\"}]}'*/
                string repStr = dbx.MakeHttpRequest(EndPoint, HttpMethod, ContentType, cleaned, Headers);
                var data = JsonConvert.DeserializeObject<dynamic>(repStr);
                string successlist = Convert.ToString(data["successList"]);
                if (successlist.Contains(mobile))
                {
                    if (successlist.Contains(mobile))
                        simstatus = "tracking";
                }
                string failurelist = Convert.ToString(data["failureList"]);
              /*  if (failurelist.Contains(mobile) & failurelist.Contains("already exists"))
                {
                    simstatus = "tracking";
                }*/
                if (simstatus == "tracking")
                {
                    try
                    {
                        dbx.updatesimtrackingstatus(vehicleid, mobile, simstatus);
                    }
                    catch (Exception ex)
                    { return "error updating status"; }
                }
                string responsecode = Convert.ToString(data["responsecode"]);
                string responsemessage = string.Empty;
                switch (responsecode)
                {
                    case "200":
                        {
                            responsemessage = "success";
                            break;
                        }
                    case "400":
                        {
                            responsemessage = "Bad Request";
                            break;
                        }
                    case "401":
                        {

                            responsemessage = "authentication failure";
                            break;
                        }
                    case "403":
                        {
                            responsemessage = "Forbidden";
                            break;


                        }
                    case "404":
                        {
                            responsemessage = "mistake in the host or path of the service URI, including a problem with the MSISDN supplied within the path";
                            break;
                        }
                    case "405":
                        {

                            responsemessage = "method not supported";
                            break;
                        }
                    case "500":
                        {
                            responsemessage = "The server encountered an unexpected condition. This could be incorrect authentication details.or limited user permission";
                            break;
                        }
                    case "503":
                        {
                            responsemessage = "Server busy and service unavailable.";
                            break;
                        }
                }
                return responsemessage;

            }
            return simstatus;
        }

