        public string gettelenityconsenttoken()
        {
            string endpoint = "https://india-agw.telenity.com/oauth/token?grant_type=client_credentials";

            string repStr = dbx.MakeHttpRequest(endpoint, "POST", "application/x-www-form-urlencoded ", "", "Authorization, Basic c21hcnR0cmFpbGNsb3VkOnNtYXJ0dHJhaWxjbG91ZA==");
            var data = JsonConvert.DeserializeObject<dynamic>(repStr);
            string access_token = data["access_token"];
            string tokenname = "telenit_access_token";
            string timestamp = dbx.formatDBDate(DateTime.UtcNow.AddSeconds(19800));
            try
            {
                dbx.updatesimtoken(tokenname, access_token, timestamp);
            }
            catch (Exception ex)
            {
                return "error";
            }
            return access_token;
        }

        public void gettelinityconsent(string mobile, string vehicleid, string drivername, string startloc, string endloc, string access_token)
        {
            string token = string.Empty;

            /*   string message = dbx.getcurrenttoken("telenit", ref token);
               if (message == "token expired" | message == "insert new token")
                   token = getTelinetytoken();*/
            string EndPoint = "https://india-agw.telenity.com/apigw/NOFBconsent/v1/NOFBconsent?address=tel:" + mobile;
            string HttpMethod = "GET";
            string ContentType = "application / json";
            string Headers = "Authorization, Bearer " + access_token;
            string PostData = "";
            string repStr = dbx.MakeHttpRequest(EndPoint, HttpMethod, ContentType, PostData, Headers);
            var data = JsonConvert.DeserializeObject<dynamic>(repStr);
            //  string consentstatus = data["simconsent"][0]["Consent"]["status"];
            string consentstatus = data["Consent"]["status"];
            if (consentstatus.ToLower() == "allowed")
                dbx.updatesimtrackingstatus(vehicleid, mobile, "tracking");

            return;
        }
