		//Method added to get short url for all customer - centralized method - sahana 10-10-2025
		public string ShortenUrl(string longUrl, string username)
		{
			DataTable table = GetCallActivationDetails(username, "txtly");
			string link = "";

			if (table.Rows.Count > 0)
			{
				string config = table.Rows[0]["CallUrl"].ToString();
				try
				{
					string apiUrl = "";
					var parts = config.Split('|');
					string endpoint = parts[0];
					string apiKey = parts[1];
					string encodedUrl = Uri.EscapeDataString(longUrl);
					if(username=="tcl")
					{
						 apiUrl = $"{endpoint}?url={longUrl}";
					}
					else
					{
						apiUrl = $"{endpoint}?url={encodedUrl}";
					} 
					string headers = $"api-key,{apiKey}";
					string result = MakeHttpRequest(apiUrl, "POST", "application/x-www-form-urlencoded", "", headers);

					//string res = MakeHttpRequest(endpoint, "POST", "application/x-www-form-urlencoded", $"url={(longUrl)}", headers);        
					var response = JsonConvert.DeserializeObject<dynamic>(result);
					link = response["data"][0]["txtly"]?.ToString();

					return link ?? "";
				}
				catch (Exception ex)
				{
					STL_RecordErrorMessage(ex.Message + " - GetShortenUrlError");
					return "";
				}
			}
			return link;
		}

