        public DataTable GetVehicleRAGReport(string fromDate, string toDate, int groupId, string circle, string transporter)
        {
            DataTable dtViolations = dbx.GetVehicleViolationCounts(fromDate, toDate, groupId, circle, transporter);
            DataTable dtDistance = dbx.GetVehicleDisatnceData(fromDate, toDate, groupId);

            DataTable finalTable = dtViolations.Copy();

            finalTable.Columns.Add("Distance", typeof(double));
            finalTable.Columns.Add("AccelerationPer100KM", typeof(double));
            finalTable.Columns.Add("DecelerationPer100KM", typeof(double));
            finalTable.Columns.Add("OverspeedPer100KM", typeof(double));
            finalTable.Columns.Add("RAG", typeof(double));

            // Dictionary for fast lookup
            var distanceDict = dtDistance.AsEnumerable()
                .Where(r => r["vehicleid"] != DBNull.Value)
                .ToDictionary(
                    r => r["vehicleid"].ToString(),
                    r => Convert.ToDouble(r["Distance"])
                );

            // 🔴 List to store rows to delete
            List<DataRow> rowsToRemove = new List<DataRow>();

            foreach (DataRow row in finalTable.Rows)
            {
                string vehicle = row["vehicleId"].ToString();

                double distance = 0;

                if (distanceDict.ContainsKey(vehicle))
                    distance = distanceDict[vehicle];

                // 🚫 Skip if distance < 100
                if (distance < 100)
                {
                    rowsToRemove.Add(row);
                    continue;
                }

                row["Distance"] = Math.Round(distance, 2);

                double accel = row["HighAcceleration"] != DBNull.Value ? Convert.ToDouble(row["HighAcceleration"]) : 0;
                double brake = row["HarshBraking"] != DBNull.Value ? Convert.ToDouble(row["HarshBraking"]) : 0;
                double over = row["Overspeeding"] != DBNull.Value ? Convert.ToDouble(row["Overspeeding"]) : 0;

                double accel100 = Math.Round((accel / distance) * 100, 2);
                double brake100 = Math.Round((brake / distance) * 100, 2);
                double over100 = Math.Round((over / distance) * 100, 2);

                row["AccelerationPer100KM"] = accel100;
                row["DecelerationPer100KM"] = brake100;
                row["OverspeedPer100KM"] = over100;

                row["RAG"] = Math.Round(accel100 + brake100 + over100, 2);
            }

            // ✅ Remove filtered rows
            foreach (var row in rowsToRemove)
            {
                finalTable.Rows.Remove(row);
            }
            // ✅ Arrange columns
            finalTable.Columns["vehicleId"].SetOrdinal(0);
            finalTable.Columns["drivername"].SetOrdinal(1);
            finalTable.Columns["HighAcceleration"].SetOrdinal(2);
            finalTable.Columns["AccelerationPer100KM"].SetOrdinal(3);
            finalTable.Columns["HarshBraking"].SetOrdinal(4);
            finalTable.Columns["DecelerationPer100KM"].SetOrdinal(5);
            finalTable.Columns["Overspeeding"].SetOrdinal(6);
            finalTable.Columns["OverspeedPer100KM"].SetOrdinal(7);
            finalTable.Columns["Distance"].SetOrdinal(8);
            finalTable.Columns["RAG"].SetOrdinal(9);

            return finalTable;
        }
